<?php
/**
 * Template Name: POS Checkout
 * Description: Professional POS Cashier System with unified design framework
 *
 * @package RUIYI_Retail_POS
 */

// Check access
if (!ruiyi_pos_check_access()) {
    wp_redirect(home_url('/pos-login/'));
    exit;
}

// Force language initialization for this template
$current_language = ruiyi_pos_get_current_language();
if (function_exists('ruiyi_pos_reload_textdomain')) {
    ruiyi_pos_reload_textdomain($current_language);
}

// Activate custom translation override
ruiyi_pos_override_translations();

// Get keyboard shortcuts settings
// 🔥 注意：F1专用于打开钱箱，结账使用F4或Ctrl+Enter
$default_shortcuts = array(
    'complete_sale' => 'F4',  // 🔥 改为F4，F1专用于钱箱
    'clear_cart' => 'F2',
    'hold_order' => 'F2',
    'view_held_orders' => 'F3',
    'barcode_scanner' => 'F3',
    'cash_drawer' => 'F1',  // F1 = 打开钱箱（唯一功能）
    'payment_cash' => 'F5',
    'quick_add_product' => 'F6', // 🔥 快速添加产品
    'supplier_management' => 'F7', // 🔥 改为供应商管理
    'points_management' => 'F8', // 🔥 积分管理改为F8
    'search_products' => 'F9', // 🔥 产品搜索改为F9
    // 🔥 移除了 'find_product' => '+' - 加号键现在用于添加Varios产品
    // 🔥 减号键 '-' 用于减少选中产品数量（不在此配置，特殊处理）
    'discount' => 'F10',
    'void_transaction' => 'F11'
);
$keyboard_shortcuts = get_option('ruiyi_pos_keyboard_shortcuts', $default_shortcuts);

// 🔥 强制移除find_product的+键绑定（如果数据库中有旧配置）
if (isset($keyboard_shortcuts['find_product']) && $keyboard_shortcuts['find_product'] === '+') {
    unset($keyboard_shortcuts['find_product']);
    ruiyi_pos_log('[RUIYI POS] 检测到旧的find_product +键配置，已强制移除');
}

// 🔥 强制移除所有Backspace键绑定（如果数据库中有旧配置）
foreach ($keyboard_shortcuts as $action => $key) {
    if ($key === 'Backspace') {
        $keyboard_shortcuts[$action] = ''; // 清空该快捷键
        ruiyi_pos_log('[RUIYI POS] 检测到 ' . $action . ' 使用Backspace键，已强制移除');
    }
}

// 🔥 强制移除Enter键作为complete_sale快捷键（防止扫描器冲突）
if (isset($keyboard_shortcuts['complete_sale']) && $keyboard_shortcuts['complete_sale'] === 'Enter') {
    $keyboard_shortcuts['complete_sale'] = 'F4'; // 强制改为F4（F1专用于钱箱）
    ruiyi_pos_log('[RUIYI POS] 检测到 complete_sale 使用Enter键，已强制改为F4（防止扫描器冲突）');
}

// 🔥 强制确保F1不用于结账（F1专用于钱箱）
if (isset($keyboard_shortcuts['complete_sale']) && $keyboard_shortcuts['complete_sale'] === 'F1') {
    $keyboard_shortcuts['complete_sale'] = 'F4'; // F1专用于钱箱，结账改为F4
    ruiyi_pos_log('[RUIYI POS] 检测到 complete_sale 使用F1键，已强制改为F4（F1专用于钱箱）');
}

// 🔥 强制将F6从payment_card改为quick_add_product（快速添加产品）
if (isset($keyboard_shortcuts['payment_card']) && $keyboard_shortcuts['payment_card'] === 'F6') {
    unset($keyboard_shortcuts['payment_card']); // 移除旧的payment_card绑定
    ruiyi_pos_log('[RUIYI POS] 检测到 payment_card 使用F6键，已强制移除（F6改为快速添加产品）');
}
// 确保quick_add_product绑定到F6
$keyboard_shortcuts['quick_add_product'] = 'F6';

// Points system configuration - use WordPress admin settings
$points_max_discount_percent = floatval(get_option('ruiyi_points_max_discount', 10)); // Maximum discount percentage (e.g., 10%)
$points_deduction_rate = floatval(get_option('ruiyi_points_redemption_rate', 10)); // Points deduction rate (e.g., 10%)
$points_reward_rate = floatval(get_option('ruiyi_points_reward_rate', 15)); // Points reward rate (e.g., 15%)

