    <p class="text-sm text-gray-400 mt-2">Configurando impresora...</p>
    <button id="clodop-refresh-btn" class="hidden mt-8 px-8 py-3 bg-blue-600 text-white rounded-lg text-lg font-medium hover:bg-blue-700" onclick="window.location.reload()">
        刷新页面 / Refrescar
    </button>
</div>
<script>
(function() {
    var screen = document.getElementById('clodop-loading-screen');
    var textEl = document.getElementById('clodop-loading-text');
    var refreshBtn = document.getElementById('clodop-refresh-btn');
    var startTime = Date.now();
    var TIMEOUT = 30000;

    var timer = setInterval(function() {
        try {
            var LODOP = getCLodop();
            if (LODOP) {
                clearInterval(timer);
                console.log('✅ [CLODOP] 打印服务就绪，移除加载屏');
                screen.remove();
                return;
            }
        } catch (e) {}

        if (Date.now() - startTime >= TIMEOUT) {
            clearInterval(timer);
            console.warn('⚠️ [CLODOP] 打印服务连接超时');
            textEl.textContent = '打印机连接超时 / Tiempo de espera agotado';
            refreshBtn.classList.remove('hidden');
        }
    }, 1000);
})();
</script>
