<!-- 🔥 强制刷新函数 -->
<script>
/**
 * 强制刷新页面 - 清空所有缓存并重新加载
 * Force refresh - clear all caches and reload
 */
async function forceRefreshPage() {
    const confirmMsg = '<?php echo ($locale == "zh_CN" || strpos($locale, "zh") === 0) ? "确定要强制刷新吗？这将清空页面缓存并重新加载。" : "Force refresh? This will clear page cache and reload."; ?>';

    if (!confirm(confirmMsg)) {
        return;
    }

    try {
        // 1. 显示加载提示
        const btn = document.getElementById('force-refresh-btn');
        if (btn) {
            btn.disabled = true;
            btn.innerHTML = '<svg class="w-5 h-5 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>';
        }

        // 2. 清除Service Worker缓存
        if ('caches' in window) {
            const cacheNames = await caches.keys();
            await Promise.all(cacheNames.map(cacheName => caches.delete(cacheName)));
            console.log('[Force Refresh] Service Worker caches cleared');
        }

        // 3. 注销Service Worker（可选，如果需要完全重置）
        if ('serviceWorker' in navigator) {
            const registrations = await navigator.serviceWorker.getRegistrations();
            for (const registration of registrations) {
                await registration.unregister();
            }
            console.log('[Force Refresh] Service Workers unregistered');
        }

        // 4. 清除IndexedDB中的产品缓存
        if (window.indexedDB) {
            try {
                // 清除产品缓存数据库
                const deleteRequest = indexedDB.deleteDatabase('ruiyi_pos_products_cache');
                deleteRequest.onsuccess = () => console.log('[Force Refresh] Products cache DB deleted');
                deleteRequest.onerror = () => console.warn('[Force Refresh] Failed to delete products cache DB');
            } catch (e) {
                console.warn('[Force Refresh] IndexedDB cleanup error:', e);
            }
        }

        // 5. 清除localStorage中的相关缓存（保留用户设置）
        const keysToRemove = [];
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            // 只清除缓存相关的键，保留用户偏好设置
            if (key && (key.includes('cache') || key.includes('Cache') || key.includes('products'))) {
                keysToRemove.push(key);
            }
        }
        keysToRemove.forEach(key => localStorage.removeItem(key));
        console.log('[Force Refresh] LocalStorage cache keys cleared:', keysToRemove.length);

        // 6. 清除sessionStorage
        sessionStorage.clear();
        console.log('[Force Refresh] SessionStorage cleared');

        // 7. 强制刷新页面（跳过缓存）
        // 使用 location.reload(true) 或添加时间戳参数
        const url = new URL(window.location.href);
        url.searchParams.set('_refresh', Date.now());
        window.location.href = url.toString();

    } catch (error) {
        console.error('[Force Refresh] Error:', error);
        // 即使出错也尝试刷新
        window.location.reload(true);
    }
}
</script>

<!-- JavaScript for Toggle Fields -->
<script>
document.addEventListener('DOMContentLoaded', function() {
    // Toggle discount percentage field
    const discountCheckbox = document.getElementById('product-discount-enabled');
    const discountField = document.getElementById('discount-percentage-field');
    if (discountCheckbox && discountField) {
        discountCheckbox.addEventListener('change', function() {
            if (this.checked) {
                discountField.classList.remove('hidden');
            } else {
                discountField.classList.add('hidden');
                document.getElementById('product-discount-percentage').value = '';
            }
        });
    }

    // Toggle invoice percentage field
    const invoiceCheckbox = document.getElementById('product-invoice-enabled');
    const invoiceField = document.getElementById('invoice-percentage-field');
    if (invoiceCheckbox && invoiceField) {
        invoiceCheckbox.addEventListener('change', function() {
            if (this.checked) {
                invoiceField.classList.remove('hidden');
            } else {
                invoiceField.classList.add('hidden');
                document.getElementById('product-invoice-percentage').value = '';
            }
        });
    }
});
</script>

