// Points system configuration with validation
const pointsConfig = {
    maxDiscountPercent: <?php echo $points_max_discount_percent ?: 10; ?>, // Maximum discount percentage
    deductionRate: <?php echo $points_deduction_rate ?: 10; ?>, // Points deduction rate
    rewardRate: <?php echo $points_reward_rate ?: 15; ?>, // Points reward rate
    ajaxUrl: '<?php echo esc_url(admin_url('admin-ajax.php')); ?>',
    nonce: '<?php echo wp_create_nonce('ruiyi_pos_nonce'); ?>'
};

// Validate points configuration to prevent NaN errors
if (isNaN(pointsConfig.maxDiscountPercent) || pointsConfig.maxDiscountPercent <= 0) {
    pointsConfig.maxDiscountPercent = 10;
    console.warn('Invalid maxDiscountPercent, using default: 10%');
}
if (isNaN(pointsConfig.deductionRate) || pointsConfig.deductionRate <= 0) {
    pointsConfig.deductionRate = 10;
    console.warn('Invalid deductionRate, using default: 10%');
}
if (isNaN(pointsConfig.rewardRate) || pointsConfig.rewardRate <= 0) {
    pointsConfig.rewardRate = 15;
    console.warn('Invalid rewardRate, using default: 15%');
}
</script>

<script>
// ============================================================
// 🔥 全局 Fetch 拦截器：自动处理 nonce 过期 + 自动重试
// 覆盖所有 AJAX 调用，无需逐个修改 50+ 个 fetch 调用
// ============================================================
(function() {
    // 通过 iframe 获取浏览器原生 fetch，避免被其他脚本覆盖导致冲突
    const _iframe = document.createElement('iframe');
    _iframe.style.display = 'none';
    document.head.appendChild(_iframe);
    const _nativeFetch = _iframe.contentWindow.fetch.bind(window);
    document.head.removeChild(_iframe);

    let _isRefreshing = false;
    let _refreshPromise = null;

    // 刷新 nonce（不需要旧 nonce，只需登录状态）
    async function _refreshNonce() {
        if (_isRefreshing) return _refreshPromise;
        _isRefreshing = true;
        _refreshPromise = (async () => {
            try {
                const resp = await _nativeFetch(ruiyi_pos_ajax.ajax_url, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    credentials: 'same-origin',
                    body: new URLSearchParams({ action: 'ruiyi_pos_ajax', pos_action: 'refresh_nonce' })
                });
                const data = await resp.json();
                if (data.success && data.data.nonce) {
                    ruiyi_pos_ajax.nonce = data.data.nonce;
                    console.log('[POS] Nonce auto-refreshed successfully');
                    return true;
                }
                // 🔥 如果刷新失败是因为未登录，重定向到登录页
                if (!data.success && data.data &&
                    (data.data.code === 'not_logged_in' || data.data.code === 'unauthorized')) {
                    console.error('[POS] Session expired during nonce refresh - redirecting to login');
                    window.location.href = '<?php echo esc_url(home_url("/pos-login/")); ?>';
                    return false;
                }
                console.warn('[POS] Nonce refresh failed:', data);
            } catch(e) {
                console.error('[POS] Nonce refresh error:', e);
            }
            return false;
        })();
        const result = await _refreshPromise;
        _isRefreshing = false;
        return result;
    }

    // 替换 body 中的 nonce 值
    function _replaceNonceInBody(body, newNonce) {
        if (body instanceof URLSearchParams) {
            const newBody = new URLSearchParams(body);
            newBody.set('nonce', newNonce);
            return newBody;
        } else if (body instanceof FormData) {
            body.set('nonce', newNonce);
            return body;
        } else if (typeof body === 'string' && body.includes('nonce=')) {
            const params = new URLSearchParams(body);
            params.set('nonce', newNonce);
            return params.toString();
        }
        return body;
    }

    window.fetch = async function(url, options = {}) {
        const response = await _nativeFetch(url, options);

        // 只拦截发往 admin-ajax.php 的 POST 请求
        if (typeof url !== 'string' || !url.includes('admin-ajax') || options.method !== 'POST') {
            return response;
        }

        // 克隆 response 以检查是否为 nonce_expired
        const cloned = response.clone();
        try {
            const data = await cloned.json();
            if (data.success === false && data.data && data.data.code === 'nonce_expired') {
                console.log('[POS] Nonce expired detected, auto-refreshing and retrying...');
                const refreshed = await _refreshNonce();
                if (refreshed) {
                    const newOptions = Object.assign({}, options, {
                        body: _replaceNonceInBody(options.body, ruiyi_pos_ajax.nonce)
                    });
                    return _nativeFetch(url, newOptions);
                }
            }
        } catch(e) {
            // Response was not JSON (e.g. HTML error page), return original
        }

        return response;
    };

    // 🔥 页面可见性变化时刷新 nonce（用户切换标签页回来）
    document.addEventListener('visibilitychange', function() {
        if (document.visibilityState === 'visible' && typeof ruiyi_pos_ajax !== 'undefined') {
            console.log('[POS] Tab visible, refreshing nonce...');
            _refreshNonce();
        }
    });

    // 🔥 网络恢复时刷新 nonce
    window.addEventListener('online', function() {
        if (typeof ruiyi_pos_ajax !== 'undefined') {
            console.log('[POS] Network restored, refreshing nonce...');
            _refreshNonce();
        }
    });
})();

// Professional POS System - Fixed Version
class ProfessionalPOS {
    constructor() {
        this.cart = [];
        this.selectedProductId = null; // Track selected product in cart
        this.cartItemIdCounter = 0; // Unique ID counter for cart items
        this.searchTimeout = null;
        this.syncTimeout = null;
        this.lastSyncData = null;
        this.taxRate = 0.21; // 21% IVA tax
        this.heldOrders = this.loadHeldOrders();
        this.scaleConfig = Object.assign({
            enabled: false,
            socket_url: '',
            socket_path: '/socket.io',
            retry_ms: 2000,
            stale_after_ms: 5000,
            precision: 3,
            min_weight_kg: 0.005,
            weight_unit: 'kg',
            unit_aliases: [],
            debug: false,
            location: 'default',
            client_type: 'pos',
            auth_token: ''
        }, ruiyi_pos_ajax.scale_integration || {});
        this.scaleState = {
            connected: false,
            latestWeight: null,
            lastUpdatedAt: 0,
            unit: this.scaleConfig.weight_unit || 'kg',
            status: 'disconnected',
            lastError: null,
            preview: null,
        };
        this.weightMetaCache = new Map();
        this.pendingWeightRequests = new Map();
        this.scaleSocket = null;

        // Customer information storage
        this.customerInfo = {
            name: '',
            phone: '',
            address: '',
            company: '',
            taxId: ''
        };

        // 🔥 Zero Price Prompt Configuration
        this.zeroPricePromptEnabled = <?php echo get_option('ruiyi_pos_zero_price_prompt_enabled', '0') === '1' ? 'true' : 'false'; ?>;
        this.pendingZeroPriceProduct = null; // Store product waiting for price input

        // 🔥 退货模式状态 (Return Mode)
        this.returnQuantity = 0; // 0 = 正常模式, -1 = 退货模式

        // 🔥 Wholesale Invoice Feature Configuration
        this.wholesaleInvoiceEnabled = <?php echo get_option('ruiyi_retail_wholesale_invoice_enabled', false) ? 'true' : 'false'; ?>;

        // 🔥 Last Order Display Feature Configuration (上一单显示功能)
        this.lastOrderDisplayEnabled = <?php echo get_option('ruiyi_retail_last_order_display_enabled', false) ? 'true' : 'false'; ?>;

        // 🔥 Auto Daily Settlement Feature Configuration (日结单自动保存)
        this.autoDailySettlementEnabled = <?php echo get_option('ruiyi_retail_auto_daily_settlement_enabled', false) ? 'true' : 'false'; ?>;
        this.autoDailySettlementTime = '<?php echo esc_js(get_option('ruiyi_retail_auto_daily_settlement_time', '00:00')); ?>';

        // 🔥 Interval IDs for cleanup on page unload (prevent memory leaks)
        this.intervalIds = [];

        // 🔥 DOM element cache (Phase 2 optimization - avoid repeated getElementById calls)
        this.domCache = {};

        // 🔥 Performance: debounced localStorage save timer
        this._cartSaveTimer = null;
        // 🔥 Performance: cart state tracking for incremental DOM updates
        this._prevCartState = null;
        this._prevCartIds = [];
        // 🔥 Performance: original products grid HTML for instant search restore
        this._originalProductsHTML = null;
        // 🔥 Performance: polling pause state
        this._pollingPaused = false;

        // 🔥 Edit Products Tab State
        this.editProductsCurrentPage = 1;
        this.editProductsTotalPages = 1;
        this.editProductsPerPage = 100;
        this.editProductsSearchTerm = '';
        this.editProductsSearchTimeout = null;
        this.editProductsData = [];
        this.editedProductIds = [];
        this.editProductsSuppliers = [];
        this.customersManagementList = [];

        // Initialize BroadcastChannel for real-time cross-tab communication
        this.initBroadcastChannel();
        
        // Listen for page visibility changes to re-sync
        document.addEventListener('visibilitychange', () => {
            if (!document.hidden && this.broadcastChannel) {
                // Re-broadcast current state when page becomes visible
                this.broadcastUpdate('cart_updated', {
                    cart: this.cart,
                    pointsDiscount: this.pendingPointsDiscount || null
                });
            }
        });
        
        this.init();
    }
    
    initBroadcastChannel() {
        // Check if BroadcastChannel is supported
        if (typeof BroadcastChannel !== 'undefined') {
            try {
                this.broadcastChannel = new BroadcastChannel('ruiyi_pos_sync');
            } catch (e) {
                this.broadcastChannel = null;
            }
        } else {
            this.broadcastChannel = null;
        }
    }

    broadcastUpdate(type, data = {}) {
        // Broadcast via BroadcastChannel if available
        if (this.broadcastChannel) {
            try {
                this.broadcastChannel.postMessage({
                    type: type,
                    data: data,
                    timestamp: Date.now()
                });
            } catch (e) {
                // Silent error
            }
        }
        
        // Always update localStorage with timestamp as fallback
        const timestamp = Date.now();
        localStorage.setItem('ruiyi_pos_last_update', timestamp.toString());
        
        // Store specific update types
        if (type === 'cart_cleared') {
            localStorage.setItem('ruiyi_pos_cart_cleared', timestamp.toString());
        }
    }

    init() {
        // 🔥 Auto-refresh nonce on page load (fixes PWA cache nonce expiration issue)
        // 存储 Promise，让 ajaxRequest 等待 nonce 就绪后再发请求
        this.nonceReady = this.refreshNonceOnLoad();

        // 每30分钟主动刷新 nonce（nonce_life = YEAR_IN_SECONDS，无需频繁刷新）
        this.nonceRefreshInterval = setInterval(() => {
            this.refreshNonceOnLoad();
        }, 30 * 60 * 1000); // 30 minutes

        // Clear cart on page load/refresh
        this.cart = [];
        this.pendingPointsDiscount = null;
        this.pendingPointsReward = null;
        localStorage.removeItem('ruiyi_pos_cart');
        localStorage.removeItem('ruiyi_pos_points_discount');
        localStorage.setItem('ruiyi_pos_cart_cleared', Date.now().toString());
        
        // Broadcast initial clear event
        this.broadcastUpdate('cart_cleared', {
            cart: [],
            pointsDiscount: null
        });

        // 🔥 最高优先级：F6快速添加弹窗 — 键盘焦点完全锁定在弹窗内
        // 注册在 window（而非 document）上的 capture 阶段，确保比所有 document 级处理器更早执行
        // 处理：空格键导航、Enter下拉选择、上下键下拉导航、所有字符输入保护
        window.addEventListener('keydown', (e) => {
            // 检查F6弹窗是否打开
            const quickAddModal = document.getElementById('quick-add-product-modal');
            if (!quickAddModal || quickAddModal.classList.contains('hidden')) return;

            // 放行功能键和Escape（让全局处理器处理）
            if (/^F\d+$/.test(e.key) || e.key === 'Escape') return;

            const ae = document.activeElement;
            const isModalInput = ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA') && quickAddModal.contains(ae);

            if (isModalInput) {
                // 🔥 F6弹窗输入框字段顺序
                const fieldIds = [
                    'quick-product-number',
                    'quick-product-name',
                    'quick-product-sku',
                    'quick-product-price',
                    'quick-product-quantity'
                ];
                const currentIndex = fieldIds.indexOf(ae.id);

                // 🔥 产品名称自动补全下拉列表：Enter/上下键/Escape 交给autocomplete处理
                if (ae.id === 'quick-product-name') {
                    const acDD = document.getElementById('quick-product-name-suggestions');
                    if (acDD && !acDD.classList.contains('hidden')) {
                        if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Enter' || e.key === 'Escape') {
                            return; // 放行给autocomplete的keydown handler
                        }
                    }
                }

                // 🔥 Enter键：下拉列表选择 / 跳到下一个输入框 / 最后一个字段添加购物车
                if (e.key === 'Enter') {
                    e.preventDefault();
                    e.stopImmediatePropagation();

                    // 产品编号输入框：如果下拉列表可见，优先选择高亮项
                    if (ae.id === 'quick-product-number' && window.pos) {
                        const dd = document.getElementById('quick-product-dropdown');
                        if (dd && !dd.classList.contains('hidden') && window.pos._quickSearchResults && window.pos._quickSearchResults.length > 0) {
                            window.pos.selectQuickProduct(window.pos._quickSearchSelectedIndex || 0);
                            return;
                        }
                    }

                    // 最后一个字段（数量）→ 添加购物车
                    if (currentIndex === fieldIds.length - 1) {
                        if (window.pos && typeof window.pos.addQuickProductToCart === 'function') {
                            window.pos.addQuickProductToCart();
                        }
                        return;
                    }

                    // 其他字段：跳到下一个输入框
                    if (currentIndex >= 0) {
                        const nextField = document.getElementById(fieldIds[currentIndex + 1]);
                        if (nextField) {
                            nextField.focus();
                            nextField.select();
                        }
                    }
                    return;
                }

                // 🔥 上下键：产品编号下拉列表导航
                if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && ae.id === 'quick-product-number' && window.pos) {
                    const dd = document.getElementById('quick-product-dropdown');
                    if (dd && !dd.classList.contains('hidden') && window.pos._quickSearchResults && window.pos._quickSearchResults.length > 0) {
                        e.preventDefault();
                        e.stopImmediatePropagation();
                        const items = dd.querySelectorAll('.quick-product-dropdown-item');
                        let idx = window.pos._quickSearchSelectedIndex || 0;
                        if (e.key === 'ArrowDown') { idx = (idx + 1) % items.length; }
                        else { idx = (idx - 1 + items.length) % items.length; }
                        window.pos._quickSearchSelectedIndex = idx;
                        items.forEach((item, i) => { item.classList.toggle('bg-green-50', i === idx); });
                        items[idx]?.scrollIntoView({ block: 'nearest' });
                        return;
                    }
                }

                // 🔥 所有其他键：阻止全局处理器，让字符正常输入
                e.stopImmediatePropagation();
                return;
            }

            // 弹窗打开但焦点不在输入框（如点了弹窗空白处）→ 自动聚焦到第一个输入框
            const firstInput = quickAddModal.querySelector('input:not([type="hidden"])');
            if (firstInput) {
                e.stopImmediatePropagation();
                firstInput.focus();
            }
        }, true); // capture 阶段，window 级别，优先级最高

        // 在捕获阶段拦截F5、F6和F7键，阻止浏览器默认行为
        document.addEventListener('keydown', (e) => {
            if (e.key === 'F5') {
                e.preventDefault();
                e.stopPropagation();
                e.stopImmediatePropagation();
                this.showAddProductModal();
            }
            // 🔥 F6 - 快速添加产品弹窗
            else if (e.key === 'F6') {
                e.preventDefault();
                e.stopPropagation();
                e.stopImmediatePropagation();
                console.log('[POS Capture] F6 - 打开快速添加产品弹窗');
                this.showQuickAddProductModal();
                return;
            }
            // 🔥 F7, F9 - 已禁用，不执行任何操作
            else if (e.key === 'F7' || e.key === 'F9') {
                return;
            }
            // 🔥 F8 - 进入/退出退货模式（固定数量 -1，直接扫描条形码即可）
            else if (e.key === 'F8') {
                e.preventDefault();
                e.stopPropagation();
                e.stopImmediatePropagation();
                if (this.returnQuantity < 0) {
                    // 已在退货模式，按F8取消
                    this.returnQuantity = 0;
                    this.showReturnModeIndicator(false);
                } else {
                    // 进入退货模式（固定 -1）
                    this.returnQuantity = -1;
                    this.showReturnModeIndicator(true);
                }
                return;
            }
        }, true); // 🔥 使用捕获阶段（优先级最高）

        this.bindEvents();
        this.updateTime();
        this.updateCart();

        // 🔥 Performance: capture original products grid HTML for instant search restore
        requestAnimationFrame(() => {
            const grid = document.getElementById('products-grid');
            if (grid) this._originalProductsHTML = grid.innerHTML;
        });
        this.updateHeldOrdersCount();
        this.cleanupOldHeldOrders();
        this.initKeyboardShortcuts();
        this.initCustomShortcuts(); // 初始化自定义快捷键显示
        this.initVariosQuickInput(); // 初始化Varios快捷输入
        this.initProductNameAutocomplete('product-name');
        this.initProductNameAutocomplete('settings-product-name');
        this.initProductNameAutocomplete('quick-product-name');
        this.initScaleIntegration();

        // 🔥 初始化工具箱可见性设置
        if (ruiyi_pos_ajax.toolbox_settings) {
            this.applyToolboxVisibility(ruiyi_pos_ajax.toolbox_settings);
        }

        // 🔥 恢复默认聚焦到Varios输入框 - 确保扫描器随时可用
        setTimeout(() => {
            const variosInput = document.getElementById('varios-price-input');
            if (variosInput) {
                variosInput.focus();

                // 🔥 添加blur事件监听 - 焦点丢失时自动恢复（无弹窗时）
                variosInput.addEventListener('blur', () => {
                    // 延迟检查，避免干扰正常的焦点切换（如打开弹窗）
                    // 增加到300ms确保弹窗有足够时间完全打开
                    setTimeout(() => {
                        // 🔥 使用shouldFocusVarios()统一判断是否应该恢复焦点
                        // 这会检查所有弹窗状态，而不仅仅是退货弹窗
                        if (this.shouldFocusVarios()) {
                            this.focusVariosInput();
                        }
                    }, 300);
                });
            }
        }, 200);

        // Update time every second (store ID for cleanup)
        this.intervalIds.push(setInterval(() => this.updateTime(), 1000));

        // Cleanup old held orders every hour (store ID for cleanup)
        this.intervalIds.push(setInterval(() => this.cleanupOldHeldOrders(), 3600000));

        // 🔥 Initialize midnight auto daily settlement check
        this.initMidnightSettlementCheck();

        // 🔥 Initialize page close auto-save feature (页面关闭时自动保存日结单)
        this.initPageCloseAutoSave();

        // 🔥 Cleanup intervals on page unload to prevent memory leaks
        window.addEventListener('beforeunload', () => this.cleanup());
        window.addEventListener('pagehide', () => this.cleanup());

        // 🔥 Performance: pause polling when tab is hidden, resume when visible
        document.addEventListener('visibilitychange', () => {
            if (document.hidden) {
                this.intervalIds.forEach(id => clearInterval(id));
                this.intervalIds = [];
                if (this.nonceRefreshInterval) {
                    clearInterval(this.nonceRefreshInterval);
                    this.nonceRefreshInterval = null;
                }
                this._pollingPaused = true;
            } else if (this._pollingPaused) {
                this._pollingPaused = false;
                this.refreshNonceOnLoad();
                this.checkDateChangeAndAutoSave();
                this.nonceRefreshInterval = setInterval(() => this.refreshNonceOnLoad(), 30 * 60 * 1000);
                this.intervalIds.push(setInterval(() => this.updateTime(), 1000));
                this.intervalIds.push(setInterval(() => this.cleanupOldHeldOrders(), 3600000));
                this.intervalIds.push(setInterval(() => this.checkDateChangeAndAutoSave(), 300000));
            }
        });
    }

    // 🔥 Cleanup method to clear all intervals and prevent memory leaks
    cleanup() {
        this.intervalIds.forEach(id => clearInterval(id));
        this.intervalIds = [];

        // Close BroadcastChannel if exists
        if (this.broadcastChannel) {
            try {
                this.broadcastChannel.close();
            } catch (e) {}
        }

        // Disconnect scale socket if exists
        if (this.scaleSocket && typeof this.scaleSocket.disconnect === 'function') {
            try {
                this.scaleSocket.disconnect();
            } catch (e) {}
        }
    }

    /**
     * 🔥 Refresh nonce on page load to fix PWA cache nonce expiration issue
     * When the page is loaded from Service Worker cache, the embedded nonce may be expired.
     * This method fetches a fresh nonce from the server.
     */
    refreshNonceOnLoad() {
        // Only refresh if we're online
        if (!navigator.onLine) {
            console.log('[POS] Offline - skipping nonce refresh');
            return Promise.resolve();
        }

        return fetch(ruiyi_pos_ajax.ajax_url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            credentials: 'same-origin',
            body: new URLSearchParams({
                action: 'ruiyi_pos_ajax',
                pos_action: 'refresh_nonce'
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.success && data.data.nonce) {
                ruiyi_pos_ajax.nonce = data.data.nonce;
                // 同步更新 pointsConfig 的 nonce，避免积分系统调用失败
                if (typeof pointsConfig !== 'undefined') {
                    pointsConfig.nonce = data.data.nonce;
                }
                console.log('[POS] Nonce refreshed successfully');
            }
        })
        .catch(error => {
            console.log('[POS] Nonce refresh failed (using cached):', error.message);
        });
    }

    /**
     * 🔥 Helper method to make AJAX requests with automatic nonce refresh on expiration
     * @param {Object} params - Request parameters (must include pos_action)
     * @param {Object} options - Optional fetch options
     * @returns {Promise} - Promise resolving to JSON response
     */
    async ajaxRequest(params, options = {}) {
        // 等待页面加载时的 nonce 刷新完成，避免用过期 nonce 发请求
        if (this.nonceReady) {
            await this.nonceReady;
        }
        const makeRequest = async (retryWithNewNonce = false) => {
            const formData = new URLSearchParams({
                action: 'ruiyi_pos_ajax',
                nonce: ruiyi_pos_ajax.nonce,
                ...params
            });

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                credentials: 'same-origin',
                body: formData,
                ...options
            });

            const data = await response.json();

            // If nonce expired and this is the first attempt, try refreshing nonce
            if (!data.success && data.data && data.data.code === 'nonce_expired' && !retryWithNewNonce) {
                console.log('[POS] Nonce expired, attempting refresh...');

                // Try to refresh nonce
                const refreshResponse = await fetch(ruiyi_pos_ajax.ajax_url, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    credentials: 'same-origin',
                    body: new URLSearchParams({
                        action: 'ruiyi_pos_ajax',
                        pos_action: 'refresh_nonce'
                    })
                });

                const refreshData = await refreshResponse.json();

                if (refreshData.success && refreshData.data.nonce) {
                    ruiyi_pos_ajax.nonce = refreshData.data.nonce;
                    console.log('[POS] Nonce refreshed, retrying request...');
                    // Retry the original request with new nonce
                    return makeRequest(true);
                }

                // 🔥 Nonce 刷新失败：检查是否因为用户已登出
                if (!refreshData.success && refreshData.data &&
                    (refreshData.data.code === 'not_logged_in' || refreshData.data.code === 'unauthorized')) {
                    console.error('[POS] Session expired - redirecting to login');
                    window.location.href = '<?php echo esc_url(home_url("/pos-login/")); ?>';
                    return data;
                }
            }

            // 🔥 直接检测未登录响应（非 nonce 相关的 AJAX 请求）
            if (!data.success && data.data &&
                (data.data.code === 'not_logged_in' || data.data.code === 'unauthorized')) {
                console.error('[POS] Not logged in - redirecting to login');
                window.location.href = '<?php echo esc_url(home_url("/pos-login/")); ?>';
                return data;
            }

            return data;
        };

        return makeRequest();
    }

    // 🔥 Get cached DOM element (Phase 2 optimization)
    getElement(id) {
        if (!this.domCache[id]) {
            this.domCache[id] = document.getElementById(id);
        }
        return this.domCache[id];
    }

    // 🔥 Clear DOM cache (call when DOM structure changes significantly)
    clearDomCache() {
        this.domCache = {};
    }

    initScaleIntegration(retryCount = 0) {
        const MAX_RETRIES = 5;
        const RETRY_DELAY = 500; // ms

        if (!this.scaleConfig.enabled) {
            this.updateScaleConnectionUI('disabled');
            return;
        }

        // Wait for Socket.IO to load (CDN may take time)
        if (typeof io === 'undefined') {
            if (retryCount < MAX_RETRIES) {
                setTimeout(() => this.initScaleIntegration(retryCount + 1), RETRY_DELAY);
                return;
            }
            // After max retries, disable scale integration
            this.updateScaleConnectionUI('disabled');
            return;
        }

        this.connectScaleSocket();
    }

    connectScaleSocket() {
        if (!this.scaleConfig.socket_url) {
            this.updateScaleConnectionUI('error', { message: 'Scale socket URL not configured' });
            return;
        }

        try {
            if (this.scaleSocket && typeof this.scaleSocket.disconnect === 'function') {
                this.scaleSocket.disconnect();
            }

            this.updateScaleConnectionUI('connecting');

        const query = Object.assign({}, this.scaleConfig.query || {}, {
            clientType: this.scaleConfig.client_type || 'pos',
            location: this.scaleConfig.location || 'default'
        });

        const socketOptions = {
            transports: ['websocket'],
            reconnection: true,
            reconnectionAttempts: Infinity,
            reconnectionDelay: this.scaleConfig.retry_ms || 2000,
            path: this.scaleConfig.socket_path || '/socket.io',
            query
        };

        if (this.scaleConfig.auth_token) {
            socketOptions.auth = Object.assign({}, this.scaleConfig.auth || {}, {
                token: this.scaleConfig.auth_token
            });
        }

        this.scaleSocket = io(this.scaleConfig.socket_url, socketOptions);
        } catch (error) {
            this.updateScaleConnectionUI('error', { message: error.message || 'Scale socket error' });
            return;
        }

        this.scaleSocket.on('connect', () => {
            // Scale connected
            this.scaleState.connected = true;
            this.handleScaleStatus({ status: 'connected' });
            this.clearScaleError();
        });

        this.scaleSocket.on('disconnect', (reason) => {
            console.warn('[Scale] Socket disconnected:', reason);
            this.scaleState.connected = false;
            this.handleScaleStatus({ status: 'disconnected', reason });
        });

        this.scaleSocket.on('connect_error', (error) => {
            console.error('[Scale] Socket connection error:', error);
            this.handleScaleError({ message: error.message || 'Connection error' });
        });

        if (this.scaleSocket.io) {
            this.scaleSocket.io.on('reconnect_attempt', () => {
                this.handleScaleStatus({ status: 'connecting' });
            });
        }

        this.scaleSocket.on('scale:status', (payload) => this.handleScaleStatus(payload));
        this.scaleSocket.on('scale:weight', (payload) => this.handleScaleWeight(payload));
        this.scaleSocket.on('scale:error', (payload) => this.handleScaleError(payload));
    }

    handleScaleStatus(payload = {}) {
        const status = payload.status || (this.scaleState.connected ? 'connected' : 'disconnected');
        if (payload.unit) {
            this.scaleState.unit = payload.unit;
        }
        this.scaleState.status = status;
        this.updateScaleConnectionUI(status, payload);
    }

    handleScaleWeight(payload = {}) {
        const weightCandidate = payload.weight !== undefined ? payload.weight : payload.value;
        const parsedWeight = weightCandidate !== undefined ? Number.parseFloat(weightCandidate) : null;

        if (payload.unit) {
            this.scaleState.unit = payload.unit;
        }

        if (parsedWeight === null || Number.isNaN(parsedWeight)) {
            console.warn('[Scale] Invalid weight payload:', payload);
            return;
        }

        this.scaleState.latestWeight = parsedWeight;
        this.scaleState.lastUpdatedAt = payload.timestamp ? Number(payload.timestamp) : Date.now();

        if (this.scaleConfig.debug) {
            // Weight received
        }

        this.clearScaleError();
        this.updateScaleDisplay();
    }

    handleScaleError(payload = {}) {
        const message = payload.message || posTranslations['Scale error detected'] || 'Scale error detected';
        this.scaleState.lastError = { message, timestamp: Date.now() };
        this.updateScaleConnectionUI('error', payload);
        this.updateScaleErrorBanner(message);
    }

    clearScaleError() {
        this.scaleState.lastError = null;
        this.updateScaleErrorBanner(null);
    }

    /**
     * Send VFD display command via socket
     * @param {string} text - Text to display on VFD
     * @param {boolean} clearFirst - Whether to clear display before showing text
     */
    sendVFDDisplay(text, clearFirst = false) {
        if (!this.scaleSocket || !this.scaleSocket.connected) {
            if (this.scaleConfig.debug) {
                // VFD Socket not connected
            }
            return;
        }

        try {
            if (clearFirst) {
                this.scaleSocket.emit('vfd:clear');
            }
            this.scaleSocket.emit('vfd:display', {
                text: String(text || '').substring(0, 20), // Limit to 20 characters
                timestamp: Date.now()
            });
            if (this.scaleConfig.debug) {
                // VFD display sent
            }
        } catch (error) {
            console.error('[VFD] Error sending display command:', error);
        }
    }

    updateScaleErrorBanner(message) {
        const errorBanner = document.getElementById('scale-error-banner');
        if (!errorBanner) return;

        if (message) {
            errorBanner.textContent = message;
            errorBanner.classList.remove('hidden');
        } else {
            errorBanner.classList.add('hidden');
            errorBanner.textContent = posTranslations['Scale error detected'] || 'Scale error detected';
        }
    }

    updateScaleConnectionUI(status, payload = {}) {
        const statusText = document.getElementById('scale-connection-text');
        const statusDot = document.getElementById('scale-connection-dot');
        const card = document.getElementById('scale-status-card');

        let label;
        switch (status) {
            case 'connected':
                label = posTranslations['Connected'] || 'Connected';
                break;
            case 'connecting':
                label = posTranslations['Connecting'] || 'Connecting';
                break;
            case 'disabled':
                label = posTranslations['Disabled'] || 'Disabled';
                break;
            case 'error':
                label = posTranslations['Scale error detected'] || 'Scale error detected';
                break;
            default:
                label = posTranslations['Disconnected'] || 'Disconnected';
        }

        if (statusText) {
            statusText.textContent = label;
        }

        if (statusDot) {
            statusDot.className = `status-dot ${status}`;
        }

        if (card) {
            card.classList.toggle('stale', this.isWeightReadingStale());
        }

        if (status !== 'error') {
            this.clearScaleError();
        } else if (payload.message) {
            this.updateScaleErrorBanner(payload.message);
        }
    }

    updateScaleDisplay() {
        const weightDisplay = document.getElementById('scale-weight-display');
        const lastUpdatedEl = document.getElementById('scale-last-updated');
        const pricePreviewEl = document.getElementById('scale-price-preview');
        const card = document.getElementById('scale-status-card');
        const weight = this.scaleState.latestWeight;
        const isStale = this.isWeightReadingStale();
        const unit = this.scaleState.unit || this.scaleConfig.weight_unit || 'kg';

        if (card) {
            card.classList.toggle('stale', isStale || weight === null);
        }

        if (weightDisplay) {
            weightDisplay.textContent = weight !== null
                ? this.formatWeight(weight)
                : `--.-- ${unit}`;
        }

        if (lastUpdatedEl) {
            const label = posTranslations['Last update label'] || 'Last update';
            if (weight !== null) {
                const timestamp = this.scaleState.lastUpdatedAt || Date.now();
                const formatted = new Date(timestamp).toLocaleTimeString();
                const staleNote = isStale ? ` (${posTranslations['Weight reading stale'] || 'stale'})` : '';
                lastUpdatedEl.textContent = `${label}: ${formatted}${staleNote}`;
            } else {
                lastUpdatedEl.textContent = `${label}: —`;
            }
        }

        if (pricePreviewEl) {
            const preview = this.scaleState.preview;
            if (preview && weight !== null && !isStale) {
                const totalPrice = this.calculateWeightPrice(preview, weight);
                const productName = preview.productName ? ` • ${preview.productName}` : '';
                pricePreviewEl.textContent = `${ruiyi_pos_ajax.currency}${totalPrice.toFixed(2)}${productName}`;
            } else if (preview && isStale) {
                pricePreviewEl.textContent = posTranslations['Weight reading stale'] || 'Weight reading stale';
            } else {
                pricePreviewEl.textContent = posTranslations['Awaiting product selection'] || 'Awaiting product selection';
            }
        }
    }

    setScalePreview(preview) {
        if (preview) {
            this.scaleState.preview = preview;
        } else {
            this.scaleState.preview = null;
        }
        this.updateScaleDisplay();
    }

    getCurrentWeight() {
        if (!this.scaleConfig.enabled) {
            return null;
        }

        const weight = this.scaleState.latestWeight;
        if (weight === null || Number.isNaN(weight)) {
            return null;
        }

        if (this.isWeightReadingStale()) {
            return null;
        }

        if (this.scaleConfig.min_weight_kg && Math.abs(weight) < this.scaleConfig.min_weight_kg) {
            return null;
        }

        return weight;
    }

    isWeightReadingStale() {
        if (!this.scaleConfig.enabled) {
            return true;
        }

        if (!this.scaleState.lastUpdatedAt) {
            return true;
        }

        const threshold = this.scaleConfig.stale_after_ms || 5000;
        return Date.now() - this.scaleState.lastUpdatedAt > threshold;
    }

    formatWeight(weight) {
        const precision = Number.isInteger(this.scaleConfig.precision) ? this.scaleConfig.precision : 3;
        const unit = this.scaleState.unit || this.scaleConfig.weight_unit || 'kg';
        return `${Number.parseFloat(weight).toFixed(precision)} ${unit}`;
    }

    calculateWeightPrice(weightInfo, weight) {
        const unitPrice = weightInfo?.unit_price_per_kg ?? weightInfo?.unitPricePerKg ?? 0;
        const total = unitPrice * weight;
        const formatted = Number.parseFloat(total.toFixed(2));
        return Number.isFinite(formatted) ? formatted : 0;
    }

    ensureProductWeightData(product) {
        if (!this.scaleConfig.enabled || !product || !product.id) {
            return Promise.resolve(product);
        }

        if (product.weightPricingLoaded) {
            return Promise.resolve(product);
        }

        const cachedMeta = this.weightMetaCache.get(product.id);
        if (cachedMeta) {
            product.weightPricing = cachedMeta;
            product.weightPricingLoaded = true;
            if (cachedMeta.is_weight_product) {
                this.setScalePreview({
                    productId: product.id,
                    productName: product.name,
                    unit_price_per_kg: cachedMeta.unit_price_per_kg,
                    weight_unit: cachedMeta.weight_unit || this.scaleState.unit || 'kg'
                });
            } else {
                this.setScalePreview(null);
            }
            return Promise.resolve(product);
        }

        if (this.pendingWeightRequests.has(product.id)) {
            return this.pendingWeightRequests.get(product.id).then(() => {
                const meta = this.weightMetaCache.get(product.id) || { is_weight_product: false };
                product.weightPricing = meta;
                product.weightPricingLoaded = true;
                return product;
            });
        }

        const doWeightFetch = (retried = false) => {
            return fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_product_weight_meta',
                    nonce: ruiyi_pos_ajax.nonce,
                    product_id: product.id
                })
            })
                .then(response => response.json())
                .then(async data => {
                    // Nonce过期时自动刷新并重试一次
                    if (!data.success && data.data && data.data.code === 'nonce_expired' && !retried) {
                        await this.refreshNonceOnLoad();
                        return doWeightFetch(true);
                    }
                    if (data.success && data.data) {
                        const meta = data.data;
                        this.weightMetaCache.set(product.id, meta);
                        product.weightPricing = meta;
                        product.weightPricingLoaded = true;
                        if (meta.is_weight_product) {
                            this.setScalePreview({
                                productId: product.id,
                                productName: product.name,
                                unit_price_per_kg: meta.unit_price_per_kg,
                                weight_unit: meta.weight_unit || this.scaleState.unit || 'kg'
                            });
                        } else {
                            this.setScalePreview(null);
                        }
                        this.updateScaleCheckoutState();
                    } else {
                        product.weightPricing = { is_weight_product: false };
                        product.weightPricingLoaded = true;
                        this.setScalePreview(null);
                        this.updateScaleCheckoutState();
                    }
                    return product;
                })
                .catch(error => {
                    console.error('[Scale] AJAX error while fetching weight metadata:', error);
                    product.weightPricing = product.weightPricing || { is_weight_product: false };
                    product.weightPricingLoaded = true;
                    this.setScalePreview(null);
                    this.updateScaleCheckoutState();
                    return product;
                })
                .finally(() => {
                    this.pendingWeightRequests.delete(product.id);
                });
        };

        const request = doWeightFetch();

        this.pendingWeightRequests.set(product.id, request);
        return request;
    }

    cartContainsScaleProductAwaitingWeight() {
        return this.cart.some(item => item.weightBased && (!item.weightKg || item.weightKg <= 0));
    }

    updateScaleCheckoutState() {
        const checkoutBtn = document.getElementById('checkout-btn');
        const albaranBtn = document.getElementById('albaran-btn');
        if (!checkoutBtn) return;

        const hasPendingScaleProduct = this.cartContainsScaleProductAwaitingWeight();

        if (hasPendingScaleProduct) {
            checkoutBtn.disabled = true;
            checkoutBtn.classList.add('opacity-70', 'cursor-not-allowed');
            if (albaranBtn) {
                albaranBtn.disabled = true;
                albaranBtn.classList.add('opacity-70', 'cursor-not-allowed');
            }
        } else {
            checkoutBtn.disabled = this.cart.length === 0;
            if (albaranBtn) {
                albaranBtn.disabled = this.cart.length === 0;
            }
            if (this.cart.length > 0) {
                checkoutBtn.classList.remove('opacity-70', 'cursor-not-allowed');
                if (albaranBtn) {
                    albaranBtn.classList.remove('opacity-70', 'cursor-not-allowed');
                }
            }
        }
    }

    bindEvents() {
        // Global keyboard shortcuts
        document.addEventListener('keydown', (e) => {
            // 禁用Backspace键功能（在非输入框中）
            if (e.key === 'Backspace') {
                // 只在输入框中允许Backspace（正常删除字符）
                const activeElement = document.activeElement;
                const isInputField = activeElement && (
                    activeElement.tagName === 'INPUT' ||
                    activeElement.tagName === 'TEXTAREA'
                );

                if (isInputField) {
                    // 在输入框中允许正常删除
                    return;
                } else {
                    // 不在输入框中，完全阻止Backspace功能
                    e.preventDefault();
                    e.stopPropagation();
                    e.stopImmediatePropagation();
                    return;
                }
            }

            // 🔥 最高优先级1：数字键自动聚焦到Varios输入框（无论焦点在哪里）
            if (/^[0-9.]$/.test(e.key)) {

                const activeElement = document.activeElement;

                // 🔥 关键修复：如果扫描器正在活动，不聚焦到Varios（让扫描器累积条码）
                if (window.isScannerActive) {
                    // 扫描器正在工作，不干扰，让全局扫描器处理
                    return;
                }

                // 🔥 如果退货弹窗打开，绝对不抢夺焦点
                if (window.isRefundModalOpen) {
                    return;
                }

                // 🔥 如果有任何弹窗打开，不触发自动聚焦（让弹窗的输入框正常工作）
                // 使用通用检测：z-50, z-[60], 或ID以-modal结尾的元素
                const anyModalOpen = Array.from(document.querySelectorAll('.fixed.z-50, .fixed.z-\\[60\\], [id$="-modal"]')).some(modal => {
                    return !modal.classList.contains('hidden');
                });

                if (anyModalOpen) {
                    // 有弹窗打开，允许正常输入到弹窗的输入框
                    return;
                }

                // 🔥 额外检查：如果焦点在弹窗内部，不抢夺焦点
                if (activeElement && activeElement.closest('[id$="-modal"]')) {
                    return;
                }

                // 如果已经在Varios输入框中，不做处理（让正常输入）
                if (activeElement && activeElement.id === 'varios-price-input') {
                    return;
                }

                // 如果在其他输入框，不自动聚焦（让用户正常输入）
                if (activeElement && (activeElement.tagName === 'INPUT' || activeElement.tagName === 'TEXTAREA')) {
                    return;
                }

                // 如果不在任何输入框且无弹窗，聚焦到Varios并输入
                const variosInput = document.getElementById('varios-price-input');
                if (variosInput) {
                    e.preventDefault();
                    variosInput.focus();

                    // 如果输入框为空，设置新值；否则追加
                    if (variosInput.value === '' || variosInput.value === '€0.00') {
                        variosInput.value = e.key;
                    } else {
                        variosInput.value += e.key;
                    }

                    // 触发input事件以确保任何监听器都能响应
                    variosInput.dispatchEvent(new Event('input', { bubbles: true }));
                }
                return;
            }

            // 🔥 最高优先级2：Delete/Supr键打开高级搜索（无论在哪里）
            if (e.key === 'Delete') {
                // 🔥 如果在输入框中，允许正常删除字符
                const delActiveEl = document.activeElement;
                if (delActiveEl && (delActiveEl.tagName === 'INPUT' || delActiveEl.tagName === 'TEXTAREA')) {
                    return;
                }
                e.preventDefault();
                e.stopPropagation();
                e.stopImmediatePropagation();
                try {
                    this.showProductSearchModal();
                } catch (error) {
                    console.error('[POS] Error opening product search:', error);
                    // Fallback: manually open modal
                    const modal = document.getElementById('product-search-modal');
                    if (modal) {
                        modal.classList.remove('hidden');
                        const input = document.getElementById('product-search-input');
                        if (input) {
                            setTimeout(() => input.focus(), 100);
                        }
                        if (this.loadInitialProducts) {
                            this.loadInitialProducts();
                        }
                    }
                }
                return;
            }
            
            // 🔥 F9 - 已禁用（在捕获阶段已处理）

            // 🔥 最高优先级3：+ 和 - 键用于Varios操作，不触发任何其他快捷键
            if (e.key === '+' || e.key === '=') {
                // 让 initKeyboardShortcuts() 中的监听器处理
                // 这里直接返回，不做任何处理
                return;
            }

            // 🔥 F8键：退货模式已在捕获阶段处理

            // 🔥 M键：在varios输入框有内容时触发产品编号搜索
            if (e.key === 'm' || e.key === 'M') {
                const activeEl = document.activeElement;
                const isVariosWithValue = activeEl &&
                    activeEl.id === 'varios-price-input' &&
                    activeEl.value.trim().length > 0;

                if (isVariosWithValue) {
                    e.preventDefault();
                }
                // 让 initKeyboardShortcuts() 中的监听器处理
                return;
            }

            // Don't trigger shortcuts when typing in input fields
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') {
                // Varios输入框特殊处理：允许Enter、Esc和M键
                if (e.target.id === 'varios-price-input') {
                    if (e.key === 'Enter' || e.key === 'Escape' || e.key === 'm' || e.key === 'M') {
                        // 这些键由专用处理器处理
                        return;
                    }
                    // 其他功能键（F1-F12等）仍然可以触发全局快捷键
                    if (/^F\d+$/.test(e.key)) {
                        // 允许功能键穿透
                    } else {
                        // 其他键不处理
                        return;
                    }
                }

                // Handle Enter key in product search modal
                if (e.key === 'Enter' && e.target.id === 'product-search-input') {
                    e.preventDefault();
                    this.handleProductSearchEnter();
                    return;
                }
                // Handle Escape key to close modals
                if (e.key === 'Escape') {
                    this.closeAllModals();
                    return;
                }
                // 其他输入框：阻止所有快捷键
                return;
            }

            // Handle keyboard shortcuts - Dynamic from settings
            const key = e.key;

            // 🔥 F5 键专用处理：打开创建产品弹窗（优先级最高，阻止页面刷新和其他冲突）
            if (key === 'F5') {
                e.preventDefault(); // 阻止浏览器默认的页面刷新
                e.stopPropagation(); // 阻止事件冒泡到其他监听器
                this.showAddProductModal();
                return;
            }

            // 🔥 数字键已在函数开始处理（第3065-3092行），这里不再需要处理
            // 避免重复执行

            // 🔥 Find product shortcut - 已禁用
            // 高级搜索现在只能通过以下方式触发：
            // 1. Delete/Supr键（无论焦点在哪里）- 第3065行处理
            // 2. 点击"高级搜索"按钮
            // 不再支持配置其他快捷键

            // 🔥 Complete sale shortcut - 只允许用户主动按Enter键触发
            // 条码扫描器的Enter键会在更早阶段被拦截（第5973行，使用捕获阶段）
            if (key === keyboardShortcuts.complete_sale && key !== 'F1') {
                // 🔥 关键修复：如果扫描器正在保护期，不触发结账
                if (window.isScannerActive) {
                    // 扫描器保护期内，忽略Enter键
                    e.preventDefault();
                    e.stopPropagation();
                    return;
                }

                e.preventDefault();
                if (!document.getElementById('checkout-btn').disabled) {
                    this.checkout();
                }
                return;
            }
            
            // Hold order shortcut
            if (key === keyboardShortcuts.hold_order) {
                e.preventDefault();
                if (!document.getElementById('hold-order-btn').disabled) {
                    this.showHoldOrderModal();
                }
                return;
            }
            
            // View held orders shortcut
            if (key === keyboardShortcuts.view_held_orders) {
                e.preventDefault();
                this.showHeldOrdersModal();
                return;
            }
            
            // Clear cart shortcut
            if (key === keyboardShortcuts.clear_cart) {
                if (this.cart.length > 0 && confirm(posTranslations['Cart cleared'] || 'Clear cart?')) {
                    e.preventDefault();
                    this.clearCart();
                }
                return;
            }
            
            // 🔥 F5键已在前面处理（第2901行），这里不再需要处理
            // 避免重复逻辑和冲突

            // Payment method shortcuts (excluding F5 which is handled above)
            if (key === keyboardShortcuts.payment_cash && key !== 'F5') {
                e.preventDefault();
                if (this.cart.length > 0) {
                    this.showCashPaymentModal();
                }
                return;
            }
            
            // 🔥 F6 - 快速添加产品（在捕获阶段已处理）
            if (key === 'F6') {
                e.preventDefault();
                e.stopPropagation();
                this.showQuickAddProductModal();
                return;
            }
            // 🔥 F7, F9 - 已禁用
            if (key === 'F7' || key === 'F9') {
                console.log('[POS BindEvents] ' + key + ' 键已禁用，不执行任何操作');
                return;
            }

            // 🔥 自定义快捷键：刷卡支付（在主界面直接触发结账→刷卡）
            const customCardKey = localStorage.getItem('ruiyi_pos_shortcut_payment_card');
            if (customCardKey && this._matchKeyCombo(e, customCardKey)) {
                // 仅在非弹窗状态下触发（支付弹窗内由 _paymentKeyHandler 处理）
                const paymentModal = document.getElementById('payment-method-modal');
                if (!paymentModal || paymentModal.classList.contains('hidden')) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (this.cart && this.cart.length > 0) {
                        this.processCreditCardPayment();
                    }
                    return;
                }
            }

            // 🔥 自定义快捷键：打印结账小票（支持组合键，如 PrintScreen、Ctrl+P 等）
            // 打开钱箱固定为 F1（已在其他 listener 硬编码），不走自定义
            const customPrintReceiptKey = localStorage.getItem('ruiyi_pos_shortcut_print_receipt');

            if (customPrintReceiptKey && this._matchKeyCombo(e, customPrintReceiptKey)) {
                e.preventDefault();
                e.stopPropagation();
                const printBtn = document.getElementById('print-last-order-btn-standalone');
                if (printBtn) printBtn.click();
                return;
            }

            // Fixed shortcuts
            switch(key) {
                // 🔥 Delete键已在函数开始处理（第3065行），这里不再需要处理
                // 🔥 Backspace键已移除 - 不再用于清空购物车
                case 'Escape':
                    e.preventDefault();
                    this.closeAllModals();
                    break;
                case '?':
                    // ? key opens keyboard shortcuts help
                    e.preventDefault();
                    this.showKeyboardShortcutsModal();
                    break;
            }
        });

        // 🔥 自定义快捷键 keyup 监听（PrintScreen 等特殊键在 Windows 11 只触发 keyup，不触发 keydown）
        document.addEventListener('keyup', (e) => {
            // 跳过 input/textarea 聚焦时
            const tag = document.activeElement?.tagName;
            if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;

            const customPrintReceiptKey = localStorage.getItem('ruiyi_pos_shortcut_print_receipt');
            if (customPrintReceiptKey && this._matchKeyCombo(e, customPrintReceiptKey)) {
                e.preventDefault();
                const printBtn = document.getElementById('print-last-order-btn-standalone');
                if (printBtn) printBtn.click();
            }
        });

        // 🔥 Keyboard Shortcuts Help Button
        const keyboardShortcutsHelpBtn = document.getElementById('keyboard-shortcuts-help-btn');
        if (keyboardShortcutsHelpBtn) {
            keyboardShortcutsHelpBtn.addEventListener('click', () => {
                this.showKeyboardShortcutsModal();
            });
        }

        // Note: Top navigation supplier and add product buttons have been moved to Settings modal
        // See openSettingsModal() and switchSettingsTab() for new implementation

        // 🔥 Find Product button - 已禁用点击功能
        // 高级搜索现在只能通过 Delete/Supr 键触发
        const findProductBtn = document.getElementById('find-product-btn');
        if (findProductBtn) {
            // 不再绑定点击事件，只能用Delete键触发
            findProductBtn.addEventListener('click', (e) => {
                e.preventDefault();
                this.showToast(posTranslations['Use Delete key for advanced search'] || 'Use Delete key for advanced search', 'info');
            });
        }

        // Product Search Modal events
        const productSearchModal = document.getElementById('product-search-modal');
        const productSearchInput = document.getElementById('product-search-input');
        const closeProductSearchBtn = document.getElementById('close-product-search-btn');

        if (closeProductSearchBtn) {
            closeProductSearchBtn.addEventListener('click', () => {
                this.closeProductSearchModal();
            });
        }

        if (productSearchInput) {
            productSearchInput.addEventListener('input', (e) => {
                const query = e.target.value.trim();
                clearTimeout(this.searchTimeout);
                this.searchTimeout = setTimeout(() => {
                    this.performProductSearch(query);
                }, 300);
            });
        }

        // 🔥 Product Not Found Confirm Modal events
        const createProductYesBtn = document.getElementById('create-product-yes-btn');
        const createProductNoBtn = document.getElementById('create-product-no-btn');

        if (createProductYesBtn) {
            createProductYesBtn.addEventListener('click', () => {
                this.confirmCreateProduct();
            });
        }

        if (createProductNoBtn) {
            createProductNoBtn.addEventListener('click', () => {
                this.closeProductNotFoundConfirm();
            });
        }

        // Add Product Modal events
        const addProductForm = document.getElementById('add-product-form');
        const closeAddProductBtn = document.getElementById('close-add-product-btn');

        if (closeAddProductBtn) {
            closeAddProductBtn.addEventListener('click', () => {
                this.closeAddProductModal();
            });
        }

        if (addProductForm) {
            addProductForm.addEventListener('submit', (e) => {
                e.preventDefault();
                this.handleAddProduct();
            });
        }

        // Customer Edit Form events
        const customerEditForm = document.getElementById('customer-edit-form');
        if (customerEditForm) {
            customerEditForm.addEventListener('submit', (e) => {
                this.saveCustomerManagement(e);
            });
        }

        // Product cards click events
        document.addEventListener('click', (e) => {
            const productCard = e.target.closest('.product-card');
            if (productCard) {
                try {
                    const productData = JSON.parse(productCard.dataset.product);
                    this.addToCart(productData);
                } catch (error) {
                    console.error('Error parsing product data:', error);
                    this.showToast(posTranslations['Product data error'] || 'Product data error', 'error');
                }
            }

            // Handle product search result clicks
            const searchResultItem = e.target.closest('.search-result-item');
            if (searchResultItem) {
                try {
                    const productData = JSON.parse(searchResultItem.dataset.product);
                    this.addToCart(productData);
                    this.closeProductSearchModal();
                    this.showToast(posTranslations['Product added to cart'] || 'Product added to cart', 'success');
                } catch (error) {
                    console.error('Error parsing search result product data:', error);
                    this.showToast(posTranslations['Product data error'] || 'Product data error', 'error');
                }
            }

            // 🔥 Event delegation for cart items (Phase 2 optimization)
            // Handles: select, quantity +/-, remove - instead of inline onclick handlers
            const cartItem = e.target.closest('.cart-item');
            if (cartItem) {
                const cartItemId = parseInt(cartItem.dataset.cartItemId);
                if (!isNaN(cartItemId)) {
                    // Check if clicked on a button or input
                    const button = e.target.closest('button');
                    const input = e.target.closest('input');

                    if (button) {
                        e.stopPropagation();
                        const action = button.dataset.action;
                        if (action === 'decrease') {
                            this.decreaseQuantityByCartItemId(cartItemId);
                        } else if (action === 'increase') {
                            this.increaseQuantityByCartItemId(cartItemId);
                        } else if (action === 'remove') {
                            this.removeFromCart(cartItemId, true);
                        }
                    } else if (!input) {
                        // Clicked on cart item itself (not button or input) - select it
                        this.selectCartItem(cartItemId);
                    }
                }
            }
        });

        // Search functionality
        const searchInput = document.getElementById('product-search');
        const clearSearchBtn = document.getElementById('clear-search-btn');
        
        if (searchInput) {
            searchInput.addEventListener('input', (e) => {
                const query = e.target.value.trim();
                
                // Show/hide clear button
                if (clearSearchBtn) {
                    clearSearchBtn.classList.toggle('hidden', query.length === 0);
                }
                
                clearTimeout(this.searchTimeout);
                this.searchTimeout = setTimeout(() => {
                    this.searchProducts(query);
                }, 300);
            });
            
            // Handle Enter key for immediate search
            searchInput.addEventListener('keypress', (e) => {
                if (e.key === 'Enter') {
                    clearTimeout(this.searchTimeout);
                    const query = e.target.value.trim();
                    
                    // Always use product search for display only
                    this.searchProducts(query);
                }
            });
        }
        
        // Clear search button
        if (clearSearchBtn) {
            clearSearchBtn.addEventListener('click', () => {
                if (searchInput) {
                    searchInput.value = '';
                    clearSearchBtn.classList.add('hidden');
                    this.clearSearch();
                }
            });
        }

        // Barcode scanner button
        const barcodeScannerBtn = document.getElementById('barcode-scanner-btn');
        if (barcodeScannerBtn) {
            barcodeScannerBtn.addEventListener('click', () => {
                this.activateBarcodeScanner();
            });
        }

        // Initialize global barcode scanner (works anywhere on the page)
        this.initGlobalBarcodeScanner();

        // Clear search results button
        const clearSearchResultsBtn = document.getElementById('clear-search-results-btn');
        if (clearSearchResultsBtn) {
            clearSearchResultsBtn.addEventListener('click', () => {
                this.clearSearch();
            });
        }

        // Clear cart
        const clearCartBtn = document.getElementById('clear-cart-btn');
        if (clearCartBtn) {
            clearCartBtn.addEventListener('click', () => {
                if (this.cart.length > 0 && confirm('Are you sure you want to clear the cart?')) {
                    this.clearCart();
                }
            });
        }

        
        // Checkout
        const checkoutBtn = document.getElementById('checkout-btn');
        if (checkoutBtn) {
            checkoutBtn.addEventListener('click', () => {
                this.checkout();
            });
        }

        // Albarán 预结单按钮
        const albaranBtn = document.getElementById('albaran-btn');
        if (albaranBtn) {
            albaranBtn.addEventListener('click', () => {
                this.createAlbaranOrder();
            });
        }

        // Modal buttons
        const newOrderBtn = document.getElementById('new-order-btn');
        if (newOrderBtn) {
            newOrderBtn.addEventListener('click', () => {
                this.newOrder();
            });
        }

        const printReceiptBtn = document.getElementById('print-receipt-btn');
        if (printReceiptBtn) {
            printReceiptBtn.addEventListener('click', () => {
                this.printReceipt();
            });
        }
        
        // Removed preview functionality

        // Payment method modal buttons
        const cashPaymentBtn = document.getElementById('cash-payment-btn');
        if (cashPaymentBtn) {
            cashPaymentBtn.addEventListener('click', () => {
                this.showCashPaymentModal();
            });
        }

        const cardPaymentBtn = document.getElementById('card-payment-btn');
        if (cardPaymentBtn) {
            cardPaymentBtn.addEventListener('click', () => {
                this.processCreditCardPayment();
            });
        }

        // Transfer payment button
        const transferPaymentBtn = document.getElementById('transfer-payment-btn');
        if (transferPaymentBtn) {
            transferPaymentBtn.addEventListener('click', () => {
                this.processTransferPayment();
            });
        }

        const pointsManagementBtn = document.getElementById('points-management-btn');
        if (pointsManagementBtn) {
            pointsManagementBtn.addEventListener('click', () => {
                this.showPointsManagementModal();
            });
        }

        const cancelPaymentBtn = document.getElementById('cancel-payment-btn');
        if (cancelPaymentBtn) {
            cancelPaymentBtn.addEventListener('click', () => {
                this.closePaymentMethodModal();
            });
        }

        // Cash payment modal
        const cashReceivedInput = document.getElementById('cash-received');
        if (cashReceivedInput) {
            cashReceivedInput.addEventListener('input', (e) => {
                this.calculateChange(e.target.value);
            });

            // 🔥 使用keydown替代keypress，并阻止事件传播，确保Enter键只触发确认支付
            cashReceivedInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    e.stopPropagation();
                    e.stopImmediatePropagation();
                    const confirmBtn = document.getElementById('confirm-cash-btn');
                    if (confirmBtn && !confirmBtn.disabled) {
                        confirmBtn.click();
                    }
                }
            });
        }

        const confirmCashBtn = document.getElementById('confirm-cash-btn');
        if (confirmCashBtn) {
            confirmCashBtn.addEventListener('click', () => {
                this.processCashPayment();
            });
        }

        const cancelCashBtn = document.getElementById('cancel-cash-btn');
        if (cancelCashBtn) {
            cancelCashBtn.addEventListener('click', () => {
                this.closeCashPaymentModal();
                this.showPaymentMethodModal();
            });
        }

        // Mixed payment modal
        const mixedCashInput = document.getElementById('mixed-cash-amount');
        const mixedCardInput = document.getElementById('mixed-card-amount');

        if (mixedCashInput) {
            mixedCashInput.addEventListener('input', (e) => {
                this.calculateMixedPayment();
            });
            // 🔥 Enter 键完成混合支付
            mixedCashInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    const confirmBtn = document.getElementById('confirm-mixed-btn');
                    if (confirmBtn && !confirmBtn.disabled) {
                        this.processMixedPayment();
                    }
                }
            });
        }

        if (mixedCardInput) {
            mixedCardInput.addEventListener('input', (e) => {
                this.calculateMixedPayment();
            });
            // 🔥 Enter 键完成混合支付
            mixedCardInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    const confirmBtn = document.getElementById('confirm-mixed-btn');
                    if (confirmBtn && !confirmBtn.disabled) {
                        this.processMixedPayment();
                    }
                }
            });
        }

        const confirmMixedBtn = document.getElementById('confirm-mixed-btn');
        if (confirmMixedBtn) {
            confirmMixedBtn.addEventListener('click', () => {
                this.processMixedPayment();
            });
        }

        const cancelMixedBtn = document.getElementById('cancel-mixed-btn');
        if (cancelMixedBtn) {
            cancelMixedBtn.addEventListener('click', () => {
                this.closeMixedPaymentModal();
                this.showPaymentMethodModal();
            });
        }

        // Mixed payment button
        const mixedPaymentBtn = document.getElementById('mixed-payment-btn');
        if (mixedPaymentBtn) {
            mixedPaymentBtn.addEventListener('click', () => {
                this.showMixedPaymentModal();
            });
        }

        // Customer information button
        const customerInfoBtn = document.getElementById('customer-info-btn');
        if (customerInfoBtn) {
            customerInfoBtn.addEventListener('click', () => {
                this.showCustomerInfoModal();
            });
        }

        // Customer information modal buttons
        const saveCustomerInfoBtn = document.getElementById('save-customer-info-btn');
        if (saveCustomerInfoBtn) {
            saveCustomerInfoBtn.addEventListener('click', () => {
                this.saveCustomerInfo();
            });
        }

        const cancelCustomerInfoBtn = document.getElementById('cancel-customer-info-btn');
        if (cancelCustomerInfoBtn) {
            cancelCustomerInfoBtn.addEventListener('click', () => {
                const wasOrderInvoice = !!this._invoiceOrderId;
                this.closeCustomerInfoModal();
                if (!wasOrderInvoice) {
                    this.showPaymentMethodModal();
                }
            });
        }

        // Hold order functionality
        const holdOrderBtn = document.getElementById('hold-order-btn');
        if (holdOrderBtn) {
            holdOrderBtn.addEventListener('click', () => {
                this.showHoldOrderModal();
            });
        }

        const viewHeldOrdersBtn = document.getElementById('view-held-orders-btn');
        if (viewHeldOrdersBtn) {
            viewHeldOrdersBtn.addEventListener('click', () => {
                this.showHeldOrdersModal();
            });
        }

        // Toolbox dropdown functionality
        const toolboxBtn = document.getElementById('toolbox-btn');
        const toolboxDropdown = document.getElementById('toolbox-dropdown');
        if (toolboxBtn && toolboxDropdown) {
            toolboxBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                toolboxDropdown.classList.toggle('hidden');
            });

            // Close dropdown when clicking outside
            document.addEventListener('click', (e) => {
                if (!toolboxBtn.contains(e.target) && !toolboxDropdown.contains(e.target)) {
                    toolboxDropdown.classList.add('hidden');
                }
            });

            // Close settings tab dropdowns when clicking outside
            document.addEventListener('click', (e) => {
                if (!e.target.closest('.settings-tab-group-btn') && !e.target.closest('[id^="settings-dropdown-"]')) {
                    pos.closeAllSettingsDropdowns();
                }
            });

            // Close dropdown after clicking any option inside
            const dropdownButtons = toolboxDropdown.querySelectorAll('button');
            dropdownButtons.forEach(btn => {
                btn.addEventListener('click', () => {
                    toolboxDropdown.classList.add('hidden');
                });
            });
        }

        // Print Last Order functionality (dropdown button)
        const printLastOrderBtn = document.getElementById('print-last-order-btn');
        if (printLastOrderBtn) {
            printLastOrderBtn.addEventListener('click', () => {
                this.printLastOrder();
            });
        }

        // Print Last Order functionality (standalone button)
        const printLastOrderBtnStandalone = document.getElementById('print-last-order-btn-standalone');
        if (printLastOrderBtnStandalone) {
            printLastOrderBtnStandalone.addEventListener('click', () => {
                this.printLastOrder();
            });
        }

        // Hold order modal
        const holdOrderReferenceInput = document.getElementById('hold-order-reference');
        if (holdOrderReferenceInput) {
            holdOrderReferenceInput.addEventListener('input', (e) => {
                this.validateHoldOrderForm();
            });
        }

        const confirmHoldBtn = document.getElementById('confirm-hold-btn');
        if (confirmHoldBtn) {
            confirmHoldBtn.addEventListener('click', () => {
                this.confirmHoldOrder();
            });
        }

        const cancelHoldBtn = document.getElementById('cancel-hold-btn');
        if (cancelHoldBtn) {
            cancelHoldBtn.addEventListener('click', () => {
                this.closeHoldOrderModal();
            });
        }

        // Held orders modal
        const closeHeldOrdersBtn = document.getElementById('close-held-orders-btn');
        if (closeHeldOrdersBtn) {
            closeHeldOrdersBtn.addEventListener('click', () => {
                this.closeHeldOrdersModal();
            });
        }

        // Keyboard shortcuts
        document.addEventListener('keydown', (e) => {
            if (e.key === 'F1') {
                e.preventDefault();
                // F1 = Open Cash Drawer
                const cashDrawerBtn = document.querySelector('[data-action="open-cash-drawer"]');
                if (cashDrawerBtn) cashDrawerBtn.click();
            } else if (e.key === 'Enter' && e.ctrlKey) {
                e.preventDefault();
                const checkoutBtn = document.getElementById('checkout-btn');
                if (checkoutBtn && !checkoutBtn.disabled) {
                    this.checkout();
                }
            } else if (e.key === 'Escape') {
                this.closeModal();
            }
        });

        // 🔥 Zero Price Modal Events
        const zeroPriceInput = document.getElementById('zero-price-input');
        const confirmZeroPriceBtn = document.getElementById('confirm-zero-price-btn');
        const cancelZeroPriceBtn = document.getElementById('cancel-zero-price-btn');

        if (zeroPriceInput) {
            // Enter key to confirm
            zeroPriceInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    e.stopPropagation();
                    if (confirmZeroPriceBtn && !confirmZeroPriceBtn.disabled) {
                        confirmZeroPriceBtn.click();
                    }
                } else if (e.key === 'Escape') {
                    e.preventDefault();
                    this.closeZeroPriceModal();
                }
            });
        }

        if (confirmZeroPriceBtn) {
            confirmZeroPriceBtn.addEventListener('click', () => {
                this.confirmZeroPrice();
            });
        }

        if (cancelZeroPriceBtn) {
            cancelZeroPriceBtn.addEventListener('click', () => {
                this.closeZeroPriceModal();
            });
        }
    }

    // 根据产品编号查找并添加产品到购物车（带nonce过期重试）
    async findAndAddProductByNumber(productNumber, retried = false) {
        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams({
                    action: 'ruiyi_find_product_by_number',
                    product_number: productNumber,
                    nonce: ruiyi_pos_ajax.nonce
                })
            });
            const data = await response.json();

            // Nonce过期时自动刷新并重试一次
            if (!data.success && data.data && data.data.code === 'nonce_expired' && !retried) {
                await this.refreshNonceOnLoad();
                return this.findAndAddProductByNumber(productNumber, true);
            }

            if (data.success && data.data) {
                const product = data.data;

                if (!product.in_stock) {
                    this.showToast(product.product_name + ' ' + (posTranslations['Out of stock'] || '缺货'), 'warning');
                    return;
                }

                const productObj = {
                    id: product.product_id,
                    name: product.product_name,
                    price: product.product_price,
                    stock: product.stock_qty,
                    image: product.product_image || ''
                };

                this.addToCart(productObj);
            } else {
                this.showToast((posTranslations['Product not found'] || '未找到产品') + ': ' + productNumber, 'error');
            }
        } catch (error) {
            this.showToast(posTranslations['Search error'] || '搜索出错', 'error');
        }
    }

    addToCart(product, options = {}) {
        if (!product || !product.id) {
            this.showToast(posTranslations['Invalid product data'] || 'Invalid product data', 'error');
            return;
        }

        const { skipWeightMeta = false, weightMetaFailed = false } = options;

        if (!skipWeightMeta && this.scaleConfig.enabled) {
            this.ensureProductWeightData(product)
                .then((enrichedProduct) => {
                    this.addToCart(enrichedProduct, { skipWeightMeta: true });
                })
                .catch((error) => {
                    console.warn('[Scale] Weight metadata fetch failed:', error);
                    this.addToCart(product, { skipWeightMeta: true, weightMetaFailed: true });
                });
            return;
        }

        this.proceedAddToCart(product, weightMetaFailed);
    }

    proceedAddToCart(product, weightMetaFailed = false) {
        if (!product || !product.id) {
            return;
        }

        // 🔥 退货模式检测：检查内部退货状态
        if (this.returnQuantity < 0) {
            const returnQty = this.returnQuantity;
            // 退货模式：添加负数量商品
            const returnItem = {
                ...product,
                cartItemId: ++this.cartItemIdCounter,
                quantity: returnQty,
                originalPrice: product.price,
                customPrice: false,
                discountPercent: 0,
                weightBased: false,
                isReturn: true // 标记为退货商品
            };
            this.cart.push(returnItem);
            this.selectedProductId = returnItem.cartItemId;
            this.returnQuantity = 0; // 重置退货模式
            this.showReturnModeIndicator(false); // 隐藏退货指示器
            this.updateCart();
            this.updateScaleCheckoutState();
            return;
        }

        // Zero Price Detection: Check if product has €0 price and prompt is enabled
        const productPrice = parseFloat(product.price) || 0;
        if (this.zeroPricePromptEnabled && productPrice === 0 && !product._zeroPriceConfirmed) {
            this.showZeroPriceModal(product);
            return;
        }

        const weightInfo = product.weightPricing || null;
        const isWeightProduct = !!(weightInfo && weightInfo.is_weight_product && !weightMetaFailed);

        if (isWeightProduct) {
            const currentWeight = this.getCurrentWeight();
            if (currentWeight === null) {
                console.warn('[Scale] No valid weight detected when adding product.');
                this.updateScaleDisplay();
                this.showToast(posTranslations['Place item on scale'] || 'Place the item on the scale', 'warning');
                return;
            }

            const baseUnitPrice = Number.parseFloat(weightInfo.unit_price_per_kg || product.price || 0);
            if (!Number.isFinite(baseUnitPrice) || baseUnitPrice <= 0) {
                console.error('[Scale] Invalid unit price for weight product', weightInfo);
                this.showToast(posTranslations['Invalid unit price'] || 'Invalid unit price', 'error');
                return;
            }

            const unit = weightInfo.weight_unit || this.scaleState.unit || this.scaleConfig.weight_unit || 'kg';
            this.setScalePreview({
                productId: product.id,
                productName: product.name,
                unit_price_per_kg: baseUnitPrice,
                weight_unit: unit
            });

            const totalPrice = this.calculateWeightPrice(weightInfo, currentWeight);
            const weightItem = this.cart.find(item => item.id === product.id && item.weightBased);

            if (weightItem) {
                weightItem.price = totalPrice;
                weightItem.originalPrice = totalPrice;
                weightItem.weightKg = currentWeight;
                weightItem.weightRecordedAt = Date.now();
                weightItem.unitPricePerKg = baseUnitPrice;
                weightItem.lineUnitPrice = baseUnitPrice;
                weightItem.weightUnit = unit;
                weightItem.weightPricing = weightInfo;
                weightItem.customPrice = false;
                this.selectedProductId = weightItem.cartItemId;
                this.updateCart();
                this.updateScaleDisplay();
                this.showToast(`${product.name} ${posTranslations['Updated with weight'] || 'updated with weight'} ${this.formatWeight(currentWeight)}`, 'success');
                this.updateScaleCheckoutState();
                return;
            }

            const weightCartItem = {
                ...product,
                cartItemId: ++this.cartItemIdCounter,
                quantity: 1,
                price: totalPrice,
                originalPrice: totalPrice,
                customPrice: false,
                discountPercent: 0,
                weightBased: true,
                weightKg: currentWeight,
                weightUnit: unit,
                unitPricePerKg: baseUnitPrice,
                lineUnitPrice: baseUnitPrice,
                weightRecordedAt: Date.now(),
                weightPricing: weightInfo
            };

            this.cart.push(weightCartItem);
            this.selectedProductId = weightCartItem.cartItemId;
            this.updateCart();
            this.updateScaleDisplay();
            this.showToast(`${product.name} ${posTranslations['Added with weight'] || 'added with weight'} ${this.formatWeight(currentWeight)}`, 'success');
            this.updateScaleCheckoutState();
            return;
        }

        // 🔥 修复：如果产品价格已被修改，不在原产品上增加数量，而是添加新的原价产品
        // Find existing item: must match product ID, not be weight-based, AND not have custom price
        const existingItem = this.cart.find(item =>
            item.id === product.id &&
            !item.weightBased &&
            !item.customPrice &&  // 🔥 关键修复：如果价格被修改过，视为不同商品
            !item.isReturn  // 🔥 退货商品不合并，始终另加一行
        );

        if (existingItem) {
            if (product.stock && existingItem.quantity >= product.stock) {
                this.showToast(posTranslations['Insufficient stock'] || 'Insufficient stock', 'error');
                return;
            }
            existingItem.quantity++;
            this.selectedProductId = existingItem.cartItemId;
        } else {
            const cartItem = {
                ...product,
                cartItemId: ++this.cartItemIdCounter,
                quantity: 1,
                originalPrice: product.price,
                customPrice: false,
                discountPercent: 0,
                weightBased: false
            };

            this.cart.push(cartItem);
            this.selectedProductId = cartItem.cartItemId;
        }

        this.updateCart();
        this.showToast(`${product.name} ${posTranslations['Product added to cart'] || 'added to cart'}`, 'success');
        this.updateScaleCheckoutState();
    }

    removeFromCart(productIdOrCartItemId, useCartItemId = false) {
        // Support both product ID (legacy) and cartItemId (new method for unique deletion)
        let itemToRemove;

        if (useCartItemId) {
            itemToRemove = this.cart.find(item => item.cartItemId === productIdOrCartItemId);
            this.cart = this.cart.filter(item => item.cartItemId !== productIdOrCartItemId);
        } else {
            itemToRemove = this.cart.find(item => item.id === productIdOrCartItemId);
            this.cart = this.cart.filter(item => item.id !== productIdOrCartItemId);
        }

        const removedWasWeight = itemToRemove && itemToRemove.weightBased;

        if (itemToRemove && this.selectedProductId === itemToRemove.cartItemId) {
            this.selectedProductId = null;
        }

        if (removedWasWeight) {
            this.setScalePreview(null);
        }

        this.updateCart();
        this.updateScaleCheckoutState();

        // 🔥 删除产品后聚焦回Varios（如果没有选中产品）
        if (!this.selectedProductId) {
            setTimeout(() => this.focusVariosInput(), 50);
        }
    }
    
    selectCartItem(cartItemId) {
        if (this.selectedProductId === cartItemId) {
            this.selectedProductId = null;
            setTimeout(() => this.focusVariosInput(), 50);
        } else {
            this.selectedProductId = cartItemId;
        }
        this.updateCart();
    }

    updateQuantity(productId, quantity) {
        const item = this.cart.find(item => item.id === productId);
        if (item) {
            if (item.weightBased) {
                this.showToast(posTranslations['Weight controlled by scale'] || 'Update weight using the scale', 'info');
                return;
            }
            if (quantity === 0) {
                this.removeFromCart(productId);
            } else if (quantity < 0) {
                // 🔥 允许负数量（退货模式）
                item.quantity = quantity;
                item.isReturn = true;
                this.updateCart();
                return;
            } else if (item.stock && quantity > item.stock) {
                this.showToast(posTranslations['Insufficient stock'] || 'Insufficient stock', 'error');
            } else {
                item.quantity = quantity;
                this.updateCart();
            }
        }
    }

    // 通过输入框手动修改数量
    updateQuantityByInput(productId, value) {
        const item = this.cart.find(item => item.id === productId);
        if (!item) return;

        if (item.weightBased) {
            this.showToast(posTranslations['Weight controlled by scale'] || 'Update weight using the scale', 'info');
            const qtyInput = document.getElementById(`qty-${productId}`);
            if (qtyInput) qtyInput.value = item.quantity;
            return;
        }

        const oldQuantity = item.quantity;
        const newQuantity = parseInt(value);

        if (isNaN(newQuantity) || newQuantity < 1) {
            this.showToast(posTranslations['Quantity must be positive integer'] || 'Quantity must be a positive integer', 'error');
            document.getElementById(`qty-${productId}`).value = oldQuantity;
            return;
        }

        if (item.stock && newQuantity > item.stock) {
            this.showToast(`库存不足，最多${item.stock}件`, 'error');
            document.getElementById(`qty-${productId}`).value = oldQuantity;
            return;
        }

        item.quantity = newQuantity;
        this.updateCart();
        this.showToast(`数量已更新为 ${newQuantity}`, 'success');
    }

    // 修改商品价格
    updatePrice(productId, value) {
        const item = this.cart.find(item => item.id === productId);
        if (!item) return;

        const oldPrice = item.price;
        const newPrice = parseFloat(value);

        if (isNaN(newPrice) || newPrice <= 0) {
            this.showToast(posTranslations['Price must be greater than 0'] || 'Price must be greater than 0', 'error');
            document.getElementById(`price-${productId}`).value = oldPrice.toFixed(2);
            return;
        }

        if (!item.originalPrice) {
            item.originalPrice = oldPrice;
        }

        item.price = newPrice;
        item.customPrice = (newPrice !== item.originalPrice);
        this.updateCart();

        // 显示提示
        if (item.customPrice) {
            const priceDiff = newPrice - item.originalPrice;
            const diffText = priceDiff > 0 ? `+${ruiyi_pos_ajax.currency}${priceDiff.toFixed(2)}` : `${ruiyi_pos_ajax.currency}${priceDiff.toFixed(2)}`;
            this.showToast(`价格已修改 (${diffText})`, 'warning');
        } else {
            this.showToast(posTranslations['Price restored to original'] || 'Price restored to original', 'info');
        }
    }

    /**
     * 🔥 Bug 6 修复：通过 cartItemId 修改价格（避免同一产品多行时 id 冲突）
     */
    updatePriceByCartItemId(cartItemId, value) {
        const item = this.cart.find(item => item.cartItemId === cartItemId);
        if (!item) return;

        const oldPrice = item.price;
        const newPrice = this.normalizePrice(value);

        if (isNaN(newPrice) || newPrice <= 0) {
            this.showToast(posTranslations['Price must be greater than 0'] || 'Price must be greater than 0', 'error');
            document.getElementById(`price-${cartItemId}`).value = oldPrice.toFixed(2);
            return;
        }

        if (!item.originalPrice) {
            item.originalPrice = oldPrice;
        }

        item.price = newPrice;
        item.customPrice = (newPrice !== item.originalPrice);
        this.updateCart();

        if (item.customPrice) {
            const priceDiff = newPrice - item.originalPrice;
            const diffText = priceDiff > 0 ? `+${ruiyi_pos_ajax.currency}${priceDiff.toFixed(2)}` : `${ruiyi_pos_ajax.currency}${priceDiff.toFixed(2)}`;
            this.showToast(`价格已修改 (${diffText})`, 'warning');
        } else {
            this.showToast(posTranslations['Price restored to original'] || 'Price restored to original', 'info');
        }
    }

    // 🔥 Performance: debounced localStorage write to avoid blocking UI thread
    _debouncedCartSave() {
        if (this._cartSaveTimer) cancelAnimationFrame(this._cartSaveTimer);
        this._cartSaveTimer = requestAnimationFrame(() => {
            localStorage.setItem('ruiyi_pos_cart', JSON.stringify(this.cart));
            if (this.pendingPointsDiscount) {
                localStorage.setItem('ruiyi_pos_points_discount', JSON.stringify(this.pendingPointsDiscount));
            } else {
                localStorage.removeItem('ruiyi_pos_points_discount');
            }
        });
    }

    updateCart() {
        // 🔥 Performance: defer localStorage writes to next animation frame
        this._debouncedCartSave();

        // Broadcast cart update
        this.broadcastUpdate('cart_updated', {
            cart: this.cart,
            pointsDiscount: this.pendingPointsDiscount || null
        });
        
        // Sync data to customer display screen
        this.syncToCustomerDisplay();

        // 🔥 Use cached DOM elements (Phase 2 optimization)
        const cartContainer = this.getElement('cart-items-container');
        const cartCount = this.getElement('cart-count');
        const totalEl = this.getElement('total-amount');
        const checkoutBtn = this.getElement('checkout-btn');

        if (!cartContainer) {
            // Cart container may not exist during SPA navigation transitions or on non-POS pages
            // This is expected behavior, not an error
            return;
        }

        if (this.cart.length === 0) {
            // Clear container (no empty message shown)
            cartContainer.innerHTML = '';

            if (cartCount) cartCount.textContent = '0';
            if (totalEl) totalEl.textContent = '0.00' + ruiyi_pos_ajax.currency;
            if (checkoutBtn) checkoutBtn.disabled = true;

            // Disable hold order button when cart is empty
            const holdOrderBtn = this.getElement('hold-order-btn');
            if (holdOrderBtn) holdOrderBtn.disabled = true;

            // Show welcome message on VFD when cart is empty
            this.sendVFDDisplay('Bienvenido', true);

            this.updateScaleCheckoutState();
            this._prevCartState = null;
            this._prevCartIds = [];
            return;
        }

        // 🔥 Performance: change detection for incremental DOM updates
        const cartStateKey = this.cart.map(i => `${i.cartItemId}:${i.quantity}:${i.price}`).join('|') + '|sel:' + (this.selectedProductId || '');

        if (this._prevCartState === cartStateKey) {
            return; // Nothing changed, skip render entirely
        }

        const currIds = this.cart.map(i => i.cartItemId);
        const prevIds = this._prevCartIds || [];
        const isSameItems = prevIds.length === currIds.length &&
            prevIds.every((id, idx) => id === currIds[idx]);

        // Incremental path: same items, only qty/price/selection changed
        if (isSameItems && cartContainer.children.length > 1) {
            let totalWithTax = 0;
            let totalQuantity = 0;

            this.cart.forEach((item) => {
                const isWeightItem = !!item.weightBased;
                const itemTotal = isWeightItem
                    ? (parseFloat(item.price) || 0)
                    : (parseFloat(item.price) || 0) * (parseFloat(item.quantity) || 0);
                totalWithTax += itemTotal;
                totalQuantity += isWeightItem ? 1 : Math.abs(item.quantity);

                const row = cartContainer.querySelector(`[data-cart-item-id="${item.cartItemId}"]`);
                if (row) {
                    // Update selection state
                    const isSelected = this.selectedProductId === item.cartItemId;
                    row.classList.toggle('cart-item-selected', isSelected);

                    // Update quantity input
                    const qtyInput = row.querySelector('.cart-quantity-input');
                    if (qtyInput && parseFloat(qtyInput.value) !== item.quantity) {
                        qtyInput.value = item.quantity;
                    }

                    // Update price input and custom price indicator
                    const priceInput = row.querySelector('.cart-price-input');
                    if (priceInput) {
                        priceInput.value = parseFloat(item.price || 0).toFixed(2);
                        const isCustomPrice = item.customPrice || (item.originalPrice && item.price !== item.originalPrice);
                        priceInput.classList.toggle('custom-price', isCustomPrice);
                    }

                    // Update discount display
                    const originalPrice = item.originalPrice || item.price;
                    const discount = (!isWeightItem && originalPrice > item.price) ? (originalPrice - item.price) : 0;
                    const discountPercent = originalPrice > 0 ? ((discount / originalPrice) * 100).toFixed(0) : 0;
                    const discountDisplay = (discount > 0) ? `${discount.toFixed(2)}${ruiyi_pos_ajax.currency} (${discountPercent}%)` : '-';
                    const discountEl = row.querySelector('.discount-display');
                    if (discountEl) discountEl.textContent = discountDisplay;

                    // Update item total
                    const totalSpan = row.querySelector('.item-total');
                    if (totalSpan) {
                        totalSpan.textContent = itemTotal.toFixed(2) + ruiyi_pos_ajax.currency;
                    }
                }
            });

            // Update summary elements
            if (cartCount) cartCount.textContent = totalQuantity;
            if (totalEl) totalEl.textContent = parseFloat(totalWithTax || 0).toFixed(2) + ruiyi_pos_ajax.currency;
            if (checkoutBtn) checkoutBtn.disabled = false;

            const holdOrderBtn = this.getElement('hold-order-btn');
            if (holdOrderBtn) holdOrderBtn.disabled = false;

            // Update VFD display
            const totalPrice = parseFloat(totalWithTax || 0).toFixed(2);
            this.sendVFDDisplay(`TOTAL: ${ruiyi_pos_ajax.currency}${totalPrice}`, true);

            this._prevCartState = cartStateKey;
            this._prevCartIds = currIds;
            this.updateScaleCheckoutState();
            return;
        }

        // Full rebuild path: items added/removed
        let totalWithTax = 0;
        let totalQuantity = 0;

        // Add header row above cart items
        const cartHeaderHTML = `
            <div class="cart-header-row px-4">
                <div class="flex items-center">
                    <div class="flex-1 min-w-0">
                        <h4 class="text-xs font-bold text-gray-700 uppercase"><?php _e('Product Name', 'ruiyi-retail-pos'); ?></h4>
                    </div>
                    <div class="w-36 text-center">
                        <h4 class="text-xs font-bold text-gray-700 uppercase"><?php _e('Quantity', 'ruiyi-retail-pos'); ?></h4>
                    </div>
                    <div class="w-28 text-center">
                        <h4 class="text-xs font-bold text-gray-700 uppercase"><?php _e('Unit Price', 'ruiyi-retail-pos'); ?></h4>
                    </div>
                    <div class="w-20 text-center">
                        <h4 class="text-xs font-bold text-gray-700 uppercase"><?php _e('Discount', 'ruiyi-retail-pos'); ?></h4>
                    </div>
                    <div class="w-28 text-right pr-2">
                        <h4 class="text-xs font-bold text-gray-700 uppercase"><?php _e('Total', 'ruiyi-retail-pos'); ?></h4>
                    </div>
                </div>
            </div>
        `;

        const cartHTML = this.cart.map(item => {
            const isWeightItem = !!item.weightBased;
            const isReturnItem = !!(item.isReturn || item.quantity < 0); // 退货商品检测
            const unit = item.weightUnit || this.scaleState.unit || this.scaleConfig.weight_unit || 'kg';
            const unitPricePerKg = item.lineUnitPrice ?? item.unitPricePerKg ?? (item.weightPricing && item.weightPricing.unit_price_per_kg);
            const weightKg = (typeof item.weightKg === 'number' && !Number.isNaN(item.weightKg)) ? item.weightKg : null;
            const itemTotal = isWeightItem
                ? (parseFloat(item.price) || 0)
                : (parseFloat(item.price) || 0) * (parseFloat(item.quantity) || 0);
            totalWithTax += itemTotal;
            totalQuantity += isWeightItem ? 1 : Math.abs(item.quantity);

            const isCustomPrice = item.customPrice || (item.originalPrice && item.price !== item.originalPrice);
            const priceInputClass = isCustomPrice ? 'cart-price-input custom-price' : 'cart-price-input';
            
            const originalPrice = item.originalPrice || item.price;
            const discount = (!isWeightItem && originalPrice > item.price) ? (originalPrice - item.price) : 0;
            const discountPercent = originalPrice > 0 ? ((discount / originalPrice) * 100).toFixed(0) : 0;
            const discountDisplay = (discount > 0) ? `${discount.toFixed(2)}${ruiyi_pos_ajax.currency} (${discountPercent}%)` : '-';

            const isSelected = this.selectedProductId === item.cartItemId;
            const selectedClass = isSelected ? 'cart-item-selected' : '';
            const formattedWeight = weightKg !== null ? this.formatWeight(weightKg) : null;
            const effectiveUnitPrice = unitPricePerKg
                ? unitPricePerKg
                : (weightKg ? Number.parseFloat((itemTotal / (weightKg || 1)).toFixed(2)) : item.price);

            const weightInfo = isWeightItem && effectiveUnitPrice
                ? `<p class="text-xs text-gray-500 mt-1">${effectiveUnitPrice.toFixed(2)}${ruiyi_pos_ajax.currency} / ${unit}</p>`
                : '';

            const quantityColumn = isWeightItem
                ? `<div class="w-36 text-center">
                        <span class="text-sm font-semibold text-gray-700">${formattedWeight || '—'}</span>
                        ${weightInfo}
                   </div>`
                : `<div class="w-36 flex items-center justify-center space-x-1">
                        <button class="w-7 h-7 rounded-full bg-gray-200 hover:bg-gray-300 flex items-center justify-center transition-all"
                                data-action="decrease">
                            <span class="text-sm font-bold">-</span>
                        </button>
                        <input type="number"
                               id="qty-${item.cartItemId}"
                               value="${item.quantity}"
                               min="0.01"
                               max="${item.stock || 9999}"
                               step="0.01"
                               class="cart-quantity-input w-10 py-1"
                               data-cart-item-id="${item.cartItemId}"
                               onchange="window.pos.updateQuantityByCartItemId(${item.cartItemId}, this.value)"
                               onclick="event.stopPropagation(); this.select()"
                               title="点击修改数量（支持小数）">
                        <button class="w-7 h-7 rounded-full bg-gray-200 hover:bg-gray-300 flex items-center justify-center transition-all"
                                data-action="increase">
                            <span class="text-sm font-bold">+</span>
                        </button>
                   </div>`;

            const unitPriceColumn = isWeightItem
                ? `<div class="w-28 text-center">
                        <p class="text-sm font-semibold text-gray-800">
                            ${effectiveUnitPrice.toFixed(2)}${ruiyi_pos_ajax.currency}/${unit}
                        </p>
                   </div>`
                : `<div class="w-28 flex items-center justify-center">
                        <input type="text"
                               inputmode="decimal"
                               id="price-${item.cartItemId}"
                               value="${parseFloat(item.price || 0).toFixed(2)}"
                               class="${priceInputClass} w-16"
                               onchange="window.pos.updatePriceByCartItemId(${item.cartItemId}, this.value)"
                               onclick="event.stopPropagation(); this.select()"
                               title="点击修改价格">
                        <span class="text-xs text-gray-400 ml-1">${ruiyi_pos_ajax.currency}</span>
                   </div>`;
            
            const returnBgClass = isReturnItem ? 'bg-red-50' : 'bg-white';
            const returnLabel = isReturnItem ? `<span class="text-xs text-red-600 font-semibold ml-1">[${posTranslations['Return'] || '退货'}]</span>` : '';

            return `
                <div class="${returnBgClass} px-4 py-2 flex items-center border-b border-gray-200 cart-item ${selectedClass}"
                     data-cart-item-id="${item.cartItemId}">
                    <div class="flex-1 min-w-0">
                        <h4 class="text-sm font-medium ${isReturnItem ? 'text-red-700' : 'text-gray-900'} truncate">${item.name}${returnLabel}</h4>
                        ${isWeightItem && formattedWeight ? `<p class="text-xs text-gray-500">${formattedWeight}</p>` : ''}
                    </div>
                    ${quantityColumn}
                    ${unitPriceColumn}
                    <div class="w-20 text-center">
                        <p class="text-sm font-medium discount-display ${discount > 0 ? 'text-green-600' : 'text-gray-400'}">${discountDisplay}</p>
                    </div>
                    <div class="w-28 flex items-center justify-end space-x-2">
                        <p class="text-sm font-bold item-total ${isReturnItem ? 'text-red-600' : 'text-gray-900'}">${itemTotal.toFixed(2)}${ruiyi_pos_ajax.currency}</p>
                        <button class="w-5 h-5 rounded-full bg-red-100 hover:bg-red-200 text-red-600 flex items-center justify-center transition-all flex-shrink-0"
                                data-action="remove"
                                title="${posTranslations['Remove from cart'] || 'Remove from cart'}">
                            <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/>
                            </svg>
                        </button>
                    </div>
                </div>
            `;
        }).join('');

        cartContainer.innerHTML = cartHeaderHTML + cartHTML;

        // Product prices include IVA, so totalWithTax is the final price
        if (cartCount) cartCount.textContent = totalQuantity;
        if (totalEl) totalEl.textContent = parseFloat(totalWithTax || 0).toFixed(2) + ruiyi_pos_ajax.currency;
        if (checkoutBtn) checkoutBtn.disabled = false;

        // Enable hold order button when cart has items
        const holdOrderBtn2 = this.getElement('hold-order-btn');
        if (holdOrderBtn2) holdOrderBtn2.disabled = false;

        // Update VFD display with total price
        const totalPrice = parseFloat(totalWithTax || 0).toFixed(2);
        const vfdText = `TOTAL: ${ruiyi_pos_ajax.currency}${totalPrice}`;
        this.sendVFDDisplay(vfdText, true);

        // 🔥 Performance: track cart state for incremental updates
        this._prevCartState = cartStateKey;
        this._prevCartIds = currIds;

        this.updateScaleCheckoutState();
    }

    clearCart() {
        this.cart = [];
        this.selectedProductId = null; // Clear selection
        this.returnQuantity = 0; // 重置退货模式
        this.showReturnModeIndicator(false); // 隐藏退货指示器
        this.setScalePreview(null);
        // Clear points state
        this.pendingPointsDiscount = null;
        this.pendingPointsReward = null;
        
        // Clear localStorage
        localStorage.removeItem('ruiyi_pos_cart');
        localStorage.removeItem('ruiyi_pos_points_discount');
        
        // Force client display to update immediately by setting a timestamp
        localStorage.setItem('ruiyi_pos_cart_cleared', Date.now().toString());
        
        // Broadcast cart cleared event
        this.broadcastUpdate('cart_cleared', {
            cart: [],
            pointsDiscount: null
        });
        
        // Reset points management buttons
        this.resetPointsButtons();
        
        this.updateCart();
        this.syncToCustomerDisplay(); // 确保清空购物车时同步到客户显示屏
        this.showToast(posTranslations['Cart cleared'] || 'Cart cleared', 'info');
        this.updateScaleCheckoutState();

        // 🔥 清空购物车后重新聚焦到Varios输入框（除非退货弹窗打开）
        setTimeout(() => {
            if (window.isRefundModalOpen) return; // 退货弹窗打开时不抢夺焦点
            const variosInput = document.getElementById('varios-price-input');
            if (variosInput && this.shouldFocusVarios()) {
                variosInput.focus();
            }
        }, 100);
    }
    
    resetPointsButtons() {
        // Reset discount button
        const discountBtn = document.getElementById('apply-points-discount');
        if (discountBtn) {
            discountBtn.disabled = false;
            discountBtn.textContent = posTranslations['Apply Points Discount'] || 'Apply Points Discount';
            discountBtn.classList.remove('opacity-50', 'cursor-not-allowed');
        }
        
        // Reset reward button
        const rewardBtn = document.getElementById('apply-points-reward');
        if (rewardBtn) {
            rewardBtn.disabled = false;
            rewardBtn.textContent = posTranslations['Confirm and Continue'] || 'Confirm and Continue';
            rewardBtn.classList.remove('opacity-50', 'cursor-not-allowed');
        }
        
        // Reset status displays
        const discountStatus = document.getElementById('discount-status');
        if (discountStatus) {
            discountStatus.textContent = '-';
            discountStatus.className = 'text-sm text-gray-500 mb-4';
        }
        
        const rewardPoints = document.getElementById('reward-points');
        if (rewardPoints) {
            rewardPoints.textContent = '0';
            rewardPoints.className = 'text-3xl font-bold text-green-600';
        }
        
        const rewardCalculation = document.getElementById('reward-calculation');
        if (rewardCalculation) {
            rewardCalculation.textContent = '-';
            rewardCalculation.className = 'text-xs text-gray-500 mt-2';
        }
    }

    async searchProducts(query) {
        if (!query) {
            this.clearSearch();
            return;
        }

        // Don't search if query is too short
        if (query.length < 2) {
            return;
        }

        const loading = document.getElementById('products-loading');
        const grid = document.getElementById('products-grid');
        const noResults = document.getElementById('no-results');

        if (loading) loading.classList.remove('hidden');
        if (grid) grid.classList.add('hidden');
        if (noResults) noResults.classList.add('hidden');

        try {
            const data = await this.ajaxRequest({
                pos_action: 'search_products',
                search: query
            });

            if (loading) loading.classList.add('hidden');

            if (data.success && data.data.products.length > 0) {
                this.displaySearchResults(data.data.products, query);
                this.showToast(`Found ${data.data.products.length} products`, 'success');

                // Cache search results to offline IndexedDB for future offline access
                if (typeof ProductCacheManager !== 'undefined' && ProductCacheManager.addProductToCache) {
                    data.data.products.forEach(product => {
                        if (product && product.id) {
                            ProductCacheManager.addProductToCache(product);
                        }
                    });
                }
            } else {
                if (noResults) noResults.classList.remove('hidden');
                this.showToast(posTranslations['No products found'] || 'No products found', 'info');
            }
        } catch (error) {
            if (loading) loading.classList.add('hidden');
            if (noResults) noResults.classList.remove('hidden');
            this.showToast(posTranslations['Search error'] || 'Search error', 'error');
            console.error('Search error:', error);
        }
    }

    clearSearch() {
        const productsGrid = document.getElementById('products-grid');
        const noResults = document.getElementById('no-results');
        const loading = document.getElementById('products-loading');
        
        if (loading) loading.classList.add('hidden');
        if (noResults) noResults.classList.add('hidden');
        if (productsGrid) {
            productsGrid.classList.remove('hidden');
            // Restore original product grid content
            this.restoreOriginalProducts();
        }
        
        this.showToast(posTranslations['Search cleared'] || 'Search cleared', 'info');
    }

    restoreOriginalProducts() {
        // 🔥 Performance: restore cached HTML instead of page reload
        const grid = document.getElementById('products-grid');
        if (grid && this._originalProductsHTML) {
            grid.innerHTML = this._originalProductsHTML;
        }
    }

    displaySearchResults(products, searchQuery = '') {
        const grid = document.getElementById('products-grid');
        if (!grid) return;
        
        const productsHTML = products.map(product => {
            const stockBadge = product.stock <= 10 && product.stock > 0 ? 
                '<span class="absolute top-2 right-2 bg-yellow-500 text-white text-xs px-2 py-1 rounded-full">' + (ruiyi_pos_ajax.i18n['Low Stock'] || 'Stock Bajo') + '</span>' : '';

            // Highlight search matches
            const highlightedName = this.highlightSearchTerm(product.name, searchQuery);
            const highlightedSku = this.highlightSearchTerm(product.sku || 'N/A', searchQuery);
            
            // Add match type indicator
            const matchIndicator = product.match_type === 'sku' ? 
                '<span class="absolute top-2 left-2 bg-blue-500 text-white text-xs px-2 py-1 rounded-full">SKU Match</span>' : '';

            return `
                <div class="bg-white rounded-lg shadow-md hover:shadow-lg transition-shadow duration-200 cursor-pointer border border-gray-200 product-card ${product.match_type === 'sku' ? 'ring-2 ring-blue-200' : ''}"
                     data-product='${JSON.stringify(product)}'>
                    <div class="relative p-3">
                        ${stockBadge}
                        ${matchIndicator}
                        <div class="text-center">
                            <h3 class="text-sm font-semibold text-gray-900 mb-1">${highlightedName}</h3>
                            <p class="text-xs text-gray-500 mb-2">SKU: ${highlightedSku}</p>
                            <div class="text-lg font-bold text-blue-600">${product.formatted_price}</div>
                            ${product.stock ? `<p class="text-xs text-gray-500 mt-1">Stock: ${product.stock}</p>` : ''}
                        </div>
                    </div>
                </div>
            `;
        }).join('');

        grid.innerHTML = productsHTML;
        grid.classList.remove('hidden');
    }

    highlightSearchTerm(text, searchTerm) {
        if (!searchTerm || !text) return text;
        
        const regex = new RegExp(`(${searchTerm})`, 'gi');
        return text.replace(regex, '<mark class="bg-yellow-200 px-1 rounded">$1</mark>');
    }

    // ========================================
    // 生成预结单功能 (Albarán)
    // ========================================

    /**
     * 🔥 点击"生成预结单"按钮时，首先显示支付方式选择弹窗
     * When clicking "Create Albarán" button, first show payment method selection modal
     */
    showAlbaranPaymentMethodModal() {
        if (this.cart.length === 0) return;

        const locale = document.documentElement.lang || 'en';

        // 创建支付方式选择弹窗HTML
        const modalHtml = `
            <div id="albaran-payment-modal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
                <div class="bg-white rounded-xl shadow-2xl max-w-lg w-full mx-4 overflow-hidden">
                    <!-- Header -->
                    <div class="bg-yellow-500 px-6 py-4">
                        <h3 class="font-bold text-lg text-white text-center">
                            ${locale.includes('zh') ? '选择支付方式' : locale.includes('es') ? 'Seleccionar Método de Pago' : 'Select Payment Method'}
                        </h3>
                        <p class="text-yellow-100 text-sm text-center mt-1">
                            ${locale.includes('zh') ? '为预结单订单选择支付方式' : locale.includes('es') ? 'Seleccione el método de pago para el albarán' : 'Select payment method for the pre-settlement order'}
                        </p>
                    </div>

                    <!-- Body -->
                    <div class="px-6 py-5">
                        <div class="grid grid-cols-2 gap-3">
                            <!-- 现金支付 -->
                            <button id="albaran-pay-cash"
                                    class="flex flex-col items-center justify-center p-4 bg-green-500 hover:bg-green-600 text-white rounded-xl transition-all">
                                <svg class="w-8 h-8 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z"></path>
                                </svg>
                                <span class="font-bold">${locale.includes('zh') ? '现金' : locale.includes('es') ? 'Efectivo' : 'Cash'}</span>
                            </button>

                            <!-- 刷卡支付 -->
                            <button id="albaran-pay-card"
                                    class="flex flex-col items-center justify-center p-4 bg-blue-500 hover:bg-blue-600 text-white rounded-xl transition-all">
                                <svg class="w-8 h-8 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z"></path>
                                </svg>
                                <span class="font-bold">${locale.includes('zh') ? '刷卡' : locale.includes('es') ? 'Tarjeta' : 'Card'}</span>
                            </button>

                            <!-- 混合支付 -->
                            <button id="albaran-pay-mixed"
                                    class="flex flex-col items-center justify-center p-4 bg-orange-500 hover:bg-orange-600 text-white rounded-xl transition-all">
                                <svg class="w-8 h-8 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"></path>
                                </svg>
                                <span class="font-bold">${locale.includes('zh') ? '混合' : locale.includes('es') ? 'Mixto' : 'Mixed'}</span>
                            </button>

                            <!-- 转账支付 -->
                            <button id="albaran-pay-transfer"
                                    class="flex flex-col items-center justify-center p-4 bg-purple-500 hover:bg-purple-600 text-white rounded-xl transition-all">
                                <svg class="w-8 h-8 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"></path>
                                </svg>
                                <span class="font-bold">${locale.includes('zh') ? '转账' : locale.includes('es') ? 'Transferencia' : 'Transfer'}</span>
                            </button>
                        </div>

                        <!-- 取消按钮 -->
                        <button id="albaran-pay-cancel"
                                class="w-full mt-4 py-3 bg-gray-200 hover:bg-gray-300 text-gray-700 rounded-lg font-bold transition-all">
                            ${locale.includes('zh') ? '取消' : locale.includes('es') ? 'Cancelar' : 'Cancel'}
                        </button>
                    </div>
                </div>
            </div>
        `;

        // 添加到DOM
        document.body.insertAdjacentHTML('beforeend', modalHtml);

        const modal = document.getElementById('albaran-payment-modal');
        const cashBtn = document.getElementById('albaran-pay-cash');
        const cardBtn = document.getElementById('albaran-pay-card');
        const mixedBtn = document.getElementById('albaran-pay-mixed');
        const transferBtn = document.getElementById('albaran-pay-transfer');
        const cancelBtn = document.getElementById('albaran-pay-cancel');

        // 选择支付方式后创建订单
        cashBtn.addEventListener('click', () => {
            modal.remove();
            this.createAlbaranOrderWithPayment('cash');
        });

        cardBtn.addEventListener('click', () => {
            modal.remove();
            this.createAlbaranOrderWithPayment('card');
        });

        mixedBtn.addEventListener('click', () => {
            modal.remove();
            this.createAlbaranOrderWithPayment('mixed');
        });

        transferBtn.addEventListener('click', () => {
            modal.remove();
            this.createAlbaranOrderWithPayment('transfer');
        });

        // 取消
        cancelBtn.addEventListener('click', () => {
            modal.remove();
        });

        // 点击背景关闭
        modal.addEventListener('click', (e) => {
            if (e.target === modal) {
                modal.remove();
            }
        });
    }

    /**
     * 🔥 带支付方式的预结单创建
     * Create albaran order with specified payment method
     */
    async createAlbaranOrderWithPayment(paymentMethod) {
        const locale = document.documentElement.lang || 'en';
        const albaranBtn = document.getElementById('albaran-btn');
        const btnOriginalText = locale.includes('zh') ? '生成预结单'
                              : locale.includes('es') ? 'Crear Albarán' : 'Create Albarán';

        // 禁用按钮并显示加载状态
        if (albaranBtn) {
            albaranBtn.disabled = true;
            albaranBtn.innerHTML = `
                <svg class="animate-spin h-5 w-5 mx-auto" fill="none" viewBox="0 0 24 24">
                    <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                    <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
            `;
        }

        try {
            // 准备购物车数据
            const cartData = this.cart.map(item => ({
                product_id: item.id,
                name: item.name,
                quantity: item.quantity,
                price: item.price,
                total: item.price * item.quantity
            }));

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'create_albaran_order',
                    nonce: ruiyi_pos_ajax.nonce,
                    cart_data: JSON.stringify(cartData),
                    total: this.calculateTotal().total,
                    payment_method: paymentMethod  // 🔥 添加支付方式参数
                })
            });

            const data = await response.json();

            if (data.success) {
                const orderId = data.data.order_id;

                // 清空购物车
                this.cart = [];
                this.updateCart();
                this.updateScaleCheckoutState();

                // 恢复按钮状态
                if (albaranBtn) {
                    albaranBtn.disabled = false;
                    albaranBtn.innerHTML = btnOriginalText;
                }

                // 显示弹窗询问是否创建预结单发票
                this.showAlbaranConfirmModal(orderId);
            } else {
                throw new Error(data.data?.message || 'Failed to create Albarán order');
            }
        } catch (error) {
            console.error('Error creating Albarán order:', error);
            this.showToast(
                locale.includes('zh')
                    ? '创建预结单订单失败'
                    : locale.includes('es')
                        ? 'Error al crear el pedido'
                        : 'Failed to create order',
                'error'
            );

            // 恢复按钮状态
            if (albaranBtn) {
                albaranBtn.disabled = false;
                albaranBtn.innerHTML = btnOriginalText;
            }
        }
    }

    /**
     * 🔥 向后兼容：保留原来的 createAlbaranOrder 函数，现在调用显示支付方式选择弹窗
     */
    createAlbaranOrder() {
        this.showAlbaranPaymentMethodModal();
    }

