    checkout() {
        // 🔥 如果购物车为空但Varios输入框有值，先添加到购物车再结账
        if (this.cart.length === 0) {
            const variosInput = document.getElementById('varios-price-input');
            if (variosInput && variosInput.value.trim()) {
                const value = variosInput.value.trim();
                // 检查是否为有效价格（≤4位数字或含小数点的数字）
                if (/^\d{1,4}([.,]\d*)?$/.test(value)) {
                    this.addVariosToCart();
                    // addVariosToCart是异步的，需要等购物车更新后再结账
                    setTimeout(() => {
                        if (this.cart.length > 0) {
                            this.checkout();
                        }
                    }, 200);
                    return;
                }
            }
            return;
        }

        // 🔥 关键修复：如果扫描器正在保护期，拒绝结账（防止误触发）
        if (window.isScannerActive) {
            console.warn('[Checkout] 扫描器保护期内，拒绝结账操作');
            return;
        }

        // 🔥 打开结算弹窗前，清空Varios输入框并失焦，重置退货模式
        const variosInput = document.getElementById('varios-price-input');
        if (variosInput) {
            variosInput.value = ''; // 清空内容
            variosInput.blur(); // 失焦
        }
        this.returnQuantity = 0; // 重置退货模式
        this.showReturnModeIndicator(false); // 隐藏退货指示器

        // Show payment method modal
        const modal = document.getElementById('payment-method-modal');
        if (modal) {
            modal.classList.remove('hidden');

            // 🔥 先移除旧的监听器（如果有）
            if (this._paymentKeyHandler) {
                document.removeEventListener('keydown', this._paymentKeyHandler, true);
            }

            // 🔥 新功能2&3：添加键盘监听器 - 支付方式弹窗中的快捷键
            this._paymentKeyHandler = (e) => {
                // 🔥 检查弹窗是否还打开，如果已关闭则移除监听器并退出
                const paymentModal = document.getElementById('payment-method-modal');
                if (!paymentModal || paymentModal.classList.contains('hidden')) {
                    document.removeEventListener('keydown', this._paymentKeyHandler, true);
                    this._paymentKeyHandler = null;
                    return;
                }

                if (e.key === 'Enter') {
                    e.preventDefault();
                    e.stopPropagation();
                    // 移除监听器（一次性）
                    document.removeEventListener('keydown', this._paymentKeyHandler, true);
                    this._paymentKeyHandler = null;
                    // 触发现金支付
                    const cashBtn = document.getElementById('cash-payment-btn');
                    if (cashBtn) {
                        cashBtn.click();
                    }
                }
                // 刷卡支付 - 支持自定义快捷键，默认 . 键
                else if (this._matchPaymentCardShortcut(e)) {
                    e.preventDefault();
                    e.stopPropagation();
                    document.removeEventListener('keydown', this._paymentKeyHandler, true);
                    this._paymentKeyHandler = null;
                    const cardBtn = document.getElementById('card-payment-btn');
                    if (cardBtn) {
                        cardBtn.click();
                    }
                }
                // M 键 - 进入混合支付
                else if (e.key === 'm' || e.key === 'M') {
                    e.preventDefault();
                    e.stopPropagation();
                    // 移除监听器（一次性）
                    document.removeEventListener('keydown', this._paymentKeyHandler, true);
                    this._paymentKeyHandler = null;
                    // 触发混合支付
                    const mixedBtn = document.getElementById('mixed-payment-btn');
                    if (mixedBtn) {
                        mixedBtn.click();
                    }
                }
                // C 键 - 进入客户信息
                else if (e.key === 'c' || e.key === 'C') {
                    e.preventDefault();
                    e.stopPropagation();
                    // 移除监听器（一次性）
                    document.removeEventListener('keydown', this._paymentKeyHandler, true);
                    this._paymentKeyHandler = null;
                    // 触发客户信息
                    const customerBtn = document.getElementById('customer-info-btn');
                    if (customerBtn) {
                        customerBtn.click();
                    }
                }
                // Esc键关闭弹窗
                else if (e.key === 'Escape') {
                    document.removeEventListener('keydown', this._paymentKeyHandler, true);
                    this._paymentKeyHandler = null;
                }
            };

            // 使用捕获阶段确保优先处理
            document.addEventListener('keydown', this._paymentKeyHandler, true);
        }
    }

    showCashPaymentModal() {
        // Close payment method modal
        this.closePaymentMethodModal();

        // 🔥 清空Varios输入框并失焦
        const variosInput = document.getElementById('varios-price-input');
        if (variosInput) {
            variosInput.value = '';
            variosInput.blur();
        }

        // Get numeric total for cash payment (considering points discount)
        let total = this.calculateNumericTotal();

        // Apply points discount if available
        if (this.pendingPointsDiscount && this.pendingPointsDiscount.discount) {
            // Use consistent rounding to 2 decimal places
            const discountedTotal = Math.round((total - this.pendingPointsDiscount.discount) * 100) / 100;
            total = Math.max(0, discountedTotal);
        }

        // Update cash payment modal
        const totalDueEl = document.getElementById('cash-total-due');
        if (totalDueEl) {
            if (total < 0) {
                // 🔥 退货模式：显示负数总额（退款金额）
                totalDueEl.textContent = '-' + ruiyi_pos_ajax.currency + Math.abs(total).toFixed(2);
                totalDueEl.style.color = '#dc2626'; // red
            } else {
                totalDueEl.textContent = ruiyi_pos_ajax.currency + total.toFixed(2);
                totalDueEl.style.color = ''; // reset
            }
        }

        // Reset inputs
        const cashReceivedInput = document.getElementById('cash-received');
        if (cashReceivedInput) {
            cashReceivedInput.value = '';
            // 延迟聚焦，确保模态框完全显示后再聚焦
            setTimeout(() => {
                cashReceivedInput.focus();
            }, 150);
        }

        // 🔥 初始化找零显示
        const changeEl = document.getElementById('change-amount');
        if (changeEl) {
            if (total < 0) {
                // 退货模式：显示退款金额
                changeEl.textContent = ruiyi_pos_ajax.currency + Math.abs(total).toFixed(2) + ' (' + (posTranslations['Refund'] || '退款') + ')';
                changeEl.className = 'text-2xl font-bold text-red-600';
            } else {
                changeEl.textContent = ruiyi_pos_ajax.currency + '0.00';
                changeEl.className = 'text-2xl font-bold text-green-600'; // 绿色表示找零为0（刚好）
            }
        }

        const confirmBtn = document.getElementById('confirm-cash-btn');
        if (confirmBtn) {
            // 🔥 默认启用按钮（允许不输入金额即刚好付款）
            confirmBtn.disabled = false;
        }
        
        // Show cash payment modal
        const modal = document.getElementById('cash-payment-modal');
        if (modal) {
            modal.classList.remove('hidden');
        }
    }

    calculateChange(amountReceived) {
        // Get numeric total for change calculation (considering points discount)
        let total = this.calculateNumericTotal();

        // Apply points discount if available
        if (this.pendingPointsDiscount && this.pendingPointsDiscount.discount) {
            // Use consistent rounding to 2 decimal places
            const discountedTotal = Math.round((total - this.pendingPointsDiscount.discount) * 100) / 100;
            total = Math.max(0, discountedTotal);
        }

        // 🔥 如果未输入金额，默认为刚好付款（received = total）
        let received = parseFloat(amountReceived);
        if (isNaN(received) || (received === 0 && total > 0) || amountReceived === '') {
            received = total < 0 ? 0 : total; // 退货时默认收款为0，正常时默认刚好付款
        }

        const change = received - total;

        const changeEl = document.getElementById('change-amount');
        const confirmBtn = document.getElementById('confirm-cash-btn');

        if (changeEl) {
            // Ensure all values are valid numbers
            if (!isNaN(change) && isFinite(change)) {
                if (change >= 0) {
                    changeEl.textContent = ruiyi_pos_ajax.currency + change.toFixed(2);
                    changeEl.className = 'text-2xl font-bold text-green-600';
                } else {
                    changeEl.textContent = '-' + ruiyi_pos_ajax.currency + Math.abs(change).toFixed(2);
                    changeEl.className = 'text-2xl font-bold text-red-600';
                }
            } else {
                // Fallback for invalid calculations
                changeEl.textContent = ruiyi_pos_ajax.currency + '0.00';
                changeEl.className = 'text-2xl font-bold text-gray-600';
            }
        }

        if (confirmBtn) {
            // 🔥 只有当找零为负（付款不足）时才禁用按钮
            // 允许received为0或空（默认刚好付款）
            confirmBtn.disabled = isNaN(change) || change < 0;
        }
    }

    processCashPayment() {
        // 🔥 获取现金收款金额和找零信息
        const cashReceivedInput = document.getElementById('cash-received');
        let total = this.calculateNumericTotal();

        // Apply points discount if available
        if (this.pendingPointsDiscount && this.pendingPointsDiscount.discount) {
            const discountedTotal = Math.round((total - this.pendingPointsDiscount.discount) * 100) / 100;
            total = Math.max(0, discountedTotal);
        }

        let cashReceived = parseFloat(cashReceivedInput?.value);
        if (isNaN(cashReceived) || (cashReceived === 0 && total > 0)) {
            cashReceived = total; // 默认刚好付款
        }
        // 🔥 退货模式：如果总额为负，客户不需要付款，找零就是退款金额
        if (total < 0) {
            cashReceived = isNaN(cashReceived) ? 0 : cashReceived;
        }

        const change = cashReceived - total; // 允许负数change（不使用Math.max）

        this.closeCashPaymentModal();
        this.processPayment('cash', {
            cashReceived: cashReceived,
            change: Math.max(0, change),
            total: total
        });
    }

    processCreditCardPayment() {
        this.closePaymentMethodModal();
        this.processPayment('card');
    }

    processTransferPayment() {
        this.closePaymentMethodModal();
        this.processPayment('transfer');
    }

    processPayment(paymentMethod, paymentDetails = null) {
        // 🔥 防重复锁：如果正在处理支付，忽略重复调用
        if (this._paymentProcessing) {
            console.warn('[POS] Payment already processing, ignoring duplicate call');
            return;
        }
        this._paymentProcessing = true;
        // 3秒后自动解锁（防止死锁）
        setTimeout(() => { this._paymentProcessing = false; }, 3000);

        const checkoutBtn = document.getElementById('checkout-btn');
        if (checkoutBtn) {
            checkoutBtn.disabled = true;
            checkoutBtn.textContent = posTranslations['Processing'] || 'Processing...';
        }

        // 🔥 计算并保存当前订单的支付详情（用于弹窗和上一单显示）
        let orderTotal = this.calculateNumericTotal();
        if (this.pendingPointsDiscount && this.pendingPointsDiscount.discount) {
            orderTotal = Math.max(0, Math.round((orderTotal - this.pendingPointsDiscount.discount) * 100) / 100);
        }

        this.lastOrderPaymentInfo = {
            total: orderTotal,
            paymentMethod: paymentMethod,
            time: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' }),
            timestamp: Date.now()
        };

        // 🔥 保存支付详情
        if (paymentMethod === 'cash' && paymentDetails) {
            this.lastOrderPaymentInfo.cashReceived = paymentDetails.cashReceived || orderTotal;
            this.lastOrderPaymentInfo.change = paymentDetails.change || 0;
        } else if (paymentMethod === 'mixed' && paymentDetails) {
            this.lastOrderPaymentInfo.cashAmount = paymentDetails.cash || 0;
            this.lastOrderPaymentInfo.cardAmount = paymentDetails.card || 0;
        }

        // 🔥 DEBUG: 追踪购物车数据（检查小数数量）
        console.log('[POS DEBUG] Cart items before sending:', this.cart.map(item => ({
            name: item.name,
            quantity: item.quantity,
            quantityType: typeof item.quantity
        })));

        // Prepare the request body
        const params = {
            action: 'ruiyi_pos_ajax',
            pos_action: 'create_order',
            cart_items: JSON.stringify(this.cart),
            payment_method: paymentMethod,
            nonce: ruiyi_pos_ajax.nonce
        };

        // 🔥 DEBUG: 追踪发送的JSON数据
        console.log('[POS DEBUG] cart_items JSON:', params.cart_items);

        // Add mixed payment details if provided
        if (paymentDetails && paymentMethod === 'mixed') {
            params.cash_amount = paymentDetails.cash || 0;
            params.card_amount = paymentDetails.card || 0;
            // Mixed payment prepared
        }

        // Add points information if available
        if (this.pendingPointsDiscount) {
            params.points_user_id = this.pendingPointsDiscount.userId;
            params.points_discount = this.pendingPointsDiscount.discount;
            params.points_used = this.pendingPointsDiscount.pointsUsed;
            params.user_shortcode = this.pendingPointsDiscount.shortcode;
        }

        if (this.pendingPointsReward) {
            params.points_user_id = params.points_user_id || this.pendingPointsReward.userId;
            params.points_reward = this.pendingPointsReward.points;
            params.user_shortcode = params.user_shortcode || this.pendingPointsReward.shortcode;
        }

        // Add customer information if available
        if (this.customerInfo && (this.customerInfo.name || this.customerInfo.phone ||
            this.customerInfo.address || this.customerInfo.company || this.customerInfo.taxId)) {
            params.customer_name = this.customerInfo.name;
            params.customer_phone = this.customerInfo.phone;
            params.customer_address = this.customerInfo.address;
            params.customer_company = this.customerInfo.company;
            params.customer_tax_id = this.customerInfo.taxId;
            // Customer info added
        }

        // ====== 🔥 乐观式结账：立即响应用户，后台同步订单 ======
        // 1. 立即给用户反馈（不等待服务器响应）
        // 2. 打开钱箱（仅现金支付）
        // 3. 清空购物车，准备下一单
        // 4. 在后台排队上传订单到服务器
        // 5. 服务器响应后打印小票（如果启用了自动打印）

        // 🔥 Step 1: 立即反馈用户
        this.showToast(`✅ ${posTranslations['Processing'] || 'Processing'}...`, 'success');

        // 🔥 Step 1.5: 显示交易完成弹窗
        this.showOrderCompleteModal();

        // 🔥 Step 1.6: 更新上一单信息显示
        this.updateLastOrderInfo();

        // 🔥 Step 2: 只有现金支付才打开钱箱
        const shouldOpenDrawer = paymentMethod === 'cash' || paymentMethod === 'mixed';
        if (shouldOpenDrawer && window.clodopConfig && window.clodopConfig.enabled && typeof ruiyiRetailOpenCashDrawer !== 'undefined') {
            ruiyiRetailOpenCashDrawer();
        }

        // Display success message on VFD
        this.sendVFDDisplay('Pago Correcto!', true);
        setTimeout(() => {
            this.sendVFDDisplay('Bienvenido', true);
        }, 2000);

        // 🔥 Step 3: 立即清理状态，准备下一单
        // Clear points data
        this.pendingPointsDiscount = null;
        this.pendingPointsReward = null;

        // Clear the cart from localStorage
        localStorage.removeItem('ruiyi_pos_cart');
        localStorage.removeItem('ruiyi_pos_points_discount');

        // Force client display to update immediately
        localStorage.setItem('ruiyi_pos_cart_cleared', Date.now().toString());

        // Broadcast order completed event
        this.broadcastUpdate('order_completed', {
            cart: [],
            pointsDiscount: null
        });

        // 🔥 Step 4: 立即重置UI并清空购物车
        if (checkoutBtn) {
            checkoutBtn.disabled = false;
            this.resetButtonTexts();
        }

        // OFFLINE SUPPORT: if offline, save as pending and auto-sync when online
        if (!navigator.onLine) {
            console.log('[POS] 📴 OFFLINE MODE - enqueueing payment');
            this.tryEnqueueOfflinePayment(params, { source: 'offline-optimistic', paymentMethod });
            console.log('[POS] ✅ Offline payment enqueued, starting new order');
            // 立即开始新订单
            this.newOrder();
            return;
        }

        // 🔥 Step 5: 在后台异步发送订单到服务器（不阻塞用户操作）
        // 立即开始新订单，让用户可以继续收银
        this.newOrder();

        // 🔥 重置当前订单数据，防止手动打印时打印上一单的小票
        this.currentOrder = null;
        this._pendingManualPrint = false;
        console.log('[POS PRINT DEBUG] ===== processPayment: currentOrder reset to NULL, _pendingManualPrint=false =====');
        console.log('[POS PRINT DEBUG] Cart items discount info:', this.cart.map(i => ({
            name: i.name, price: i.price, originalPrice: i.originalPrice, discountPercent: i.discountPercent, isReturn: i.isReturn
        })));

        // 异步发送订单（不阻塞）
        fetch(ruiyi_pos_ajax.ajax_url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams(params)
        })
        .then(response => response.json())
        .then(data => {
            // 🔥 DEBUG: 追踪服务器响应（检查小数数量）
            if (data.success && data.data && data.data.items) {
                console.log('[POS DEBUG] Server response items:', data.data.items.map(item => ({
                    name: item.name,
                    quantity: item.quantity,
                    quantityType: typeof item.quantity
                })));
            }

            console.log('[POS PRINT DEBUG] ===== AJAX Response =====');
            console.log('[POS PRINT DEBUG] data.success:', data.success);
            console.log('[POS PRINT DEBUG] order_number:', data.data?.order_number);
            console.log('[POS PRINT DEBUG] order total:', data.data?.total);
            console.log('[POS PRINT DEBUG] items count:', data.data?.items?.length);
            console.log('[POS PRINT DEBUG] items discount data:', data.data?.items?.map(i => ({
                name: i.name, unit_price: i.unit_price, original_price: i.original_price, discount_percent: i.discount_percent, quantity: i.quantity, is_return: i.is_return
            })));
            console.log('[POS PRINT DEBUG] _pendingManualPrint before check:', this._pendingManualPrint);

            if (data.success) {
                // 保存订单数据用于手动打印
                this.currentOrder = data.data;
                console.log('[POS PRINT DEBUG] ✅ currentOrder SET to order #' + data.data.order_number);

                // 服务器响应后打印小票（自动打印）
                const autoPrintEnabled = ruiyi_pos_ajax.store_settings && ruiyi_pos_ajax.store_settings.auto_print_receipt;
                const clodopAvailable = window.clodopConfig && window.clodopConfig.enabled && typeof ruiyiRetailUnifiedPrint !== 'undefined';
                console.log('[POS PRINT DEBUG] autoPrint:', autoPrintEnabled, 'clodopAvailable:', clodopAvailable);

                if (autoPrintEnabled && clodopAvailable) {
                    console.log('[POS PRINT DEBUG] 🖨️ Triggering AUTO print');
                    this.printReceipt();
                }

                // 🔥 如果用户在AJAX返回前点了手动打印，现在执行
                if (this._pendingManualPrint) {
                    console.log('[POS PRINT DEBUG] 🖨️ Triggering PENDING MANUAL print');
                    this._pendingManualPrint = false;
                    this.printReceipt();
                }

                // 更新成功提示（显示真实订单号）
                this.showToast(`✅ #${data.data.order_number} ${posTranslations['completed'] || 'completed'}`, 'success');

                // 🔥 弹窗询问是否要创建发票（仅在启用批发商发票功能时显示）
                if (this.wholesaleInvoiceEnabled) {
                    this.showInvoicePromptModal(data.data.order_id, data.data.order_number);
                }

            } else {
                // 订单创建失败 - 显示错误但不阻塞用户
                console.error('[POS PRINT DEBUG] ❌ AJAX returned success=false:', data.data?.message);
                console.error('[POS PRINT DEBUG] ❌ currentOrder remains:', this.currentOrder ? ('order #' + this.currentOrder.order_number) : 'NULL');
                this.showToast(`⚠️ ${data.data?.message || 'Order sync failed'}`, 'error');
            }
        })
        .catch(error => {
            console.error('[POS PRINT DEBUG] ❌ AJAX NETWORK ERROR:', error.message);
            console.error('[POS PRINT DEBUG] ❌ currentOrder remains:', this.currentOrder ? ('order #' + this.currentOrder.order_number) : 'NULL');
            // 网络错误时，尝试排队离线同步
            if (this.tryEnqueueOfflinePayment(params, { source: 'offline-catch-optimistic', paymentMethod })) {
                this.showToast(posTranslations['Saved offline'] || 'Saved offline (will sync when online)', 'warning');
            } else {
                this.showToast(posTranslations['Network error'] || 'Network error', 'error');
            }
        });

    }

    /**
     * Try to enqueue an offline payment. Returns true if queued.
     * Has an inline fallback localStorage queue if OfflinePaymentQueue isn't ready.
     */
    tryEnqueueOfflinePayment(params, options = {}, retries = 5) {
        if (window.OfflinePaymentQueue && typeof window.OfflinePaymentQueue.enqueue === 'function') {
            window.OfflinePaymentQueue.enqueue(params, this, options);
            return true;
        }

        if (retries > 0) {
            // Wait briefly for the queue script to load
            setTimeout(() => this.tryEnqueueOfflinePayment(params, options, retries - 1), 100);
            return true; // assume it will succeed; suppress error toast
        }

        // Fallback: store locally so it's not lost
        try {
            const key = 'ruiyi_pos_pending_orders_fallback';
            const existing = JSON.parse(localStorage.getItem(key) || '[]');
            existing.push({ params, ts: Date.now(), options });
            localStorage.setItem(key, JSON.stringify(existing));
            // light toast to inform user
            if (typeof this.showToast === 'function') {
                this.showToast(posTranslations['Saved offline'] || 'Saved offline (will sync when online)', 'success');
            }
            return true;
        } catch (e) {
            console.warn('[Payment] Fallback local save failed:', e);
            return false;
        }
    }

    showPaymentMethodModal() {
        const modal = document.getElementById('payment-method-modal');
        if (modal) {
            modal.classList.remove('hidden');
        }
    }

    closePaymentMethodModal() {
        const modal = document.getElementById('payment-method-modal');
        if (modal) {
            modal.classList.add('hidden');
        }
        // 🔥 移除支付方式弹窗的键盘监听器
        if (this._paymentKeyHandler) {
            document.removeEventListener('keydown', this._paymentKeyHandler, true);
            this._paymentKeyHandler = null;
        }
        // 🔥 关闭弹窗后聚焦回Varios
        setTimeout(() => this.focusVariosInput(), 100);
    }

    closeCashPaymentModal() {
        const modal = document.getElementById('cash-payment-modal');
        if (modal) {
            modal.classList.add('hidden');
        }
        // 🔥 关闭弹窗后聚焦回Varios
        setTimeout(() => this.focusVariosInput(), 100);
    }

    showMixedPaymentModal() {
        this.closePaymentMethodModal();

        // 🔥 清空Varios输入框并失焦
        const variosInput = document.getElementById('varios-price-input');
        if (variosInput) {
            variosInput.value = '';
            variosInput.blur();
        }

        let total = this.calculateNumericTotal();
        if (this.pendingPointsDiscount && this.pendingPointsDiscount.discount) {
            const discountedTotal = Math.round((total - this.pendingPointsDiscount.discount) * 100) / 100;
            total = Math.max(0, discountedTotal);
        }

        const totalDueEl = document.getElementById('mixed-total-due');
        if (totalDueEl) {
            totalDueEl.textContent = ruiyi_pos_ajax.currency + total.toFixed(2);
        }

        // Reset inputs
        const mixedCashInput = document.getElementById('mixed-cash-amount');
        const mixedCardInput = document.getElementById('mixed-card-amount');
        if (mixedCashInput) {
            mixedCashInput.value = '';
            setTimeout(() => mixedCashInput.focus(), 150);
        }
        if (mixedCardInput) {
            mixedCardInput.value = '';
        }

        const remainingEl = document.getElementById('mixed-remaining');
        if (remainingEl) {
            remainingEl.textContent = ruiyi_pos_ajax.currency + total.toFixed(2);
            remainingEl.className = 'text-2xl font-bold text-red-600';
        }

        const confirmBtn = document.getElementById('confirm-mixed-btn');
        if (confirmBtn) {
            confirmBtn.disabled = true;
        }

        const modal = document.getElementById('mixed-payment-modal');
        if (modal) {
            modal.classList.remove('hidden');
        }
    }

    closeMixedPaymentModal() {
        const modal = document.getElementById('mixed-payment-modal');
        if (modal) {
            modal.classList.add('hidden');
        }

        setTimeout(() => this.focusVariosInput(), 100);
    }

    calculateMixedPayment() {
        let total = this.calculateNumericTotal();
        if (this.pendingPointsDiscount && this.pendingPointsDiscount.discount) {
            const discountedTotal = Math.round((total - this.pendingPointsDiscount.discount) * 100) / 100;
            total = Math.max(0, discountedTotal);
        }

        const cashAmount = parseFloat(document.getElementById('mixed-cash-amount').value) || 0;

        // 🔥 自动计算刷卡金额 = 总额 - 现金金额
        const cardAmount = Math.max(0, total - cashAmount);
        const cardInput = document.getElementById('mixed-card-amount');
        if (cardInput) {
            cardInput.value = cardAmount.toFixed(2);
        }

        const totalPaid = cashAmount + cardAmount;
        const remaining = total - totalPaid;

        const remainingEl = document.getElementById('mixed-remaining');
        const confirmBtn = document.getElementById('confirm-mixed-btn');

        if (remainingEl) {
            remainingEl.textContent = ruiyi_pos_ajax.currency + Math.abs(remaining).toFixed(2);
            if (remaining <= 0.01) { // 允许1分钱的误差
                remainingEl.className = 'text-2xl font-bold text-green-600';
            } else {
                remainingEl.className = 'text-2xl font-bold text-red-600';
            }
        }

        if (confirmBtn) {
            // 🔥 优化验证：现金+刷卡必须大于0，且剩余金额接近0
            confirmBtn.disabled = cashAmount <= 0 || cardAmount <= 0 || Math.abs(remaining) > 0.01;
        }
    }

    processMixedPayment() {
        const cashAmount = parseFloat(document.getElementById('mixed-cash-amount').value) || 0;
        const cardAmount = parseFloat(document.getElementById('mixed-card-amount').value) || 0;

        this.closeMixedPaymentModal();
        this.processPayment('mixed', { cash: cashAmount, card: cardAmount });
    }

