    newOrder() {
        this.clearCart();
        const searchInput = document.getElementById('product-search');

        if (searchInput) searchInput.value = '';

        this.closeModal();

        // 🔥 清空客户信息，准备下一单
        this.customerInfo = {
            name: '',
            phone: '',
            address: '',
            company: '',
            taxId: ''
        };
        // Customer info cleared

        // 🔥 聚焦到Varios输入框而不是搜索框（扫描器就绪）
        setTimeout(() => {
            // 🔥 如果退货弹窗打开，不抢夺焦点
            if (window.isRefundModalOpen) return;
            const variosInput = document.getElementById('varios-price-input');
            if (variosInput && this.shouldFocusVarios()) {
                variosInput.focus();
            }
        }, 100);
    }

    async printReceipt() {
        console.log('[POS PRINT DEBUG] ===== printReceipt() called =====');
        console.log('[POS PRINT DEBUG] currentOrder:', this.currentOrder ? ('order #' + this.currentOrder.order_number + ', total: ' + this.currentOrder.total) : 'NULL');
        console.log('[POS PRINT DEBUG] _pendingManualPrint:', this._pendingManualPrint);
        if (!this.currentOrder) {
            // 🔥 订单数据还没从服务器返回，设置标记等AJAX返回后自动打印
            this._pendingManualPrint = true;
            console.log('[POS PRINT DEBUG] ⏳ currentOrder is NULL, set _pendingManualPrint=true, waiting for AJAX...');
            this.showToast(posTranslations['Receipt not ready'] || 'Preparando ticket, espere...', 'info');
            return;
        }
        if (this.currentOrder) {
            // 在打印前获取Verifactu二维码和发票号码
            const verifactuData = await this.fetchVerifactuQRCode(this.currentOrder.order_id);
            if (verifactuData) {
                this.currentOrder.verifactu_qr_base64 = verifactuData.qr_base64;
                this.currentOrder.invoice_number = verifactuData.invoice_number;
                this.currentOrder.has_verifactu = verifactuData.has_verifactu;
            }

            // Generate receipt HTML
            const receiptHTML = this.generateReceiptHTML(this.currentOrder);

            // 优先使用CLodop打印
            if (typeof ruiyiRetailUnifiedPrint !== 'undefined') {
                // Using CLodop print
                ruiyiRetailUnifiedPrint(receiptHTML, 'order_complete');
                this.showToast(ruiyi_pos_ajax.i18n['Print completed'] || 'Receipt sent to printer', 'success');
                return;
            }

            // 降级到浏览器打印
            // Using browser print

            // Check if browser supports printing
            if (typeof window.print !== 'function') {
                alert('El navegador no soporta la función de impresión. Por favor, use Ctrl+P manualmente.');
                return;
            }

            // Remove any existing print container first
            const existingPrint = document.getElementById('print-receipt');
            if (existingPrint) {
                existingPrint.remove();
            }

            // Create simple print container for thermal receipt
            const printContainer = document.createElement('div');
            printContainer.id = 'print-receipt';
            printContainer.style.display = 'none';

            // Use the current order data for receipt generation (now includes QR code)
            printContainer.innerHTML = receiptHTML;
            document.body.appendChild(printContainer);

            // 等待二维码图片加载完成
            const waitForQRImage = async () => {
                return new Promise((resolve) => {
                    const qrImage = printContainer.querySelector('img[alt="Verifactu QR Code"]');
                    if (!qrImage) {
                        resolve();
                        return;
                    }

                    // 如果图片已加载
                    if (qrImage.complete && qrImage.naturalHeight !== 0) {
                        resolve();
                    } else {
                        // 等待图片加载
                        qrImage.onload = () => {
                            resolve();
                        };
                        qrImage.onerror = () => {
                            resolve(); // Continue even on error
                        };

                        // 设置超时
                        setTimeout(() => {
                            resolve();
                        }, 3000);
                    }
                });
            };

            // 等待图片加载
            await waitForQRImage();

            // Create comprehensive print styles with all formatting included
            const printStyles = document.createElement('style');
            printStyles.type = 'text/css';
            printStyles.media = 'all'; // Apply to all media, not just print
            printStyles.innerHTML = `
                /* Print styles */
                @media print {
                    /* Hide all other content */
                    body * { 
                        visibility: hidden !important; 
                    }
                    #print-receipt, #print-receipt * { 
                        visibility: visible !important; 
                    }
                    #print-receipt { 
                        position: absolute !important; 
                        left: 0 !important; 
                        top: 0 !important; 
                        width: 100% !important; 
                        display: block !important; 
                        background: white !important;
                        color: black !important;
                    }
                    
                    /* Page setup for 80mm thermal receipt */
                    @page {
                        size: 72mm auto;
                        margin: 0.5mm 1mm;
                    }
                    
                    /* Base styles */
                    * {
                        box-sizing: border-box !important;
                        font-family: Tahoma, sans-serif !important;
                        color: #000 !important;
                    }
                    
                    body {
                        margin: 0 !important;
                        padding: 0 !important;
                        font-size: 11pt !important;
                        font-weight: normal !important;
                        line-height: 1.2 !important;
                        -webkit-print-color-adjust: exact !important;
                        print-color-adjust: exact !important;
                        width: 80mm !important;
                    }
                    
                    /* Receipt wrapper */
                    #print-receipt .receipt-wrapper {
                        width: 78mm !important;
                        max-width: 78mm !important;
                        padding: 2mm !important;
                        margin: 0 auto !important;
                        background: white !important;
                        font-family: Tahoma, sans-serif !important;
                        font-weight: normal !important;
                        line-height: 1.3 !important;
                    }
                    
                    /* Store header */
                    #print-receipt .store-header {
                        text-align: center !important;
                        margin-bottom: 8pt !important;
                        border-bottom: 1px solid #000 !important;
                        padding-bottom: 4pt !important;
                    }
                    
                    #print-receipt .store-name {
                        font-size: 16pt !important;
                        font-weight: bold !important;
                        margin: 0 0 4pt 0 !important;
                        text-transform: uppercase !important;
                        letter-spacing: 0.5pt !important;
                        text-align: center !important;
                    }
                    
                    #print-receipt .store-address,
                    #print-receipt .store-phone,
                    #print-receipt .store-tax {
                        font-size: 11pt !important;
                        margin: 2pt 0 !important;
                        line-height: 1.3 !important;
                        font-weight: normal !important;
                        text-align: center !important;
                    }
                    
                    /* Order info */
                    #print-receipt .order-info {
