                    /* Page break handling */
                    #print-receipt { page-break-inside: avoid !important; }
                    #print-receipt * { page-break-inside: avoid !important; }
                }
            `;
            
            document.head.appendChild(printStyles);

            // Show print container and trigger print after DOM is ready
            printContainer.style.display = 'block';

            // Direct print without preview
            this.showToast(ruiyi_pos_ajax.i18n['Printing receipt...'] || 'Imprimiendo recibo...', 'info');

            // Pequeña demora para asegurar que el DOM esté completamente renderizado
            setTimeout(() => {
                // Trigger print
                window.print();
            }, 100);
            
            // Clean up after print dialog closes
            const cleanupPrint = () => {
                printContainer.remove();
                printStyles.remove();
                window.removeEventListener('afterprint', cleanupPrint);
                this.showToast(ruiyi_pos_ajax.i18n['Print completed'] || 'Impresión completada', 'success');
            };
            
            // Listen for print completion
            window.addEventListener('afterprint', cleanupPrint);
            
            // Fallback cleanup in case afterprint doesn't fire
            setTimeout(() => {
                if (printContainer.parentNode) {
                    cleanupPrint();
                }
            }, 10000);
        }
    }

    async printLastOrder() {
        try {
            // 🔥 Check if offline - use saved offline order data
            if (!navigator.onLine) {
                console.log('[Print Last Order] Offline mode detected, looking for offline order...');

                // Try to get last offline order from multiple sources
                let lastOfflineOrder = window.lastOfflineOrder;
                console.log('[Print Last Order] window.lastOfflineOrder:', lastOfflineOrder ? 'found' : 'not found');

                // Try localStorage if not in memory
                if (!lastOfflineOrder) {
                    try {
                        const saved = localStorage.getItem('ruiyi_last_offline_order');
                        console.log('[Print Last Order] localStorage ruiyi_last_offline_order:', saved ? 'found' : 'not found');
                        if (saved) {
                            lastOfflineOrder = JSON.parse(saved);
                        }
                    } catch (e) {
                        console.error('[Print Last Order] Error reading localStorage:', e);
                    }
                }

                // Try to get from pending orders in IndexedDB
                if (!lastOfflineOrder && typeof window.OfflinePaymentQueue !== 'undefined' &&
                    typeof window.OfflinePaymentQueue.list === 'function') {
                    try {
                        const pendingOrders = await window.OfflinePaymentQueue.list();
                        console.log('[Print Last Order] Pending orders from IndexedDB:', pendingOrders?.length || 0);
                        if (pendingOrders && pendingOrders.length > 0) {
                            // Get the most recent pending order
                            const mostRecent = pendingOrders.sort((a, b) => (b.created_at || 0) - (a.created_at || 0))[0];
                            if (mostRecent && mostRecent.orderData) {
                                lastOfflineOrder = mostRecent.orderData;
                                console.log('[Print Last Order] Using orderData from pending order');
                            }
                        }
                    } catch (e) {
                        console.error('[Print Last Order] Error loading pending orders:', e);
                    }
                }

                if (lastOfflineOrder) {
                    console.log('[Print Last Order] Found offline order, printing...');

                    // Use offline print function
                    if (typeof window.OfflinePaymentQueue !== 'undefined' &&
                        typeof window.OfflinePaymentQueue.printOfflineReceipt === 'function') {
                        window.OfflinePaymentQueue.printOfflineReceipt(lastOfflineOrder);
                        return;
                    } else if (typeof window.OfflinePaymentQueue !== 'undefined' &&
                               typeof window.OfflinePaymentQueue.generateOfflineReceiptHTML === 'function') {
                        // Fallback: generate HTML and print directly
                        const receiptHTML = window.OfflinePaymentQueue.generateOfflineReceiptHTML(lastOfflineOrder);
                        if (typeof ruiyiRetailUnifiedPrint !== 'undefined') {
                            ruiyiRetailUnifiedPrint(receiptHTML, 'reprint_offline_order');
                            this.showToast(posTranslations['Print completed'] || 'Receipt sent to printer', 'success');
                            return;
                        }
                    }

                    // Last resort: try direct CLodop print with basic HTML
                    if (typeof ruiyiRetailUnifiedPrint !== 'undefined') {
                        const basicHTML = this.generateOfflineReceiptHTMLFallback(lastOfflineOrder);
                        ruiyiRetailUnifiedPrint(basicHTML, 'reprint_offline_order');
                        this.showToast(posTranslations['Print completed'] || 'Receipt sent to printer', 'success');
                        return;
                    }
                }

                // No offline order available
                console.log('[Print Last Order] No offline order found');
                this.showToast(posTranslations['No offline order'] || 'No hay pedido offline disponible para imprimir', 'warning');
                return;
            }

            // 🔥 Online mode: fetch from server
            // Show loading indicator
            this.showToast(posTranslations['Loading last order'] || 'Loading last order...', 'info');

            // Fetch the last completed order from the database
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'get_last_order',
                    nonce: ruiyi_pos_ajax.nonce
                })
            });

            const data = await response.json();

            if (!data.success) {
                this.showToast(data.data?.message || posTranslations['No order found'] || 'No order found to print', 'error');
                return;
            }

            const lastOrder = data.data;

            if (!lastOrder || !lastOrder.order_id) {
                this.showToast(posTranslations['No order found'] || 'No order found to print', 'error');
                return;
            }

            // Fetch Verifactu QR code and invoice number for the last order
            const verifactuData = await this.fetchVerifactuQRCode(lastOrder.order_id);
            if (verifactuData) {
                lastOrder.verifactu_qr_base64 = verifactuData.qr_base64;
                lastOrder.invoice_number = verifactuData.invoice_number;
                lastOrder.has_verifactu = verifactuData.has_verifactu;
            }

            // Generate receipt HTML
            const receiptHTML = this.generateReceiptHTML(lastOrder);

            // Use CLodop printing if available
            if (typeof ruiyiRetailUnifiedPrint !== 'undefined') {
                ruiyiRetailUnifiedPrint(receiptHTML, 'reprint_order');
                this.showToast(posTranslations['Print completed'] || 'Receipt sent to printer', 'success');
                return;
            }

            // Fallback to browser printing

            // Remove existing print container
            const existingPrint = document.getElementById('print-receipt');
            if (existingPrint) {
                existingPrint.remove();
            }

            // Create print container
            const printContainer = document.createElement('div');
            printContainer.id = 'print-receipt';
            printContainer.style.display = 'none';
            printContainer.innerHTML = receiptHTML;
            document.body.appendChild(printContainer);

            // Wait for QR image to load
            const waitForQRImage = async () => {
                return new Promise((resolve) => {
                    const qrImage = printContainer.querySelector('img[alt="Verifactu QR Code"]');
                    if (!qrImage) {
                        resolve();
                        return;
                    }

                    if (qrImage.complete && qrImage.naturalHeight !== 0) {
                        resolve();
                    } else {
                        qrImage.onload = () => resolve();
                        qrImage.onerror = () => resolve();
                        setTimeout(() => resolve(), 3000);
                    }
                });
            };

            await waitForQRImage();

            // Create print styles
            const printStyles = document.createElement('style');
            printStyles.type = 'text/css';
            printStyles.media = 'all';
            printStyles.innerHTML = `
                @media print {
                    body * { visibility: hidden !important; }
                    #print-receipt, #print-receipt * { visibility: visible !important; }
                    #print-receipt {
                        position: absolute !important;
                        left: 0 !important;
                        top: 0 !important;
                        width: 100% !important;
                        display: block !important;
                    }
                }
            `;
            document.head.appendChild(printStyles);

            // Trigger browser print
            setTimeout(() => {
                window.print();
            }, 500);

            // Cleanup after printing
            const cleanupPrint = () => {
                if (printContainer.parentNode) {
                    printContainer.remove();
                }
                if (printStyles.parentNode) {
                    printStyles.remove();
                }
                window.removeEventListener('afterprint', cleanupPrint);
                this.showToast(posTranslations['Print completed'] || 'Print completed', 'success');
            };

            window.addEventListener('afterprint', cleanupPrint);
            setTimeout(() => {
                if (printContainer.parentNode) {
                    cleanupPrint();
                }
            }, 10000);

        } catch (error) {
            console.error('[Print Last Order] Error:', error);
            this.showToast(posTranslations['Print failed'] || 'Failed to print last order', 'error');
        }
    }

    // Preview functionality removed

    // Fallback function to generate offline receipt HTML when OfflinePaymentQueue is not available
    generateOfflineReceiptHTMLFallback(orderData) {
        const storeSettings = ruiyi_pos_ajax.store_settings || {};
        const storeName = orderData.store_name || storeSettings.store_name || 'TIENDA';
        const storeAddress = orderData.store_address || storeSettings.store_address || '';
        const storePhone = orderData.store_phone || storeSettings.store_phone || '';
        const storeTaxNumber = orderData.store_tax_number || storeSettings.store_tax_number || '';
        const receiptFooter = storeSettings.receipt_footer || 'GRACIAS POR TU PEDIDO!';

        const orderDate = new Date(orderData.date || Date.now());
        const dateStr = orderDate.toLocaleDateString('es-ES');
        const timeStr = orderDate.toLocaleTimeString('es-ES', { hour12: false });

        const invoiceNumber = orderData.invoice_number || (orderData.order_number || '').replace('OFF-', '');

        let itemsHtml = '';
        if (orderData.items && orderData.items.length > 0) {
            orderData.items.forEach(item => {
                const itemTotal = (item.price || 0) * (item.quantity || 1);
                itemsHtml += `<div class="item-line"><div class="item-desc">${item.name} <span class="item-quantity">x${item.quantity}</span></div><div class="item-price">${itemTotal.toFixed(2)}€</div></div>`;
            });
        }

        const total = orderData.total || 0;
        const taxAmount = total - (total / 1.21);

        return `
            <div class="receipt-wrapper">
                <div class="store-header">
                    <div class="store-name">${storeName}</div>
                    ${storeAddress ? `<div class="store-address">${storeAddress}</div>` : ''}
                    ${storePhone ? `<div class="store-phone">${storePhone}</div>` : ''}
                    ${storeTaxNumber ? `<div class="store-tax">CIF: ${storeTaxNumber}</div>` : ''}
                </div>
                <div class="order-info">
                    <div class="invoice-number verifactu-invoice-number">Factura simplificada: ${invoiceNumber}</div>
                    ${orderData.order_id ? `<div class="order-number">Nº Pedido: ${orderData.order_id}</div>` : ''}
                    <div class="date-time">Fecha: ${dateStr}</div>
                    <div class="date-time">Hora: ${timeStr}</div>
                </div>
                <div class="items-section">
                    <div class="items-header">PRODUCTOS</div>
                    ${itemsHtml}
                </div>
                <div class="totals-section">
                    <div class="total-line subtotal-line"><span>Subtotal:</span><span class="currency">${(orderData.subtotal || total).toFixed(2)}€</span></div>
                    <div class="total-line vat-line"><span>IVA (21%):</span><span class="currency">${taxAmount.toFixed(2)}€</span></div>
                    <div class="total-line total-final"><span>TOTAL:</span><span class="currency">${total.toFixed(2)}€</span></div>
                </div>
                <div class="receipt-footer">
                    <div class="thank-you">${receiptFooter}</div>
                </div>
            </div>
        `;
    }

    generateReceiptHTML(order) {
        const currentDate = new Date();
        const dateStr = currentDate.toLocaleDateString('es-ES', { 
            year: 'numeric',
            month: '2-digit', 
            day: '2-digit' 
        });
        const timeStr = currentDate.toLocaleTimeString('es-ES', { 
            hour12: false,
            hour: '2-digit', 
            minute: '2-digit', 
            second: '2-digit' 
        });
        
        // Get store settings
        const storeSettings = ruiyi_pos_ajax.store_settings || {};
        const businessName = storeSettings.business_name || '';
        const storeName = storeSettings.store_name || ruiyi_pos_ajax.site_name || 'Store Name';
        const storeAddress = storeSettings.store_address || '';
        const storePhone = storeSettings.store_phone || '';
        const receiptFooter = storeSettings.receipt_footer || 'GRACIAS POR TU PEDIDO!';

        // Generate receipt HTML matching updated CSS structure
        return `
            <div class="receipt-wrapper">
                <!-- Store Header - Centered -->
                <div class="store-header">
                    ${businessName ? `<div class="business-name">${businessName}</div>` : ''}
                    <div class="store-name">${storeName}</div>
                    ${storeAddress ? `<div class="store-address">${storeAddress}</div>` : ''}
                    ${storePhone ? `<div class="store-phone">${storePhone}</div>` : ''}
                    ${storeSettings.store_tax_number ? `<div class="store-tax">CIF: ${storeSettings.store_tax_number}</div>` : ''}
                </div>
                
                <!-- Order Info - Left aligned -->
                <div class="order-info">
                    ${order.invoice_number ? `<div class="invoice-number verifactu-invoice-number" data-invoice-number="${order.invoice_number}">${order.invoice_number}</div>` : ''}
                    ${order.order_id ? `<div class="order-number">Nº Pedido: ${order.order_id}</div>` : ''}
                    <div class="date-time">Fecha: ${dateStr}</div>
                    <div class="date-time">Hora: ${timeStr}</div>
                    <div class="cashier-name">Cajero: ${order.cashier}</div>
                </div>

                <!-- Customer Information - Only show if data exists -->
                ${this.generateCustomerInfo(order)}

                <!-- Items List - Simple format -->
                <div class="items-section">
                    <div class="items-header">PRODUCTOS</div>
                    ${this.generateReceiptItems(order)}
                </div>
                
                <!-- Totals - Right aligned amounts -->
                <div class="totals-section">
                    <div class="total-line subtotal-line">
                        <span>Subtotal:</span>
                        <span class="currency">${order.formatted_subtotal}</span>
                    </div>
                    ${this.generateDiscountLines(order)}
                    ${order.points_used && order.points_used > 0 ? `
                    <div class="total-line points-discount-line">
                        <span>Descuento Puntos (${order.points_used}pts):</span>
                        <span class="currency">-${order.formatted_points_discount}</span>
                    </div>` : ''}
                    ${this.generateTaxBreakdown(order)}
                    <div class="total-line total-final">
                        <span>TOTAL:</span>
                        <span class="currency">${order.formatted_total}</span>
                    </div>
                </div>
                
                <!-- Footer - Centered -->
                <div class="receipt-footer">
                    ${storeSettings.return_policy ? `<div class="return-policy">${storeSettings.return_policy}</div>` : ''}
                    <div class="thank-you">${receiptFooter}</div>
                </div>

                <!-- Verifactu QR Code Section -->
                <div style="border-top: 1px dashed #000; margin: 6pt 0;"></div>
                <div style="text-align: center; font-size: 12pt; font-weight: bold; margin-bottom: 3pt;">VERIFACTU QR</div>
                ${order && order.verifactu_qr_base64 ? `
                <div style="text-align: center; margin: 6pt 0;">
                    <img src="data:image/png;base64,${order.verifactu_qr_base64}"
                         alt="Verifactu QR Code"
                         style="width: 150px; height: 150px; margin: 0 auto; display: block; border: 1px solid #000; image-rendering: pixelated; image-rendering: -moz-crisp-edges; image-rendering: crisp-edges;">
                </div>
                ` : `
                <div style="text-align: center; margin: 6pt 0; font-size: 10pt; color: #999;">
                    QR Code not available
                </div>
                `}
                <div style="text-align: center; font-size: 11pt; margin-top: 4pt; font-weight: normal;">
                    Escanear para verificar factura
                </div>
            </div>
        `;
    }

    // Helper function to generate customer information section
    generateCustomerInfo(order) {
        // Check if any customer information exists
        const hasCustomerInfo = order.customer_name || order.customer_phone ||
                               order.customer_address || order.customer_company ||
                               order.customer_tax_id;

        if (!hasCustomerInfo) {
            return '';
        }

        let customerHTML = '<div style="border-top: 1px dashed #000; margin: 6pt 0;"></div>';
        customerHTML += '<div style="text-align: left; font-size: 11pt; font-weight: bold; margin-bottom: 3pt;">Datos cliente:</div>';
        customerHTML += '<div style="text-align: left; font-size: 10pt; line-height: 1.4;">';

        if (order.customer_name) {
            customerHTML += `<div>Nombre: ${order.customer_name}</div>`;
        }
        if (order.customer_phone) {
            customerHTML += `<div>Teléfono: ${order.customer_phone}</div>`;
        }
        if (order.customer_address) {
            customerHTML += `<div>Dirección: ${order.customer_address}</div>`;
        }
        if (order.customer_company) {
            customerHTML += `<div>Empresa: ${order.customer_company}</div>`;
        }
        if (order.customer_tax_id) {
            customerHTML += `<div>CIF/NIF: ${order.customer_tax_id}</div>`;
        }

        customerHTML += '</div>';
        customerHTML += '<div style="border-bottom: 1px dashed #000; margin: 6pt 0;"></div>';

        return customerHTML;
    }

    // Helper function to generate payment info
    getPaymentInfo(order) {
        if (order.payment_method === 'cash' && order.amount_paid > 0) {
            return `
                <p class="amount">Importe Pagado: <strong>${this.formatPrice(order.amount_paid)}</strong></p>
                ${order.change > 0 ? `<p class="amount">Cambio: <strong>${order.formatted_change}</strong></p>` : ''}
            `;
        }
        return '';
    }

    // 🔥 显示交易完成弹窗
    showOrderCompleteModal() {
        // 🔥 检查功能是否启用
        if (!this.lastOrderDisplayEnabled) return;

        const modal = document.getElementById('order-complete-modal');
        if (!modal || !this.lastOrderPaymentInfo) return;

        const currency = ruiyi_pos_ajax.currency || '€';
        const info = this.lastOrderPaymentInfo;
        const isReturn = info.total < 0;

        // 🔥 退货模式：更新图标和标题
        const iconContainer = modal.querySelector('.rounded-full');
        const titleEl = modal.querySelector('h3');
        if (iconContainer) {
            if (isReturn) {
                iconContainer.className = 'mx-auto flex items-center justify-center h-20 w-20 rounded-full bg-red-100 mb-6';
                iconContainer.innerHTML = '<svg class="h-12 w-12 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 10h10a5 5 0 015 5v2M3 10l4-4M3 10l4 4"/></svg>';
            } else {
                iconContainer.className = 'mx-auto flex items-center justify-center h-20 w-20 rounded-full bg-green-100 mb-6';
                iconContainer.innerHTML = '<svg class="h-12 w-12 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg>';
            }
        }
        if (titleEl) {
            titleEl.textContent = isReturn
                ? (posTranslations['Return Complete'] || '退货完成')
                : (posTranslations['Transaction Complete'] || '交易完成');
        }

        // 🔥 更新总额标签和金额
        const totalEl = document.getElementById('oc-total');
        const totalRow = totalEl ? totalEl.closest('.flex') : null;
        const totalLabel = totalRow ? totalRow.querySelector('.text-gray-600') : null;
        if (totalLabel) {
            totalLabel.textContent = isReturn
                ? (posTranslations['Refund Amount'] || '退款金额')
                : 'Total';
        }
        if (totalEl) {
            if (isReturn) {
                totalEl.textContent = '-' + currency + Math.abs(info.total).toFixed(2);
                totalEl.className = 'text-2xl font-bold text-red-600';
            } else {
                totalEl.textContent = currency + info.total.toFixed(2);
                totalEl.className = 'text-2xl font-bold text-gray-900';
            }
        }

        // 更新支付方式
        const methodEl = document.getElementById('oc-payment-method');
        const cashDetails = document.getElementById('oc-cash-details');
        const mixedDetails = document.getElementById('oc-mixed-details');

        // 隐藏所有详情区域
        if (cashDetails) cashDetails.classList.add('hidden');
        if (mixedDetails) mixedDetails.classList.add('hidden');

        // 支付方式名称翻译
        const methodNames = {
            'cash': posTranslations['Cash'] || 'Efectivo',
            'card': posTranslations['Card'] || 'Tarjeta',
            'transfer': posTranslations['Transfer'] || 'Transferencia',
            'mixed': posTranslations['Mixed'] || 'Mixto'
        };

        if (methodEl) {
            methodEl.textContent = methodNames[info.paymentMethod] || info.paymentMethod;
        }

        // 根据支付方式显示详情
        if (info.paymentMethod === 'cash' && cashDetails) {
            cashDetails.classList.remove('hidden');
            const receivedEl = document.getElementById('oc-cash-received');
            const changeEl = document.getElementById('oc-change');
            const changeRow = changeEl ? changeEl.closest('.flex') : null;
            const changeLabel = changeRow ? changeRow.querySelector('span:first-child') : null;

            if (isReturn) {
                // 退货现金：显示退款金额
                if (receivedEl) {
                    receivedEl.textContent = currency + '0.00';
                }
                if (changeLabel) {
                    changeLabel.textContent = posTranslations['Refund'] || '退款';
                    changeLabel.className = 'text-red-700 font-medium';
                }
                if (changeEl) {
                    changeEl.textContent = currency + Math.abs(info.total).toFixed(2);
                    changeEl.className = 'text-xl font-bold text-red-600';
                }
                if (changeRow) {
                    changeRow.className = 'flex justify-between items-center bg-red-50 -mx-2 px-2 py-2 rounded-lg';
                }
            } else {
                if (receivedEl) receivedEl.textContent = currency + (info.cashReceived || info.total).toFixed(2);
                if (changeLabel) {
                    changeLabel.textContent = posTranslations['Change'] || '找零';
                    changeLabel.className = 'text-green-700 font-medium';
                }
                if (changeEl) {
                    changeEl.textContent = currency + (info.change || 0).toFixed(2);
                    changeEl.className = 'text-xl font-bold text-green-600';
                }
                if (changeRow) {
                    changeRow.className = 'flex justify-between items-center bg-green-50 -mx-2 px-2 py-2 rounded-lg';
                }
            }
        } else if (info.paymentMethod === 'mixed' && mixedDetails) {
            mixedDetails.classList.remove('hidden');
            const mixedCashEl = document.getElementById('oc-mixed-cash');
            const mixedCardEl = document.getElementById('oc-mixed-card');
            if (mixedCashEl) mixedCashEl.textContent = currency + (info.cashAmount || 0).toFixed(2);
            if (mixedCardEl) mixedCardEl.textContent = currency + (info.cardAmount || 0).toFixed(2);
        }

        // 显示弹窗
        modal.classList.remove('hidden');

        // 🔥 添加键盘监听器（按任意键关闭）
        this._orderCompleteKeyHandler = (e) => {
            this.closeOrderCompleteModal();
        };
        document.addEventListener('keydown', this._orderCompleteKeyHandler, { once: true });
    }

    // 🔥 关闭交易完成弹窗
    closeOrderCompleteModal() {
        const modal = document.getElementById('order-complete-modal');
        if (modal) {
            modal.classList.add('hidden');
        }

        // 移除键盘监听器
        if (this._orderCompleteKeyHandler) {
            document.removeEventListener('keydown', this._orderCompleteKeyHandler);
            this._orderCompleteKeyHandler = null;
        }

        // 聚焦回Varios输入框
        setTimeout(() => this.focusVariosInput(), 100);
    }

    // 🔥 查看历史订单详情
    async viewOrderDetails(orderId) {
        this.currentViewOrderId = orderId;
        const modal = document.getElementById('order-details-modal');
        if (!modal) return;

        // Show loading state
        const itemsBody = document.getElementById('od-items-body');
        const paymentDetails = document.getElementById('od-payment-details');
        if (itemsBody) itemsBody.innerHTML = '<tr><td colspan="4" class="text-center py-4 text-gray-500">Loading...</td></tr>';
        if (paymentDetails) paymentDetails.innerHTML = '<div class="text-center py-4 text-gray-500">Loading...</div>';

        modal.classList.remove('hidden');

        try {
            const formData = new URLSearchParams({
                action: 'ruiyi_pos_ajax',
                pos_action: 'get_full_order_details',
                order_id: orderId,
                nonce: ruiyi_pos_ajax.nonce
            });

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                body: formData
            });

            const data = await response.json();

            if (data.success) {
                this.renderOrderDetailsModal(data.data.order);
            } else {
                this.showToast(data.data?.message || 'Failed to load order', 'error');
                modal.classList.add('hidden');
            }
        } catch (error) {
            console.error('Error loading order details:', error);
            this.showToast('Failed to load order details', 'error');
            modal.classList.add('hidden');
        }
    }

    // 🔥 渲染订单详情弹窗 (简化版 - 只显示商品明细)
    renderOrderDetailsModal(order) {
        // Order number
        document.getElementById('od-order-number').textContent = order.invoice_label || `#${order.number}`;

        // Items table
        const itemsBody = document.getElementById('od-items-body');
        let itemsHtml = '';
        order.items.forEach(item => {
            itemsHtml += `
                <tr>
                    <td class="px-3 py-3">
                        <div class="font-medium text-gray-900">${item.name}</div>
                        ${item.sku ? `<div class="text-xs text-gray-500">SKU: ${item.sku}</div>` : ''}
                    </td>
                    <td class="text-center px-3 py-3 text-gray-700">${item.quantity}</td>
                    <td class="text-right px-3 py-3 text-gray-700">${item.price}</td>
                    <td class="text-right px-3 py-3 font-medium text-gray-900">${item.subtotal}</td>
                </tr>
            `;
        });
        itemsBody.innerHTML = itemsHtml;

        // Total
        document.getElementById('od-total').textContent = order.total;
    }

    // 🔥 关闭订单详情弹窗
    closeOrderDetailsModal() {
        const modal = document.getElementById('order-details-modal');
        if (modal) {
            modal.classList.add('hidden');
        }
        this.currentViewOrderId = null;
    }

    // 🔥 打印历史订单小票
    async printHistoricalReceipt(orderId) {
        if (!orderId) {
            this.showToast('Invalid order ID', 'error');
            return;
        }

        const locale = document.documentElement.lang || 'en';
        this.showToast(
            locale.includes('zh') ? '正在准备打印...' :
            locale.includes('es') ? 'Preparando impresión...' :
            'Preparing to print...',
            'info'
        );

        try {
            // Fetch full order data for receipt
            const formData = new URLSearchParams({
                action: 'ruiyi_pos_ajax',
                pos_action: 'get_order_receipt_data',
                order_id: orderId,
                nonce: ruiyi_pos_ajax.nonce
            });

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                body: formData
            });

            const data = await response.json();

            if (!data.success) {
                throw new Error(data.data?.message || 'Failed to get order data');
            }

            const orderData = data.data.order;

            // Fetch Verifactu QR code if available
            const verifactuData = await this.fetchVerifactuQRCode(orderId);
            if (verifactuData) {
                orderData.verifactu_qr_base64 = verifactuData.qr_base64;
                orderData.invoice_number = verifactuData.invoice_number;
                orderData.has_verifactu = verifactuData.has_verifactu;
            }

            // Generate receipt HTML
            const receiptHTML = this.generateReceiptHTML(orderData);

            // Use CLodop printing if available
            if (typeof ruiyiRetailUnifiedPrint !== 'undefined') {
                ruiyiRetailUnifiedPrint(receiptHTML, 'reprint_order');
                this.showToast(ruiyi_pos_ajax.i18n['Print completed'] || 'Receipt sent to printer', 'success');
            } else {
                // Fallback to window print
                const printWindow = window.open('', '_blank', 'width=300,height=600');
                printWindow.document.write(receiptHTML);
                printWindow.document.close();
                printWindow.onload = () => {
                    printWindow.print();
                    printWindow.close();
                };
            }
        } catch (error) {
            console.error('Error printing historical receipt:', error);
            this.showToast(
                locale.includes('zh') ? '打印失败' :
                locale.includes('es') ? 'Error de impresión' :
                'Print failed',
                'error'
            );
        }
    }

    // 🔥 更新上一单信息显示
    updateLastOrderInfo() {
        // 🔥 检查功能是否启用
        if (!this.lastOrderDisplayEnabled) return;

        const container = document.getElementById('last-order-info');
        if (!container || !this.lastOrderPaymentInfo) return;

        const currency = ruiyi_pos_ajax.currency || '€';
        const info = this.lastOrderPaymentInfo;

        // 显示容器
        container.classList.remove('hidden');

        // 更新时间
        const timeEl = document.getElementById('last-order-time');
        if (timeEl) {
            timeEl.textContent = info.time;
        }

        // 更新总额
        const totalEl = document.getElementById('last-order-total');
        if (totalEl) {
            totalEl.textContent = currency + info.total.toFixed(2);
        }

        // 更新支付详情
        const detailsEl = document.getElementById('last-order-payment-details');
        if (detailsEl) {
            const methodNames = {
                'cash': posTranslations['Cash'] || 'Efectivo',
                'card': posTranslations['Card'] || 'Tarjeta',
                'transfer': posTranslations['Transfer'] || 'Transferencia',
                'mixed': posTranslations['Mixed'] || 'Mixto'
            };

            let detailsHtml = '';

            if (info.paymentMethod === 'cash') {
                detailsHtml = `
                    <div class="flex justify-between items-center py-1">
                        <span class="text-gray-600">${methodNames['cash']}</span>
                        <span class="text-lg font-bold text-gray-800">${currency}${(info.cashReceived || info.total).toFixed(2)}</span>
                    </div>
                    <div class="flex justify-between items-center py-1 border-t border-green-200">
                        <span class="text-green-700 font-medium">${posTranslations['Change'] || 'Cambio'}</span>
                        <span class="text-xl font-black text-green-600">${currency}${(info.change || 0).toFixed(2)}</span>
                    </div>
                `;
            } else if (info.paymentMethod === 'mixed') {
                detailsHtml = `
                    <div class="flex justify-between items-center py-1">
                        <span class="text-gray-600">${methodNames['cash']}</span>
                        <span class="text-lg font-bold text-green-600">${currency}${(info.cashAmount || 0).toFixed(2)}</span>
                    </div>
                    <div class="flex justify-between items-center py-1 border-t border-blue-200">
                        <span class="text-gray-600">${methodNames['card']}</span>
                        <span class="text-lg font-bold text-blue-600">${currency}${(info.cardAmount || 0).toFixed(2)}</span>
                    </div>
                `;
            } else {
                detailsHtml = `
                    <div class="flex justify-between items-center py-1">
                        <span class="text-gray-600">${posTranslations['Payment Method'] || 'Método de pago'}</span>
                        <span class="text-lg font-bold text-blue-600">${methodNames[info.paymentMethod] || info.paymentMethod}</span>
                    </div>
                `;
            }

            detailsEl.innerHTML = detailsHtml;
        }
    }

    closeModal() {
        // Close all modals (except order-complete-modal which is user-dismissable)
        const successModal = document.getElementById('success-modal');
        const paymentMethodModal = document.getElementById('payment-method-modal');
        const cashPaymentModal = document.getElementById('cash-payment-modal');
        const holdOrderModal = document.getElementById('hold-order-modal');
        const heldOrdersModal = document.getElementById('held-orders-modal');
        // 🔥 不关闭 order-complete-modal，由用户点击或按键关闭

        if (successModal) successModal.classList.add('hidden');
        if (paymentMethodModal) paymentMethodModal.classList.add('hidden');
        if (cashPaymentModal) cashPaymentModal.classList.add('hidden');
        if (holdOrderModal) holdOrderModal.classList.add('hidden');
        if (heldOrdersModal) heldOrdersModal.classList.add('hidden');
        // 🔥 关闭弹窗后聚焦回Varios
        setTimeout(() => this.focusVariosInput(), 100);
    }

    focusSearch() {
        const searchInput = document.getElementById('product-search');
        if (searchInput) searchInput.focus();
    }

    updateTime() {
        const now = new Date();
        const dateEl = document.getElementById('current-date');
        const timeEl = document.getElementById('current-time');
        
        if (dateEl) {
            dateEl.textContent = now.toLocaleDateString('en-US', {
                year: 'numeric',
                month: 'long',
                day: 'numeric'
            });
        }
        
        if (timeEl) {
            timeEl.textContent = now.toLocaleTimeString('en-US', {
                hour12: false,
                hour: '2-digit',
                minute: '2-digit'
            });
        }
    }

    showToast(message, type = 'info') {
        // 只显示错误和警告类型的通知，禁用成功和信息类通知（避免干扰）
        if (type === 'success' || type === 'info') {
            return;
        }

        const container = document.getElementById('toast-container');
        if (!container) return;

        const toast = document.createElement('div');
        
        const colors = {
            success: 'bg-green-600 border-green-500',
            error: 'bg-red-600 border-red-500',
            info: 'bg-blue-600 border-blue-500',
            warning: 'bg-yellow-600 border-yellow-500'
        };
        
        toast.className = `${colors[type]} text-white px-4 py-3 rounded-lg shadow-xl border-l-4 flex items-center space-x-2 transform transition-all duration-300 -translate-x-full opacity-0 min-w-[320px] max-w-[400px]`;
        const icons = {
            success: '<svg class="w-5 h-5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"></path></svg>',
            error: '<svg class="w-5 h-5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clip-rule="evenodd"></path></svg>',
            info: '<svg class="w-5 h-5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clip-rule="evenodd"></path></svg>',
            warning: '<svg class="w-5 h-5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clip-rule="evenodd"></path></svg>'
        };
        
        toast.innerHTML = `
            ${icons[type]}
            <span class="font-medium flex-1">${message}</span>
            <button onclick="this.parentElement.classList.add('-translate-x-full', 'opacity-0'); setTimeout(() => { if(this.parentElement.parentNode) this.parentElement.remove(); }, 300);" class="ml-2 text-xl leading-none hover:text-gray-200 opacity-80 hover:opacity-100">&times;</button>
        `;
        
        container.appendChild(toast);
        
        setTimeout(() => {
            toast.classList.remove('-translate-x-full', 'opacity-0');
        }, 100);
        
        // Auto-remove after 4 seconds with smooth animation
        setTimeout(() => {
            if (toast.parentNode) {
                toast.classList.add('-translate-x-full', 'opacity-0');
                setTimeout(() => {
                    if (toast.parentNode) {
                        toast.remove();
                    }
                }, 300);
            }
        }, 4000);
    }

    /**
     * 🔥 显示成功提示弹窗（强制显示，用于重要操作的成功提示）
     * @param {string} message - 提示消息
     * @param {number} duration - 显示时间（毫秒），默认1500ms
     */
    showSuccessPopup(message, duration = 1500) {
        // 创建弹窗容器
        const popup = document.createElement('div');
        popup.className = 'fixed inset-0 flex items-center justify-center z-[9999] pointer-events-none';
        popup.innerHTML = `
            <div class="bg-green-600 text-white px-8 py-4 rounded-xl shadow-2xl transform transition-all duration-300 scale-0 opacity-0 flex items-center space-x-3">
                <svg class="w-8 h-8 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
                    <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"></path>
                </svg>
                <span class="text-xl font-semibold">${message}</span>
            </div>
        `;

        document.body.appendChild(popup);
        const popupContent = popup.querySelector('div');

        // 显示动画
        setTimeout(() => {
            popupContent.classList.remove('scale-0', 'opacity-0');
            popupContent.classList.add('scale-100', 'opacity-100');
        }, 10);

        // 自动关闭
        setTimeout(() => {
            popupContent.classList.remove('scale-100', 'opacity-100');
            popupContent.classList.add('scale-0', 'opacity-0');
            setTimeout(() => {
                if (popup.parentNode) {
                    popup.remove();
                }
            }, 300);
        }, duration);
    }

    // Points Management Methods
    showPointsManagementModal() {
        this.closePaymentMethodModal();

        // 🔥 清空Varios输入框并失焦
        const variosInput = document.getElementById('varios-price-input');
        if (variosInput) {
            variosInput.value = '';
            variosInput.blur();
        }

        const modal = document.getElementById('points-management-modal');
        if (modal) {
            modal.classList.remove('hidden');
            this.initPointsManagement();
        }
        this.showToast(posTranslations['Points management selected'] || 'Points management selected', 'info');
    }

    initPointsManagement() {
        // Initialize tab functionality
        const tabButtons = document.querySelectorAll('.tab-button');
        const tabPanels = document.querySelectorAll('.tab-panel');
        
        tabButtons.forEach(button => {
            button.addEventListener('click', () => {
                // Remove active class from all tabs
                tabButtons.forEach(btn => btn.classList.remove('active'));
                tabPanels.forEach(panel => panel.classList.add('hidden'));
                
                // Add active class to clicked tab
                button.classList.add('active');
                const targetPanel = document.getElementById(`${button.dataset.tab}-panel`);
                if (targetPanel) {
                    targetPanel.classList.remove('hidden');
                }
            });
        });

        // Cancel button
        const cancelBtn = document.getElementById('cancel-points-btn');
        if (cancelBtn) {
            cancelBtn.addEventListener('click', () => {
                this.closePointsManagementModal();
                this.showPaymentMethodModal();
            });
        }

        // Initialize discount tab
        this.initPointsDiscountTab();
        
        // Initialize reward tab
        this.initPointsRewardTab();
        
        // Check and display current applied states
        this.updatePointsManagementState();
    }
    
    updatePointsManagementState() {
        // Update discount tab state if discount is applied
        if (this.pendingPointsDiscount && this.pendingPointsDiscount.discount > 0) {
            const discountBtn = document.getElementById('apply-points-discount');
            const discountStatus = document.getElementById('discount-status');
            
            if (discountBtn) {
                discountBtn.disabled = true;
                discountBtn.textContent = posTranslations['Points Applied'] || 'Points Applied';
                discountBtn.classList.add('opacity-50', 'cursor-not-allowed');
            }
            
            if (discountStatus) {
                const appliedText = (posTranslations['Applied: %s discount'] || 'Applied: %s discount').replace('%s', this.formatPrice(this.pendingPointsDiscount.discount));
                discountStatus.textContent = appliedText;
                discountStatus.className = 'text-sm text-green-600 mb-4';
            }
        }
        
        // Update reward tab state if reward is pending
        if (this.pendingPointsReward && this.pendingPointsReward.points > 0) {
            const rewardBtn = document.getElementById('apply-points-reward');
            const rewardPoints = document.getElementById('reward-points');
            const rewardCalculation = document.getElementById('reward-calculation');
            
            if (rewardBtn) {
                rewardBtn.disabled = true;
                rewardBtn.textContent = posTranslations['Reward Confirmed'] || 'Reward Confirmed';
                rewardBtn.classList.add('opacity-50', 'cursor-not-allowed');
            }
            
            if (rewardPoints) {
                rewardPoints.textContent = this.pendingPointsReward.points;
                rewardPoints.className = 'text-3xl font-bold text-green-600';
            }
            
            if (rewardCalculation) {
                rewardCalculation.textContent = posTranslations['Reward confirmed and will be applied after payment'] || 'Reward confirmed and will be applied after payment';
                rewardCalculation.className = 'text-xs text-green-600 mt-2';
            }
        }
    }

    initPointsDiscountTab() {
        const verifyBtn = document.getElementById('verify-discount-shortcode');
        const shortcodeInput = document.getElementById('discount-user-shortcode');
        const applyBtn = document.getElementById('apply-points-discount');
        
        if (verifyBtn) {
            verifyBtn.addEventListener('click', () => {
                const shortcode = shortcodeInput.value.trim();
                if (shortcode.length === 4) {
                    this.verifyUserShortcode(shortcode, 'discount');
                } else {
                    this.showToast(posTranslations['Invalid shortcode'] || 'Invalid shortcode', 'error');
                }
            });
        }

        if (shortcodeInput) {
            shortcodeInput.addEventListener('keypress', (e) => {
                if (e.key === 'Enter') {
                    verifyBtn.click();
                }
            });
        }

        if (applyBtn) {
            applyBtn.addEventListener('click', () => {
                this.applyPointsDiscount();
            });
        }
    }

    initPointsRewardTab() {
        const verifyBtn = document.getElementById('verify-reward-shortcode');
        const shortcodeInput = document.getElementById('reward-user-shortcode');
        const applyBtn = document.getElementById('apply-points-reward');
        
        if (verifyBtn) {
            verifyBtn.addEventListener('click', () => {
                const shortcode = shortcodeInput.value.trim();
                if (shortcode.length === 4) {
                    this.verifyUserShortcode(shortcode, 'reward');
                } else {
                    this.showToast(posTranslations['Invalid shortcode'] || 'Invalid shortcode', 'error');
                }
            });
        }

        if (shortcodeInput) {
            shortcodeInput.addEventListener('keypress', (e) => {
                if (e.key === 'Enter') {
                    verifyBtn.click();
                }
            });
        }

        if (applyBtn) {
            applyBtn.addEventListener('click', () => {
                this.applyPointsReward();
            });
        }
    }

    verifyUserShortcode(shortcode, type) {
        const formData = new FormData();
        formData.append('action', 'ruiyi_lookup_user_by_shortcode');
        formData.append('shortcode', shortcode);
        formData.append('nonce', pointsConfig.nonce);

        fetch(pointsConfig.ajaxUrl, {
            method: 'POST',
            body: formData
        })
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                this.handleUserVerified(data.data, type);
            } else {
                this.showToast(data.data.message || posTranslations['User not found'] || 'User not found', 'error');
            }
        })
        .catch(error => {
            console.error('Error verifying shortcode:', error);
            this.showToast(posTranslations['Network error'] || 'Network error', 'error');
        });
    }

    handleUserVerified(userData, type) {
        if (type === 'discount') {
            // Update UI for discount tab
            document.getElementById('discount-user-name').textContent = userData.user_name;
            document.getElementById('discount-user-points').textContent = userData.points;
            document.getElementById('discount-user-verify').classList.add('hidden');
            document.getElementById('discount-user-info').classList.remove('hidden');
            document.getElementById('discount-operation').classList.remove('hidden');
            
            // Calculate discount
            const totalData = this.calculateTotal();
            const totalAmount = totalData.total || 0;

            // Validate total amount to prevent NaN
            if (isNaN(totalAmount) || totalAmount <= 0) {
                document.getElementById('max-discount-amount').textContent = '€0.00';
                document.getElementById('points-needed').textContent = '0';
                document.getElementById('discount-status').textContent = 'Invalid cart total';
                return;
            }

            // Maximum discount amount = cart total × maximum discount percentage
            const maxDiscountAmount = totalAmount * (pointsConfig.maxDiscountPercent / 100);
            // Points needed = cart total × deduction rate × 100
            const pointsNeeded = Math.floor(totalAmount * (pointsConfig.deductionRate / 100) * 100);
            
            document.getElementById('max-discount-amount').textContent = this.formatPrice(maxDiscountAmount);
            document.getElementById('points-needed').textContent = pointsNeeded;
            
            const applyBtn = document.getElementById('apply-points-discount');
            if (userData.points >= pointsNeeded) {
                document.getElementById('discount-status').textContent = posTranslations['Customer has enough points for maximum discount'] || 'Customer has enough points for maximum discount';
                document.getElementById('discount-status').className = 'text-sm text-green-600 mb-4';
                applyBtn.disabled = false;
                applyBtn.dataset.points = pointsNeeded;
                applyBtn.dataset.discount = maxDiscountAmount;
                applyBtn.dataset.userId = userData.user_id;
            } else {
                const pointsShortage = pointsNeeded - userData.points;
                document.getElementById('discount-status').textContent = (posTranslations['Insufficient points. Customer needs %d more points'] || 'Insufficient points. Customer needs %d more points').replace('%d', pointsShortage);
                document.getElementById('discount-status').className = 'text-sm text-red-600 mb-4';
                applyBtn.disabled = true;
            }
        } else if (type === 'reward') {
            // Update UI for reward tab
            document.getElementById('reward-user-name').textContent = userData.user_name;
            document.getElementById('reward-user-points').textContent = userData.points;
            document.getElementById('reward-user-verify').classList.add('hidden');
            document.getElementById('reward-user-info').classList.remove('hidden');
            document.getElementById('reward-operation').classList.remove('hidden');
            
            // Calculate reward points
            const totalData = this.calculateTotal();
            const totalAmount = totalData.total || 0;

            // Validate total amount to prevent NaN
            if (isNaN(totalAmount) || totalAmount <= 0) {
                document.getElementById('reward-points').textContent = '0';
                document.getElementById('reward-calculation').textContent = 'Invalid cart total';
                return;
            }

            // Reward points = cart total × reward rate × 100
            const rewardPoints = Math.floor(totalAmount * (pointsConfig.rewardRate / 100) * 100);
            
            document.getElementById('reward-points').textContent = rewardPoints;
            const purchaseText = (posTranslations['Purchase of'] || 'Purchase of');
            const rewardRateText = (posTranslations['reward rate'] || 'reward rate');
            document.getElementById('reward-calculation').textContent =
                `${purchaseText} ${this.formatPrice(totalAmount)} × ${pointsConfig.rewardRate}% ${rewardRateText}`;
            
            const applyBtn = document.getElementById('apply-points-reward');
            applyBtn.dataset.points = rewardPoints;
            applyBtn.dataset.userId = userData.user_id;
        }
    }

    applyPointsDiscount() {
        const applyBtn = document.getElementById('apply-points-discount');
        const points = parseInt(applyBtn.dataset.points || 0);
        const discount = parseFloat(applyBtn.dataset.discount || 0);
        const userId = applyBtn.dataset.userId;
        const shortcodeInput = document.getElementById('discount-user-shortcode');
        const shortcode = shortcodeInput ? shortcodeInput.value.trim() : '';

        if (!userId || !points || !discount) return;

        // Apply discount to current order
        this.pendingPointsDiscount = {
            userId: userId,
            pointsUsed: points,
            discount: discount,
            shortcode: shortcode
        };
        
        // Update localStorage for client display
        localStorage.setItem('ruiyi_pos_points_discount', JSON.stringify(this.pendingPointsDiscount));

        // Disable only the discount button to prevent duplicate discount operations
        applyBtn.disabled = true;
        applyBtn.textContent = posTranslations['Points Applied'] || 'Points Applied';
        applyBtn.classList.add('opacity-50', 'cursor-not-allowed');

        this.showToast(posTranslations['Points discount applied'] || 'Points discount applied', 'success');
        this.closePointsManagementModal();

        // Update cart display to show discounted total
        this.updateCartTotalDisplay();

        // Return to payment method selection with updated total
        this.showPaymentMethodModal();
    }

    applyPointsReward() {
        const applyBtn = document.getElementById('apply-points-reward');
        const points = parseInt(applyBtn.dataset.points || 0);
        const userId = applyBtn.dataset.userId;
        const shortcodeInput = document.getElementById('reward-user-shortcode');
        const shortcode = shortcodeInput ? shortcodeInput.value.trim() : '';

        if (!userId || !points) return;

        // Store reward info for after payment
        this.pendingPointsReward = {
            userId: userId,
            points: points,
            shortcode: shortcode
        };

        // Disable only the reward button to prevent duplicate reward operations
        applyBtn.disabled = true;
        applyBtn.textContent = posTranslations['Reward Confirmed'] || 'Reward Confirmed';
        applyBtn.classList.add('opacity-50', 'cursor-not-allowed');

        this.showToast(posTranslations['Points will be rewarded'] || 'Points will be rewarded after payment', 'success');
        this.closePointsManagementModal();
        
        // Continue with normal payment - show payment method modal
        const modal = document.getElementById('payment-method-modal');
        if (modal) {
            modal.classList.remove('hidden');
        }
    }

    processPaymentWithPoints(paymentMethod) {
        // Process payment with points discount applied
        if (this.pendingPointsDiscount) {
            const totalData = this.calculateTotal();
            const totalAmount = totalData.total || 0;
            const discountedTotal = totalAmount - this.pendingPointsDiscount.discount;
            
            // Update the total display temporarily
            const totalEl = document.getElementById('total-amount');
            if (totalEl) {
                totalEl.innerHTML = `<del class="text-gray-400">${this.formatPrice(total.total)}</del> ${this.formatPrice(discountedTotal)}`;
            }
        }
        
        // Continue with payment
        if (paymentMethod === 'cash') {
            this.showCashPaymentModal();
        } else {
            this.processCreditCardPayment();
        }
    }

    closePointsManagementModal() {
        const modal = document.getElementById('points-management-modal');
        if (modal) {
            modal.classList.add('hidden');
        }

        // Reset forms
        document.getElementById('discount-user-shortcode').value = '';
        document.getElementById('reward-user-shortcode').value = '';
        document.getElementById('discount-user-verify').classList.remove('hidden');
        document.getElementById('reward-user-verify').classList.remove('hidden');
        document.getElementById('discount-user-info').classList.add('hidden');
        document.getElementById('reward-user-info').classList.add('hidden');
        document.getElementById('discount-operation').classList.add('hidden');
        document.getElementById('reward-operation').classList.add('hidden');
        // 🔥 关闭弹窗后聚焦回Varios
        setTimeout(() => this.focusVariosInput(), 100);
    }

    // Customer Information Management Methods
    showCustomerInfoModal() {
        this.closePaymentMethodModal();

        // Clear Varios input and blur
        const variosInput = document.getElementById('varios-price-input');
        if (variosInput) {
            variosInput.value = '';
            variosInput.blur();
        }

        // Load existing customer info into form fields
        document.getElementById('customer-name').value = this.customerInfo.name || '';
        document.getElementById('customer-phone').value = this.customerInfo.phone || '';
        document.getElementById('customer-address').value = this.customerInfo.address || '';
        document.getElementById('customer-company').value = this.customerInfo.company || '';
        document.getElementById('customer-tax-id').value = this.customerInfo.taxId || '';

        const modal = document.getElementById('customer-info-modal');
        if (modal) {
            modal.classList.remove('hidden');
        }
    }

    closeCustomerInfoModal() {
        const modal = document.getElementById('customer-info-modal');
        if (modal) {
            modal.classList.add('hidden');
            modal.style.zIndex = '';
        }
        this._invoiceOrderId = null;
        // Focus back to Varios after closing modal
        setTimeout(() => this.focusVariosInput(), 100);
    }

    saveCustomerInfo() {
        // If saving for a historical order invoice, use different flow
        if (this._invoiceOrderId) {
            this.saveOrderCustomerInfo();
            return;
        }

        // Save customer information from form fields to this.customerInfo
        this.customerInfo = {
            name: document.getElementById('customer-name').value.trim(),
            phone: document.getElementById('customer-phone').value.trim(),
            address: document.getElementById('customer-address').value.trim(),
            company: document.getElementById('customer-company').value.trim(),
            taxId: document.getElementById('customer-tax-id').value.trim()
        };

        // Auto-save to customer database if not loaded from existing customer
        if (!this._customerInfoFromDB) {
            const ci = this.customerInfo;
            const hasAnyData = ci.name || ci.phone || ci.address || ci.company || ci.taxId;
            if (hasAnyData) {
                const companyName = ci.company || ci.name || ci.phone || 'Customer';
                this.ajaxRequest({
                    pos_action: 'add_invoice_customer',
                    company: companyName,
                    cif: ci.taxId || '',
                    phone: ci.phone || '',
                    address: ci.address || ''
                }).then(resp => {
                    if (resp.success) {
                        console.log('[POS] Customer auto-saved to database, id:', resp.data.customer_id);
                    } else {
                        console.warn('[POS] Customer auto-save failed:', resp.data?.message);
                    }
                }).catch(e => console.warn('[POS] Customer auto-save error:', e));
            }
        }
        this._customerInfoFromDB = false;

        // Close modal and return to payment method selection
        this.closeCustomerInfoModal();
        this.showPaymentMethodModal();

        // Show success toast
        this.showToast(posTranslations['Customer information saved'] || 'Customer information saved', 'success');
    }

    // Open customer info modal for a historical order (创建发票)
    openOrderInvoiceModal(orderId) {
        this._invoiceOrderId = orderId;
        // Clear form
        document.getElementById('customer-search-input').value = '';
        document.getElementById('customer-name').value = '';
        document.getElementById('customer-phone').value = '';
        document.getElementById('customer-address').value = '';
        document.getElementById('customer-company').value = '';
        document.getElementById('customer-tax-id').value = '';
        // Hide search results
        const searchResultsDiv = document.getElementById('customer-search-results');
        if (searchResultsDiv) searchResultsDiv.classList.add('hidden');
        const resultsDiv = document.getElementById('customer-phone-results');
        if (resultsDiv) resultsDiv.classList.add('hidden');
        // Open modal (z-index 9999 确保在开票弹窗之上)
        const modal = document.getElementById('customer-info-modal');
        modal.style.zIndex = '9999';
        modal.classList.remove('hidden');
    }

    // Save customer info to a historical order, then auto-print
    async saveOrderCustomerInfo() {
        const orderId = this._invoiceOrderId;
        const ci = {
            customer_name: document.getElementById('customer-name').value.trim(),
            customer_phone: document.getElementById('customer-phone').value.trim(),
            customer_address: document.getElementById('customer-address').value.trim(),
            customer_company: document.getElementById('customer-company').value.trim(),
            customer_tax_id: document.getElementById('customer-tax-id').value.trim()
        };

        try {
            const resp = await this.ajaxRequest({
                pos_action: 'save_order_customer_info',
                order_id: orderId,
                ...ci
            });
            if (resp.success) {
                this.closeCustomerInfoModal();
                this.showToast(posTranslations['Customer information saved'] || 'Customer information saved', 'success');

                // Also auto-save to customer database
                const companyName = ci.customer_company || ci.customer_name || ci.customer_phone;
                if (companyName && !this._customerInfoFromDB) {
                    this.ajaxRequest({
                        pos_action: 'add_invoice_customer',
                        company: companyName,
                        cif: ci.customer_tax_id || '',
                        phone: ci.customer_phone || '',
                        address: ci.customer_address || ''
                    }).catch(() => {});
                }
                this._customerInfoFromDB = false;

                // Refresh order history to show updated buttons
                this.loadOrderHistory();

                // Auto-print invoice receipt
                this.printHistoricalReceipt(orderId);
            } else {
                this.showToast(resp.data?.message || 'Save failed', 'error');
            }
        } catch (e) {
            this.showToast('Save failed', 'error');
        }
        this._invoiceOrderId = null;
    }

    // 🔥 统一客户搜索（支持名称、电话、编号、税号）
    searchCustomerUnified(query) {
        const resultsDiv = document.getElementById('customer-search-results');
        if (!resultsDiv) return;

        if (!query || query.trim().length < 1) {
            resultsDiv.classList.add('hidden');
            resultsDiv.innerHTML = '';
            return;
        }

        const trimmed = query.trim();
        // 至少输入2个字符才搜索（纯数字1个即可，因为客户编号可能是1位）
        if (trimmed.length < 2 && !/^\d+$/.test(trimmed)) {
            resultsDiv.classList.add('hidden');
            return;
        }

        clearTimeout(this._customerSearchTimer);
        this._customerSearchTimer = setTimeout(async () => {
            try {
                const data = await this.ajaxRequest({
                    pos_action: 'search_customers',
                    query: trimmed
                });
                if (data.success && data.data && data.data.length > 0) {
                    resultsDiv.innerHTML = data.data.map(c => {
                        const num = c.customer_number ? `#${c.customer_number}` : '';
                        const name = this.escapeHtml(c.company || c.customer_name || '');
                        const cif = this.escapeHtml(c.cif || '');
                        const phone = this.escapeHtml(c.phone || '');
                        const city = this.escapeHtml(c.city || '');
                        return `
                            <div class="px-4 py-3 hover:bg-blue-50 cursor-pointer border-b border-gray-100 last:border-0"
                                 onclick="pos.selectSearchedCustomer(${JSON.stringify(c).replace(/"/g, '&quot;')})">
                                <div class="flex items-center justify-between">
                                    <span class="font-medium text-gray-900 text-sm">${name}</span>
                                    ${num ? `<span class="text-xs bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full">${num}</span>` : ''}
                                </div>
                                <div class="text-xs text-gray-500 mt-0.5">${[cif, phone, city].filter(Boolean).join(' | ')}</div>
                            </div>
                        `;
                    }).join('');
                    resultsDiv.classList.remove('hidden');
                } else {
                    resultsDiv.innerHTML = `<div class="px-4 py-3 text-sm text-gray-400 text-center">${
                        (document.documentElement.lang || '').includes('zh') ? '未找到客户' : 'No encontrado'
                    }</div>`;
                    resultsDiv.classList.remove('hidden');
                }
            } catch (e) {
                resultsDiv.classList.add('hidden');
            }
        }, 300);
    }

    // 🔥 选择搜索到的客户，自动填充所有字段
    selectSearchedCustomer(customer) {
        document.getElementById('customer-name').value = customer.customer_name || customer.company || '';
        document.getElementById('customer-phone').value = customer.phone || '';
        document.getElementById('customer-address').value = customer.address || '';
        document.getElementById('customer-company').value = customer.company || '';
        document.getElementById('customer-tax-id').value = customer.cif || '';
        document.getElementById('customer-search-input').value = '';
        document.getElementById('customer-search-results').classList.add('hidden');
        this._customerInfoFromDB = true;
    }

    // Search customer by phone number (triggers on 4+ digits input)
    searchCustomerByPhone(value) {
        const digits = value.replace(/\D/g, '');
        const resultsDiv = document.getElementById('customer-phone-results');
        if (!resultsDiv) return;

        if (digits.length < 4) {
            resultsDiv.classList.add('hidden');
            resultsDiv.innerHTML = '';
            return;
        }

        // Debounce
        clearTimeout(this._phoneSearchTimer);
        this._phoneSearchTimer = setTimeout(async () => {
            try {
                const data = await this.ajaxRequest({
                    pos_action: 'search_customer_by_phone',
                    phone: digits
                });
                if (data.success && data.data.length > 0) {
                    const locale = document.documentElement.lang || 'en';
                    resultsDiv.innerHTML = data.data.map(c => `
                        <div class="px-4 py-3 hover:bg-teal-50 cursor-pointer border-b border-gray-100 last:border-0"
                             onclick="pos.selectPhoneCustomer(${c.id}, '${this.escapeHtml(c.company || '')}', '${this.escapeHtml(c.phone || '')}', '${this.escapeHtml(c.address || '')}', '${this.escapeHtml(c.cif || '')}')">
                            <div class="font-medium text-gray-900 text-sm">${this.escapeHtml(c.company || c.customer_name || '')}</div>
                            <div class="text-xs text-gray-500">${this.escapeHtml(c.phone || '')} ${c.cif ? '| ' + this.escapeHtml(c.cif) : ''} ${c.address ? '| ' + this.escapeHtml(c.address) : ''}</div>
                        </div>
                    `).join('');
                    resultsDiv.classList.remove('hidden');
                } else {
                    resultsDiv.classList.add('hidden');
                    resultsDiv.innerHTML = '';
                }
            } catch (e) {
                resultsDiv.classList.add('hidden');
            }
        }, 300);
    }

    // Auto-fill customer info from search result
    selectPhoneCustomer(id, company, phone, address, cif) {
        document.getElementById('customer-name').value = company;
        document.getElementById('customer-phone').value = phone;
        document.getElementById('customer-address').value = address;
        document.getElementById('customer-company').value = company;
        document.getElementById('customer-tax-id').value = cif;
        document.getElementById('customer-phone-results').classList.add('hidden');
        this._customerInfoFromDB = true; // Flag: loaded from DB, skip auto-save
    }

    // Update cart total display considering points discount
    updateCartTotalDisplay() {
        const totalEl = document.getElementById('total-amount');
        if (!totalEl) return;

        // Calculate the original total without discount (支持小数数量)
        const originalTotal = this.cart.reduce((total, item) => {
            const price = parseFloat(item.price) || 0;
            const quantity = parseFloat(item.quantity) || 0;
            return total + (price * quantity);
        }, 0);

        const formatPrice = (amount) => parseFloat(amount || 0).toFixed(2) + ruiyi_pos_ajax.currency;

        if (this.pendingPointsDiscount && this.pendingPointsDiscount.discount > 0) {
            // Show discounted total with strikethrough original price
            // Use consistent rounding to 2 decimal places throughout
            const discount = parseFloat(this.pendingPointsDiscount.discount) || 0;
            const discountedTotal = Math.round((originalTotal - discount) * 100) / 100;
            const finalTotal = Math.max(0, discountedTotal);

            totalEl.innerHTML = `
                <div class="text-2xl text-gray-400 line-through">${formatPrice(originalTotal)}</div>
                <div class="text-4xl font-bold text-green-600">${formatPrice(finalTotal)}</div>
                <div class="text-sm text-green-600 mt-1">积分折扣: -${formatPrice(discount)}</div>
            `;
        } else {
            // Show normal total
            totalEl.innerHTML = `<div class="text-4xl font-bold text-gray-900">${formatPrice(originalTotal)}</div>`;
        }
    }


    // Fetch Verifactu QR code for order
    async fetchVerifactuQRCode(orderId) {
        if (!orderId) return null;

        try {
            const formData = new URLSearchParams({
                action: 'ruiyi_get_verifactu_qr',
                order_id: orderId,
                nonce: pointsConfig.nonce
            });

            const response = await fetch(pointsConfig.ajaxUrl, {
                method: 'POST',
                body: formData
            });

            const data = await response.json();
            if (data.success) {
                // 返回完整的数据对象，包括qr_base64和invoice_number
                return {
                    qr_base64: data.data.qr_base64 || null,
                    invoice_number: data.data.invoice_number || null,
                    has_verifactu: data.data.has_verifactu || false
                };
            }
        } catch (error) {
            console.error('Error fetching Verifactu QR code:', error);
        }

        return null;
    }

    // Hold Order Functionality
    loadHeldOrders() {
        try {
            const stored = localStorage.getItem('ruiyi_pos_held_orders');
            return stored ? JSON.parse(stored) : [];
        } catch (error) {
            console.error('Error loading held orders:', error);
            return [];
        }
    }

    saveHeldOrders() {
        try {
            localStorage.setItem('ruiyi_pos_held_orders', JSON.stringify(this.heldOrders));
        } catch (error) {
            console.error('Error saving held orders:', error);
            this.showToast(posTranslations['Error saving held order'] || 'Error saving held order', 'error');
        }
    }

    showHoldOrderModal() {
        if (this.cart.length === 0) {
            this.showToast(posTranslations['Cart is empty'] || 'Cart is empty', 'error');
            return;
        }

        // Calculate totals - Product prices already include IVA
        const totalWithTax = this.cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
        const totalItems = this.cart.reduce((sum, item) => sum + item.quantity, 0);

        // Update modal content
        const itemsCountEl = document.getElementById('hold-order-items-count');
        const totalEl = document.getElementById('hold-order-total');
        
        if (itemsCountEl) itemsCountEl.textContent = `${totalItems} ${posTranslations['items'] || 'items'}`;
        if (totalEl) totalEl.textContent = ruiyi_pos_ajax.currency + parseFloat(totalWithTax || 0).toFixed(2);

        // Reset form
        const referenceInput = document.getElementById('hold-order-reference');
        const notesInput = document.getElementById('hold-order-notes');
        if (referenceInput) referenceInput.value = '';
        if (notesInput) notesInput.value = '';

        this.validateHoldOrderForm();

        const modal = document.getElementById('hold-order-modal');
        if (modal) {
            modal.classList.remove('hidden');
            if (referenceInput) referenceInput.focus();
        }
    }

    validateHoldOrderForm() {
        const referenceInput = document.getElementById('hold-order-reference');
        const confirmBtn = document.getElementById('confirm-hold-btn');
        
        if (referenceInput && confirmBtn) {
            const reference = referenceInput.value.trim();
            confirmBtn.disabled = reference.length < 1;
        }
    }

    confirmHoldOrder() {
        const referenceInput = document.getElementById('hold-order-reference');
        const notesInput = document.getElementById('hold-order-notes');
        
        if (!referenceInput) return;
        
        const reference = referenceInput.value.trim();
        const notes = notesInput ? notesInput.value.trim() : '';
        
        if (reference.length < 1) {
            this.showToast(posTranslations['Please enter a customer name or reference'] || 'Please enter a customer name or reference', 'error');
            return;
        }

        // Create held order
        const heldOrder = {
            id: Date.now().toString(),
            reference: reference,
            notes: notes,
            cart: [...this.cart],
            subtotal: this.calculateSubtotalFromTotal(this.cart.reduce((sum, item) => sum + (item.price * item.quantity), 0)),
            tax: this.calculateIVAFromTotal(this.cart.reduce((sum, item) => sum + (item.price * item.quantity), 0)),
            total: this.cart.reduce((sum, item) => sum + (item.price * item.quantity), 0),
            itemCount: this.cart.reduce((sum, item) => sum + item.quantity, 0),
            timestamp: new Date().toISOString(),
            cashier: ruiyi_pos_ajax.user_name
        };

        this.heldOrders.push(heldOrder);
        this.saveHeldOrders();
        this.updateHeldOrdersCount();

        // Clear current cart
        this.clearCart();
        
        this.closeHoldOrderModal();
        this.showToast(`Order held for ${reference}`, 'success');
    }

    closeHoldOrderModal() {
        const modal = document.getElementById('hold-order-modal');
        if (modal) modal.classList.add('hidden');
        // 🔥 关闭弹窗后聚焦回Varios
        setTimeout(() => this.focusVariosInput(), 100);
    }

    updateHeldOrdersCount() {
        const countEl = document.getElementById('held-orders-count');
        if (countEl) {
            const count = this.heldOrders.length;
            countEl.textContent = count;
            countEl.classList.toggle('hidden', count === 0);
        }
    }

    showHeldOrdersModal() {
        this.renderHeldOrdersList();
        const modal = document.getElementById('held-orders-modal');
        if (modal) modal.classList.remove('hidden');
    }

    renderHeldOrdersList() {
        const listContainer = document.getElementById('held-orders-list');
        if (!listContainer) return;

        if (this.heldOrders.length === 0) {
            listContainer.innerHTML = `
                <div class="text-center py-12">
                    <div class="text-gray-400 mb-4">
                        <svg class="mx-auto h-16 w-16" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/>
                        </svg>
                    </div>
                    <h3 class="text-lg font-medium text-gray-900 mb-2">${posTranslations['No Held Orders'] || 'No Held Orders'}</h3>
                    <p class="text-gray-500">${posTranslations['Hold orders will appear here'] || 'Hold orders will appear here'}</p>
                </div>
            `;
            return;
        }

        const ordersHTML = this.heldOrders.map(order => {
            const timeHeld = this.getTimeAgo(order.timestamp);
            return `
                <div class="bg-white border border-gray-200 rounded-lg p-4 mb-3">
                    <div class="flex justify-between items-start mb-3">
                        <div>
                            <h4 class="font-semibold text-gray-900">${order.reference}</h4>
                            <p class="text-sm text-gray-500">${timeHeld}</p>
                            ${order.notes ? `<p class="text-sm text-gray-600 mt-1">${order.notes}</p>` : ''}
                        </div>
                        <div class="text-right">
                            <p class="font-bold text-lg">${ruiyi_pos_ajax.currency}${parseFloat(order.total || 0).toFixed(2)}</p>
                            <p class="text-sm text-gray-500">${order.itemCount} items</p>
                        </div>
                    </div>
                    <div class="flex space-x-2">
                        <button onclick="window.pos.resumeHeldOrder('${order.id}')" 
                                class="flex-1 bg-green-600 hover:bg-green-700 text-white py-2 px-4 rounded-lg text-sm font-medium transition-all">
                            ${posTranslations['Resume Order'] || 'Resume Order'}
                        </button>
                        <button onclick="window.pos.deleteHeldOrder('${order.id}')" 
                                class="bg-red-600 hover:bg-red-700 text-white py-2 px-4 rounded-lg text-sm font-medium transition-all">
                            ${posTranslations['Delete'] || 'Delete'}
                        </button>
                    </div>
                </div>
            `;
        }).join('');

        listContainer.innerHTML = ordersHTML;
    }

    getTimeAgo(timestamp) {
        const now = new Date();
        const time = new Date(timestamp);
        const diffInMs = now - time;
        const diffInMinutes = Math.floor(diffInMs / 60000);
        const diffInHours = Math.floor(diffInMinutes / 60);
        const diffInDays = Math.floor(diffInHours / 24);

        if (diffInMinutes < 1) return posTranslations['Just now'] || 'Just now';
        if (diffInMinutes < 60) return `${diffInMinutes} ${posTranslations['minutes ago'] || 'minutes ago'}`;
        if (diffInHours < 24) return `${diffInHours} ${posTranslations['hours ago'] || 'hours ago'}`;
        return `${diffInDays} ${posTranslations['days ago'] || 'days ago'}`;
    }

    resumeHeldOrder(orderId) {
        const order = this.heldOrders.find(o => o.id === orderId);
        if (!order) {
            this.showToast(posTranslations['Order not found'] || 'Order not found', 'error');
            return;
        }

        // Check if current cart has items
        if (this.cart.length > 0) {
            if (!confirm('Current cart will be replaced with the held order. Continue?')) {
                return;
            }
        }

        // Load held order to cart
        this.cart = [...order.cart];
        this.updateCart();

        // Remove from held orders
        this.heldOrders = this.heldOrders.filter(o => o.id !== orderId);
        this.saveHeldOrders();
        this.updateHeldOrdersCount();

        this.closeHeldOrdersModal();
        this.showToast(`Resumed order for ${order.reference}`, 'success');
    }

    deleteHeldOrder(orderId) {
        const order = this.heldOrders.find(o => o.id === orderId);
        if (!order) return;

        if (confirm(`Delete held order for ${order.reference}?`)) {
            this.heldOrders = this.heldOrders.filter(o => o.id !== orderId);
            this.saveHeldOrders();
            this.updateHeldOrdersCount();
            this.renderHeldOrdersList();
            this.showToast(`Deleted order for ${order.reference}`, 'info');
        }
    }

    closeHeldOrdersModal() {
        const modal = document.getElementById('held-orders-modal');
        if (modal) modal.classList.add('hidden');
        // 🔥 关闭弹窗后聚焦回Varios
        setTimeout(() => this.focusVariosInput(), 100);
    }

    // IVA tax calculation functions
    calculateIVAFromTotal(totalWithTax) {
        // Calculate IVA amount from total price (price includes tax)
        return totalWithTax - (totalWithTax / (1 + this.taxRate));
    }

    calculateSubtotalFromTotal(totalWithTax) {
        // Calculate subtotal (without tax) from total price
        return totalWithTax / (1 + this.taxRate);
    }

    calculateTotalFromSubtotal(subtotal) {
        // Calculate total (with tax) from subtotal
        return subtotal * (1 + this.taxRate);
    }
    
    calculateTotal() {
        // Calculate the current cart total
        let totalWithTax = 0;
        let totalQuantity = 0;
        
        this.cart.forEach(item => {
            const itemTotal = item.price * item.quantity;
            totalWithTax += itemTotal;
            totalQuantity += item.quantity;
        });
        
        const subtotal = this.calculateSubtotalFromTotal(totalWithTax);
        const tax = this.calculateIVAFromTotal(totalWithTax);
        
        return {
            subtotal: subtotal,
            tax: tax,
            total: totalWithTax,
            quantity: totalQuantity
        };
    }

    // Format price
    formatPrice(price) {
        const parsed = parseFloat(price || 0);
        if (isNaN(parsed)) {
            return ruiyi_pos_ajax.currency + '0.00';
        }
        return ruiyi_pos_ajax.currency + parsed.toFixed(2);
    }

    // Generate professional receipt items from WooCommerce order data
    generateSimpleReceiptItems(order) {
        let itemsHtml = '';
        
        if (order && order.items && order.items.length > 0) {
            // Use real WooCommerce order items
            order.items.forEach(item => {
                const itemName = item.name; // Show full product name without truncation
                
                itemsHtml += `
                    <div class="item-line">
                        <div class="item-desc">
                            ${itemName} <span class="item-quantity">x${item.quantity}</span>
                        </div>
                        <div class="item-price">${this.formatPrice(item.line_total)}</div>
                    </div>
                `;
            });
        } else if (this.cart && this.cart.length > 0) {
            // Fallback to cart data if order items not available
            this.cart.forEach(item => {
                const itemName = item.name; // Show full product name without truncation
                const itemTotal = item.price * item.quantity;
                
                itemsHtml += `
                    <div class="item-line">
                        <div class="item-desc">
                            ${itemName} <span class="item-quantity">x${item.quantity}</span>
                        </div>
                        <div class="item-price">${this.formatPrice(itemTotal)}</div>
                    </div>
                `;
            });
        }
        
        return itemsHtml;
    }

    // 🔥 生成折扣信息行（小票）
    generateDiscountLines(order) {
        console.log('[POS DISCOUNT DEBUG] ===== generateDiscountLines() called =====');
        console.log('[POS DISCOUNT DEBUG] order items:', order?.items?.map(i => ({
            name: i.name, unit_price: i.unit_price, original_price: i.original_price, discount_percent: i.discount_percent
        })));
        if (!order || !order.items) return '';
        const currency = order.currency_symbol || '€';
        let html = '';
        let totalDiscount = 0;
        let discountPercent = 0;

        order.items.forEach(item => {
            console.log('[POS DISCOUNT DEBUG] Item:', item.name, 'discount_percent:', item.discount_percent, 'original_price:', item.original_price, 'unit_price:', item.unit_price);
            if (item.discount_percent && item.discount_percent > 0 && item.original_price) {
                const qty = Math.abs(parseFloat(item.quantity) || 1);
                const itemDiscount = (parseFloat(item.original_price) - parseFloat(item.unit_price)) * qty;
                totalDiscount += itemDiscount;
                discountPercent = item.discount_percent; // 使用最后一个折扣百分比（通常全部相同）
            }
        });

        if (totalDiscount > 0) {
            html += `<div class="total-line discount-line" data-discount-percent="${discountPercent}" data-discount-amount="${totalDiscount.toFixed(2)}">
                <span>Descuento (${discountPercent}%):</span>
                <span class="currency">-${currency}${totalDiscount.toFixed(2)}</span>
            </div>`;
        }

        return html;
    }

    generateTaxBreakdown(order) {
        let taxHtml = '';

        // Check if we have tax breakdown data
        if (order && order.tax_breakdown) {
            // Sort tax rates for consistent display
            const sortedRates = Object.keys(order.tax_breakdown).sort();

            sortedRates.forEach(rateKey => {
                const rateData = order.tax_breakdown[rateKey];
                const taxAmount = rateData.tax || 0;
                const baseAmount = rateData.base || 0;

                // 🔥 显示所有税率（包括负数退货金额）
                if (taxAmount !== 0) {
                    taxHtml += `
                        <div class="total-line vat-line">
                            <span>Base Imp. ${rateKey}:</span>
                            <span class="currency">${this.formatPrice(baseAmount)}</span>
                        </div>
                        <div class="total-line vat-line">
                            <span>IVA ${rateKey}:</span>
                            <span class="currency">${this.formatPrice(taxAmount)}</span>
                        </div>
                    `;
                }
            });
        } else {
            // Fallback to single tax line if no breakdown available
            taxHtml = `
                <div class="total-line vat-line">
                    <span>IVA (21%):</span>
                    <span class="currency">${order.formatted_tax || this.formatPrice(0)}</span>
                </div>
            `;
        }

        return taxHtml;
    }

    generateReceiptItems(order) {
        let itemsHtml = '';

        // 🔥 列头：Producto / Cant. / Precio / Total
        itemsHtml += `
            <div class="item-line item-header-row" style="border-bottom:1px solid #000;padding-bottom:2pt;margin-bottom:3pt;">
                <div class="item-name-col" style="flex:1;font-weight:700;font-size:10pt;">Producto</div>
                <div class="item-cant-col" style="width:12%;text-align:center;font-weight:700;font-size:10pt;">Cant.</div>
                <div class="item-precio-col" style="width:22%;text-align:right;font-weight:700;font-size:10pt;">Precio</div>
                <div class="item-total-col" style="width:22%;text-align:right;font-weight:700;font-size:10pt;">Total</div>
            </div>
        `;

        if (order && order.items && order.items.length > 0) {
            // Use real WooCommerce order items with tax rates
            order.items.forEach(item => {
                const itemName = item.name;
                const taxRate = item.tax_rate || 21;
                const isReturnItem = item.is_return || item.quantity < 0;
                const displayQty = Number.isInteger(item.quantity) ? item.quantity : parseFloat(item.quantity).toFixed(2).replace(/\.?0+$/, '');

                // 🔥 计算单价和总价（优先使用 line_total/quantity 保证含税价格正确）
                const unitPrice = (item.line_total && item.quantity) ? (item.line_total / item.quantity) : (item.unit_price || 0);
                const lineTotal = item.line_total;

                itemsHtml += `
                    <div class="item-line">
                        <div class="item-name-col" style="flex:1;font-size:11pt;line-height:1.3;">${itemName}</div>
                        <div class="item-cant-col" style="width:12%;text-align:center;font-size:11pt;">${displayQty}</div>
                        <div class="item-precio-col" style="width:22%;text-align:right;font-size:11pt;">${this.formatPrice(unitPrice)}</div>
                        <div class="item-total-col" style="width:22%;text-align:right;font-size:11pt;font-weight:700;">${this.formatPrice(lineTotal)}</div>
                    </div>
                `;
            });
        } else if (this.cart && this.cart.length > 0) {
            // Fallback to cart data if order items not available
            this.cart.forEach(item => {
                const itemName = item.name;
                const isReturnItem = item.isReturn || item.quantity < 0;
                const displayQty = Number.isInteger(item.quantity) ? item.quantity : parseFloat(item.quantity).toFixed(2).replace(/\.?0+$/, '');
                const unitPrice = isReturnItem ? -Math.abs(item.price) : item.price;
                const lineTotal = item.price * item.quantity;

                itemsHtml += `
                    <div class="item-line">
                        <div class="item-name-col" style="flex:1;font-size:11pt;line-height:1.3;">${itemName}</div>
                        <div class="item-cant-col" style="width:12%;text-align:center;font-size:11pt;">${displayQty}</div>
                        <div class="item-precio-col" style="width:22%;text-align:right;font-size:11pt;">${this.formatPrice(unitPrice)}</div>
                        <div class="item-total-col" style="width:22%;text-align:right;font-size:11pt;font-weight:700;">${this.formatPrice(lineTotal)}</div>
                    </div>
                `;
            });
        }

        return itemsHtml;
    }

    cleanupOldHeldOrders() {
        const oneDayAgo = new Date();
        oneDayAgo.setDate(oneDayAgo.getDate() - 1);

        const initialCount = this.heldOrders.length;
        this.heldOrders = this.heldOrders.filter(order => {
            const orderDate = new Date(order.timestamp);
            return orderDate > oneDayAgo;
        });

        if (this.heldOrders.length < initialCount) {
            this.saveHeldOrders();
            this.updateHeldOrdersCount();
        }
    }

    // Barcode Scanner Methods
    initBarcodeScanner(inputElement) {
        if (!inputElement) return;

        let barcodeBuffer = '';
        let lastKeyTime = 0;
        let scannerInputActive = false;

        // Listen for rapid key inputs (barcode scanner behavior)
        inputElement.addEventListener('keydown', (e) => {
            const currentTime = Date.now();
            const timeDiff = currentTime - lastKeyTime;

            // Filter out unwanted keys and system events
            if (e.key.length > 1 && e.key !== 'Enter') {
                return;
            }

            // If time between keys is less than 50ms, it's likely a barcode scanner
            if (timeDiff < 50 && timeDiff > 0) {
                scannerInputActive = true;
                if (e.key !== 'Enter') {
                    barcodeBuffer += e.key;
                }
            } else if (timeDiff >= 50) {
                // New input sequence or manual typing
                if (scannerInputActive && e.key === 'Enter') {
                    e.preventDefault();
                    if (barcodeBuffer.length > 0 && this.isBarcode(barcodeBuffer)) {
                        this.searchByBarcode(barcodeBuffer);
                        inputElement.value = '';
                    }
                    barcodeBuffer = '';
                    scannerInputActive = false;
                } else {
                    barcodeBuffer = e.key !== 'Enter' ? e.key : '';
                    scannerInputActive = false;
                }
            }

            lastKeyTime = currentTime;

            // Handle Enter key for scanner input
            if (e.key === 'Enter' && scannerInputActive && barcodeBuffer.length > 0) {
                e.preventDefault();
                if (this.isBarcode(barcodeBuffer)) {
                    this.searchByBarcode(barcodeBuffer);
                    inputElement.value = '';
                }
                barcodeBuffer = '';
                scannerInputActive = false;
            }
        });
        
        // Also listen for input events as fallback
        inputElement.addEventListener('input', (e) => {
            const value = e.target.value;
            
            // If input contains only barcode-like characters and is complete
            if (value.length > 0 && this.isBarcode(value)) {
                // Small delay to allow full input to complete
                setTimeout(() => {
                    if (e.target.value === value && this.isBarcode(value)) {
                        this.searchByBarcode(value);
                        e.target.value = '';
                    }
                }, 100);
            }
        });
    }

    initGlobalBarcodeScanner() {
        let globalBarcodeBuffer = '';
        let globalLastKeyTime = 0;
        let globalScannerInputActive = false;
        let enterProcessedTime = 0;  // 🔥 新增：记录Enter键最后处理时间，用于防抖
        let scannerProtectionTimeout = null; // 🔥 扫描器保护超时器

        // 🔥 初始化全局扫描器活动标记
        window.isScannerActive = false;

        // Global barcode scanner initialized

        // 🔥 使用捕获阶段监听，优先级最高，确保条码扫描器Enter键被完全拦截
        document.addEventListener('keydown', (e) => {
            // Skip if user is typing in an input field (except search box during barcode scan)
            const activeElement = document.activeElement;
            const isInputField = activeElement && (
                activeElement.tagName === 'INPUT' ||
                activeElement.tagName === 'TEXTAREA' ||
                activeElement.contentEditable === 'true'
            );

            // 🔥 如果退货弹窗打开，完全跳过全局扫描器处理
            if (window.isRefundModalOpen) {
                return;
            }

            // Skip if user is typing in any input field (including search box)
            if (isInputField) {
                return;
            }

            const currentTime = Date.now();
            const timeDiff = currentTime - globalLastKeyTime;

            // 🔥 超时重置：如果超过1秒没有按键，重置扫描器状态
            if (timeDiff > 1000 && globalBarcodeBuffer.length > 0) {
                globalBarcodeBuffer = '';
                globalScannerInputActive = false;
                window.isScannerActive = false;
                // 清除保护超时器
                if (scannerProtectionTimeout) {
                    clearTimeout(scannerProtectionTimeout);
                    scannerProtectionTimeout = null;
                }
            }

            // Filter out unwanted keys and system events
            if (e.key.length > 1 && e.key !== 'Enter') {
                return;
            }

            // 🔥 简化：Enter键完全交给Varios输入框处理
            // 全局扫描器只负责检测并聚焦，不处理Enter键
            if (e.key === 'Enter') {
                // 重置全局扫描器状态
                globalBarcodeBuffer = '';
                globalScannerInputActive = false;

                // 延迟重置扫描器标记
                if (scannerProtectionTimeout) {
                    clearTimeout(scannerProtectionTimeout);
                }
                scannerProtectionTimeout = setTimeout(() => {
                    window.isScannerActive = false;
                }, 300);

                // 让Enter键传播到Varios输入框
                return;
            }

            // If time between keys is less than 50ms, it's likely a barcode scanner
            // 🔥 修复：扫描器模式激活后，放宽时间阈值到200ms，防止末尾字符丢失
            const scannerThreshold = globalScannerInputActive ? 200 : 50;
            if (timeDiff < scannerThreshold && timeDiff > 0 && globalBarcodeBuffer.length > 0) {
                // 🔥 检测到扫描器！立即聚焦到Varios输入框
                globalScannerInputActive = true;
                window.isScannerActive = true;

                // 🔥 阻止默认输入，防止字符重复
                e.preventDefault();

                const variosInput = document.getElementById('varios-price-input');
                if (variosInput) {
                    // 🔥 聚焦到Varios输入框
                    if (activeElement !== variosInput) {
                        variosInput.focus();
                    }
                    // 🔥 将缓冲区+当前字符输入到Varios
                    globalBarcodeBuffer += e.key;
                    variosInput.value = globalBarcodeBuffer;
                    // 触发input事件
                    variosInput.dispatchEvent(new Event('input', { bubbles: true }));
                } else {
                    globalBarcodeBuffer += e.key;
                }

                globalLastKeyTime = currentTime;
                return;
            } else if (timeDiff >= 50 || globalBarcodeBuffer.length === 0) {
                // New input sequence or manual typing (慢速或第一次按键)
                if (e.key !== 'Enter') {
                    globalBarcodeBuffer = e.key;
                    // 🔥 延迟检查：如果50ms内有下一个字符，说明是扫描器，回溯处理第一个字符
                    this._globalScanFirstCharTimeout = setTimeout(() => {
                        // 超时未检测到快速输入，是手动按键，清空buffer让正常输入
                        // （scanner detection会在下一个keydown中处理）
                    }, 60);

                    // 🔥 新增：手动按数字键时，自动聚焦到Varios输入框并输入
                    if (/^[0-9.]$/.test(e.key)) {
                        // 检查是否有弹窗打开
                        const anyModalOpen = Array.from(document.querySelectorAll('[id$="-modal"]')).some(modal => {
                            return modal && !modal.classList.contains('hidden') &&
                                   modal.classList.contains('fixed');
                        });

                        // 检查退货弹窗
                        if (window.isRefundModalOpen) {
                            // 退货弹窗打开，不处理
                        } else if (anyModalOpen) {
                            // 有其他弹窗打开，不处理
                        } else {
                            // 没有弹窗打开，聚焦到Varios并输入数字
                            const variosInput = document.getElementById('varios-price-input');
                            if (variosInput) {
                                e.preventDefault();
                                variosInput.focus();

                                // 如果输入框为空或是默认值，设置新值；否则追加
                                if (variosInput.value === '' || variosInput.value === '€0.00' || variosInput.value === '0.00€') {
                                    variosInput.value = e.key;
                                } else {
                                    variosInput.value += e.key;
                                }

                                // 触发input事件
                                variosInput.dispatchEvent(new Event('input', { bubbles: true }));
                            }
                        }
                    }
                } else {
                    // Enter键但不在扫描状态，清空缓冲区
                    globalBarcodeBuffer = '';
                }
                globalScannerInputActive = false;
                window.isScannerActive = false;
            }

            globalLastKeyTime = currentTime;
        }, true);  // 🔥 使用捕获阶段（优先级最高），确保条码扫描器Enter键被首先拦截
    }

    isBarcode(input) {
        // Check if input looks like a barcode
        // Common barcode formats: EAN-13 (13 digits), UPC-A (12 digits), Code 128, etc.
        const barcodePatterns = [
            /^\d{8}$/,          // EAN-8
            /^\d{12}$/,         // UPC-A
            /^\d{13}$/,         // EAN-13
            /^\d{14}$/,         // ITF-14
            /^[A-Z0-9]{6,}$/i,  // Code 128 (alphanumeric)
            /^[A-Z0-9\-_]{4,}$/i, // SKU format with dashes/underscores (like MPABC-1)
        ];
        
        return barcodePatterns.some(pattern => pattern.test(input));
    }

    activateBarcodeScanner() {
        const searchInput = document.getElementById('product-search');
        if (searchInput) {
            searchInput.focus();
            searchInput.select();
            this.showToast(posTranslations['Ready to scan barcode'] || 'Ready to scan barcode...', 'info');
        }
    }

    async searchByBarcode(barcode) {
        if (!barcode) return;

        this.showToast(posTranslations['Searching for product'] || 'Searching for product...', 'info');

        // 步骤1：首先尝试从本地IndexedDB查找（无论在线还是离线）
        try {
            const localProduct = await this.searchLocalBySKU(barcode);
            if (localProduct) {
                this.addToCart(localProduct);
                this.showToast(posTranslations['Product added (local)'] || 'Product added (local)', 'success');

                const searchInput = document.getElementById('product-search');
                if (searchInput) {
                    searchInput.value = '';
                }
                return; // 本地找到，直接返回
            }
        } catch (e) {
            // 本地查找失败，继续尝试服务器
        }

        // 步骤2：本地未找到，且在线时先尝试Meilisearch（<50ms），再AJAX兜底
        if (!navigator.onLine) {
            this.showToast(posTranslations['Product not found in local cache (offline)'] || 'Product not found in local cache (offline)', 'error');
            return;
        }

        // 步骤2a：Meilisearch 快速查找
        const msConfig = ruiyi_pos_ajax.meilisearch;
        if (msConfig && msConfig.host && msConfig.search_key) {
            try {
                const msResp = await fetch(msConfig.host + '/indexes/' + msConfig.index_name + '/search', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': 'Bearer ' + msConfig.search_key
                    },
                    body: JSON.stringify({ q: barcode, limit: 1 })
                });
                const msData = await msResp.json();
                if (msData.hits && msData.hits.length > 0) {
                    const hit = msData.hits[0];
                    // 精确匹配条码或SKU才算命中
                    const hitBarcode = (hit.barcode || '').toLowerCase().trim();
                    const hitSku = (hit.sku || '').toLowerCase().trim();
                    const barcodeLC = barcode.toLowerCase().trim();
                    if (hitBarcode === barcodeLC || hitSku === barcodeLC) {
                        this.addToCart(hit);
                        this.showToast(posTranslations['Product added'] || 'Product added to cart', 'success');
                        if (typeof ProductCacheManager !== 'undefined' && ProductCacheManager.addProductToCache) {
                            ProductCacheManager.addProductToCache(hit);
                        }
                        const searchInput = document.getElementById('product-search');
                        if (searchInput) searchInput.value = '';
                        return;
                    }
                }
            } catch (e) {
                // Meilisearch 失败，继续AJAX兜底
            }
        }

        // 步骤2b：AJAX MySQL 兜底查找
        try {
            const data = await this.ajaxRequest({
                pos_action: 'search_by_barcode',
                barcode: barcode
            });

            if (data.success) {
                const product = data.data.product;
                if (product && product.id) {
                    this.addToCart(product);
                    this.showToast(data.data.message || 'Product added to cart', 'success');

                    // Save found product to offline IndexedDB cache
                    if (typeof ProductCacheManager !== 'undefined' && ProductCacheManager.addProductToCache) {
                        ProductCacheManager.addProductToCache(product);
                    }
                } else {
                    this.showToast(posTranslations['Invalid product data'] || 'Invalid product data', 'error');
                }

                const searchInput = document.getElementById('product-search');
                if (searchInput) {
                    searchInput.value = '';
                }
            } else {
                // 产品未找到，清空输入框并显示确认弹窗询问是否创建
                const variosInput = document.getElementById('varios-price-input');
                if (variosInput) variosInput.value = '';
                this.showProductNotFoundConfirm(barcode);
            }
        } catch (error) {
            this.showToast(posTranslations['Barcode search failed'] || 'Barcode search failed', 'error');
        }
    }

    /**
     * 从本地IndexedDB按SKU/条码精确查找产品
     */
    searchLocalBySKU(sku) {
        return new Promise((resolve, reject) => {
            if (!sku) {
                resolve(null);
                return;
            }

            const skuLower = sku.toLowerCase().trim();

            const request = indexedDB.open('ruiyi_pos_cache', 5);

            request.onerror = () => resolve(null);

            request.onsuccess = () => {
                const db = request.result;
                if (!db.objectStoreNames.contains('products')) {
                    resolve(null);
                    return;
                }

                const transaction = db.transaction(['products'], 'readonly');
                const store = transaction.objectStore('products');

                // 尝试使用SKU索引快速查找
                if (store.indexNames.contains('sku')) {
                    const index = store.index('sku');
                    const getRequest = index.get(skuLower);
                    getRequest.onsuccess = () => {
                        if (getRequest.result) {
                            resolve(getRequest.result);
                        } else {
                            // 索引未找到，回退到遍历查找
                            this.searchLocalByTraversal(store, skuLower, resolve);
                        }
                    };
                    getRequest.onerror = () => {
                        this.searchLocalByTraversal(store, skuLower, resolve);
                    };
                } else {
                    // 无索引，遍历查找
                    this.searchLocalByTraversal(store, skuLower, resolve);
                }
            };

            request.onupgradeneeded = (event) => {
                // 数据库版本升级时会触发，这里不处理，让offline-products-cache.js处理
            };
        });
    }

    /**
     * 遍历IndexedDB查找产品（回退方案）
     */
    searchLocalByTraversal(store, skuLower, resolve) {
        const getAllRequest = store.getAll();
        getAllRequest.onsuccess = () => {
            const products = getAllRequest.result || [];
            // 第一优先：精确匹配
            const exactMatch = products.find(p => {
                const productSku = (p.sku || '').toLowerCase().trim();
                const productBarcode = (p.barcode || '').toLowerCase().trim();
                return productSku === skuLower || productBarcode === skuLower;
            });
            if (exactMatch) {
                resolve(exactMatch);
                return;
            }
            // 第二优先：后缀匹配（输入条码后几位也能找到产品）
            if (skuLower.length >= 4) {
                const suffixMatch = products.find(p => {
                    const productSku = (p.sku || '').toLowerCase().trim();
                    const productBarcode = (p.barcode || '').toLowerCase().trim();
                    return (productSku.length > skuLower.length && productSku.endsWith(skuLower)) ||
                           (productBarcode.length > skuLower.length && productBarcode.endsWith(skuLower));
                });
                if (suffixMatch) {
                    resolve(suffixMatch);
                    return;
                }
            }
            resolve(null);
        };
        getAllRequest.onerror = () => resolve(null);
    }

    updateSearchResults(results, searchTerm) {
        const searchResultsInfo = document.getElementById('search-results-info');
        const searchResultsText = document.getElementById('search-results-text');
        
        if (searchResultsInfo && searchResultsText) {
            if (results.length > 0) {
                searchResultsText.textContent = `Found ${results.length} product${results.length > 1 ? 's' : ''} for "${searchTerm}"`;
                searchResultsInfo.classList.remove('hidden');
            } else {
                searchResultsInfo.classList.add('hidden');
            }
        }
    }

    // Keyboard Shortcuts
    initKeyboardShortcuts() {
        document.addEventListener('keydown', (e) => {
            // 禁用Backspace键（在非输入框中）
            if (e.key === 'Backspace') {
                const activeElement = document.activeElement;
                const isInputField = activeElement && (
                    activeElement.tagName === 'INPUT' ||
                    activeElement.tagName === 'TEXTAREA'
                );

                if (!isInputField) {
                    e.preventDefault();
                    e.stopPropagation();
                    e.stopImmediatePropagation();
                    return;
                }
                // 在输入框中允许正常删除
                return;
            }

            // 🔥 特殊键位处理：+ 和 - 键（不受输入框限制）
            // 这些键在任何时候都应该工作，即使在输入框中
            if (e.key === '+' || e.key === '=') {
                // 🔥 如果在输入框中（非Varios），允许正常输入特殊符号
                const plusActiveEl = document.activeElement;
                if (plusActiveEl && (plusActiveEl.tagName === 'INPUT' || plusActiveEl.tagName === 'TEXTAREA') && plusActiveEl.id !== 'varios-price-input') {
                    return;
                }
                // 🔥 检查是否有结算弹窗打开
                const modalsOpen = [
                    'payment-method-modal',
                    'cash-payment-modal',
                    'points-management-modal'
                ].some(modalId => {
                    const modal = document.getElementById(modalId);
                    return modal && !modal.classList.contains('hidden');
                });

                if (modalsOpen) {
                    // 结算弹窗打开时，屏蔽+键
                    e.preventDefault();
                    e.stopPropagation();
                    e.stopImmediatePropagation();
                    return;
                }

                e.preventDefault();
                e.stopPropagation();
                e.stopImmediatePropagation();
                this.addVariosFromKeyboard();
                return;
            }

            // 产品编号搜索快捷键（可配置，在varios输入框有内容时）
            const productNumberKey = window.productNumberKey || 'm';
            if (e.key.toLowerCase() === productNumberKey.toLowerCase()) {
                const activeElement = document.activeElement;
                const isVariosInput = activeElement && activeElement.id === 'varios-price-input';
                const variosValue = isVariosInput ? activeElement.value.trim() : '';

                if (isVariosInput && variosValue.length > 0) {
                    e.preventDefault();
                    e.stopPropagation();
                    e.stopImmediatePropagation();
                    this.findAndAddProductByNumber(variosValue);
                    activeElement.value = '';
                    activeElement.focus();
                    return;
                }
                return;
            }

            // F8 键：已在 bindEvents() 中处理退货模式，此处不再处理

            // 🔥 新功能1：上下键选中购物车产品
            if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
                // 检查是否有弹窗打开
                const modalsOpen = [
                    'add-product-modal',
                    'product-search-modal',
                    'payment-method-modal',
                    'cash-payment-modal',
                    'points-management-modal',
                    'hold-order-modal',
                    'held-orders-modal'
                ].some(modalId => {
                    const modal = document.getElementById(modalId);
                    return modal && !modal.classList.contains('hidden');
                });

                if (modalsOpen) {
                    // 有弹窗打开，不处理上下键
                    return;
                }

                if (this.cart.length === 0) {
                    // 购物车为空，不处理
                    return;
                }

                e.preventDefault();
                this.navigateCart(e.key === 'ArrowUp' ? 'up' : 'down');
                return;
            }

            // Skip if user is typing in an input field (for other keys)
            const activeElement = document.activeElement;
            const isInputField = activeElement && (
                activeElement.tagName === 'INPUT' ||
                activeElement.tagName === 'TEXTAREA' ||
                activeElement.contentEditable === 'true'
            );

            if (isInputField) return;

            // 🔥 F5 键专用处理：此监听器不应处理F5（已在主监听器中处理）
            if (e.key === 'F5') {
                // F5已经在主键盘监听器（bindEvents）中处理，这里直接返回避免重复处理
                return;
            }

            // Build current key combination
            let currentKey = '';
            const modifiers = [];

            if (e.ctrlKey) modifiers.push('Ctrl');
            if (e.altKey) modifiers.push('Alt');
            if (e.shiftKey && e.key.length > 1) modifiers.push('Shift'); // Only add Shift for special keys
            if (e.metaKey) modifiers.push('Meta');

            // Get the key name
            if (e.key.length === 1) {
                // Regular character
                currentKey = e.key.toUpperCase();
            } else {
                // Special key
                currentKey = e.key;
            }

            // Combine modifiers and key
            if (modifiers.length > 0) {
                currentKey = modifiers.join('+') + '+' + currentKey;
            }

            // Check for keyboard shortcuts
            if (keyboardShortcuts) {
                Object.entries(keyboardShortcuts).forEach(([action, shortcut]) => {
                    if (currentKey === shortcut) {
                        e.preventDefault();
                        this.handleKeyboardShortcut(action);
                    }
                });
            }
        });
    }

    handleKeyboardShortcut(action) {
        switch (action) {
            case 'complete_sale':
                const checkoutBtn = document.querySelector('[data-action="checkout"]');
                if (checkoutBtn && !checkoutBtn.disabled) {
                    checkoutBtn.click();
                }
                break;
                
            case 'clear_cart':
                const clearBtn = document.querySelector('[data-action="clear-cart"]');
                if (clearBtn) clearBtn.click();
                break;
                
            case 'barcode_scanner':
                this.activateBarcodeScanner();
                break;
                
            case 'hold_order':
                const holdBtn = document.querySelector('[data-action="hold-order"]');
                if (holdBtn) holdBtn.click();
                break;
                
            case 'retrieve_order':
                const retrieveBtn = document.querySelector('[data-action="held-orders"]');
                if (retrieveBtn) retrieveBtn.click();
                break;
                
            case 'payment_cash':
                if (this.cart.length > 0) {
                    this.showCashPaymentModal();
                }
                break;
                
            case 'quick_add_product':
                // 🔥 F6 - 快速添加产品弹窗
                console.log('[POS handleKeyboardShortcut] quick_add_product (F6) - 打开快速添加产品弹窗');
                this.showQuickAddProductModal();
                break;

            case 'points_management':
                // 🔥 F8 - 退货模式（已在bindEvents中处理）
                break;

            case 'search_products':
                // 🔥 F9 - 已禁用
                console.log('[POS handleKeyboardShortcut] search_products (F9) 已禁用');
                break;

            case 'supplier_management':
                // 🔥 F7 - 已禁用
                console.log('[POS handleKeyboardShortcut] supplier_management (F7) 已禁用');
                break;

            case 'void_transaction':
                if (this.cart.length > 0) {
                    if (confirm(posTranslations['Are you sure you want to void this transaction?'])) {
                        this.clearCart();
                        this.showToast(posTranslations['Transaction voided'], 'warning');
                    }
                }
                break;

            case 'cash_drawer':
                const cashDrawerBtn = document.querySelector('[data-action="open-cash-drawer"]');
                if (cashDrawerBtn) cashDrawerBtn.click();
                break;

            default:
                console.log('Unknown shortcut action:', action);
        }
    }

