    performProductSearch(query) {
        if (!query || query.length < 1) {
            this.hideSearchStates();
            // If query is empty, show initial products
            if (!navigator.onLine && window.ProductCacheManager) {
                window.ProductCacheManager.getCachedProducts().then(products => {
                    if (products && products.length > 0) {
                        const limited = products.slice(0, 30);
                        this.displaySearchResults(limited);
                    }
                });
            } else {
                this.loadInitialProducts();
            }
            return;
        }

        this.showSearchLoading();

        // SKU SUFFIX SEARCH: pure digits, length >= 6
        // Bypasses Meilisearch / offline cache; goes straight to backend AJAX
        // with sku_suffix flag so the backend runs a dedicated LIKE '%digits' query.
        if (/^\d{6,}$/.test(query)) {
            if (!navigator.onLine) {
                this.hideSearchStates();
                this.showToast('SKU 后缀搜索需要联网', 'warning');
                this.showNoResults();
                return;
            }
            this._searchViaAjax(query, true);
            return;
        }

        // OFFLINE: search IndexedDB cache
        if (!navigator.onLine && window.ProductCacheManager) {
            window.ProductCacheManager.searchCachedProducts(query).then(products => {
                this.hideSearchStates();
                if (products && products.length > 0) {
                    this.displaySearchResults(products);
                } else {
                    this.showNoResults();
                }
            }).catch(error => {
                console.error('Cache search error:', error);
                this.hideSearchStates();
                this.showNoResults();
            });
            return;
        }

        // ONLINE: use Meilisearch if configured, else fallback to AJAX
        const msConfig = (typeof ruiyi_pos_ajax !== 'undefined') ? ruiyi_pos_ajax.meilisearch : null;

        if (msConfig && msConfig.host && msConfig.search_key) {
            // Direct Meilisearch search (fastest: browser -> Meilisearch, no PHP)
            fetch(msConfig.host + '/indexes/' + msConfig.index_name + '/search', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': 'Bearer ' + msConfig.search_key
                },
                body: JSON.stringify({ q: query, limit: 20 })
            })
            .then(response => response.json())
            .then(data => {
                this.hideSearchStates();
                const hits = data.hits || [];
                if (hits.length > 0) {
                    // Map Meilisearch hits to expected product format
                    const products = hits.map(hit => ({
                        id: hit.id,
                        name: hit.name,
                        sku: hit.sku || '',
                        barcode: hit.barcode || '',
                        price: hit.price_numeric || 0,
                        stock: hit.stock,
                        image: hit.image || '',
                        formatted_price: hit.formatted_price || hit.price || '',
                        match_type: 'meilisearch'
                    }));
                    this.displaySearchResults(products);
                } else {
                    this.showNoResults();
                }
            })
            .catch(error => {
                console.warn('Meilisearch search failed, falling back to AJAX:', error.message);
                this._searchViaAjax(query);
            });
        } else {
            // Fallback: original AJAX search
            this._searchViaAjax(query);
        }
    }

    /**
     * Fallback search via WordPress AJAX (when Meilisearch is not available)
     */
    _searchViaAjax(query, isSkuSuffix = false) {
        const params = {
            action: 'ruiyi_pos_ajax',
            pos_action: 'search_products',
            search: query,
            nonce: ruiyi_pos_ajax.nonce
        };
        if (isSkuSuffix) {
            params.sku_suffix = '1';
        }
        fetch(ruiyi_pos_ajax.ajax_url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams(params)
        })
        .then(response => response.json())
        .then(data => {
            this.hideSearchStates();
            if (data.success && data.data.products && data.data.products.length > 0) {
                this.displaySearchResults(data.data.products);
            } else {
                this.showNoResults();
            }
        })
        .catch(error => {
            console.error('Product search error:', error);
            // Try cache if network fails
            if (window.ProductCacheManager) {
                window.ProductCacheManager.searchCachedProducts(query).then(products => {
                    this.hideSearchStates();
                    if (products && products.length > 0) {
                        this.displaySearchResults(products);
                    } else {
                        this.showNoResults();
                    }
                }).catch(() => {
                    this.hideSearchStates();
                    this.showNoResults();
                });
            } else {
                this.hideSearchStates();
                this.showNoResults();
            }
        });
    }

    handleProductSearchEnter() {
        const results = document.querySelectorAll('.search-result-item');
        if (results.length === 1) {
            // If only one result, add it automatically
            results[0].click();
        } else if (results.length > 1) {
            // If multiple results, add the first one
            results[0].click();
        }
    }

    displaySearchResults(products) {
        const resultsContainer = document.getElementById('product-search-results');
        if (!resultsContainer) return;

        resultsContainer.innerHTML = '';

        products.forEach(product => {
            const resultItem = document.createElement('div');
            resultItem.className = 'search-result-item p-4 border border-gray-200 rounded-lg cursor-pointer hover:bg-blue-50 hover:border-blue-300 transition-all';
            resultItem.dataset.product = JSON.stringify(product);

            resultItem.innerHTML = `
                <div class="flex items-center justify-between">
                    <div class="flex-1">
                        <h4 class="font-semibold text-gray-900">${product.name}</h4>
                        <p class="text-sm text-gray-600">SKU: ${product.sku || 'N/A'}</p>
                        ${product.stock ? `<p class="text-xs text-gray-500">Stock: ${product.stock}</p>` : ''}
                    </div>
                    <div class="text-right">
                        <p class="text-xl font-bold text-blue-600">${product.formatted_price}</p>
                        <p class="text-sm text-gray-500">Click to add</p>
                    </div>
                </div>
            `;

            resultsContainer.appendChild(resultItem);
        });
    }

    showSearchLoading() {
        const loading = document.getElementById('product-search-loading');
        const results = document.getElementById('product-search-results');
        const noResults = document.getElementById('product-search-no-results');

        if (loading) loading.classList.remove('hidden');
        if (results) results.innerHTML = '';
        if (noResults) noResults.classList.add('hidden');
    }

    showNoResults() {
        const loading = document.getElementById('product-search-loading');
        const results = document.getElementById('product-search-results');
        const noResults = document.getElementById('product-search-no-results');

        if (loading) loading.classList.add('hidden');
        if (results) results.innerHTML = '';
        if (noResults) noResults.classList.remove('hidden');
    }

    hideSearchStates() {
        const loading = document.getElementById('product-search-loading');
        const noResults = document.getElementById('product-search-no-results');

        if (loading) loading.classList.add('hidden');
        if (noResults) noResults.classList.add('hidden');
    }

    loadInitialProducts() {
        this.showSearchLoading();

        // OFFLINE: use cached products
        if (!navigator.onLine && window.ProductCacheManager) {
            window.ProductCacheManager.getCachedProducts().then(products => {
                this.hideSearchStates();
                if (products && products.length > 0) {
                    this.displaySearchResults(products.slice(0, 30));
                } else {
                    this.showNoResults();
                }
            }).catch(() => {
                this.hideSearchStates();
                this.showNoResults();
            });
            return;
        }

        // ONLINE: Meilisearch empty query (returns recent products by id:desc)
        const msConfig = (typeof ruiyi_pos_ajax !== 'undefined') ? ruiyi_pos_ajax.meilisearch : null;

        if (msConfig && msConfig.host && msConfig.search_key) {
            fetch(msConfig.host + '/indexes/' + msConfig.index_name + '/search', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': 'Bearer ' + msConfig.search_key
                },
                body: JSON.stringify({ q: '', limit: 30, sort: ['id:desc'] })
            })
            .then(response => response.json())
            .then(data => {
                this.hideSearchStates();
                const hits = data.hits || [];
                if (hits.length > 0) {
                    const products = hits.map(hit => ({
                        id: hit.id,
                        name: hit.name,
                        sku: hit.sku || '',
                        barcode: hit.barcode || '',
                        price: hit.price_numeric || 0,
                        stock: hit.stock,
                        image: hit.image || '',
                        formatted_price: hit.formatted_price || hit.price || '',
                    }));
                    this.displaySearchResults(products);
                } else {
                    this.showNoResults();
                }
            })
            .catch(() => {
                // Fallback to AJAX
                this._loadInitialViaAjax();
            });
        } else {
            this._loadInitialViaAjax();
        }
    }

    /**
     * Fallback: load initial products via WordPress AJAX
     */
    _loadInitialViaAjax() {
        fetch(ruiyi_pos_ajax.ajax_url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
                action: 'ruiyi_pos_ajax',
                pos_action: 'get_initial_products',
                limit: 30,
                nonce: ruiyi_pos_ajax.nonce
            })
        })
        .then(response => response.json())
        .then(data => {
            this.hideSearchStates();
            if (data.success && data.data.products && data.data.products.length > 0) {
                this.displaySearchResults(data.data.products);
            } else {
                this.showNoResults();
            }
        })
        .catch(error => {
            console.error('Initial products load error:', error);
            if (window.ProductCacheManager) {
                window.ProductCacheManager.getCachedProducts().then(products => {
                    this.hideSearchStates();
                    if (products && products.length > 0) {
                        this.displaySearchResults(products.slice(0, 30));
                    } else {
                        this.showNoResults();
                    }
                }).catch(() => {
                    this.hideSearchStates();
                    this.showNoResults();
                });
            } else {
                this.hideSearchStates();
                this.showNoResults();
            }
        });
    }

    // Add Product Modal Methods
    // 🔥 支持传入预填的条码/SKU参数
    showAddProductModal(prefillBarcode = null) {
        // 🔥 清空Varios输入框并失焦
        const variosInput = document.getElementById('varios-price-input');
        if (variosInput) {
            variosInput.value = '';
            variosInput.blur();
        }

        // 🔥 加载供应商到下拉框
        this.loadSupplierOptions();

        const modal = document.getElementById('add-product-modal');
        const form = document.getElementById('add-product-form');
        if (modal) {
            modal.classList.remove('hidden');
            if (form) {
                form.reset();
                // 🔥 重置编辑状态
                document.getElementById('product-edit-id').value = '';
                this.resetAddProductFormState();

                // 🔥 初始化SKU输入框扫描检测
                this.initSkuScannerDetection();

                // 显示/隐藏SKU生成器
                this.toggleSkuGeneratorVisibility();

                // 🔥 如果有预填条码，设置到SKU输入框
                const skuInput = document.getElementById('product-sku');
                if (skuInput) {
                    if (prefillBarcode) {
                        skuInput.value = prefillBarcode;
                        // 聚焦到产品名称输入框（SKU已填好）
                        const nameInput = document.getElementById('product-name');
                        if (nameInput) {
                            setTimeout(() => nameInput.focus(), 100);
                        }
                    } else {
                        // 聚焦到SKU输入框，方便扫描条码
                        setTimeout(() => skuInput.focus(), 100);
                    }
                }
            }
        }
    }

