    /**
     * 重置添加产品表单状态
     */
    resetAddProductFormState() {
        const saveBtn = document.getElementById('save-product-btn');
        const statusEl = document.getElementById('sku-search-status');
        if (saveBtn) {
            saveBtn.textContent = saveBtn.dataset.saveText || '保存产品';
            saveBtn.classList.remove('bg-green-600', 'hover:bg-green-700');
            saveBtn.classList.add('bg-blue-600', 'hover:bg-blue-700');
        }
        if (statusEl) {
            statusEl.textContent = '';
            statusEl.className = 'ml-2 text-xs font-normal';
        }
    }

    /**
     * 初始化SKU输入框扫描检测
     */
    initSkuScannerDetection() {
        const skuInput = document.getElementById('product-sku');
        if (!skuInput || skuInput._scannerInitialized) return;

        skuInput._scannerInitialized = true;
        let skuBuffer = '';
        let lastKeyTime = 0;
        let scannerActive = false;
        let searchTimeout = null;

        skuInput.addEventListener('keydown', (e) => {
            const currentTime = Date.now();
            const timeDiff = currentTime - lastKeyTime;

            // 检测快速输入（条码扫描器特征）
            if (timeDiff < 50 && timeDiff > 0 && skuBuffer.length > 0) {
                scannerActive = true;
            }

            // Enter键处理
            if (e.key === 'Enter') {
                e.preventDefault();
                const sku = skuInput.value.trim();
                if (sku) {
                    this.searchProductBySku(sku);
                }
                skuBuffer = '';
                scannerActive = false;
                return;
            }

            // 累积输入
            if (e.key.length === 1) {
                skuBuffer += e.key;
            }

            lastKeyTime = currentTime;

            // 清除之前的搜索延时
            if (searchTimeout) {
                clearTimeout(searchTimeout);
            }

            // 延迟搜索（用户停止输入500ms后自动搜索）
            searchTimeout = setTimeout(() => {
                const sku = skuInput.value.trim();
                if (sku && sku.length >= 3) {
                    this.searchProductBySku(sku);
                }
                skuBuffer = '';
                scannerActive = false;
            }, 500);
        });

        // 粘贴处理
        skuInput.addEventListener('paste', (e) => {
            setTimeout(() => {
                const sku = skuInput.value.trim();
                if (sku) {
                    this.searchProductBySku(sku);
                }
            }, 100);
        });
    }

    /**
     * 根据SKU搜索产品
     */
    searchProductBySku(sku) {
        const loadingEl = document.getElementById('sku-loading');
        const statusEl = document.getElementById('sku-search-status');

        if (loadingEl) loadingEl.classList.remove('hidden');
        if (statusEl) {
            statusEl.textContent = '搜索中...';
            statusEl.className = 'ml-2 text-xs font-normal text-blue-600';
        }

        // 🔥 使用 ajaxRequest 方法，支持自动 nonce 刷新
        this.ajaxRequest({
            pos_action: 'search_product_by_sku',
            sku: sku
        })
        .then(data => {
            if (loadingEl) loadingEl.classList.add('hidden');

            if (data.success && data.data && data.data.product) {
                // 找到产品，填充表单
                this.fillProductForm(data.data.product);
                if (statusEl) {
                    statusEl.textContent = '✓ 找到产品，可编辑';
                    statusEl.className = 'ml-2 text-xs font-normal text-green-600';
                }
            } else {
                // 未找到产品，重置为新建模式
                document.getElementById('product-edit-id').value = '';
                this.resetAddProductFormState();
                if (statusEl) {
                    statusEl.textContent = '新产品';
                    statusEl.className = 'ml-2 text-xs font-normal text-orange-600';
                }
            }
        })
        .catch(error => {
            console.error('[SKU Search] Error:', error);
            if (loadingEl) loadingEl.classList.add('hidden');
            if (statusEl) {
                statusEl.textContent = '搜索失败';
                statusEl.className = 'ml-2 text-xs font-normal text-red-600';
            }
        });
    }

    /**
     * 填充产品表单（用于编辑已有产品）
     */
    fillProductForm(product) {
        // 填充产品ID（用于更新）
        document.getElementById('product-edit-id').value = product.id || '';

        // 填充表单字段
        const nameInput = document.getElementById('product-name');
        const skuInput = document.getElementById('product-sku');
        const retailPriceInput = document.getElementById('product-retail-price');
        const categorySelect = document.getElementById('product-category');
        const supplierInput = document.getElementById('product-supplier');
        const stockInput = document.getElementById('product-stock');

        if (nameInput) nameInput.value = product.name || '';
        if (skuInput) skuInput.value = product.sku || '';
        if (retailPriceInput) retailPriceInput.value = product.regular_price || product.price || '';
        if (categorySelect && product.category_id) {
            categorySelect.value = product.category_id;
        }
        if (supplierInput) supplierInput.value = product.supplier || '';
        if (stockInput) {
            const stockValue = product.stock !== null && product.stock !== undefined && product.stock !== -1 ? product.stock : '';
            stockInput.value = stockValue;
        }

        // 更新按钮文本为"更新产品"
        const saveBtn = document.getElementById('save-product-btn');
        if (saveBtn) {
            saveBtn.textContent = saveBtn.dataset.updateText || '更新产品';
            saveBtn.classList.remove('bg-blue-600', 'hover:bg-blue-700');
            saveBtn.classList.add('bg-green-600', 'hover:bg-green-700');
        }

        // 聚焦到产品名称输入框
        const productNameInput = document.getElementById('product-name');
        if (productNameInput) {
            productNameInput.focus();
            productNameInput.select();
        }
    }

    closeAddProductModal() {
        const modal = document.getElementById('add-product-modal');
        const form = document.getElementById('add-product-form');
        const loading = document.getElementById('add-product-loading');

        if (modal) {
            modal.classList.add('hidden');
        }
        if (form) {
            form.reset();
            form.style.display = '';
        }
        if (loading) {
            loading.classList.add('hidden');
        }

        // 重置编辑状态
        const editIdInput = document.getElementById('product-edit-id');
        if (editIdInput) editIdInput.value = '';

        const statusEl = document.getElementById('sku-search-status');
        if (statusEl) {
            statusEl.textContent = '';
            statusEl.className = 'ml-2 text-xs font-normal';
        }

        // 重置按钮状态
        this.resetAddProductFormState();

        // 🔥 关闭弹窗后聚焦回Varios
        setTimeout(() => this.focusVariosInput(), 100);
    }

    handleAddProduct() {
        const form = document.getElementById('add-product-form');
        const loading = document.getElementById('add-product-loading');

        // 检查是否是编辑现有产品
        const editId = document.getElementById('product-edit-id')?.value || '';
        const isEditing = editId && editId.trim() !== '';

        // 🔥 读取新表单的7个字段
        const productName = document.getElementById('product-name')?.value.trim() || '';
        const productSku = document.getElementById('product-sku')?.value.trim() || '';
        const productRetailPrice = parseFloat(document.getElementById('product-retail-price')?.value) || 0;
        const productCategory = document.getElementById('product-category')?.value || '';
        const productSupplier = document.getElementById('product-supplier')?.value.trim() || '';
        // 🔥 如果用户没有填写库存，默认设置为 -1 表示"有库存但不管理具体数量"
        const stockInput = document.getElementById('product-stock')?.value;
        const productStock = stockInput === '' || stockInput === null || stockInput === undefined ? -1 : parseInt(stockInput) || 0;

        // Validate required fields
        if (!productName) {
            this.showToast(posTranslations['Product name is required'] || 'Product name is required', 'error');
            return;
        }

        if (!productRetailPrice || productRetailPrice <= 0) {
            this.showToast(posTranslations['Valid retail price required'] || 'A valid retail price is required', 'error');
            return;
        }

        // Show loading state
        if (form) form.style.display = 'none';
        if (loading) loading.classList.remove('hidden');

        // 🔥 准备请求参数 (使用 ajaxRequest 方法，支持自动 nonce 刷新)
        const params = {
            pos_action: isEditing ? 'update_product' : 'create_product',
            product_name: productName,
            product_sku: productSku,
            product_price: productRetailPrice,
            product_category: productCategory,
            product_supplier: productSupplier,
            product_stock: productStock
        };

        // 如果是编辑模式，添加产品ID
        if (isEditing) {
            params.product_id = editId;
        }

        // 🔥 使用 ajaxRequest 方法 (自动处理 nonce 过期并重试)
        this.ajaxRequest(params)
        .then(data => {
            // Hide loading state
            if (form) form.style.display = '';
            if (loading) loading.classList.add('hidden');

            if (data.success && data.data.product) {
                const product = data.data.product;
                const successMsg = isEditing
                    ? (posTranslations['Product updated successfully'] || '产品更新成功!')
                    : (posTranslations['Product created successfully'] || 'Product created successfully!');
                this.showToast(successMsg, 'success');

                // Save to offline IndexedDB cache for offline access
                if (typeof ProductCacheManager !== 'undefined' && ProductCacheManager.addProductToCache) {
                    // Format product data for cache (ensure all required fields are present)
                    const cacheProduct = {
                        id: product.id,
                        name: product.name || productName,
                        sku: product.sku || productSku,
                        barcode: product.sku || productSku, // Use SKU as barcode if not provided
                        price: product.price || productRetailPrice,
                        sale_price: product.sale_price || null,
                        regular_price: product.regular_price || productRetailPrice,
                        stock_quantity: product.stock_quantity !== undefined ? product.stock_quantity : productStock,
                        stock_status: product.stock_status || 'instock',
                        category: product.category || productCategory,
                        image: product.image || null,
                        formatted_price: product.formatted_price || `${ruiyi_pos_ajax.currency}${productRetailPrice.toFixed(2)}`
                    };

                    ProductCacheManager.addProductToCache(cacheProduct);
                    console.log('[POS] New product saved to offline cache:', cacheProduct.sku);
                }

                // 标记为已保存，编辑产品列表中显示"已保存"
                if (product.id) {
                    if (!this.editedProductIds) this.editedProductIds = [];
                    const pid = Number(product.id);
                    if (!this.editedProductIds.includes(pid)) {
                        this.editedProductIds.push(pid);
                    }
                }

                // Close modal (don't add to cart)
                this.closeAddProductModal();
            } else {
                const errorMsg = data.data && data.data.message ? data.data.message : (posTranslations['Failed to save product'] || 'Failed to save product');
                this.showToast(errorMsg, 'error');
            }
        })
        .catch(error => {
            console.error((isEditing ? 'Update' : 'Create') + ' product error:', error);

            // Hide loading state
            if (form) form.style.display = '';
            if (loading) loading.classList.add('hidden');

            this.showToast((posTranslations['Save product error'] || 'Error saving product') + ': ' + error.message, 'error');
        });
    }

    // Sync cart data to customer display screen
    syncToCustomerDisplay() {
        // Debounce to prevent rapid successive calls
        clearTimeout(this.syncTimeout);
        this.syncTimeout = setTimeout(() => {
            this.performCustomerSync();
        }, 100);
    }
    
    performCustomerSync() {
        // Format cart data for customer display
        const customerCartData = {
            items: this.cart.map(item => {
                const isWeightItem = !!item.weightBased;
                const weightKg = (typeof item.weightKg === 'number' && !Number.isNaN(item.weightKg)) ? item.weightKg : null;
                const unit = item.weightUnit || this.scaleState.unit || this.scaleConfig.weight_unit || 'kg';
                const unitPricePerKg = item.lineUnitPrice ?? item.unitPricePerKg ?? (item.weightPricing && item.weightPricing.unit_price_per_kg);
                const totalNumeric = isWeightItem ? (parseFloat(item.price) || 0) : (parseFloat(item.price) || 0) * (parseFloat(item.quantity) || 0);
                const formattedTotal = this.formatPrice(totalNumeric);

                const unitPriceValue = isWeightItem
                    ? unitPricePerKg ?? (weightKg ? totalNumeric / (weightKg || 1) : item.price)
                    : item.price;

                const unitPriceDisplay = isWeightItem
                    ? `${ruiyi_pos_ajax.currency}${Number.parseFloat(unitPriceValue || 0).toFixed(2)} / ${unit}`
                    : (item.formatted_price || this.formatPrice(unitPriceValue));

                return {
                    name: item.name,
                    quantity: item.quantity,
                    displayQuantity: isWeightItem && weightKg !== null ? this.formatWeight(weightKg) : item.quantity,
                    price: unitPriceDisplay,
                    total: item.formatted_total || formattedTotal,
                    weightBased: isWeightItem,
                    weightKg: isWeightItem ? weightKg : null,
                    weightUnit: isWeightItem ? unit : null
                };
            }),
            total: this.calculateTotalFormatted(),
            timestamp: Date.now()
        };
        
        // Check if data actually changed
        const currentDataString = JSON.stringify(customerCartData);
        if (this.lastSyncData === currentDataString) {
            return; // No changes, skip sync
        }
        this.lastSyncData = currentDataString;
        
        // Save to localStorage for customer display screen to read
        localStorage.setItem('ruiyi_pos_customer_cart', JSON.stringify(customerCartData));
        
        // Trigger storage event for cross-tab communication
        window.dispatchEvent(new StorageEvent('storage', {
            key: 'ruiyi_pos_customer_cart',
            newValue: JSON.stringify(customerCartData)
        }));
        
        // Also trigger custom event for same-tab communication
        document.dispatchEvent(new CustomEvent('posCartUpdated', {
            detail: customerCartData
        }));
    }
    
    // Calculate numeric total for internal calculations
    calculateNumericTotal() {
        const total = this.cart.reduce((total, item) => {
            const isWeightItem = !!item.weightBased;
            if (isWeightItem) {
                return total + (parseFloat(item.price) || 0);
            }
            const price = parseFloat(item.price) || 0;
            const quantity = parseFloat(item.quantity) || 0;
            return total + (price * quantity);
        }, 0);

        // Apply points discount if any
        let discountedTotal = total;
        if (this.pendingPointsDiscount && this.pendingPointsDiscount.discount) {
            // Use consistent rounding to 2 decimal places
            const discount = parseFloat(this.pendingPointsDiscount.discount) || 0;
            discountedTotal = Math.round((total - discount) * 100) / 100;
            discountedTotal = Math.max(0, discountedTotal);
        }

        return discountedTotal;
    }
    
    // Calculate total for customer display (商品价格已含税)
    calculateTotalFormatted() {
        return this.formatPrice(this.calculateNumericTotal());
    }
    
    // Format price for display
    formatPrice(amount) {
        if (typeof wc_price_format !== 'undefined') {
            return wc_price_format.format(amount);
        }
        
        // Fallback formatting
        const formatted = parseFloat(amount).toFixed(2);
        return '€' + formatted;
    }

    // Helper function to reset button text to correct translation
    resetButtonTexts() {
        const checkoutBtn = document.getElementById('checkout-btn');
        if (checkoutBtn) {
            // Reset to original translated text with shortcut
            const originalHtml = checkoutBtn.getAttribute('data-original-text');
            if (originalHtml) {
                checkoutBtn.innerHTML = originalHtml;
            } else {
                checkoutBtn.textContent = posTranslations['Complete Transaction'] || 'Complete Transaction';
            }
        }
    }

    // ========================================
    // 产品名称自动补全 (Product Name Autocomplete)
    // ========================================
    initProductNameAutocomplete(inputId) {
        const input = document.getElementById(inputId);
        const dropdown = document.getElementById(inputId + '-suggestions');
        if (!input || !dropdown) return;

        let debounceTimer = null;
        let highlightIndex = -1;
        let justSelected = false; // 选中后抑制下一次input事件触发搜索

        const closeDropdown = () => {
            dropdown.classList.add('hidden');
            dropdown.innerHTML = '';
            highlightIndex = -1;
        };

        const renderSuggestions = (items, query) => {
            if (!items.length) { closeDropdown(); return; }
            dropdown.innerHTML = '';
            highlightIndex = -1;
            items.forEach((name, idx) => {
                const div = document.createElement('div');
                div.className = 'px-3 py-2 cursor-pointer hover:bg-blue-50 text-sm text-gray-800';
                div.setAttribute('data-index', idx);
                // Highlight matching portion
                const lowerName = name.toLowerCase();
                const matchStart = lowerName.indexOf(query.toLowerCase());
                if (matchStart >= 0) {
                    const before = name.substring(0, matchStart);
                    const match = name.substring(matchStart, matchStart + query.length);
                    const after = name.substring(matchStart + query.length);
                    div.innerHTML = before + '<strong class="text-blue-600">' + match + '</strong>' + after;
                } else {
                    div.textContent = name;
                }
                div.addEventListener('mousedown', (e) => {
                    e.preventDefault(); // Prevent blur before filling
                    justSelected = true;
                    input.value = name;
                    closeDropdown();
                    input.dispatchEvent(new Event('input', { bubbles: true }));
                });
                dropdown.appendChild(div);
            });
            dropdown.classList.remove('hidden');
        };

        const updateHighlight = () => {
            const items = dropdown.querySelectorAll('[data-index]');
            items.forEach((el, i) => {
                el.classList.toggle('bg-blue-100', i === highlightIndex);
            });
            if (highlightIndex >= 0 && items[highlightIndex]) {
                items[highlightIndex].scrollIntoView({ block: 'nearest' });
            }
        };

        input.addEventListener('input', () => {
            clearTimeout(debounceTimer);
            if (justSelected) { justSelected = false; return; }
            const query = input.value.trim();
            if (query.length < 1) { closeDropdown(); return; }

            debounceTimer = setTimeout(async () => {
                try {
                    let products = null;
                    if (typeof ProductCacheManager !== 'undefined') {
                        products = await ProductCacheManager.getCachedProducts();
                    }
                    if (!products || !products.length) {
                        closeDropdown();
                        return;
                    }
                    const lowerQ = query.toLowerCase();
                    const seen = new Set();
                    const matches = [];
                    for (const p of products) {
                        if (!p.name) continue;
                        const name = p.name.trim();
                        if (name.toLowerCase().startsWith(lowerQ) && !seen.has(name.toLowerCase())) {
                            seen.add(name.toLowerCase());
                            matches.push(name);
                            if (matches.length >= 100) break;
                        }
                    }
                    renderSuggestions(matches, query);
                } catch (err) {
                    console.warn('Product name autocomplete error:', err);
                    closeDropdown();
                }
            }, 200);
        });

        input.addEventListener('keydown', (e) => {
            if (dropdown.classList.contains('hidden')) return;
            const items = dropdown.querySelectorAll('[data-index]');
            const count = items.length;
            if (!count) return;

            if (e.key === 'ArrowDown') {
                e.preventDefault();
                e.stopPropagation();
                highlightIndex = (highlightIndex + 1) % count;
                updateHighlight();
            } else if (e.key === 'ArrowUp') {
                e.preventDefault();
                e.stopPropagation();
                highlightIndex = (highlightIndex - 1 + count) % count;
                updateHighlight();
            } else if (e.key === 'Enter' && highlightIndex >= 0) {
                e.preventDefault();
                e.stopPropagation();
                const selected = items[highlightIndex];
                if (selected) {
                    justSelected = true;
                    input.value = selected.textContent;
                    closeDropdown();
                    input.dispatchEvent(new Event('input', { bubbles: true }));
                }
            } else if (e.key === 'Escape') {
                e.stopPropagation();
                closeDropdown();
            }
        });

        input.addEventListener('blur', () => {
            // Delay to allow mousedown on suggestion to fire first
            setTimeout(closeDropdown, 150);
        });

        // Close when clicking outside
        document.addEventListener('click', (e) => {
            if (!input.contains(e.target) && !dropdown.contains(e.target)) {
                closeDropdown();
            }
        });
    }

    // ========================================
    // Varios 快捷输入功能
    // ========================================
    initVariosQuickInput() {
        const variosInput = document.getElementById('varios-price-input');
        if (!variosInput) {
            console.warn('Varios输入框未找到');
            return;
        }

        // 获取或创建Varios产品ID
        window.VARIOS_PRODUCT_ID = null;
        this.fetchOrCreateVariosProduct();

        // 🔥 监听输入框中的条码扫描器快速输入
        let variosInputBuffer = '';
        let variosLastKeyTime = 0;
        let variosScannerActive = false;

        // 🔥 监听输入事件，检测快速输入（条码扫描器）
        variosInput.addEventListener('input', (e) => {
            const currentTime = Date.now();
            const timeDiff = currentTime - variosLastKeyTime;

            // 检测快速输入（条码扫描器的特征：输入间隔<50ms）
            if (timeDiff > 0 && timeDiff < 50) {
                variosScannerActive = true;
            } else if (timeDiff >= 100) {
                // 如果间隔较长，重置扫描器状态（可能是手动输入）
                variosScannerActive = false;
            }

            variosLastKeyTime = currentTime;
        });

        // No longer restrict input - allow alphanumeric for SKU
        // Input is always active, no F1 activation needed

        // 按键事件处理
        variosInput.addEventListener('keydown', (e) => {
            // 🔥 如果退货弹窗打开，不处理任何键盘事件
            if (window.isRefundModalOpen) {
                return;
            }

            // Enter key - 智能判断：条码扫描/SKU搜索/Varios添加/结账
            if (e.key === 'Enter') {
                // 🔥 修复：不再检查isScannerActive，因为全局扫描器已经处理了键入
                // 只需检查输入框是否有值，如果有值就处理

                e.preventDefault();
                const value = e.target.value.trim();

                // 🔥 重置扫描器标记（Enter键意味着扫描完成）
                window.isScannerActive = false;

                // 🔥 立即清空输入框，防止重复扫描累积
                e.target.value = '';

                if (!value) {
                    // 🔥 如果购物车有产品，触发结账
                    if (this.cart.length > 0) {
                        const checkoutBtn = document.getElementById('checkout-btn');
                        if (checkoutBtn && !checkoutBtn.disabled) {
                            checkoutBtn.click();
                        }
                    }
                    return;
                }

                // 🔥 优先判断：如果检测到快速输入，直接按SKU/条码搜索
                if (variosScannerActive) {
                    this.searchAndAddBySKU(value);
                    variosScannerActive = false;  // 重置状态
                    return;
                }

                // 手动输入模式：根据内容判断
                // 🔥 规则：≥5 位纯数字视为 SKU/条码搜索，≤4 位纯数字视为 Varios 价格
                // 这样可以覆盖 EAN-8/12/13/14、自定义 5-7 位 SKU 等各种长度的数字条码
                // 同时保留 4 位及以下的数字作为杂项商品价格（如 "9.50"、"1234"）
                const isLikelyBarcode = /^\d{5,}$/.test(value);  // ≥5 位纯数字 = 条码/SKU

                if (isLikelyBarcode) {
                    // ≥5 位纯数字 → 按 SKU/条码搜索产品
                    this.searchAndAddBySKU(value);
                } else if (/^\d{1,4}([.,]\d*)?$/.test(value)) {
                    // ≤4 位数字（可含小数点/逗号，如 "10.50"、"9,50"、"1234"）= Varios 价格
                    e.target.value = value;
                    this.addVariosToCart();
                } else {
                    // 包含字母或特殊字符 = SKU
                    this.searchAndAddBySKU(value);
                }
                return;
            }

            // 🔥 移除了 + 键处理 - 现在由全局键盘监听统一处理（避免重复触发）
            // 不再需要在Varios输入框内单独处理+键

            // PageUp key - Modify selected product price (支持欧洲小数分隔符)
            if (e.key === 'PageUp') {
                e.preventDefault();
                // 🔥 支持欧洲小数分隔符（逗号）：将 "10,50" 转换为 "10.50"
                const normalizedValue = e.target.value.replace(',', '.');
                const value = parseFloat(normalizedValue);
                if (!isNaN(value) && value > 0) {
                    this.modifySelectedProductPrice(value);
                    e.target.value = ''; // Clear input after action
                } else {
                    this.showToast(posTranslations['Enter a valid price first'] || 'Enter a valid price first', 'warning');
                }
                return;
            }
            
            // Pause/Break key - Modify selected product quantity (支持小数，如1.5, 2.75, 1,25)
            if (e.key === 'Pause') {
                e.preventDefault();
                // 🔥 支持欧洲小数分隔符（逗号）：将 "1,25" 转换为 "1.25"
                const normalizedValue = e.target.value.replace(',', '.');
                const value = parseFloat(normalizedValue);
                if (!isNaN(value) && value > 0) {
                    this.modifySelectedProductQuantity(value);
                    e.target.value = ''; // Clear input after action
                } else {
                    this.showToast(posTranslations['Enter a valid quantity first'] || 'Enter a valid quantity first', 'warning');
                }
                return;
            }
            
            // "Ctrl + /" keys - Apply discount to all products (check FIRST before single /)
            if (e.key === '/' && e.ctrlKey) {
                e.preventDefault();
                // 🔥 支持欧洲小数分隔符（逗号）
                const normalizedValue = e.target.value.replace(',', '.');
                const value = parseFloat(normalizedValue);
                if (!isNaN(value) && value >= 0 && value <= 100) {
                    this.applyBulkDiscount(value);
                    e.target.value = ''; // Clear input after action
                } else {
                    this.showToast(posTranslations['Enter a valid discount (0-100)'] || 'Enter a valid discount (0-100)', 'warning');
                }
                return;
            }

            // "/" key - Apply discount to selected product (check AFTER Ctrl+/)
            if (e.key === '/') {
                e.preventDefault();
                // 🔥 支持欧洲小数分隔符（逗号）
                const normalizedValue = e.target.value.replace(',', '.');
                const value = parseFloat(normalizedValue);
                if (!isNaN(value) && value >= 0 && value <= 100) {
                    this.applyDiscountToSelected(value);
                    e.target.value = ''; // Clear input after action
                } else {
                    this.showToast(posTranslations['Enter a valid discount (0-100)'] || 'Enter a valid discount (0-100)', 'warning');
                }
                return;
            }
            
            // Home key - Change selected product name
            if (e.key === 'Home') {
                e.preventDefault();
                const newName = e.target.value.trim();
                if (newName && newName.length > 0) {
                    this.changeSelectedProductName(newName);
                    e.target.value = ''; // Clear input after action
                } else {
                    this.showToast(posTranslations['Enter a product name first'] || 'Enter a product name first', 'warning');
                }
                return;
            }
            
            // Escape - Clear input
            if (e.key === 'Escape') {
                e.preventDefault();
                e.target.value = '';
                return;
            }
        });

        // Enhanced input initialized
    }

    // Search and add product by SKU - 🔥 支持离线模式
    async searchAndAddBySKU(sku) {
        if (!sku) return;

        this.showToast(posTranslations['Searching for product'] || 'Searching for product...', 'info');

        // 🔥 步骤1：首先尝试从本地IndexedDB查找（无论在线还是离线）
        try {
            const localProduct = await this.searchLocalBySKU(sku);
            if (localProduct) {
                this.addToCart(localProduct);
                this.showToast(posTranslations['Product added (local)'] || 'Product added (local)', 'success');
                return; // 本地找到，直接返回
            }
        } catch (e) {
            // 本地查找失败，继续尝试服务器
        }

        // 🔥 步骤2：本地未找到，检查是否离线
        if (!navigator.onLine) {
            // 离线且本地未找到，显示确认弹窗询问是否创建
            this.showProductNotFoundConfirm(sku);
            return;
        }

        // 🔥 步骤3：在线时请求服务器（使用ajaxRequest自动处理nonce刷新）
        try {
            const data = await this.ajaxRequest({
                pos_action: 'search_by_barcode',
                barcode: sku
            });

            if (data.success) {
                const product = data.data.product;
                if (product && product.id) {
                    this.addToCart(product);
                    this.showToast(data.data.message || `${product.name} added to cart`, 'success');

                    // 🔥 将找到的产品保存到离线缓存
                    if (typeof ProductCacheManager !== 'undefined' && ProductCacheManager.addProductToCache) {
                        ProductCacheManager.addProductToCache(product);
                    }
                } else {
                    this.showToast(posTranslations['Invalid product data'] || 'Invalid product data', 'error');
                }
            } else {
                // 🔥 产品未找到，显示确认弹窗询问是否创建
                this.showProductNotFoundConfirm(sku);
            }
        } catch (error) {
            // 🔥 网络错误时也显示确认弹窗（可能刚断网）
            this.showProductNotFoundConfirm(sku);
        }
    }
    
    // Modify selected product price (Page Up key)
    modifySelectedProductPrice(newPrice) {
        if (!this.selectedProductId) {
            this.showToast(posTranslations['No product selected - Click a cart item first'] || 'No product selected - Click a cart item first', 'warning');
            return;
        }
        
        const item = this.cart.find(i => i.cartItemId === this.selectedProductId);
        if (!item) {
            this.showToast(posTranslations['Selected product not found in cart'] || 'Selected product not found in cart', 'error');
            return;
        }
        
        // Update price
        item.price = newPrice;
        item.customPrice = true;
        
        this.updateCart();
        this.showToast(`Price changed to €${newPrice.toFixed(2)}`, 'success');
    }
    
    // Modify selected product quantity (Pause/Break key) - 支持小数数量
    modifySelectedProductQuantity(newQuantity) {
        if (!this.selectedProductId) {
            this.showToast(posTranslations['No product selected - Click a cart item first'] || 'No product selected - Click a cart item first', 'warning');
            return;
        }

        const item = this.cart.find(i => i.cartItemId === this.selectedProductId);
        if (!item) {
            this.showToast(posTranslations['Selected product not found in cart'] || 'Selected product not found in cart', 'error');
            return;
        }

        // Check stock (对于小数数量，仍然检查库存上限)
        if (item.stock && newQuantity > item.stock) {
            this.showToast(`Only ${item.stock} in stock`, 'error');
            return;
        }

        // Update quantity (支持小数，如1.5, 2.75)
        item.quantity = newQuantity;

        this.updateCart();
        // 显示数量时，如果是整数则不显示小数点，否则显示小数
        const displayQuantity = Number.isInteger(newQuantity) ? newQuantity : newQuantity.toFixed(2);
        this.showToast(`Quantity changed to ${displayQuantity}`, 'success');
    }
    
    // Apply discount to selected product (/ key)
    applyDiscountToSelected(discountPercent) {
        if (!this.selectedProductId) {
            this.showToast(posTranslations['No product selected - Click a cart item first'] || 'No product selected - Click a cart item first', 'warning');
            return;
        }
        
        const item = this.cart.find(i => i.cartItemId === this.selectedProductId);
        if (!item) {
            this.showToast(posTranslations['Selected product not found in cart'] || 'Selected product not found in cart', 'error');
            return;
        }
        
        // Ensure we have original price saved
        if (!item.originalPrice) {
            item.originalPrice = item.price;
        }
        
        // Calculate discounted price
        const discountedPrice = item.originalPrice * (1 - discountPercent / 100);
        
        // Store discount percentage
        item.discountPercent = discountPercent;
        item.price = discountedPrice;
        item.customPrice = true; // Mark as modified
        
        this.updateCart();
        this.showToast(`${discountPercent}% discount applied to ${item.name}`, 'success');
    }
    
    // Apply bulk discount to all products (Ctrl + / keys)
    applyBulkDiscount(discountPercent) {
        if (this.cart.length === 0) {
            this.showToast(posTranslations['Cart is empty'] || 'Cart is empty', 'warning');
            return;
        }
        
        let discountedCount = 0;
        
        this.cart.forEach(item => {
            // Ensure we have original price saved
            if (!item.originalPrice) {
                item.originalPrice = item.price;
            }
            
            // Calculate discounted price
            const discountedPrice = item.originalPrice * (1 - discountPercent / 100);
            
            // Store discount percentage
            item.discountPercent = discountPercent;
            item.price = discountedPrice;
            item.customPrice = true; // Mark as modified
            
            discountedCount++;
        });
        
        this.updateCart();
        this.showToast(`${discountPercent}% discount applied to ${discountedCount} product(s)`, 'success');
    }
    
    // Change selected product name (Home key)
    changeSelectedProductName(newName) {
        if (!this.selectedProductId) {
            this.showToast(posTranslations['No product selected - Click a cart item first'] || 'No product selected - Click a cart item first', 'warning');
            return;
        }
        
        const item = this.cart.find(i => i.cartItemId === this.selectedProductId);
        if (!item) {
            this.showToast(posTranslations['Selected product not found in cart'] || 'Selected product not found in cart', 'error');
            return;
        }
        
        // Validate name length
        if (newName.length < 1) {
            this.showToast(posTranslations['Product name must be at least 1 character'] || 'Product name must be at least 1 character', 'warning');
            return;
        }
        
        // Store original name if not already stored (for potential restore)
        if (!item.originalName) {
            item.originalName = item.name;
        }
        
        // Change the name locally
        const oldName = item.name;
        item.name = newName;
        
        // Update cart display
        this.updateCart();
        this.showToast(`Name changed: "${oldName}" → "${newName}"`, 'success');

        // Send to backend immediately (real-time sync)
        this.syncNameChangeToBackend(item);
    }

    // Sync name change to backend - Updates product permanently in database
    syncNameChangeToBackend(item) {
        fetch(ruiyi_pos_ajax.ajax_url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
                action: 'ruiyi_pos_update_cart_item_name',
                nonce: ruiyi_pos_ajax.nonce,
                cart_item_id: item.cartItemId,
                product_id: item.id,
                new_name: item.name,
                original_name: item.originalName || item.name
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                this.showToast(posTranslations['Product name saved to database'] || 'Product name saved to database', 'success');
            } else {
                this.showToast(posTranslations['Failed to update product name'] || 'Failed to update product name', 'warning');
            }
        })
        .catch(error => {
            this.showToast(posTranslations['Network error updating name'] || 'Network error updating name', 'error');
        });
    }

    // 添加Varios到购物车 (支持欧洲小数分隔符)
    addVariosToCart() {
        const variosInput = document.getElementById('varios-price-input');
        if (!variosInput) return;

        // 🔥 支持欧洲小数分隔符（逗号）：将 "10,50" 转换为 "10.50"
        const normalizedValue = variosInput.value.replace(',', '.');
        const priceValue = parseFloat(normalizedValue);

        // 如果输入框为空或无效，增加最后一个Varios的数量
        if (!priceValue || priceValue <= 0 || isNaN(priceValue)) {
            const lastVarios = this.cart.filter(item => item.isVarios).pop();
            if (lastVarios) {
                lastVarios.quantity += 1;
                this.updateCart();
                this.showToast(`Varios €${lastVarios.price.toFixed(2)} x${lastVarios.quantity}`, 'success');
                return;
            } else {
                this.showToast('Por favor ingrese un precio válido', 'warning');
                // 🔥 不自动聚焦 - 保持当前焦点位置
                // 只有数字键(0-9)才会聚焦到Varios输入框
                return;
            }
        }

        // 检查Varios产品ID是否已获取
        if (!window.VARIOS_PRODUCT_ID) {
            this.showToast('Producto Varios no disponible, recargando...', 'warning');
            this.fetchOrCreateVariosProduct(() => {
                this.addVariosToCart(); // 重试
            });
            return;
        }

        // 🔥 退货模式：如果returnQuantity < 0，添加退货Varios
        if (this.returnQuantity < 0) {
            const returnQty = this.returnQuantity;
            const returnItem = {
                id: window.VARIOS_PRODUCT_ID,
                cartItemId: ++this.cartItemIdCounter,
                name: 'Varios',
                price: priceValue,
                originalPrice: priceValue,
                quantity: returnQty,
                image: ruiyi_pos_ajax.placeholder_image,
                stock: 9999,
                isVarios: true,
                isReturn: true,
                customPrice: false,
                discountPercent: 0
            };
            this.cart.push(returnItem);
            this.selectedProductId = returnItem.cartItemId;
            this.returnQuantity = 0; // 重置退货模式
            this.showReturnModeIndicator(false);
            this.updateCart();
            variosInput.value = '';
            return;
        }

        // 检查是否已有相同价格的Varios，有则合并数量
        const existingVarios = this.cart.find(item =>
            item.isVarios && parseFloat(item.price) === priceValue && !item.isReturn
        );

        if (existingVarios) {
            // 相同价格的Varios已存在，增加数量
            existingVarios.quantity += 1;
        } else {
            // 添加新的Varios商品
            const variosItem = {
                id: window.VARIOS_PRODUCT_ID,
                cartItemId: ++this.cartItemIdCounter, // Unique cart item ID
                name: 'Varios',
                price: priceValue,
                originalPrice: priceValue,
                quantity: 1,
                image: ruiyi_pos_ajax.placeholder_image,
                stock: 9999,
                isVarios: true, // 标记为Varios商品
                customPrice: false,
                discountPercent: 0
            };
            this.cart.push(variosItem);

            // Auto-select the newly added Varios item
            this.selectedProductId = variosItem.cartItemId;
        }

        this.updateCart();
        variosInput.value = ''; // 清空输入框
        this.showToast(`Varios €${priceValue.toFixed(2)} agregado al carrito`, 'success');
    }

    // 🔥 从键盘快捷键添加Varios产品（问题1修复，支持欧洲小数分隔符）
    addVariosFromKeyboard() {
        // 🔥 优先级1：检查Varios输入框是否有价格
        const variosInput = document.getElementById('varios-price-input');
        // 🔥 支持欧洲小数分隔符（逗号）：将 "10,50" 转换为 "10.50"
        const normalizedValue = variosInput ? variosInput.value.replace(',', '.') : '0';
        const priceValue = parseFloat(normalizedValue);


        if (priceValue && priceValue > 0 && !isNaN(priceValue)) {
            // 输入框有有效价格，添加Varios产品
            this.addVariosToCart();
            return;
        }

        // 🔥 优先级2：输入框为空，如果有选中的产品，增加该产品数量
        if (this.selectedProductId) {
            this.increaseSelectedItemQuantity();
            return;
        }

        // 🔥 优先级3：输入框为空且无选中产品，尝试增加最后一个Varios或提示
        this.addVariosToCart(); // 会尝试增加最后一个Varios或显示警告
    }

    // 🔥 增加选中产品数量（与-键对应）
    increaseSelectedItemQuantity() {
        // 如果没有选中产品，选择购物车中的最后一个产品
        if (!this.selectedProductId && this.cart.length > 0) {
            this.selectedProductId = this.cart[this.cart.length - 1].cartItemId;
        }

        if (!this.selectedProductId) {
            this.showToast('没有选中的产品', 'warning');
            return;
        }

        // 找到选中的产品
        const selectedItem = this.cart.find(item => item.cartItemId === this.selectedProductId);
        if (!selectedItem) {
            this.selectedProductId = null;
            return;
        }

        // 检查库存
        if (selectedItem.stock && selectedItem.quantity >= selectedItem.stock) {
            this.showToast('库存不足', 'error');
            return;
        }

        // 增加数量
        selectedItem.quantity += 1;
        this.updateCart();
        this.showToast(`${selectedItem.name} 数量: ${selectedItem.quantity}`, 'info');
    }

    // 🔥 减少选中产品数量（问题3修复）
    decreaseSelectedItemQuantity() {
        // 如果没有选中产品，选择购物车中的最后一个产品
        if (!this.selectedProductId && this.cart.length > 0) {
            this.selectedProductId = this.cart[this.cart.length - 1].cartItemId;
        }

        if (!this.selectedProductId) {
            this.showToast('没有选中的产品', 'warning');
            return;
        }

        // 找到选中的产品
        const selectedItem = this.cart.find(item => item.cartItemId === this.selectedProductId);
        if (!selectedItem) {
            this.selectedProductId = null;
            return;
        }

        if (selectedItem.quantity > 1) {
            selectedItem.quantity -= 1;
            this.updateCart();
            this.showToast(`${selectedItem.name} 数量: ${selectedItem.quantity}`, 'info');
        } else {
            // 数量为1时，删除产品（使用cartItemId确保只删除选中的项）
            this.removeFromCart(selectedItem.cartItemId, true);
            this.selectedProductId = null;
        }
    }

    // 🔥 按cartItemId增加数量（问题4修复辅助方法）
    increaseQuantityByCartItemId(cartItemId) {
        const item = this.cart.find(item => item.cartItemId === cartItemId);
        if (!item) return;

        if (item.weightBased) {
            this.showToast(posTranslations['Weight controlled by scale'] || 'Update weight using the scale', 'info');
            return;
        }

        if (item.stock && item.quantity >= item.stock) {
            this.showToast(posTranslations['Insufficient stock'] || 'Insufficient stock', 'error');
            return;
        }

        item.quantity += 1;
        this.updateCart();
    }

    // 🔥 按cartItemId减少数量（问题4修复辅助方法）
    decreaseQuantityByCartItemId(cartItemId) {
        const item = this.cart.find(item => item.cartItemId === cartItemId);
        if (!item) return;

        if (item.weightBased) {
            this.showToast(posTranslations['Weight controlled by scale'] || 'Update weight using the scale', 'info');
            return;
        }

        if (item.quantity > 1) {
            item.quantity -= 1;
            this.updateCart();
        } else {
            // 数量为1时，删除（使用cartItemId确保只删除这一个，修复问题2）
            this.removeFromCart(cartItemId, true);
        }
    }

    // 🔥 按cartItemId直接设置数量（输入框修改用）- 支持小数和欧洲格式
    updateQuantityByCartItemId(cartItemId, newQuantity) {
        const item = this.cart.find(item => item.cartItemId === cartItemId);
        if (!item) return;

        // 🔥 支持欧洲小数分隔符（逗号）：将 "1,25" 转换为 "1.25"
        const normalizedQuantity = String(newQuantity).replace(',', '.');
        const quantity = parseFloat(normalizedQuantity);
        if (isNaN(quantity)) {
            this.updateCart(); // 重置显示
            return;
        }

        if (item.weightBased) {
            this.showToast(posTranslations['Weight controlled by scale'] || 'Update weight using the scale', 'info');
            this.updateCart(); // 重置显示
            return;
        }

        if (quantity === 0) {
            // 删除产品（使用cartItemId，修复问题2）
            this.removeFromCart(cartItemId, true);
        } else if (quantity < 0) {
            // 🔥 允许负数量（退货模式）
            item.quantity = quantity;
            item.isReturn = true;
            this.updateCart();
        } else if (item.stock && quantity > item.stock) {
            this.showToast(posTranslations['Insufficient stock'] || 'Insufficient stock', 'error');
            this.updateCart(); // 重置显示
        } else {
            item.quantity = quantity;
            item.isReturn = false;
            this.updateCart();
        }
    }

    // 获取或创建Varios产品
    fetchOrCreateVariosProduct(callback) {
        fetch(ruiyi_pos_ajax.ajax_url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
                action: 'ruiyi_get_or_create_varios_product',
                nonce: ruiyi_pos_ajax.nonce
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.success && data.data.product_id) {
                window.VARIOS_PRODUCT_ID = data.data.product_id;
                if (callback && typeof callback === 'function') {
                    callback();
                }
            }
        })
        .catch(() => {});
    }

    // ========================================
    // 🔥 购物车导航功能（上下键选中产品）
    // ========================================

    /**
     * 使用上下键导航购物车
     * @param {string} direction - 'up' 或 'down'
     */
    navigateCart(direction) {
        if (this.cart.length === 0) return;

        const currentIndex = this.cart.findIndex(item => item.cartItemId === this.selectedProductId);

        if (direction === 'down') {
            // 向下：选择下一个产品
            if (currentIndex === -1) {
                // 没有选中，选择第一个
                this.selectedProductId = this.cart[0].cartItemId;
            } else if (currentIndex < this.cart.length - 1) {
                // 选择下一个
                this.selectedProductId = this.cart[currentIndex + 1].cartItemId;
            } else {
                // 已经是最后一个，循环到第一个
                this.selectedProductId = this.cart[0].cartItemId;
            }
        } else if (direction === 'up') {
            // 向上：选择上一个产品
            if (currentIndex === -1) {
                // 没有选中，选择最后一个
                this.selectedProductId = this.cart[this.cart.length - 1].cartItemId;
            } else if (currentIndex > 0) {
                // 选择上一个
                this.selectedProductId = this.cart[currentIndex - 1].cartItemId;
            } else {
                // 已经是第一个，循环到最后一个
                this.selectedProductId = this.cart[this.cart.length - 1].cartItemId;
            }
        }

        this.updateCart(); // 更新显示高亮
    }

    // ========================================
    // Supplier Management Methods
    // ========================================

    /**
     * Show supplier management modal and load suppliers
     */
    showSupplierModal() {
        const modal = document.getElementById('supplier-management-modal');
        if (modal) {
            modal.classList.remove('hidden');
            this.loadSuppliers();

            // Focus on supplier name input
            setTimeout(() => {
                const input = document.getElementById('new-supplier-name');
                if (input) input.focus();
            }, 100);
        }
    }

    /**
     * Close supplier management modal
     */
    closeSupplierModal() {
        const modal = document.getElementById('supplier-management-modal');
        if (modal) {
            modal.classList.add('hidden');
        }

        // Clear input
        const input = document.getElementById('new-supplier-name');
        if (input) input.value = '';

        // Focus back to Varios input
        setTimeout(() => this.focusVariosInput(), 100);
    }

    /**
     * Load suppliers list via AJAX
     */
    loadSuppliers() {
        const listContainer = document.getElementById('suppliers-list');
        if (!listContainer) return;

        // Show loading state
        const locale = document.documentElement.lang || 'en';
        const loadingText = locale.includes('zh') ? '加载中...' :
                           locale.includes('es') ? 'Cargando...' : 'Loading...';
        listContainer.innerHTML = `<div class="text-center py-8 text-gray-500">${loadingText}</div>`;

        // 🔥 使用 ajaxRequest 方法，支持自动 nonce 刷新
        this.ajaxRequest({ pos_action: 'get_suppliers' })
        .then(data => {
            if (data.success) {
                this.renderSuppliersList(data.data.suppliers || []);
            } else {
                const errorText = locale.includes('zh') ? '加载失败' :
                                 locale.includes('es') ? 'Error al cargar' : 'Failed to load';
                listContainer.innerHTML = `<div class="text-center py-8 text-red-500">${errorText}: ${data.data.message || ''}</div>`;
            }
        })
        .catch(error => {
            console.error('Error loading suppliers:', error);
            const errorText = locale.includes('zh') ? '加载失败' :
                             locale.includes('es') ? 'Error al cargar' : 'Failed to load';
            listContainer.innerHTML = `<div class="text-center py-8 text-red-500">${errorText}</div>`;
        });
    }

    /**
     * Load suppliers into datalist for product form
     */
    loadSupplierOptions() {
        // 🔥 使用 ajaxRequest 方法，支持自动 nonce 刷新
        this.ajaxRequest({ pos_action: 'get_suppliers' })
        .then(data => {
            if (data.success && data.data.suppliers) {
                const datalist = document.getElementById('supplier-datalist');
                if (datalist) {
                    datalist.innerHTML = '';
                    data.data.suppliers.forEach(supplier => {
                        const option = document.createElement('option');
                        option.value = supplier.name;
                        datalist.appendChild(option);
                    });
                }
            }
        })
        .catch(error => {
            console.error('[Supplier] 加载供应商选项失败:', error);
        });
    }

    /**
     * Add a new supplier via AJAX
     */
    addSupplier() {
        const input = document.getElementById('new-supplier-name');
        if (!input) return;

        const name = input.value.trim();
        if (!name) {
            const locale = document.documentElement.lang || 'en';
            const message = locale.includes('zh') ? '请输入供应商名称' :
                           locale.includes('es') ? 'Ingrese el nombre del proveedor' :
                           'Please enter supplier name';
            this.showToast(message, 'error');
            return;
        }

        // Disable button during request
        const addBtn = input.nextElementSibling;
        if (addBtn) addBtn.disabled = true;

        // 🔥 使用 ajaxRequest 方法，支持自动 nonce 刷新
        this.ajaxRequest({
            pos_action: 'add_supplier',
            supplier_name: name
        })
        .then(data => {
            if (addBtn) addBtn.disabled = false;

            if (data.success) {
                input.value = '';
                this.loadSuppliers();

                const locale = document.documentElement.lang || 'en';
                const message = locale.includes('zh') ? '供应商已添加' :
                               locale.includes('es') ? 'Proveedor agregado' :
                               'Supplier added';
                this.showToast(message, 'success');
            } else {
                this.showToast(data.data.message || 'Error adding supplier', 'error');
            }
        })
        .catch(error => {
            if (addBtn) addBtn.disabled = false;
            console.error('Error adding supplier:', error);
            const locale = document.documentElement.lang || 'en';
            const message = locale.includes('zh') ? '添加失败' :
                           locale.includes('es') ? 'Error al agregar' :
                           'Failed to add';
            this.showToast(message, 'error');
        });
    }

    /**
     * Delete a supplier via AJAX
     */
    deleteSupplier(id) {
        if (!id) return;

        const locale = document.documentElement.lang || 'en';
        const confirmText = locale.includes('zh') ? '确定要删除此供应商吗？' :
                           locale.includes('es') ? '¿Eliminar este proveedor?' :
                           'Delete this supplier?';

        if (!confirm(confirmText)) return;

        // 🔥 使用 ajaxRequest 方法，支持自动 nonce 刷新
        this.ajaxRequest({
            pos_action: 'delete_supplier',
            supplier_id: id
        })
        .then(data => {
            if (data.success) {
                this.loadSuppliers();

                const message = locale.includes('zh') ? '供应商已删除' :
                               locale.includes('es') ? 'Proveedor eliminado' :
                               'Supplier deleted';
                this.showToast(message, 'success');
            } else {
                this.showToast(data.data.message || 'Error deleting supplier', 'error');
            }
        })
        .catch(error => {
            console.error('Error deleting supplier:', error);
            const message = locale.includes('zh') ? '删除失败' :
                           locale.includes('es') ? 'Error al eliminar' :
                           'Failed to delete';
            this.showToast(message, 'error');
        });
    }

    /**
     * Render suppliers list HTML
     */
    renderSuppliersList(suppliers) {
        const listContainer = document.getElementById('suppliers-list');
        if (!listContainer) return;

        const locale = document.documentElement.lang || 'en';

        if (!suppliers || suppliers.length === 0) {
            const emptyText = locale.includes('zh') ? '暂无供应商' :
                             locale.includes('es') ? 'No hay proveedores' :
                             'No suppliers yet';
            listContainer.innerHTML = `<div class="text-center py-8 text-gray-500">${emptyText}</div>`;
            return;
        }

        const deleteText = locale.includes('zh') ? '删除' :
                          locale.includes('es') ? 'Eliminar' :
                          'Delete';

        listContainer.innerHTML = suppliers.map(supplier => `
            <div class="flex justify-between items-center p-3 bg-white border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors">
                <div class="flex-1">
                    <div class="font-medium text-gray-900">${this.escapeHtml(supplier.name)}</div>
                    <div class="text-sm text-gray-500">ID: ${supplier.id} | ${new Date(supplier.created_at).toLocaleDateString()}</div>
                </div>
                <button onclick="pos.deleteSupplier('${supplier.id}')"
                        class="ml-4 text-red-600 hover:text-red-800 px-3 py-1 text-sm font-medium transition-colors">
                    ${deleteText}
                </button>
            </div>
        `).join('');
    }

    /**
     * Escape HTML to prevent XSS
     */
    escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    // ========================================
    // 🔥 Varios输入框智能聚焦管理系统
    // ========================================

    /**
     * 智能聚焦到Varios输入框
     * @param {string} reason - 聚焦原因（用于调试）
     * @returns {boolean} - 是否成功聚焦
     */
    focusVariosInput(reason = '') {
        // 检查是否应该聚焦
        if (!this.shouldFocusVarios()) {
            return false;
        }

        const variosInput = document.getElementById('varios-price-input');
        if (variosInput && document.activeElement !== variosInput) {
            variosInput.focus();
            return true;
        }
        return false;
    }

    // 🔥 退货模式视觉指示器
    showReturnModeIndicator(show) {
        let indicator = document.getElementById('return-mode-indicator');
        if (show) {
            if (!indicator) {
                indicator = document.createElement('div');
                indicator.id = 'return-mode-indicator';
                indicator.style.cssText = 'position:fixed;bottom:20px;left:20px;background:#dc2626;color:#fff;padding:10px 20px;border-radius:8px;font-size:15px;font-weight:bold;z-index:9999;box-shadow:0 4px 12px rgba(220,38,38,0.4);cursor:pointer;animation:pulse 1.5s infinite;';
                indicator.onclick = () => {
                    this.returnQuantity = 0; // 重置退货模式
                    this.showReturnModeIndicator(false);
                    this.showToast(posTranslations['Return mode cancelled'] || '退货模式已取消', 'info');
                };
                // 添加脉冲动画
                if (!document.getElementById('return-mode-style')) {
                    const style = document.createElement('style');
                    style.id = 'return-mode-style';
                    style.textContent = '@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.7}}';
                    document.head.appendChild(style);
                }
                document.body.appendChild(indicator);
            }
            indicator.textContent = posTranslations['Return: Please scan product barcode'] || '退货：请扫描产品条形码';
            indicator.style.display = 'block';
        } else {
            if (indicator) {
                indicator.style.display = 'none';
            }
        }
    }

    /**
     * 判断是否应该聚焦到Varios输入框
     * @returns {boolean}
     */
    shouldFocusVarios() {
        // 🔥 检查0: 退货弹窗是否打开（最优先检查）
        if (window.isRefundModalOpen === true) {
            return false; // 退货弹窗打开，绝对不聚焦varios
        }

        // 🔥 检查1: 是否有任何弹窗打开（更通用的检测方法）
        // 检测所有弹窗：z-50, z-[60], 或ID以-modal结尾的元素
        const anyModalOpen = Array.from(document.querySelectorAll('.fixed.z-50, .fixed.z-\\[60\\], [id$="-modal"]')).some(modal => {
            return !modal.classList.contains('hidden');
        });

        if (anyModalOpen) {
            return false; // 有弹窗打开，不聚焦
        }

        // 🔥 检查2: 是否当前焦点在退货搜索框
        const activeElement = document.activeElement;
        if (activeElement && activeElement.id === 'refund-search-input') {
            return false; // 在退货搜索框，不聚焦varios
        }

        // 🔥 检查2.5: 是否当前焦点在任何弹窗内的输入框
        if (activeElement && activeElement.closest('[id$="-modal"]')) {
            return false; // 焦点在弹窗内，不聚焦varios
        }

        // 检查3: 当前焦点是否在其他需要保留的输入框
        if (activeElement && activeElement.tagName === 'INPUT' &&
            activeElement.id !== 'varios-price-input' &&
            activeElement.type !== 'number' && // 允许从数量输入框聚焦回来
            activeElement.classList.contains('cart-quantity-input')) {
            // 用户正在修改购物车数量，暂时不聚焦
            return false;
        }

        return true; // 可以聚焦
    }

    // ========================================
    // 账单模态框功能 (Bills Modal with Tabs)
    // ========================================

    /**
     * 打开账单弹窗
     */
    openBillsModal(tab = 'daily') {
        const modal = document.getElementById('bills-modal');
        if (modal) {
            modal.classList.remove('hidden');
            this.switchBillsTab(tab);
        }
    }

    /**
     * 关闭账单弹窗
     */
    closeBillsModal() {
        const modal = document.getElementById('bills-modal');
        if (modal) {
            modal.classList.add('hidden');
        }
    }

    /**
     * 切换账单标签页
     */
    switchBillsTab(tab) {
        // 更新标签按钮样式
        const tabs = document.querySelectorAll('.bills-tab-btn');
        tabs.forEach(t => {
            t.classList.remove('border-blue-500', 'text-blue-600');
            t.classList.add('border-transparent', 'text-gray-500');
        });

        const activeTab = document.getElementById(`bills-tab-${tab}`);
        if (activeTab) {
            activeTab.classList.remove('border-transparent', 'text-gray-500');
            activeTab.classList.add('border-blue-500', 'text-blue-600');
        }

        // 切换内容区域
        const contents = document.querySelectorAll('.bills-tab-content');
        contents.forEach(c => c.classList.add('hidden'));

        const activeContent = document.getElementById(`bills-content-${tab}`);
        if (activeContent) {
            activeContent.classList.remove('hidden');
        }

        // 加载对应数据
        if (tab === 'daily') {
            this.loadDailySettlement();
        } else if (tab === 'monthly') {
            this.loadMonthlySettlement();
        } else if (tab === 'products') {
            this.loadProductStats('today');
        }
    }

    // ========================================
    // 产品统计功能 (Product Statistics)
    // ========================================

    /**
     * 加载产品统计数据
     * @param {string} period - 'today' 或 'month'
     */
    async loadProductStats(period) {
        // 更新按钮样式
        const todayBtn = document.getElementById('product-stats-today-btn');
        const monthBtn = document.getElementById('product-stats-month-btn');
        const monthInput = document.getElementById('product-stats-month-input');

        if (period === 'today') {
            todayBtn.className = 'px-4 py-2 rounded-lg text-sm font-medium bg-blue-500 text-white';
            monthBtn.className = 'px-4 py-2 rounded-lg text-sm font-medium bg-gray-200 text-gray-700 hover:bg-gray-300';
            monthInput.classList.add('hidden');
        } else {
            todayBtn.className = 'px-4 py-2 rounded-lg text-sm font-medium bg-gray-200 text-gray-700 hover:bg-gray-300';
            monthBtn.className = 'px-4 py-2 rounded-lg text-sm font-medium bg-blue-500 text-white';
            monthInput.classList.remove('hidden');
            if (!monthInput.value) {
                const now = new Date();
                monthInput.value = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
            }
        }

        // 显示加载状态
        document.getElementById('product-stats-loading').classList.remove('hidden');
        document.getElementById('product-stats-content').style.opacity = '0.5';

        // 保存当前周期
        this._productStatsPeriod = period;
        // 重置排序
        this._productStatsSort = { field: 'total', direction: 'desc' };

        // 统一使用WC订单查询接口
        const params = {
            action: 'ruiyi_retail_get_product_statistics',
            nonce: ruiyi_pos_ajax.nonce,
            period: period
        };
        if (period === 'month') {
            const monthInput = document.getElementById('product-stats-month-input');
            params.month = monthInput.value;
        }

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams(params)
            });
            const data = await response.json();
            this._productStatsLoaded(data);
        } catch (error) {
            console.error('Failed to load product stats:', error);
            this._productStatsLoaded(null);
        }
    }

    /**
     * 数据加载完成后的统一处理
     */
    _productStatsLoaded(response) {
        document.getElementById('product-stats-loading').classList.add('hidden');
        document.getElementById('product-stats-content').style.opacity = '1';

        let products = [];
        let dateLabel = '';
        let totalOrders = 0;

        if (response && response.success && response.data) {
            const data = response.data;
            products = data.products || [];
            dateLabel = data.date_label || '';
            totalOrders = data.total_orders || 0;
        }

        // 存储完整数据供排序/搜索使用
        this._productStatsData = products;

        // 更新日期标签
        document.getElementById('product-stats-date-label').textContent = dateLabel;

        // 更新汇总卡片
        const totalTypes = products.length;
        let totalQty = 0, totalAmount = 0;
        products.forEach(p => {
            totalQty += Number(p.quantity) || 0;
            totalAmount += Number(p.total) || 0;
        });
        document.getElementById('product-stats-orders').textContent = totalOrders;
        document.getElementById('product-stats-quantity').textContent = totalQty;
        document.getElementById('product-stats-amount').textContent = totalAmount.toFixed(2) + '€';

        // 清除搜索框
        const searchInput = document.getElementById('product-stats-search');
        if (searchInput) searchInput.value = '';

        // 渲染表格
        this.renderProductStatsTable(products);
    }

    /**
     * 渲染产品统计表格
     */
    renderProductStatsTable(products) {
        const tbody = document.getElementById('product-stats-table-body');
        if (!tbody) return;

        if (!products || products.length === 0) {
            tbody.innerHTML = '<tr><td colspan="5" class="px-3 py-8 text-center text-gray-400">' +
                (document.documentElement.lang === 'zh-CN' ? '暂无数据' : 'Sin datos') + '</td></tr>';
            return;
        }

        // 排序
        const sort = this._productStatsSort || { field: 'total', direction: 'desc' };
        const sorted = [...products].sort((a, b) => {
            let va = a[sort.field], vb = b[sort.field];
            if (sort.field === 'name') {
                va = (va || '').toLowerCase();
                vb = (vb || '').toLowerCase();
                return sort.direction === 'asc' ? va.localeCompare(vb) : vb.localeCompare(va);
            }
            va = Number(va) || 0;
            vb = Number(vb) || 0;
            return sort.direction === 'asc' ? va - vb : vb - va;
        });

        // 更新排序图标
        ['name', 'quantity', 'total'].forEach(f => {
            const icon = document.getElementById('sort-icon-' + f);
            if (icon) {
                if (f === sort.field) {
                    icon.textContent = sort.direction === 'asc' ? '▲' : '▼';
                } else {
                    icon.textContent = '';
                }
            }
        });

        let html = '';
        sorted.forEach((p, i) => {
            const qty = Number(p.quantity) || 0;
            const total = Number(p.total) || 0;
            html += `<tr class="hover:bg-gray-50">
                <td class="px-3 py-2 text-gray-500">${i + 1}</td>
                <td class="px-3 py-2 font-medium text-gray-900">${this.escapeHtml(p.name || '')}</td>
                <td class="px-3 py-2 text-gray-500 text-xs">${this.escapeHtml(p.sku || '')}</td>
                <td class="px-3 py-2 text-right text-gray-700">${qty}</td>
                <td class="px-3 py-2 text-right font-medium text-gray-900">${total.toFixed(2)}€</td>
            </tr>`;
        });
        tbody.innerHTML = html;
    }

    /**
     * 按表头排序产品统计
     */
    sortProductStats(field) {
        const sort = this._productStatsSort || { field: 'total', direction: 'desc' };
        if (sort.field === field) {
            sort.direction = sort.direction === 'asc' ? 'desc' : 'asc';
        } else {
            sort.field = field;
            sort.direction = field === 'name' ? 'asc' : 'desc';
        }
        this._productStatsSort = sort;

        // 获取当前过滤后的数据
        const searchInput = document.getElementById('product-stats-search');
        const keyword = searchInput ? searchInput.value.trim().toLowerCase() : '';
        let data = this._productStatsData || [];
        if (keyword) {
            data = data.filter(p => (p.name || '').toLowerCase().includes(keyword) || (p.sku || '').toLowerCase().includes(keyword));
        }
        this.renderProductStatsTable(data);
    }

    /**
     * 搜索过滤产品统计
     */
    filterProductStats() {
        const searchInput = document.getElementById('product-stats-search');
        const keyword = searchInput ? searchInput.value.trim().toLowerCase() : '';
        let data = this._productStatsData || [];
        if (keyword) {
            data = data.filter(p => (p.name || '').toLowerCase().includes(keyword) || (p.sku || '').toLowerCase().includes(keyword));
        }
        this.renderProductStatsTable(data);
    }

    /**
     * 打印产品统计报表
     */
    printProductStats() {
        const products = this._productStatsData || [];
        if (products.length === 0) {
            this.showToast('没有数据可打印', 'warning');
            return;
        }

        const dateLabel = document.getElementById('product-stats-date-label').textContent;
        const periodLabel = this._productStatsPeriod === 'today' ? '今日产品统计' : '月度产品统计';

        let totalQty = 0, totalAmount = 0;
        products.forEach(p => {
            totalQty += Number(p.quantity) || 0;
            totalAmount += Number(p.total) || 0;
        });

        // 按金额降序排列打印
        const sorted = [...products].sort((a, b) => (Number(b.total) || 0) - (Number(a.total) || 0));

        // 尝试使用CLODOP打印
        if (typeof CLODOP !== 'undefined' || typeof getCLodop !== 'undefined') {
            try {
                const LODOP = typeof getCLodop === 'function' ? getCLodop() : CLODOP;
                if (LODOP) {
                    LODOP.PRINT_INIT(periodLabel);
                    LODOP.SET_PRINT_PAGESIZE(3, '80mm', '20mm', '');
                    LODOP.SET_PRINT_STYLE('FontSize', 10);

                    let top = 5;
                    const left = 5;
                    const width = 280;

                    // 标题
                    LODOP.ADD_PRINT_TEXT(top + 'mm', left + 'mm', width + 'px', '8mm',
                        this.storeName || '锐意零售收银系统');
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 2);
                    LODOP.SET_PRINT_STYLEA(0, 'FontSize', 14);
                    LODOP.SET_PRINT_STYLEA(0, 'Bold', 1);
                    top += 10;

                    // 副标题
                    LODOP.ADD_PRINT_TEXT(top + 'mm', left + 'mm', width + 'px', '6mm', periodLabel);
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 2);
                    LODOP.SET_PRINT_STYLEA(0, 'FontSize', 11);
                    top += 7;

                    // 日期
                    LODOP.ADD_PRINT_TEXT(top + 'mm', left + 'mm', width + 'px', '5mm', dateLabel);
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 2);
                    LODOP.SET_PRINT_STYLEA(0, 'FontSize', 9);
                    top += 6;

                    // 分隔线
                    LODOP.ADD_PRINT_TEXT(top + 'mm', left + 'mm', width + 'px', '4mm', '--------------------------------');
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 2);
                    top += 5;

                    // 表头
                    LODOP.ADD_PRINT_TEXT(top + 'mm', left + 'mm', '150px', '5mm', '产品名称');
                    LODOP.SET_PRINT_STYLEA(0, 'Bold', 1);
                    LODOP.ADD_PRINT_TEXT(top + 'mm', (left + 38) + 'mm', '40px', '5mm', '数量');
                    LODOP.SET_PRINT_STYLEA(0, 'Bold', 1);
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 3);
                    LODOP.ADD_PRINT_TEXT(top + 'mm', (left + 52) + 'mm', '60px', '5mm', '金额');
                    LODOP.SET_PRINT_STYLEA(0, 'Bold', 1);
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 3);
                    top += 5;

                    LODOP.ADD_PRINT_TEXT(top + 'mm', left + 'mm', width + 'px', '4mm', '--------------------------------');
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 2);
                    top += 4;

                    // 产品行
                    sorted.forEach(p => {
                        const qty = Number(p.quantity) || 0;
                        const total = Number(p.total) || 0;
                        const name = (p.name || '').substring(0, 18);

                        LODOP.ADD_PRINT_TEXT(top + 'mm', left + 'mm', '150px', '5mm', name);
                        LODOP.SET_PRINT_STYLEA(0, 'FontSize', 9);
                        LODOP.ADD_PRINT_TEXT(top + 'mm', (left + 38) + 'mm', '40px', '5mm', String(qty));
                        LODOP.SET_PRINT_STYLEA(0, 'FontSize', 9);
                        LODOP.SET_PRINT_STYLEA(0, 'Alignment', 3);
                        LODOP.ADD_PRINT_TEXT(top + 'mm', (left + 52) + 'mm', '60px', '5mm', total.toFixed(2) + '€');
                        LODOP.SET_PRINT_STYLEA(0, 'FontSize', 9);
                        LODOP.SET_PRINT_STYLEA(0, 'Alignment', 3);
                        top += 5;
                    });

                    // 汇总
                    LODOP.ADD_PRINT_TEXT(top + 'mm', left + 'mm', width + 'px', '4mm', '================================');
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 2);
                    top += 5;
                    LODOP.ADD_PRINT_TEXT(top + 'mm', left + 'mm', '150px', '5mm',
                        '合计: ' + products.length + '种');
                    LODOP.SET_PRINT_STYLEA(0, 'Bold', 1);
                    LODOP.ADD_PRINT_TEXT(top + 'mm', (left + 38) + 'mm', '40px', '5mm', String(totalQty));
                    LODOP.SET_PRINT_STYLEA(0, 'Bold', 1);
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 3);
                    LODOP.ADD_PRINT_TEXT(top + 'mm', (left + 52) + 'mm', '60px', '5mm', totalAmount.toFixed(2) + '€');
                    LODOP.SET_PRINT_STYLEA(0, 'Bold', 1);
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 3);
                    top += 8;

                    // 打印时间
                    LODOP.ADD_PRINT_TEXT(top + 'mm', left + 'mm', width + 'px', '5mm',
                        '打印时间: ' + new Date().toLocaleString('zh-CN'));
                    LODOP.SET_PRINT_STYLEA(0, 'FontSize', 8);
                    LODOP.SET_PRINT_STYLEA(0, 'Alignment', 2);

                    LODOP.PREVIEW();
                    return;
                }
            } catch (e) {
                console.warn('CLODOP print failed, falling back to browser print:', e);
            }
        }

        // 浏览器打印兜底
        let printHtml = `<html><head><title>${periodLabel}</title>
            <style>body{font-family:sans-serif;padding:20px;font-size:14px;}
            table{width:100%;border-collapse:collapse;margin-top:10px;}
            th,td{border:1px solid #ddd;padding:6px 8px;text-align:left;}
            th{background:#f5f5f5;font-size:12px;}
            .text-right{text-align:right;}
            .total-row{font-weight:bold;background:#f9f9f9;}
            h2{margin:0 0 5px;font-size:18px;}
            .subtitle{color:#666;margin-bottom:15px;}</style></head><body>
            <h2>${this.storeName || '锐意零售收银系统'}</h2>
            <div class="subtitle">${periodLabel} - ${dateLabel}</div>
            <table><thead><tr><th>#</th><th>产品名称</th><th class="text-right">数量</th><th class="text-right">金额</th><th class="text-right">均价</th></tr></thead><tbody>`;

        sorted.forEach((p, i) => {
            const qty = Number(p.quantity) || 0;
            const total = Number(p.total) || 0;
            const avg = qty > 0 ? (total / qty) : 0;
            printHtml += `<tr><td>${i + 1}</td><td>${this.escapeHtml(p.name || '')}</td>
                <td class="text-right">${qty}</td><td class="text-right">${total.toFixed(2)}€</td>
                <td class="text-right">${avg.toFixed(2)}€</td></tr>`;
        });

        printHtml += `<tr class="total-row"><td></td><td>合计 (${products.length}种)</td>
            <td class="text-right">${totalQty}</td><td class="text-right">${totalAmount.toFixed(2)}€</td>
            <td class="text-right"></td></tr></tbody></table>
            <p style="margin-top:15px;font-size:12px;color:#999;">打印时间: ${new Date().toLocaleString('zh-CN')}</p>
            </body></html>`;

        const printWindow = window.open('', '_blank');
        printWindow.document.write(printHtml);
        printWindow.document.close();
        printWindow.focus();
        printWindow.print();
    }

    // ========================================
    // 设置模态框功能 (Settings Modal with Tabs)
    // ========================================

    /**
     * 打开设置弹窗
     */
