    /**
     * 🔥 更新日结单自动保存时间
     */
    async updateAutoDailySettlementTime(timeValue) {
        // 验证时间格式
        if (!/^\d{2}:\d{2}$/.test(timeValue)) {
            console.error('[Auto Settlement] Invalid time format:', timeValue);
            return;
        }

        console.log(`[Auto Settlement] Updating auto save time to: ${timeValue}`);

        // 更新本地状态
        this.autoDailySettlementTime = timeValue;

        // 保存到服务器 (通过saveAllBackendSettings)
        try {
            const formData = new FormData();
            formData.append('action', 'ruiyi_pos_ajax');
            formData.append('pos_action', 'save_auto_settlement_time');
            formData.append('time', timeValue);
            formData.append('nonce', ruiyi_pos_ajax.nonce);

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                body: formData
            });

            const data = await response.json();
            if (data.success) {
                console.log(`[Auto Settlement] Time updated successfully to ${timeValue}`);
                const locale = document.documentElement.lang || 'en';
                this.showToast(
                    locale.includes('zh') ? `自动保存时间已设置为 ${timeValue}` :
                    locale.includes('es') ? `Hora de guardado automático: ${timeValue}` :
                    `Auto save time set to ${timeValue}`,
                    'success'
                );
            } else {
                console.error('[Auto Settlement] Failed to save time:', data);
            }
        } catch (error) {
            console.error('[Auto Settlement] Error saving time:', error);
        }
    }

    /**
     * 🔥 手动触发自动保存（用于测试）
     */
    async manualTriggerAutoSettlement() {
        const locale = document.documentElement.lang || 'en';

        console.log('[Auto Settlement] Manual trigger requested');

        // 确认执行
        const confirmMsg = locale.includes('zh') ? '确定要立即执行日结单自动保存吗？这将保存当前的日结单到月结单并清空日结单。' :
                          locale.includes('es') ? '¿Ejecutar el guardado automático ahora?' :
                          'Run auto settlement now? This will save current daily settlement to monthly.';

        if (!confirm(confirmMsg)) {
            return;
        }

        try {
            this.showToast(
                locale.includes('zh') ? '正在执行...' :
                locale.includes('es') ? 'Ejecutando...' :
                'Executing...',
                'info'
            );

            const formData = new FormData();
            formData.append('action', 'ruiyi_pos_ajax');
            formData.append('pos_action', 'manual_trigger_auto_settlement');
            formData.append('nonce', ruiyi_pos_ajax.nonce);

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                body: formData
            });

            const data = await response.json();
            console.log('[Auto Settlement] Manual trigger response:', data);

            if (data.success) {
                if (data.data?.skipped) {
                    this.showToast(
                        locale.includes('zh') ? `跳过: ${data.data.message}` :
                        locale.includes('es') ? `Omitido: ${data.data.message}` :
                        `Skipped: ${data.data.message}`,
                        'warning'
                    );
                } else {
                    this.showToast(
                        locale.includes('zh') ? `日结单已保存! 金额: €${data.data.total_amount?.toFixed(2) || '0.00'}` :
                        locale.includes('es') ? `¡Guardado! Total: €${data.data.total_amount?.toFixed(2) || '0.00'}` :
                        `Saved! Total: €${data.data.total_amount?.toFixed(2) || '0.00'}`,
                        'success'
                    );

                    // 刷新页面以显示最新状态
                    setTimeout(() => {
                        window.location.reload();
                    }, 1500);
                }
            } else {
                this.showToast(
                    locale.includes('zh') ? `失败: ${data.data?.message}` :
                    locale.includes('es') ? `Error: ${data.data?.message}` :
                    `Failed: ${data.data?.message}`,
                    'error'
                );
            }
        } catch (error) {
            console.error('[Auto Settlement] Manual trigger error:', error);
            this.showToast(
                locale.includes('zh') ? '执行失败' :
                locale.includes('es') ? 'Error al ejecutar' :
                'Execution failed',
                'error'
            );
        }
    }

