    /**
     * 初始化自定义快捷键显示
     * Initialize custom shortcut key displays from localStorage
     */
    initCustomShortcuts() {
        const locale = document.documentElement.lang || 'en';
        const notSetText = locale.includes('zh') ? '未设置' : (locale.includes('es') ? 'No config.' : 'Not set');

        // 打印结账小票快捷键：默认 PrintScreen（Impr Pant），用户可自定义
        const printKey = 'ruiyi_pos_shortcut_print_receipt';
        if (!localStorage.getItem(printKey)) {
            localStorage.setItem(printKey, 'PrintScreen');
        }
        const printDisplay = document.getElementById('shortcut-print-receipt-display');
        if (printDisplay) {
            printDisplay.textContent = localStorage.getItem(printKey) || notSetText;
        }

        // 刷卡支付快捷键：恢复显示
        const cardKey = 'ruiyi_pos_shortcut_payment_card';
        const cardDisplay = document.getElementById('shortcut-payment-card-display');
        if (cardDisplay) {
            cardDisplay.textContent = localStorage.getItem(cardKey) || notSetText;
        }
    }

    /**
     * 🔥 匹配刷卡支付快捷键（自定义优先，默认 . 键）
     */
    _matchPaymentCardShortcut(e) {
        const customKey = localStorage.getItem('ruiyi_pos_shortcut_payment_card');
        if (customKey) {
            return this._matchKeyCombo(e, customKey);
        }
        // 默认 . 键
        return e.key === '.';
    }

    /**
     * 捕获自定义快捷键
     * Capture a custom shortcut key for the given action
     */
    /**
     * 构建按键组合描述符（格式："Ctrl+Shift+F5"、"PrintScreen"、"Alt+P" 等）
     * 用于存储和匹配快捷键，支持单键和任意修饰键组合
     */
    _buildKeyCombo(e) {
        const parts = [];
        if (e.ctrlKey) parts.push('Ctrl');
        if (e.altKey) parts.push('Alt');
        if (e.shiftKey) parts.push('Shift');
        if (e.metaKey) parts.push('Meta');
        // 规范化键名：空格用 Space，单字母大写，其他原样
        let keyName = e.key;
        if (keyName === ' ') keyName = 'Space';
        else if (keyName.length === 1) keyName = keyName.toUpperCase();
        parts.push(keyName);
        return parts.join('+');
    }

    /**
     * 检查当前按键事件是否匹配某个组合键描述符
     */
    _matchKeyCombo(e, combo) {
        if (!combo) return false;
        return this._buildKeyCombo(e) === combo;
    }

    captureShortcut(id) {
        const locale = document.documentElement.lang || 'en';
        const displayId = `shortcut-${id.replace('_', '-')}-display`;
        const display = document.getElementById(displayId);
        if (!display) return;

        const storageKeyMap = {
            'print_receipt': 'ruiyi_pos_shortcut_print_receipt',
            'open_drawer': 'ruiyi_pos_shortcut_open_drawer',
            'payment_card': 'ruiyi_pos_shortcut_payment_card'
        };
        const storageKey = storageKeyMap[id];
        if (!storageKey) return;

        // Show capturing prompt
        display.textContent = locale.includes('zh') ? '按下快捷键...' : (locale.includes('es') ? 'Presione tecla...' : 'Press a key...');
        display.classList.add('animate-pulse', 'text-blue-600');

        const handler = (e) => {
            e.preventDefault();
            e.stopPropagation();
            e.stopImmediatePropagation();

            // 忽略单独按下的修饰键（等待用户按下实际的目标键）
            if (['Shift', 'Control', 'Alt', 'Meta'].includes(e.key)) return;

            document.removeEventListener('keyup', handler, true);
            document.removeEventListener('keydown', handler, true);
            display.classList.remove('animate-pulse', 'text-blue-600');

            // 构建完整的组合键描述符（如 "Ctrl+Shift+F5"、"PrintScreen"、"F1"）
            const keyCombo = this._buildKeyCombo(e);
            localStorage.setItem(storageKey, keyCombo);
            display.textContent = keyCombo;

            this.showToast(
                locale.includes('zh') ? `快捷键已设置为 "${keyCombo}"` :
                locale.includes('es') ? `Atajo configurado: "${keyCombo}"` :
                `Shortcut set to "${keyCombo}"`,
                'success'
            );
        };

        // 同时监听 keydown 和 keyup：PrintScreen 等特殊键在 Windows 11 只触发 keyup
        document.addEventListener('keydown', handler, true);
        document.addEventListener('keyup', handler, true);
    }

    /**
     * 清除自定义快捷键
     * Clear a custom shortcut key for the given action
     */
    clearShortcut(id) {
        const locale = document.documentElement.lang || 'en';
        const displayId = `shortcut-${id.replace('_', '-')}-display`;
        const display = document.getElementById(displayId);
        if (!display) return;

        const storageKeyMap = {
            'print_receipt': 'ruiyi_pos_shortcut_print_receipt',
            'open_drawer': 'ruiyi_pos_shortcut_open_drawer',
            'payment_card': 'ruiyi_pos_shortcut_payment_card'
        };
        const storageKey = storageKeyMap[id];
        if (!storageKey) return;

        localStorage.removeItem(storageKey);
        const notSetText = locale.includes('zh') ? '未设置' : (locale.includes('es') ? 'No config.' : 'Not set');
        display.textContent = notSetText;

        this.showToast(
            locale.includes('zh') ? '快捷键已清除' :
            locale.includes('es') ? 'Atajo eliminado' :
            'Shortcut cleared',
            'info'
        );
    }

    /**
     * 🔥 统一保存所有后台设置
     */
    async saveAllBackendSettings() {
        const saveBtn = document.getElementById('backend-settings-save-btn');
        const locale = document.documentElement.lang || 'en';

        // 获取所有设置值
        const productNumberKey = document.getElementById('product-number-key-input')?.value.trim().toLowerCase() || 'm';
        const wholesaleAlbaranToggle = document.getElementById('wholesale-albaran-toggle');
        const transferPaymentToggle = document.getElementById('transfer-payment-toggle');
        const wholesaleInvoiceToggle = document.getElementById('wholesale-invoice-toggle');
        const lastOrderDisplayToggle = document.getElementById('last-order-display-toggle');
        const autoDailySettlementToggle = document.getElementById('auto-daily-settlement-toggle');

        const wholesaleEnabled = wholesaleAlbaranToggle?.getAttribute('data-enabled') === 'true';
        const transferEnabled = transferPaymentToggle?.getAttribute('data-enabled') === 'true';
        const wholesaleInvoiceEnabled = wholesaleInvoiceToggle?.getAttribute('data-enabled') === 'true';
        const lastOrderDisplayEnabled = lastOrderDisplayToggle?.getAttribute('data-enabled') === 'true';
        const autoDailySettlementEnabled = autoDailySettlementToggle?.getAttribute('data-enabled') === 'true';
        const autoDailySettlementTime = document.getElementById('auto-daily-settlement-time')?.value || '00:00';

        // 显示保存中状态
        if (saveBtn) {
            saveBtn.disabled = true;
            saveBtn.innerHTML = `
                <svg class="animate-spin w-5 h-5 mr-2" fill="none" viewBox="0 0 24 24">
                    <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                    <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                ${locale.includes('zh') ? '保存中...' : locale.includes('es') ? 'Guardando...' : 'Saving...'}
            `;
        }

        try {
            const formData = new FormData();
            formData.append('action', 'ruiyi_pos_ajax');
            formData.append('pos_action', 'save_all_backend_settings');
            formData.append('product_number_key', productNumberKey);
            formData.append('wholesale_albaran_enabled', wholesaleEnabled ? '1' : '0');
            formData.append('transfer_payment_enabled', transferEnabled ? '1' : '0');
            formData.append('wholesale_invoice_enabled', wholesaleInvoiceEnabled ? '1' : '0');
            formData.append('last_order_display_enabled', lastOrderDisplayEnabled ? '1' : '0');
            formData.append('auto_daily_settlement_enabled', autoDailySettlementEnabled ? '1' : '0');
            formData.append('auto_daily_settlement_time', autoDailySettlementTime);
            formData.append('nonce', ruiyi_pos_ajax.nonce);

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                body: formData
            });

            const data = await response.json();

            if (data.success) {
                // 更新全局变量
                window.productNumberKey = productNumberKey;

                this.showToast(
                    locale.includes('zh') ? '设置保存成功，正在刷新页面...' :
                    locale.includes('es') ? 'Configuración guardada, actualizando...' :
                    'Settings saved, refreshing...',
                    'success'
                );

                // 显示成功状态
                if (saveBtn) {
                    saveBtn.innerHTML = `
                        <svg class="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/>
                        </svg>
                        ${locale.includes('zh') ? '已保存' : locale.includes('es') ? 'Guardado' : 'Saved'}
                    `;
                    saveBtn.classList.remove('bg-green-600', 'hover:bg-green-700');
                    saveBtn.classList.add('bg-green-500');
                }

                // 🔥 强制刷新页面使设置生效（清空所有缓存）
                setTimeout(async () => {
                    try {
                        // 清除 Service Worker 缓存
                        if ('caches' in window) {
                            const cacheNames = await caches.keys();
                            await Promise.all(cacheNames.map(name => caches.delete(name)));
                            console.log('[Settings] Cleared all caches');
                        }

                        // 如果有 Service Worker，让它更新
                        if ('serviceWorker' in navigator) {
                            const registrations = await navigator.serviceWorker.getRegistrations();
                            for (const registration of registrations) {
                                await registration.update();
                            }
                            console.log('[Settings] Updated service workers');
                        }
                    } catch (e) {
                        console.log('[Settings] Cache clearing error (non-critical):', e);
                    }

                    // 添加时间戳参数强制绕过浏览器缓存
                    const url = new URL(window.location.href);
                    url.searchParams.set('_nocache', Date.now());
                    window.location.replace(url.toString()); // 使用 replace 避免历史记录
                }, 800);
            } else {
                throw new Error(data.data?.message || 'Failed to save');
            }
        } catch (error) {
            console.error('Error saving backend settings:', error);
            this.showToast(
                locale.includes('zh') ? '保存失败' :
                locale.includes('es') ? 'Error al guardar' :
                'Failed to save settings',
                'error'
            );

            // 恢复按钮状态
            if (saveBtn) {
                saveBtn.innerHTML = `
                    <svg class="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/>
                    </svg>
                    ${locale.includes('zh') ? '保存设置' : locale.includes('es') ? 'Guardar Configuración' : 'Save Settings'}
                `;
                saveBtn.disabled = false;
            }
        }
    }

    /**
     * 切换设置下拉菜单
     */
    toggleSettingsDropdown(group) {
        const dropdown = document.getElementById(`settings-dropdown-${group}`);
        const allDropdowns = document.querySelectorAll('[id^="settings-dropdown-"]');
        allDropdowns.forEach(d => {
            if (d !== dropdown) d.classList.add('hidden');
        });
        dropdown.classList.toggle('hidden');
    }

    /**
     * 关闭所有设置下拉菜单
     */
    closeAllSettingsDropdowns() {
        document.querySelectorAll('[id^="settings-dropdown-"]').forEach(d => d.classList.add('hidden'));
    }

    /**
     * 切换设置标签页
     */
    switchSettingsTab(tab) {
        // 关闭所有下拉菜单
        this.closeAllSettingsDropdowns();

        // 定义分组映射（仅系统dropdown）
        const groupMap = {
            'tax-settings': 'system', 'system': 'system', 'backend': 'system'
        };

        // 更新标签按钮样式
        const tabs = document.querySelectorAll('.settings-tab-btn:not(.settings-dropdown-item)');
        tabs.forEach(t => {
            t.classList.remove('border-blue-500', 'text-blue-600');
            t.classList.add('border-transparent', 'text-gray-500');
        });
        // 高亮下拉项
        document.querySelectorAll('.settings-dropdown-item').forEach(t => {
            t.classList.remove('bg-blue-50', 'text-blue-600', 'font-semibold');
        });

        // 高亮当前选中的tab（如果是下拉项，高亮对应的组按钮）
        const group = groupMap[tab];
        if (group) {
            const groupBtn = document.getElementById(`settings-tab-group-${group}`);
            if (groupBtn) {
                groupBtn.classList.remove('border-transparent', 'text-gray-500');
                groupBtn.classList.add('border-blue-500', 'text-blue-600');
            }
            // 高亮下拉项
            const activeDropdownItem = document.getElementById(`settings-tab-${tab}`);
            if (activeDropdownItem) {
                activeDropdownItem.classList.add('bg-blue-50', 'text-blue-600', 'font-semibold');
            }
        } else {
            const activeTab = document.getElementById(`settings-tab-${tab}`);
            if (activeTab) {
                activeTab.classList.remove('border-transparent', 'text-gray-500');
                activeTab.classList.add('border-blue-500', 'text-blue-600');
            }
        }

        // 切换内容区域
        const contents = document.querySelectorAll('.settings-tab-content');
        contents.forEach(c => c.classList.add('hidden'));

        const activeContent = document.getElementById(`settings-content-${tab}`);
        if (activeContent) {
            activeContent.classList.remove('hidden');
        }

        // 加载对应数据
        if (tab === 'contacts') {
            this.loadSuppliers();
            this.loadCustomersManagement();
        } else if (tab === 'edit-product') {
            this.loadEditProductsList();
            this.loadEditProductSuppliers();
        } else if (tab === 'company') {
            // 数据已由 PHP 预渲染，无需 AJAX 加载
        } else if (tab === 'toolbox') {
            this.loadToolboxSettings();
        } else if (tab === 'product') {
            this.toggleSkuGeneratorVisibility();
        } else if (tab === 'tax-settings') {
            this.loadTaxSettings();
        } else if (tab === 'system') {
            this.loadSystemSettings();
        } else if (tab === 'import-data') {
            // Initialize drag-and-drop on the dropzone (once)
            if (!this._importDropzoneInit) {
                this._importDropzoneInit = true;
                const dropzone = document.getElementById('import-data-dropzone');
                if (dropzone) {
                    dropzone.addEventListener('dragover', (e) => {
                        e.preventDefault();
                        dropzone.classList.add('border-blue-400', 'bg-blue-50');
                    });
                    dropzone.addEventListener('dragleave', (e) => {
                        e.preventDefault();
                        dropzone.classList.remove('border-blue-400', 'bg-blue-50');
                    });
                    dropzone.addEventListener('drop', (e) => {
                        e.preventDefault();
                        dropzone.classList.remove('border-blue-400', 'bg-blue-50');
                        const files = e.dataTransfer.files;
                        if (files.length > 0) {
                            const input = document.getElementById('import-data-file-input');
                            input.files = files;
                            this.handleImportFileSelect(input);
                        }
                    });
                }
            }
        } else if (tab === 'excel-import') {
            // Initialize drag-and-drop on the Excel import dropzone (once)
            if (!this._excelImportDropzoneInit) {
                this._excelImportDropzoneInit = true;
                const dropzone = document.getElementById('excel-import-dropzone');
                if (dropzone) {
                    dropzone.addEventListener('dragover', (e) => {
                        e.preventDefault();
                        dropzone.classList.add('border-blue-400', 'bg-blue-50');
                    });
                    dropzone.addEventListener('dragleave', (e) => {
                        e.preventDefault();
                        dropzone.classList.remove('border-blue-400', 'bg-blue-50');
                    });
                    dropzone.addEventListener('drop', (e) => {
                        e.preventDefault();
                        dropzone.classList.remove('border-blue-400', 'bg-blue-50');
                        const files = e.dataTransfer.files;
                        if (files.length > 0) {
                            const input = document.getElementById('excel-import-file-input');
                            input.files = files;
                            this.handleExcelImportFileSelect(input);
                        }
                    });
                }
            }
        } else if (tab === 'barcode-print') {
            this.initBarcodePrintTab();
        }
    }

    /**
     * 切换联系人子标签页 (供应商/客户)
     */
    switchContactsSubTab(subTab) {
        // 更新子标签按钮样式
        const subTabs = document.querySelectorAll('.contacts-subtab-btn');
        subTabs.forEach(t => {
            t.classList.remove('bg-white', 'text-blue-600', 'shadow-sm');
            t.classList.add('text-gray-600');
        });

        const activeSubTab = document.getElementById(`contacts-subtab-${subTab}`);
        if (activeSubTab) {
            activeSubTab.classList.remove('text-gray-600');
            activeSubTab.classList.add('bg-white', 'text-blue-600', 'shadow-sm');
        }

        // 切换子内容区域
        const subContents = document.querySelectorAll('.contacts-subcontent');
        subContents.forEach(c => c.classList.add('hidden'));

        const activeSubContent = document.getElementById(`contacts-content-${subTab}`);
        if (activeSubContent) {
            activeSubContent.classList.remove('hidden');
        }
    }

    // ========================================
    // 🔥 税费设置功能 (TAX SETTINGS)
    // ========================================

    loadTaxSettings() {
        const locale = document.documentElement.lang || 'en';
        const loading = document.getElementById('tax-settings-categories-loading');
        const list = document.getElementById('tax-settings-categories-list');
        const tbody = document.getElementById('tax-categories-tbody');

        if (loading) loading.classList.remove('hidden');
        if (list) list.classList.add('hidden');

        this.ajaxRequest({ pos_action: 'get_tax_settings' })
        .then(data => {
            if (data.success && data.data.categories) {
                const categories = data.data.categories;
                let html = '';
                categories.forEach(cat => {
                    const currentRate = cat.tax_rate !== '' && cat.tax_rate !== null ? cat.tax_rate : '';
                    const noRateLabel = locale.includes('zh') ? '未设置(默认21%)' : locale.includes('es') ? 'Sin definir (21%)' : 'Not set (21%)';
                    html += `<tr class="border-b border-gray-100 hover:bg-gray-50" data-category-id="${cat.id}">
                        <td class="px-3 py-2.5">
                            <span class="font-medium text-gray-800">${this.escapeHtml(cat.name)}</span>
                        </td>
                        <td class="px-3 py-2.5">
                            <input type="number" class="tax-cat-rate-input w-20 px-2 py-1 text-sm border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                                   data-category-id="${cat.id}" value="${currentRate}" min="0" max="100" step="0.01" placeholder="21">
                        </td>
                        <td class="px-3 py-2.5">
                            <div class="flex gap-1">
                                <button onclick="pos.setCategoryTaxRate(${cat.id}, 4)" class="px-2 py-0.5 text-xs rounded border border-gray-300 hover:bg-yellow-50 hover:border-yellow-400 transition-all ${currentRate == '4' ? 'bg-yellow-100 border-yellow-400 font-bold' : ''}">4%</button>
                                <button onclick="pos.setCategoryTaxRate(${cat.id}, 10)" class="px-2 py-0.5 text-xs rounded border border-gray-300 hover:bg-orange-50 hover:border-orange-400 transition-all ${currentRate == '10' ? 'bg-orange-100 border-orange-400 font-bold' : ''}">10%</button>
                                <button onclick="pos.setCategoryTaxRate(${cat.id}, 21)" class="px-2 py-0.5 text-xs rounded border border-gray-300 hover:bg-red-50 hover:border-red-400 transition-all ${currentRate == '21' ? 'bg-red-100 border-red-400 font-bold' : ''}">21%</button>
                            </div>
                        </td>
                    </tr>`;
                });
                if (tbody) tbody.innerHTML = html;
                if (loading) loading.classList.add('hidden');
                if (list) list.classList.remove('hidden');
            }
        })
        .catch(error => {
            console.error('[Tax Settings] Load failed:', error);
            if (loading) loading.innerHTML = `<div class="text-red-500 text-sm">${locale.includes('zh') ? '加载失败' : 'Error'}</div>`;
        });
    }

    setCategoryTaxRate(categoryId, rate) {
        const input = document.querySelector(`.tax-cat-rate-input[data-category-id="${categoryId}"]`);
        if (input) {
            input.value = rate;
            const row = input.closest('tr');
            if (row) {
                row.querySelectorAll('td:last-child button').forEach(btn => {
                    btn.classList.remove('bg-yellow-100', 'border-yellow-400', 'bg-orange-100', 'border-orange-400', 'bg-red-100', 'border-red-400', 'font-bold');
                });
                const map = { 4: ['bg-yellow-100', 'border-yellow-400'], 10: ['bg-orange-100', 'border-orange-400'], 21: ['bg-red-100', 'border-red-400'] };
                if (map[rate]) {
                    row.querySelectorAll('td:last-child button').forEach(btn => {
                        if (btn.textContent.trim() === rate + '%') btn.classList.add(...map[rate], 'font-bold');
                    });
                }
            }
        }
    }

    saveCategoryTaxRates() {
        const locale = document.documentElement.lang || 'en';
        const saveBtn = document.getElementById('save-category-tax-btn');
        const inputs = document.querySelectorAll('.tax-cat-rate-input');
        const rates = [];
        inputs.forEach(input => { rates.push({ category_id: input.dataset.categoryId, tax_rate: input.value }); });

        if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = locale.includes('zh') ? '保存中...' : 'Saving...'; }

        this.ajaxRequest({ pos_action: 'save_category_tax_rates', rates: JSON.stringify(rates) })
        .then(data => {
            if (data.success) {
                this.showToast(locale.includes('zh') ? '分类税率保存成功' : locale.includes('es') ? 'IVA guardado' : 'Category tax rates saved', 'success');
                this.loadTaxSettings();
            } else { throw new Error(data.data?.message || 'Error'); }
        })
        .catch(error => { this.showToast(locale.includes('zh') ? '保存失败' : 'Save failed', 'error'); })
        .finally(() => {
            if (saveBtn) {
                saveBtn.disabled = false;
                saveBtn.innerHTML = `<svg class="w-4 h-4 mr-1.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg>${locale.includes('zh') ? '保存全部分类税率' : locale.includes('es') ? 'Guardar Todos' : 'Save All'}`;
            }
        });
    }

    searchProductForTax(query) {
        const resultsDiv = document.getElementById('tax-product-search-results');
        const locale = document.documentElement.lang || 'en';
        if (!query || query.length < 2) { if (resultsDiv) resultsDiv.classList.add('hidden'); return; }

        if (this._taxSearchTimer) clearTimeout(this._taxSearchTimer);
        this._taxSearchTimer = setTimeout(() => {
            this.ajaxRequest({ pos_action: 'search_products_for_tax', query: query })
            .then(data => {
                if (data.success && data.data.products) {
                    const products = data.data.products;
                    if (products.length === 0) {
                        resultsDiv.innerHTML = `<div class="px-4 py-3 text-sm text-gray-500">${locale.includes('zh') ? '未找到' : 'Not found'}</div>`;
                    } else {
                        let html = '';
                        products.forEach(p => {
                            const taxLabel = p.tax_category ? (p.tax_category === 'custom' ? (p.custom_rate + '%') : {'super_reduced':'4%','reduced':'10%','standard':'21%'}[p.tax_category] || '') : '';
                            html += `<div onclick="pos.selectProductForTax(${p.id}, '${this.escapeHtml(p.name).replace(/'/g, "\\'")}', '${p.tax_category}', '${p.custom_rate}', '${this.escapeHtml(p.sku || '').replace(/'/g, "\\'")}')" class="px-4 py-2.5 hover:bg-blue-50 cursor-pointer border-b border-gray-100 last:border-0">
                                <div class="flex items-center justify-between">
                                    <span class="text-sm font-medium text-gray-800">${this.escapeHtml(p.name)}</span>
                                    ${taxLabel ? `<span class="text-xs px-2 py-0.5 bg-blue-100 text-blue-700 rounded-full">${taxLabel}</span>` : ''}
                                </div>
                            </div>`;
                        });
                        resultsDiv.innerHTML = html;
                    }
                    resultsDiv.classList.remove('hidden');
                }
            }).catch(e => console.error('[Tax] Search failed:', e));
        }, 300);
    }

    selectProductForTax(productId, name, taxCategory, customRate, sku) {
        document.getElementById('tax-product-search-results').classList.add('hidden');
        document.getElementById('tax-product-search').value = '';
        document.getElementById('tax-product-selected-id').value = productId;
        document.getElementById('tax-product-selected-name').textContent = name;
        document.getElementById('tax-product-selected-sku').textContent = sku ? 'SKU: ' + sku : '';
        document.getElementById('tax-product-selected').classList.remove('hidden');
        document.querySelectorAll('.tax-product-rate-btn').forEach(btn => btn.classList.remove('bg-blue-100', 'border-blue-500', 'text-blue-700'));
        this._selectedProductTaxCategory = taxCategory || '';
        if (taxCategory) {
            this.setProductTaxCategory(taxCategory);
            if (taxCategory === 'custom' && customRate) document.getElementById('tax-product-custom-rate').value = customRate;
        }
    }

    setProductTaxCategory(category) {
        this._selectedProductTaxCategory = category;
        document.querySelectorAll('.tax-product-rate-btn').forEach(btn => {
            btn.classList.remove('bg-blue-100', 'border-blue-500', 'text-blue-700');
            if (btn.dataset.rate === category) btn.classList.add('bg-blue-100', 'border-blue-500', 'text-blue-700');
        });
        const cw = document.getElementById('tax-product-custom-rate-wrapper');
        if (cw) { category === 'custom' ? cw.classList.remove('hidden') : cw.classList.add('hidden'); }
    }

    clearProductTaxSelection() {
        document.getElementById('tax-product-selected').classList.add('hidden');
        this._selectedProductTaxCategory = '';
        document.getElementById('tax-product-selected-id').value = '';
        document.getElementById('tax-product-custom-rate').value = '';
    }

    saveProductTaxRate() {
        const locale = document.documentElement.lang || 'en';
        const productId = document.getElementById('tax-product-selected-id').value;
        const taxCategory = this._selectedProductTaxCategory;
        const customRate = document.getElementById('tax-product-custom-rate').value;
        const saveBtn = document.getElementById('save-product-tax-btn');

        if (!productId) { this.showToast(locale.includes('zh') ? '请先选择产品' : 'Select a product first', 'error'); return; }
        if (!taxCategory) { this.showToast(locale.includes('zh') ? '请选择税率' : 'Select a tax category', 'error'); return; }
        if (taxCategory === 'custom' && (customRate === '' || isNaN(customRate))) { this.showToast(locale.includes('zh') ? '请输入自定义税率' : 'Enter custom rate', 'error'); return; }

        if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = locale.includes('zh') ? '保存中...' : 'Saving...'; }

        this.ajaxRequest({ pos_action: 'save_product_tax_rate', product_id: productId, tax_category: taxCategory, custom_rate: customRate || '0' })
        .then(data => {
            if (data.success) {
                this.showToast(locale.includes('zh') ? '产品税率保存成功' : locale.includes('es') ? 'IVA guardado' : 'Product tax rate saved', 'success');
                this.clearProductTaxSelection();
            } else { throw new Error(data.data?.message || 'Error'); }
        })
        .catch(error => { this.showToast(locale.includes('zh') ? '保存失败' : 'Save failed', 'error'); })
        .finally(() => {
            if (saveBtn) {
                saveBtn.disabled = false;
                saveBtn.innerHTML = `<svg class="w-4 h-4 mr-1.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg>${locale.includes('zh') ? '保存产品税率' : locale.includes('es') ? 'Guardar IVA' : 'Save Product Tax Rate'}`;
            }
        });
    }

    /**
     * 加载系统设置
     */
    loadSystemSettings() {
        // 从 localStorage 读取 PDF 自定义文件名设置
        const pdfCustomFilename = localStorage.getItem('pos_pdf_custom_filename') === 'true';
        const checkbox = document.getElementById('setting-pdf-custom-filename');
        if (checkbox) {
            checkbox.checked = pdfCustomFilename;
        }

        // 从服务器加载 PDF Codigo 列设置
        this.ajaxRequest({ pos_action: 'get_pdf_codigo_setting' })
        .then(data => {
            if (data.success) {
                const codigoCheckbox = document.getElementById('setting-pdf-show-codigo');
                if (codigoCheckbox) {
                    codigoCheckbox.checked = !!data.data.show_pdf_codigo;
                }
            }
        })
        .catch(() => {});

        // 加载自动生成SKU设置
        const autoSku = localStorage.getItem('pos_auto_generate_sku') === 'true';
        const autoSkuCheckbox = document.getElementById('setting-auto-generate-sku');
        if (autoSkuCheckbox) autoSkuCheckbox.checked = autoSku;
        this.toggleSkuGeneratorVisibility();

        // 恢复 PDF 下载目录显示
        this._restorePdfDirDisplay();
    }

    /**
     * 保存所有系统设置（总保存按钮）
     */
    saveAllSystemSettings() {
        const locale = document.documentElement.lang || 'en';
        const saveBtn = document.getElementById('system-settings-save-btn');
        const savedStatus = document.getElementById('system-settings-saved-status');

        // 显示加载状态
        if (saveBtn) {
            saveBtn.disabled = true;
            saveBtn.innerHTML = `<svg class="animate-spin w-4 h-4 mr-2" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>${locale.includes('zh') ? '保存中...' : locale.includes('es') ? 'Guardando...' : 'Saving...'}`;
        }
        if (savedStatus) savedStatus.classList.add('hidden');

        // 1. 保存 PDF 自定义文件名到 localStorage
        const pdfCustomFilename = document.getElementById('setting-pdf-custom-filename')?.checked || false;
        localStorage.setItem('pos_pdf_custom_filename', pdfCustomFilename.toString());

        // 2. 保存自动生成SKU设置到 localStorage
        const autoGenerateSku = document.getElementById('setting-auto-generate-sku')?.checked || false;
        localStorage.setItem('pos_auto_generate_sku', autoGenerateSku.toString());
        this.toggleSkuGeneratorVisibility();

        // 3. 保存 PDF Codigo 列设置到服务器
        const showCodigo = document.getElementById('setting-pdf-show-codigo')?.checked || false;
        this.ajaxRequest({
            pos_action: 'save_pdf_codigo_setting',
            show_pdf_codigo: showCodigo ? '1' : '0'
        })
        .then(data => {
            if (data.success) {
                if (savedStatus) {
                    savedStatus.classList.remove('hidden');
                    setTimeout(() => savedStatus.classList.add('hidden'), 3000);
                }
                this.showToast(
                    locale.includes('zh') ? '系统设置已保存' :
                    locale.includes('es') ? 'Configuración del sistema guardada' :
                    'System settings saved',
                    'success'
                );
            } else {
                throw new Error(data.data?.message || 'Save failed');
            }
        })
        .catch(error => {
            this.showToast(
                locale.includes('zh') ? '保存失败' :
                locale.includes('es') ? 'Error al guardar' :
                'Save failed',
                'error'
            );
        })
        .finally(() => {
            if (saveBtn) {
                saveBtn.disabled = false;
                saveBtn.innerHTML = `<svg class="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg>${locale.includes('zh') ? '保存系统设置' : locale.includes('es') ? 'Guardar configuración' : 'Save System Settings'}`;
            }
        });
    }

    // ===== Auto Generate SKU Feature =====

    /**
     * 切换SKU生成器显示状态
     */
    toggleSkuGeneratorVisibility() {
        const enabled = localStorage.getItem('pos_auto_generate_sku') === 'true';
        ['settings-sku-generator', 'modal-sku-generator'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.classList.toggle('hidden', !enabled);
        });
        if (enabled) this._loadSkuCategories();
    }

    /**
     * 加载产品分类到SKU生成器下拉框
     */
    _loadSkuCategories() {
        this.ajaxRequest({ pos_action: 'get_tax_settings' })
        .then(data => {
            if (data.success && data.data.categories) {
                const locale = document.documentElement.lang || 'en';
                const placeholder = locale.includes('zh') ? '选择分类...' : locale.includes('es') ? 'Seleccionar...' : 'Select...';
                const opts = `<option value="">${placeholder}</option>` +
                    data.data.categories.map(c => `<option value="${this.escapeHtml(c.slug)}" data-name="${this.escapeHtml(c.name)}">${this.escapeHtml(c.name)}</option>`).join('');
                ['settings-sku-category', 'modal-sku-category'].forEach(id => {
                    const sel = document.getElementById(id);
                    if (sel) sel.innerHTML = opts;
                });
            }
        }).catch(() => {});
    }

    /**
     * 添加新分类并选中
     */
    addSkuCategory(prefix) {
        const input = document.getElementById(`${prefix}-new-category-name`);
        const name = input?.value.trim();
        if (!name) return;

        const locale = document.documentElement.lang || 'en';
        input.disabled = true;

        this.ajaxRequest({
            pos_action: 'create_product_category',
            category_name: name
        })
        .then(data => {
            if (data.success) {
                this._loadSkuCategories();
                // 等分类加载完后选中新分类
                setTimeout(() => {
                    ['settings-sku-category', 'modal-sku-category'].forEach(id => {
                        const sel = document.getElementById(id);
                        if (sel) {
                            const opt = Array.from(sel.options).find(o => o.dataset.name === name);
                            if (opt) sel.value = opt.value;
                        }
                    });
                }, 500);
                input.value = '';
                this.showToast(locale.includes('zh') ? '分类已添加' : locale.includes('es') ? 'Categoría añadida' : 'Category added', 'success');
            } else {
                this.showToast(data.data?.message || 'Error', 'error');
            }
        })
        .catch(() => this.showToast('Error', 'error'))
        .finally(() => { if (input) input.disabled = false; });
    }

    /**
     * 为指定表单生成唯一SKU
     */
    generateSkuForField(prefix) {
        const selectId = `${prefix}-sku-category`;
        const skuFieldId = prefix === 'settings' ? 'settings-product-sku' : 'product-sku';
        const select = document.getElementById(selectId);
        const locale = document.documentElement.lang || 'en';

        if (!select?.value) {
            this.showToast(locale.includes('zh') ? '请先选择产品分类' : locale.includes('es') ? 'Seleccione una categoría' : 'Please select a category', 'error');
            return;
        }

        const slug = select.value;
        // 取分类前缀：slug前4个字母
        const catPrefix = slug.replace(/[^a-z0-9]/gi, '').substring(0, 4).toUpperCase();
        const random = Math.floor(Math.random() * 1000000).toString().padStart(6, '0');
        const sku = `${catPrefix}${random}`;

        // 通过AJAX检查唯一性
        this.ajaxRequest({
            pos_action: 'check_sku_unique',
            sku: sku
        })
        .then(data => {
            if (data.success && data.data.unique) {
                const field = document.getElementById(skuFieldId);
                if (field) {
                    field.value = sku;
                    field.dispatchEvent(new Event('input', { bubbles: true }));
                }
                this.showToast(locale.includes('zh') ? 'SKU已生成' : locale.includes('es') ? 'SKU generado' : 'SKU generated', 'success');
                // 触发产品匹配搜索
                this._searchSkuForPrefix(prefix, sku);
            } else {
                // 极小概率冲突，重试
                this.generateSkuForField(prefix);
            }
        })
        .catch(() => {
            // 网络错误时仍使用生成的SKU（概率极低冲突）
            const field = document.getElementById(skuFieldId);
            if (field) field.value = sku;
        });
    }

    /**
     * 为指定前缀的表单搜索SKU匹配
     */
    _searchSkuForPrefix(prefix, sku) {
        if (prefix === 'modal') {
            // 主弹窗直接用现有方法
            this.searchProductBySku(sku);
            return;
        }
        // settings表单的SKU搜索
        const statusEl = document.getElementById('settings-sku-search-status');
        if (statusEl) {
            statusEl.textContent = '搜索中...';
            statusEl.className = 'ml-2 text-xs font-normal text-blue-600';
        }
        this.ajaxRequest({ pos_action: 'search_product_by_sku', sku: sku })
        .then(data => {
            if (data.success && data.data && data.data.product) {
                // 找到产品，填充settings表单
                const p = data.data.product;
                const el = id => document.getElementById(id);
                if (el('settings-product-edit-id')) el('settings-product-edit-id').value = p.id || '';
                if (el('settings-product-name')) el('settings-product-name').value = p.name || '';
                if (el('settings-product-retail-price')) el('settings-product-retail-price').value = p.regular_price || p.price || '';
                if (el('settings-product-stock')) {
                    el('settings-product-stock').value = (p.stock !== null && p.stock !== undefined && p.stock !== -1) ? p.stock : '';
                }
                if (el('settings-product-number')) el('settings-product-number').value = p.product_number || '';
                if (statusEl) {
                    statusEl.textContent = '✓ 找到产品，可编辑';
                    statusEl.className = 'ml-2 text-xs font-normal text-green-600';
                }
                // 更新保存按钮为"更新"
                const saveBtn = el('settings-save-product-btn');
                if (saveBtn) {
                    saveBtn.textContent = saveBtn.dataset.updateText || '更新产品';
                    saveBtn.classList.remove('bg-blue-600', 'hover:bg-blue-700');
                    saveBtn.classList.add('bg-green-600', 'hover:bg-green-700');
                }
            } else {
                if (el('settings-product-edit-id')) document.getElementById('settings-product-edit-id').value = '';
                if (statusEl) {
                    statusEl.textContent = '新产品';
                    statusEl.className = 'ml-2 text-xs font-normal text-orange-600';
                }
            }
        })
        .catch(() => {
            if (statusEl) {
                statusEl.textContent = '搜索失败';
                statusEl.className = 'ml-2 text-xs font-normal text-red-600';
            }
        });
    }

    // ===== PDF Download Directory Feature (File System Access API + IndexedDB) =====

    /**
     * IndexedDB helper - open database for storing directory handle
     */
    _openPdfDirDB() {
        return new Promise((resolve, reject) => {
            const req = indexedDB.open('pos_pdf_dir', 1);
            req.onupgradeneeded = (e) => {
                e.target.result.createObjectStore('handles');
            };
            req.onsuccess = (e) => resolve(e.target.result);
            req.onerror = (e) => reject(e.target.error);
        });
    }

    /**
     * Save directory handle to IndexedDB
     */
    async _saveDirHandle(handle) {
        const db = await this._openPdfDirDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction('handles', 'readwrite');
            tx.objectStore('handles').put(handle, 'pdf_dir');
            tx.oncomplete = () => resolve();
            tx.onerror = (e) => reject(e.target.error);
        });
    }

    /**
     * Get directory handle from IndexedDB
     */
    async _getDirHandle() {
        try {
            const db = await this._openPdfDirDB();
            return new Promise((resolve) => {
                const tx = db.transaction('handles', 'readonly');
                const req = tx.objectStore('handles').get('pdf_dir');
                req.onsuccess = () => resolve(req.result || null);
                req.onerror = () => resolve(null);
            });
        } catch {
            return null;
        }
    }

    /**
     * Remove directory handle from IndexedDB
     */
    async _removeDirHandle() {
        try {
            const db = await this._openPdfDirDB();
            return new Promise((resolve) => {
                const tx = db.transaction('handles', 'readwrite');
                tx.objectStore('handles').delete('pdf_dir');
                tx.oncomplete = () => resolve();
                tx.onerror = () => resolve();
            });
        } catch {}
    }

    /**
     * Select PDF download directory via File System Access API
     */
    async selectPdfDownloadDir() {
        const locale = document.documentElement.lang || 'en';

        if (!('showDirectoryPicker' in window)) {
            this.showToast(
                locale.includes('zh') ? '当前浏览器不支持此功能，请使用Chrome或Edge浏览器' :
                locale.includes('es') ? 'Su navegador no soporta esta función. Use Chrome o Edge' :
                'Your browser does not support this feature. Please use Chrome or Edge',
                'error'
            );
            return;
        }

        try {
            const handle = await window.showDirectoryPicker({ mode: 'readwrite' });
            await this._saveDirHandle(handle);

            const display = document.getElementById('pdf-dir-path-display');
            const clearBtn = document.getElementById('pdf-dir-clear-btn');
            if (display) {
                display.textContent = handle.name;
                display.classList.remove('hidden');
            }
            if (clearBtn) clearBtn.classList.remove('hidden');

            this.showToast(
                locale.includes('zh') ? `PDF将保存到: ${handle.name}` :
                locale.includes('es') ? `PDF se guardará en: ${handle.name}` :
                `PDF will be saved to: ${handle.name}`,
                'success'
            );
        } catch (e) {
            if (e.name !== 'AbortError') {
                console.error('[PdfDir] Error selecting directory:', e);
                this.showToast(
                    locale.includes('zh') ? '选择文件夹失败' :
                    locale.includes('es') ? 'Error al seleccionar carpeta' :
                    'Failed to select folder',
                    'error'
                );
            }
        }
    }

    /**
     * Clear PDF download directory setting
     */
    async clearPdfDownloadDir() {
        await this._removeDirHandle();

        const display = document.getElementById('pdf-dir-path-display');
        const clearBtn = document.getElementById('pdf-dir-clear-btn');
        if (display) {
            display.textContent = '';
            display.classList.add('hidden');
        }
        if (clearBtn) clearBtn.classList.add('hidden');

        const locale = document.documentElement.lang || 'en';
        this.showToast(
            locale.includes('zh') ? 'PDF保存路径已清除，将使用浏览器默认下载位置' :
            locale.includes('es') ? 'Ruta de PDF borrada. Se usará la ubicación predeterminada' :
            'PDF path cleared. Browser default download location will be used',
            'info'
        );
    }

    /**
     * Download PDF to selected directory, or fall back to browser default download
     */
    async downloadPdfToDir(url, filename) {
        const locale = document.documentElement.lang || 'en';

        const handle = await this._getDirHandle();

        if (handle) {
            try {
                const perm = await handle.requestPermission({ mode: 'readwrite' });
                if (perm === 'granted') {
                    const response = await fetch(url);
                    if (!response.ok) throw new Error('Fetch failed: ' + response.status);
                    const blob = await response.blob();

                    const fileHandle = await handle.getFileHandle(filename, { create: true });
                    const writable = await fileHandle.createWritable();
                    await writable.write(blob);
                    await writable.close();

                    this.showToast(
                        locale.includes('zh') ? `PDF已保存到: ${handle.name}/${filename}` :
                        locale.includes('es') ? `PDF guardado en: ${handle.name}/${filename}` :
                        `PDF saved to: ${handle.name}/${filename}`,
                        'success'
                    );
                    return;
                }
            } catch (e) {
                console.warn('[PdfDir] Failed to save to directory, falling back:', e);
            }
        }

        // Fallback: normal browser download
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        link.target = '_blank';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    }

    /**
     * Restore PDF directory display on settings load
     */
    async _restorePdfDirDisplay() {
        try {
            const handle = await this._getDirHandle();
            if (handle) {
                const display = document.getElementById('pdf-dir-path-display');
                const clearBtn = document.getElementById('pdf-dir-clear-btn');
                if (display) {
                    display.textContent = handle.name;
                    display.classList.remove('hidden');
                }
                if (clearBtn) clearBtn.classList.remove('hidden');
            }
        } catch (e) {
            console.warn('[PdfDir] Could not restore directory display:', e);
        }
    }

    /**
     * 🔥 切换公司信息 显示/编辑 模式
     */
    toggleCompanyEdit(editMode) {
        const display = document.getElementById('company-display-mode');
        const form = document.getElementById('company-settings-form');
        if (!display || !form) return;
        if (editMode) {
            display.classList.add('hidden');
            form.classList.remove('hidden');
        } else {
            form.classList.add('hidden');
            display.classList.remove('hidden');
        }
    }

    /**
     * 🔥 保存后刷新只读显示区
     */
    _updateCompanyDisplay() {
        const v = (id) => document.getElementById(id)?.value || '';
        const s = (id, text) => { const el = document.getElementById(id); if (el) el.textContent = text || '-'; };
        s('cd-emitter-name', v('company-emitter-name'));
        s('cd-emitter-vat', v('company-emitter-vat'));
        s('cd-emitter-phone', v('company-emitter-phone'));
        const addr = [v('company-emitter-address1'), v('company-emitter-address2'), (v('company-emitter-city') + ' ' + v('company-emitter-postcode')).trim(), v('company-emitter-country')].filter(Boolean).join(', ');
        s('cd-address', addr);
        s('cd-bank-name', v('company-bank-name'));
        s('cd-bank-iban', v('company-bank-iban'));
        s('cd-bank-bic', v('company-bank-bic'));
        s('cd-store-name', v('company-receipt-store-name'));
        s('cd-receipt-footer', v('company-receipt-footer'));
        const autoPrint = document.getElementById('company-auto-print-toggle')?.dataset.enabled === 'true';
        s('cd-auto-print', autoPrint ? '✓' : '✗');
    }

    /**
     * 🔥 保存公司/Emisor设置
     */
    saveCompanySettings() {
        const locale = document.documentElement.lang || 'en';
        const saveBtn = document.getElementById('company-settings-save-btn');

        // Show loading state
        if (saveBtn) {
            saveBtn.innerHTML = `
                <svg class="animate-spin w-5 h-5 mr-2" fill="none" viewBox="0 0 24 24">
                    <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                    <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                ${locale.includes('zh') ? '保存中...' : locale.includes('es') ? 'Guardando...' : 'Saving...'}
            `;
            saveBtn.disabled = true;
        }

        // Collect form data
        const formData = {
            pos_action: 'save_company_settings',
            emitter_name: document.getElementById('company-emitter-name')?.value || '',
            emitter_vat: document.getElementById('company-emitter-vat')?.value || '',
            emitter_phone: document.getElementById('company-emitter-phone')?.value || '',
            emitter_address_1: document.getElementById('company-emitter-address1')?.value || '',
            emitter_address_2: document.getElementById('company-emitter-address2')?.value || '',
            emitter_city: document.getElementById('company-emitter-city')?.value || '',
            emitter_postcode: document.getElementById('company-emitter-postcode')?.value || '',
            emitter_country: document.getElementById('company-emitter-country')?.value || 'ES',
            default_bank_name: document.getElementById('company-bank-name')?.value || '',
            default_bank_iban: document.getElementById('company-bank-iban')?.value || '',
            default_bank_bic: document.getElementById('company-bank-bic')?.value || '',
            receipt_store_name: document.getElementById('company-receipt-store-name')?.value || '',
            receipt_footer: document.getElementById('company-receipt-footer')?.value || '',
            auto_print_receipt: document.getElementById('company-auto-print-toggle')?.dataset.enabled === 'true' ? '1' : '0'
        };

        this.ajaxRequest(formData)
        .then(data => {
            if (data.success) {
                // 🔥 更新本地变量，无需刷新页面
                ruiyi_pos_ajax.default_bank = {
                    bank_name: formData.default_bank_name,
                    bank_iban: formData.default_bank_iban,
                    bank_bic: formData.default_bank_bic
                };
                // 更新小票用的 store_settings
                if (ruiyi_pos_ajax.store_settings) {
                    const addr = [formData.emitter_address_1, (formData.emitter_city + ' ' + formData.emitter_postcode).trim()].filter(Boolean).join(', ');
                    ruiyi_pos_ajax.store_settings.business_name = formData.emitter_name;
                    ruiyi_pos_ajax.store_settings.store_name = formData.receipt_store_name || formData.emitter_name;
                    ruiyi_pos_ajax.store_settings.store_address = addr;
                    ruiyi_pos_ajax.store_settings.store_phone = formData.emitter_phone;
                    ruiyi_pos_ajax.store_settings.store_tax_number = formData.emitter_vat;
                    ruiyi_pos_ajax.store_settings.receipt_footer = formData.receipt_footer || ruiyi_pos_ajax.store_settings.receipt_footer;
                    ruiyi_pos_ajax.store_settings.auto_print_receipt = formData.auto_print_receipt === '1';
                }
                this.showToast(
                    locale.includes('zh') ? '公司信息保存成功' :
                    locale.includes('es') ? 'Datos de empresa guardados' :
                    'Company settings saved',
                    'success'
                );
                // 刷新只读显示 & 切回显示模式
                this._updateCompanyDisplay();
                this.toggleCompanyEdit(false);
            } else {
                throw new Error(data.data?.message || 'Save failed');
            }
        })
        .catch(error => {
            console.error('[Company Settings] Save failed:', error);
            this.showToast(
                locale.includes('zh') ? '保存失败' :
                locale.includes('es') ? 'Error al guardar' :
                'Failed to save settings',
                'error'
            );
        })
        .finally(() => {
            // Restore button state
            if (saveBtn) {
                saveBtn.innerHTML = `
                    <svg class="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/>
                    </svg>
                    ${locale.includes('zh') ? '保存公司信息' : locale.includes('es') ? 'Guardar Datos' : 'Save Company Info'}
                `;
                saveBtn.disabled = false;
            }
        });
    }

    // ====== 条码打印功能 (Barcode Print) ======

    /**
     * HTML 实体解码（用于 formatted_price 等）
     */
    decodeHtmlEntities(str) {
        if (!str || typeof str !== 'string') return str;
        const el = document.createElement('textarea');
        el.innerHTML = str;
        return el.value;
    }

    /**
     * 自动检测条码格式
     */
    detectBarcodeFormat(value) {
        if (!value) return 'CODE128';
        const v = String(value).trim();
        if (/^\d{13}$/.test(v)) return 'EAN13';
        if (/^\d{12}$/.test(v)) return 'UPC';
        if (/^\d{8}$/.test(v)) return 'EAN8';
        if (/^\d{14}$/.test(v)) return 'ITF14';
        if (/^\d+$/.test(v) && v.length >= 2) return 'CODE128';
        return 'CODE128';
    }

    /**
     * 安全生成 JsBarcode（自动格式 + fallback）
     */
    generateBarcode(svgEl, value, opts = {}) {
        const v = String(value || '').trim();
        if (!v) return false;
        const format = this.detectBarcodeFormat(v);
        const defaults = { width: 1.2, height: 30, displayValue: true, fontSize: 8, margin: 0, textMargin: 1 };
        const options = { ...defaults, ...opts, format };
        try {
            JsBarcode(svgEl, v, options);
            return true;
        } catch(e) {
            // fallback CODE128
            try {
                JsBarcode(svgEl, v, { ...options, format: 'CODE128' });
                return true;
            } catch(e2) {
                return false;
            }
        }
    }

    /**
     * 初始化条码打印选项卡
     */
    initBarcodePrintTab() {
        if (!this.barcodePrintList) {
            this.barcodePrintList = [];
        }
        // 从 localStorage 加载标签配置
        try {
            const saved = JSON.parse(localStorage.getItem('ruiyi_barcode_label_config'));
            if (saved) {
                const presetEl = document.getElementById('barcode-label-preset');
                if (presetEl) presetEl.value = saved.preset || '40x30';
                if (saved.preset === 'custom') {
                    document.getElementById('barcode-custom-size').classList.remove('hidden');
                    document.getElementById('barcode-label-width').value = saved.width || 40;
                    document.getElementById('barcode-label-height').value = saved.height || 30;
                }
                const setVal = (id, val) => { const el = document.getElementById(id); if (el && val) el.value = val; };
                setVal('barcode-labels-per-row', saved.perRow);
                setVal('barcode-font-name', saved.fontName);
                setVal('barcode-font-code', saved.fontCode);
                setVal('barcode-font-price', saved.fontPrice);
                const showNameEl = document.getElementById('barcode-show-name');
                if (showNameEl) showNameEl.checked = saved.showName !== false;
                const showPriceEl = document.getElementById('barcode-show-price');
                if (showPriceEl) showPriceEl.checked = saved.showPrice !== false;
                setVal('barcode-bar-scale', saved.barScale);
                setVal('barcode-offset-x', saved.offsetX || 0);
            }
        } catch(e) {}
        this.renderBarcodeSelectedList();
        // 加载产品列表
        this.loadBarcodeProductList();
    }

    /**
     * 获取当前标签尺寸配置（含字体大小）
     */
    getBarcodeLabelConfig() {
        const preset = document.getElementById('barcode-label-preset')?.value || '40x30';
        let width, height;
        if (preset === 'custom') {
            width = parseInt(document.getElementById('barcode-label-width')?.value) || 40;
            height = parseInt(document.getElementById('barcode-label-height')?.value) || 30;
        } else {
            const parts = preset.split('x');
            width = parseInt(parts[0]);
            height = parseInt(parts[1]);
        }
        const perRow = parseInt(document.getElementById('barcode-labels-per-row')?.value) || 1;
        const showName = document.getElementById('barcode-show-name')?.checked !== false;
        const showPrice = document.getElementById('barcode-show-price')?.checked !== false;
        const fontName = parseInt(document.getElementById('barcode-font-name')?.value) || 7;
        const fontCode = parseInt(document.getElementById('barcode-font-code')?.value) || 8;
        const fontPrice = parseInt(document.getElementById('barcode-font-price')?.value) || 9;
        const barScale = parseFloat(document.getElementById('barcode-bar-scale')?.value) || 1.0;
        const offsetX = parseFloat(document.getElementById('barcode-offset-x')?.value) || 0;
        const config = { preset, width, height, perRow, showName, showPrice, fontName, fontCode, fontPrice, barScale, offsetX };
        localStorage.setItem('ruiyi_barcode_label_config', JSON.stringify(config));
        return config;
    }

    /**
     * 标签预设尺寸变更
     */
    onBarcodeLabelPresetChange() {
        const preset = document.getElementById('barcode-label-preset')?.value;
        const customDiv = document.getElementById('barcode-custom-size');
        if (customDiv) {
            customDiv.classList.toggle('hidden', preset !== 'custom');
        }
        this.getBarcodeLabelConfig();
    }

    /**
     * 加载所有产品列表
     */
    loadBarcodeProductList() {
        const listDiv = document.getElementById('barcode-product-list');
        this.ajaxRequest({ pos_action: 'search_products', search: '*' })
        .then(resp => {
            const products = resp?.data?.products || resp?.products || [];
            this._barcodeAllProducts = products;
            this._barcodeCurrentPage = 1;
            this._barcodeFilteredProducts = products;
            this._renderBarcodeProductList(products);
        })
        .catch(() => {
            listDiv.innerHTML = '<p class="text-sm text-red-400 text-center py-2">Error loading products</p>';
        });
    }

    /**
     * 本地筛选产品列表（输入时实时过滤，重置到第1页）
     */
    filterBarcodeProductList() {
        const query = document.getElementById('barcode-search-input')?.value?.trim().toLowerCase();
        this._barcodeCurrentPage = 1;
        if (!query) {
            this._barcodeFilteredProducts = this._barcodeAllProducts || [];
        } else {
            this._barcodeFilteredProducts = (this._barcodeAllProducts || []).filter(p =>
                (p.name && p.name.toLowerCase().includes(query)) ||
                (p.sku && p.sku.toLowerCase().includes(query)) ||
                (p.barcode && p.barcode.toLowerCase().includes(query))
            );
        }
        this._renderBarcodeProductList(this._barcodeFilteredProducts);
    }

    /**
     * 渲染产品列表（懒加载，滚动到底部自动加载更多）
     */
    _renderBarcodeProductList(products) {
        const listDiv = document.getElementById('barcode-product-list');
        this._barcodeSearchResults = products;
        this._barcodeRenderedCount = 0;

        // 清除旧的滚动监听
        if (this._barcodeScrollHandler) {
            listDiv.removeEventListener('scroll', this._barcodeScrollHandler);
            this._barcodeScrollHandler = null;
        }

        if (!products || products.length === 0) {
            listDiv.innerHTML = '<p class="text-sm text-gray-400 text-center py-2">' +
                (document.documentElement.lang?.startsWith('zh') ? '未找到产品' : 'No products found') + '</p>';
            return;
        }

        listDiv.innerHTML = '';
        listDiv.scrollTop = 0;
        this._barcodeLoadMore(products, listDiv);

        // 滚动懒加载
        this._barcodeScrollHandler = () => {
            if (this._barcodeRenderedCount >= products.length) return;
            if (listDiv.scrollTop + listDiv.clientHeight >= listDiv.scrollHeight - 80) {
                this._barcodeLoadMore(products, listDiv);
            }
        };
        listDiv.addEventListener('scroll', this._barcodeScrollHandler);
    }

    /**
     * 懒加载：追加一批产品到列表
     */
    _barcodeLoadMore(products, listDiv) {
        const batchSize = 50;
        const start = this._barcodeRenderedCount;
        const end = Math.min(start + batchSize, products.length);
        if (start >= end) return;

        const addLabel = document.documentElement.lang?.startsWith('zh') ? '添加' :
            document.documentElement.lang?.startsWith('es') ? 'Añadir' : 'Add';

        const fragment = document.createDocumentFragment();
        for (let i = start; i < end; i++) {
            const p = products[i];
            const row = document.createElement('div');
            row.className = 'flex items-center justify-between py-1.5 px-2 hover:bg-blue-50 text-sm border-b border-gray-100 last:border-0';
            row.innerHTML = `<div class="flex-1 min-w-0">
                    <span class="font-medium text-gray-800 truncate block">${this.escapeHtml(p.name)}</span>
                    <span class="text-xs text-gray-400">${this.escapeHtml(p.sku || '-')} | ${this.decodeHtmlEntities(p.formatted_price || String(p.price))}</span>
                </div>
                <button onclick="pos.addToBarcodeListByIndex(${i})" class="bg-blue-500 hover:bg-blue-600 text-white px-2.5 py-1 rounded text-xs font-medium transition-colors ml-2 flex-shrink-0">${addLabel}</button>`;
            fragment.appendChild(row);
        }
        listDiv.appendChild(fragment);
        this._barcodeRenderedCount = end;
    }

    /**
     * 服务器搜索产品（条码打印用，回车或点搜索按钮）
     */
    searchBarcodeProducts() {
        const query = document.getElementById('barcode-search-input')?.value?.trim();
        if (!query) { this.filterBarcodeProductList(); return; }

        const listDiv = document.getElementById('barcode-product-list');
        listDiv.innerHTML = '<p class="text-sm text-gray-400 text-center py-2">...</p>';

        const noFoundMsg = document.documentElement.lang?.startsWith('zh') ? '未找到产品' :
            document.documentElement.lang?.startsWith('es') ? 'No se encontraron productos' : 'No products found';

        this.ajaxRequest({ pos_action: 'search_products', search: query })
        .then(resp => {
            const products = resp?.data?.products || resp?.products || [];
            if (products.length > 0) {
                this._renderBarcodeProductList(products);
                return;
            }
            return this.ajaxRequest({ pos_action: 'search_by_barcode', barcode: query })
            .then(bResp => {
                const product = bResp?.data?.product || bResp?.product;
                if (product) {
                    this._renderBarcodeProductList([product]);
                } else {
                    listDiv.innerHTML = `<p class="text-sm text-gray-400 text-center py-2">${noFoundMsg}</p>`;
                }
            })
            .catch(() => {
                listDiv.innerHTML = `<p class="text-sm text-gray-400 text-center py-2">${noFoundMsg}</p>`;
            });
        })
        .catch(() => {
            this.ajaxRequest({ pos_action: 'search_by_barcode', barcode: query })
            .then(bResp => {
                const product = bResp?.data?.product || bResp?.product;
                if (product) {
                    this._renderBarcodeProductList([product]);
                } else {
                    listDiv.innerHTML = `<p class="text-sm text-gray-400 text-center py-2">${noFoundMsg}</p>`;
                }
            })
            .catch(() => {
                listDiv.innerHTML = '<p class="text-sm text-red-400 text-center py-2">Error</p>';
            });
        });
    }

    /**
     * 通过列表索引添加产品
     */
    addToBarcodeListByIndex(idx) {
        if (!this._barcodeSearchResults || !this._barcodeSearchResults[idx]) return;
        this.addToBarcodeList(this._barcodeSearchResults[idx]);
    }

    /**
     * 添加产品到打印列表
     */
    addToBarcodeList(product) {
        if (!this.barcodePrintList) this.barcodePrintList = [];

        const existing = this.barcodePrintList.find(item => item.id === product.id);
        if (existing) {
            existing.qty += 1;
        } else {
            this.barcodePrintList.push({
                id: product.id,
                name: product.name,
                sku: product.sku || '',
                barcode: product.barcode || product.sku || `PROD-${product.id}`,
                price: product.price,
                formatted_price: this.decodeHtmlEntities(product.formatted_price || String(product.price)),
                qty: 1
            });
        }
        this.renderBarcodeSelectedList();
    }

    /**
     * 渲染已选产品列表
     */
    renderBarcodeSelectedList() {
        const listDiv = document.getElementById('barcode-selected-list');
        const countSpan = document.getElementById('barcode-list-count');
        const hint = document.getElementById('barcode-empty-hint');

        if (!this.barcodePrintList || this.barcodePrintList.length === 0) {
            if (hint) hint.style.display = '';
            listDiv.querySelectorAll('.barcode-item-row').forEach(el => el.remove());
            if (countSpan) countSpan.textContent = '(0)';
            return;
        }
        if (hint) hint.style.display = 'none';

        const totalLabels = this.barcodePrintList.reduce((sum, item) => sum + item.qty, 0);
        if (countSpan) countSpan.textContent = `(${this.barcodePrintList.length} / ${totalLabels})`;

        listDiv.innerHTML = this.barcodePrintList.map((item, idx) => `
            <div class="barcode-item-row flex items-center justify-between py-1.5 px-2 hover:bg-gray-50 rounded text-sm border-b border-gray-100 last:border-0">
                <div class="flex-1 min-w-0">
                    <span class="font-medium text-gray-800 truncate block">${this.escapeHtml(item.name)}</span>
                    <span class="text-xs text-gray-400">SKU: ${this.escapeHtml(item.sku || '-')} | ${this.escapeHtml(item.formatted_price)}</span>
                </div>
                <div class="flex items-center gap-1.5 ml-2 flex-shrink-0">
                    <button onclick="pos.updateBarcodeQty(${idx}, -1)" class="w-6 h-6 rounded bg-gray-200 hover:bg-gray-300 text-gray-600 text-xs flex items-center justify-center">-</button>
                    <input type="number" min="1" value="${item.qty}" onchange="pos.setBarcodeQty(${idx}, this.value)" onclick="this.select()" class="w-10 h-6 text-center text-sm font-medium border border-gray-300 rounded focus:border-blue-500 focus:outline-none [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none">
                    <button onclick="pos.updateBarcodeQty(${idx}, 1)" class="w-6 h-6 rounded bg-gray-200 hover:bg-gray-300 text-gray-600 text-xs flex items-center justify-center">+</button>
                    <button onclick="pos.removeBarcodeItem(${idx})" class="text-red-400 hover:text-red-600 ml-1">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
                    </button>
                </div>
            </div>
        `).join('');
    }

    updateBarcodeQty(index, delta) {
        if (!this.barcodePrintList || !this.barcodePrintList[index]) return;
        this.barcodePrintList[index].qty = Math.max(1, this.barcodePrintList[index].qty + delta);
        this.renderBarcodeSelectedList();
    }

    setBarcodeQty(index, value) {
        if (!this.barcodePrintList || !this.barcodePrintList[index]) return;
        const qty = parseInt(value);
        if (isNaN(qty) || qty < 1) return;
        this.barcodePrintList[index].qty = qty;
        // 只更新计数显示，不重新渲染整个列表（避免输入框失焦）
        const countSpan = document.getElementById('barcode-list-count');
        if (countSpan) {
            const totalLabels = this.barcodePrintList.reduce((sum, item) => sum + item.qty, 0);
            countSpan.textContent = `(${this.barcodePrintList.length} / ${totalLabels})`;
        }
    }

    removeBarcodeItem(index) {
        if (!this.barcodePrintList) return;
        this.barcodePrintList.splice(index, 1);
        this.renderBarcodeSelectedList();
    }

    clearBarcodeList() {
        this.barcodePrintList = [];
        this.renderBarcodeSelectedList();
        this.closeBarcodePreview();
    }

    /**
     * 预览条码标签
     */
    /**
     * 根据标签尺寸计算最佳条码参数
     */
    _getBarcodeSizeParams(config) {
        const w = config.width;
        const h = config.height;
        const scale = config.barScale || 1.0;
        // 条码线宽：小标签细线，大标签粗线，确保可扫描
        const barWidth = (w <= 35 ? 1.0 : w <= 45 ? 1.2 : w <= 55 ? 1.4 : 1.6) * scale;

        // 计算条码可用高度（mm转px，1mm≈3.78px at 96dpi）
        // 减去名称、价格、padding占用的空间
        const ptToMm = 0.353; // 1pt ≈ 0.353mm
        let usedH = 1; // padding top+bottom
        if (config.showName) usedH += (config.fontName || 7) * ptToMm * 1.2;
        if (config.showPrice) usedH += (config.fontPrice || 9) * ptToMm * 1.2;
        usedH += (config.fontCode || 8) * ptToMm * 1.3; // 条码下方数字
        const availH = Math.max(5, h - usedH); // 条码可用高度(mm)
        const barHeight = Math.max(15, availH * 3.78 * 0.85) * scale; // mm转px，留15%余量

        // 内边距：紧凑
        const padV = Math.max(0.5, h * 0.02);
        const padH = Math.max(1, w * 0.03);
        // 条码区域宽度占比
        const barcodeWidthPct = w <= 35 ? 98 : w <= 50 ? 95 : 92;
        return { barWidth, barHeight, padV, padH, barcodeWidthPct };
    }

    /**
     * 打开标签预览弹窗（动态挂载到 body，只预览第一个产品）
     */
    toggleBarcodePreview() {
        if (!this.barcodePrintList || this.barcodePrintList.length === 0) return;

        // 如果已有弹窗，先关闭
        this.closeBarcodePreview();

        const config = this.getBarcodeLabelConfig();
        const sp = this._getBarcodeSizeParams(config);
        const item = this.barcodePrintList[0];

        const lang = document.documentElement.lang || 'en';
        const isZh = lang.startsWith('zh');
        const isEs = lang.startsWith('es');
        const titleText = isZh ? '标签预览' : isEs ? 'Vista previa' : 'Label Preview';
        const hintText = isZh ? '预览打印列表中第一个产品的标签样式' : isEs ? 'Vista previa del primer producto' : 'Preview of the first product label';

        // 创建弹窗
        const modal = document.createElement('div');
        modal.id = 'barcode-preview-modal';
        modal.style.cssText = 'position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;';

        // 遮罩
        const backdrop = document.createElement('div');
        backdrop.style.cssText = 'position:absolute;inset:0;background:rgba(0,0,0,0.5);';
        backdrop.onclick = () => this.closeBarcodePreview();
        modal.appendChild(backdrop);

        // 弹窗主体
        const dialog = document.createElement('div');
        dialog.style.cssText = 'position:relative;background:#fff;border-radius:12px;box-shadow:0 25px 50px -12px rgba(0,0,0,0.25);padding:24px;max-width:420px;width:calc(100% - 32px);';

        // 标题栏
        const header = document.createElement('div');
        header.style.cssText = 'display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;';
        header.innerHTML = `<h3 style="font-size:16px;font-weight:600;color:#1f2937;margin:0;">${titleText}</h3>`;
        const closeBtn = document.createElement('button');
        closeBtn.style.cssText = 'background:none;border:none;cursor:pointer;color:#9ca3af;padding:4px;border-radius:4px;display:flex;';
        closeBtn.innerHTML = '<svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>';
        closeBtn.onmouseenter = () => closeBtn.style.color = '#4b5563';
        closeBtn.onmouseleave = () => closeBtn.style.color = '#9ca3af';
        closeBtn.onclick = () => this.closeBarcodePreview();
        header.appendChild(closeBtn);
        dialog.appendChild(header);

        // 标签预览容器
        const container = document.createElement('div');
        container.style.cssText = 'display:flex;justify-content:center;';

        const label = document.createElement('div');
        label.style.cssText = `width:${config.width}mm;height:${config.height}mm;border:1px solid #d0d0d0;display:inline-flex;flex-direction:column;align-items:center;justify-content:center;gap:0.5mm;overflow:hidden;padding:${sp.padV}mm ${sp.padH}mm;box-sizing:border-box;font-family:Arial,Helvetica,sans-serif;background:#fff;`;

        if (config.showName) {
            const nameEl = document.createElement('div');
            nameEl.style.cssText = `font-size:${config.fontName}pt;text-align:center;line-height:1.2;width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600;color:#111;flex-shrink:0;`;
            nameEl.textContent = item.name;
            label.appendChild(nameEl);
        }

        const barcodeWrap = document.createElement('div');
        barcodeWrap.style.cssText = `width:${sp.barcodeWidthPct}%;display:flex;justify-content:center;align-items:center;flex:none;`;
        const svgEl = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svgEl.style.cssText = 'max-width:100%;height:auto;';
        barcodeWrap.appendChild(svgEl);
        label.appendChild(barcodeWrap);

        const barcodeValue = item.barcode || item.sku || `PROD-${item.id}`;
        if (!this.generateBarcode(svgEl, barcodeValue, {
            width: sp.barWidth,
            height: sp.barHeight,
            displayValue: true,
            fontSize: config.fontCode,
            margin: 0,
            textMargin: 1,
            font: 'Arial'
        })) {
            barcodeWrap.remove();
            const errEl = document.createElement('div');
            errEl.style.cssText = 'font-size:7pt;color:#cc0000;flex:1;display:flex;align-items:center;';
            errEl.textContent = 'Barcode error';
            label.appendChild(errEl);
        }

        if (config.showPrice) {
            const priceEl = document.createElement('div');
            priceEl.style.cssText = `font-size:${config.fontPrice}pt;font-weight:bold;text-align:center;color:#111;flex-shrink:0;`;
            priceEl.textContent = (item.formatted_price || '').replace(/([€$£¥])(\d)/, '$1 $2').replace(/(\d)([€$£¥])/, '$1 $2').replace(/(\d)\.(\d)/g, '$1,$2');
            label.appendChild(priceEl);
        }

        container.appendChild(label);
        dialog.appendChild(container);

        // 提示文字
        const hint = document.createElement('p');
        hint.style.cssText = 'font-size:12px;color:#9ca3af;text-align:center;margin:12px 0 0;';
        hint.textContent = hintText;
        dialog.appendChild(hint);

        modal.appendChild(dialog);
        document.body.appendChild(modal);
    }

    closeBarcodePreview() {
        const modal = document.getElementById('barcode-preview-modal');
        if (modal) modal.remove();
    }

    /**
     * 打印条码标签（通过 iframe 隔离）
     */
    printBarcodeLabels() {
        if (!this.barcodePrintList || this.barcodePrintList.length === 0) return;

        const config = this.getBarcodeLabelConfig();
        const sp = this._getBarcodeSizeParams(config);

        const iframe = document.createElement('iframe');
        iframe.style.cssText = 'position:fixed;top:-9999px;left:-9999px;width:0;height:0;border:none;';
        document.body.appendChild(iframe);

        const doc = iframe.contentDocument || iframe.contentWindow.document;
        let labelsHtml = '';

        // 生成所有标签的 SVG（displayValue: true 让条码数字直接集成在 SVG 内）
        const allLabels = [];
        this.barcodePrintList.forEach(item => {
            for (let i = 0; i < item.qty; i++) allLabels.push(item);
        });

        allLabels.forEach(item => {
            const svgEl = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            document.body.appendChild(svgEl);

            // 价格格式化：货币符号与数字之间加空格，小数点换逗号 (€30.90 → € 30,90)
            const labelPrice = (item.formatted_price || '').replace(/([€$£¥])(\d)/, '$1 $2').replace(/(\d)([€$£¥])/, '$1 $2').replace(/(\d)\.(\d)/g, '$1,$2');

            const barcodeValue = item.barcode || item.sku || `PROD-${item.id}`;
            this.generateBarcode(svgEl, barcodeValue, {
                width: sp.barWidth,
                height: sp.barHeight,
                displayValue: true,
                fontSize: config.fontCode,
                margin: 0,
                textMargin: 1,
                font: 'Arial'
            });

            labelsHtml += `
                <div class="label">
                    ${config.showName ? `<div class="label-name">${this.escapeHtml(item.name)}</div>` : ''}
                    <div class="label-barcode">${svgEl.outerHTML}</div>
                    ${config.showPrice ? `<div class="label-price">${this.escapeHtml(labelPrice)}</div>` : ''}
                </div>
            `;
            svgEl.remove();
        });

        const colCount = config.perRow;
        const isLabelPrinter = colCount === 1;
        const pageW = config.width * colCount;
        const pageH = config.height;
        const offsetX = config.offsetX || 0;
        doc.open();
        doc.write(`<!DOCTYPE html>
        <html><head><meta charset="utf-8">
        <style>
            @page { size: ${pageW}mm ${pageH}mm; margin: 0 !important; padding: 0 !important; }
            @media print { html, body { margin: 0 !important; padding: 0 !important; width: ${pageW}mm !important; } @page { margin: 0 !important; } }
            * { margin: 0; padding: 0; box-sizing: border-box; }
            html, body { margin: 0 !important; padding: 0 !important; width: ${pageW}mm; height: ${pageH}mm; font-family: Arial, Helvetica, sans-serif; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
            .labels-row { display: flex; flex-wrap: wrap; width: ${pageW}mm; margin: 0; padding: 0; ${offsetX ? `margin-left: ${offsetX}mm;` : ''} }
            .label {
                width: ${config.width}mm;
                height: ${pageH}mm;
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                gap: 0;
                page-break-inside: avoid;
                ${isLabelPrinter ? 'page-break-after: always;' : ''}
                overflow: hidden;
                padding: 0.3mm 1mm 0.8mm;
                box-sizing: border-box;
                margin: 0;
            }
            .label-name {
                font-size: ${config.fontName}pt;
                text-align: center;
                line-height: 1.1;
                width: 100%;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
                font-weight: 600;
                color: #000;
                flex-shrink: 0;
            }
            .label-barcode {
                display: flex;
                justify-content: center;
                align-items: center;
                width: ${sp.barcodeWidthPct}%;
                flex: 1;
                min-height: 0;
            }
            .label-barcode svg { max-width: 100%; max-height: 100%; }
            .label-price {
                font-size: ${config.fontPrice}pt;
                font-weight: bold;
                text-align: center;
                line-height: 1.1;
                color: #000;
                flex-shrink: 0;
                margin-top: 0.2mm;
            }
        </style></head>
        <body><div class="labels-row">${labelsHtml}</div></body></html>`);
        doc.close();

        setTimeout(() => {
            iframe.contentWindow.focus();
            iframe.contentWindow.print();
            setTimeout(() => { document.body.removeChild(iframe); }, 1000);
        }, 300);
    }

    /**
     * 🔥 加载工具箱设置
     */
    loadToolboxSettings() {
        const locale = document.documentElement.lang || 'en';

        this.ajaxRequest({ pos_action: 'get_toolbox_settings' })
        .then(data => {
            if (data.success && data.data.settings) {
                const settings = data.data.settings;

                // Update checkboxes
                document.getElementById('toolbox-show-hold-order').checked = settings.show_hold_order !== false;
                document.getElementById('toolbox-show-view-held').checked = settings.show_view_held !== false;
                document.getElementById('toolbox-show-clear-cart').checked = settings.show_clear_cart !== false;
                document.getElementById('toolbox-show-print-last').checked = settings.show_print_last !== false;

                console.log('[Toolbox Settings] Loaded successfully');
            }
        })
        .catch(error => {
            console.error('[Toolbox Settings] Failed to load:', error);
        });
    }

    /**
     * 🔥 保存工具箱设置
     */
    saveToolboxSettings() {
        const locale = document.documentElement.lang || 'en';
        const saveBtn = document.getElementById('save-toolbox-btn');

        // Show loading state
        if (saveBtn) {
            saveBtn.innerHTML = `
                <svg class="w-5 h-5 mr-2 animate-spin" fill="none" viewBox="0 0 24 24">
                    <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                    <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                ${locale.includes('zh') ? '保存中...' : locale.includes('es') ? 'Guardando...' : 'Saving...'}
            `;
            saveBtn.disabled = true;
        }

        const formData = {
            show_hold_order: document.getElementById('toolbox-show-hold-order').checked,
            show_view_held: document.getElementById('toolbox-show-view-held').checked,
            show_clear_cart: document.getElementById('toolbox-show-clear-cart').checked,
            show_print_last: document.getElementById('toolbox-show-print-last').checked
        };

        this.ajaxRequest({
            pos_action: 'save_toolbox_settings',
            settings: JSON.stringify(formData)
        })
        .then(data => {
            if (data.success) {
                this.showToast(
                    locale.includes('zh') ? '工具箱设置保存成功' :
                    locale.includes('es') ? 'Configuración guardada' :
                    'Toolbox settings saved',
                    'success'
                );
                // Apply settings to toolbox dropdown immediately
                this.applyToolboxVisibility(formData);
            } else {
                throw new Error(data.data?.message || 'Unknown error');
            }
        })
        .catch(error => {
            console.error('[Toolbox Settings] Save failed:', error);
            this.showToast(
                locale.includes('zh') ? '保存失败' :
                locale.includes('es') ? 'Error al guardar' :
                'Failed to save settings',
                'error'
            );
        })
        .finally(() => {
            // Restore button state
            if (saveBtn) {
                saveBtn.innerHTML = `
                    <svg class="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/>
                    </svg>
                    ${locale.includes('zh') ? '保存设置' : locale.includes('es') ? 'Guardar Configuración' : 'Save Settings'}
                `;
                saveBtn.disabled = false;
            }
        });
    }

    /**
     * 🔥 应用工具箱可见性设置
     */
    applyToolboxVisibility(settings) {
        const holdOrderBtn = document.getElementById('hold-order-btn');
        const viewHeldBtn = document.getElementById('view-held-orders-btn');
        const clearCartBtn = document.getElementById('clear-cart-btn');
        const printLastBtn = document.getElementById('print-last-order-btn');

        if (holdOrderBtn) {
            holdOrderBtn.style.display = settings.show_hold_order ? '' : 'none';
        }
        if (viewHeldBtn) {
            viewHeldBtn.style.display = settings.show_view_held ? '' : 'none';
        }
        if (clearCartBtn) {
            clearCartBtn.style.display = settings.show_clear_cart ? '' : 'none';
        }
        if (printLastBtn) {
            printLastBtn.style.display = settings.show_print_last ? '' : 'none';
        }
    }

    /**
     * 🔥 加载客户管理列表
     */
    loadCustomersManagement() {
        // 支持两个容器：旧的 customers-management-list 和新的 contacts-customers-list
        const listDivOld = document.getElementById('customers-management-list');
        const listDivNew = document.getElementById('contacts-customers-list');
        const listDiv = listDivNew || listDivOld;
        const locale = document.documentElement.lang || 'en';

        if (!listDiv) return;

        // Show loading
        const loadingHtml = `
            <div class="text-center py-6 text-gray-500">
                <div class="w-6 h-6 mx-auto mb-2 rounded-full border-2 border-gray-200 border-t-blue-600" style="animation: spin 0.8s linear infinite;"></div>
                ${locale.includes('zh') ? '加载中...' : locale.includes('es') ? 'Cargando...' : 'Loading...'}
            </div>
        `;
        listDiv.innerHTML = loadingHtml;
        if (listDivOld && listDivNew) listDivOld.innerHTML = loadingHtml;

        this.ajaxRequest({ pos_action: 'get_all_customers' })
        .then(data => {
            if (data.success) {
                this.customersManagementList = data.data || [];
                this.renderCustomersManagementList(this.customersManagementList);
            } else {
                throw new Error(data.data?.message || 'Failed to load');
            }
        })
        .catch(error => {
            console.error('[Customers] Load failed:', error);
            const errorHtml = `
                <div class="text-center py-6 text-red-500">
                    ${locale.includes('zh') ? '加载失败' : locale.includes('es') ? 'Error al cargar' : 'Failed to load'}
                </div>
            `;
            listDiv.innerHTML = errorHtml;
            if (listDivOld && listDivNew) listDivOld.innerHTML = errorHtml;
        });
    }

    /**
     * 🔥 渲染客户管理列表（表格形式）
     */
    renderCustomersManagementList(customers) {
        // 支持两个容器
        const listDivOld = document.getElementById('customers-management-list');
        const listDivNew = document.getElementById('contacts-customers-list');
        const listDiv = listDivNew || listDivOld;
        const locale = document.documentElement.lang || 'en';

        if (!listDiv) return;

        // 列标题翻译
        const headers = {
            number: locale.includes('zh') ? '编号' : locale.includes('es') ? 'Nº' : '#',
            company: locale.includes('zh') ? '客户名称' : locale.includes('es') ? 'Cliente' : 'Customer',
            cif: locale.includes('zh') ? '税号' : locale.includes('es') ? 'CIF' : 'CIF',
            address: locale.includes('zh') ? '地址' : locale.includes('es') ? 'Dirección' : 'Address',
            city: locale.includes('zh') ? '城市' : locale.includes('es') ? 'Ciudad' : 'City',
            postcode: locale.includes('zh') ? '邮编' : locale.includes('es') ? 'C.P.' : 'Postcode',
            phone: locale.includes('zh') ? '电话' : locale.includes('es') ? 'Teléfono' : 'Phone',
            actions: locale.includes('zh') ? '操作' : locale.includes('es') ? 'Acciones' : 'Actions'
        };

        if (!customers || customers.length === 0) {
            listDiv.innerHTML = `
                <div class="text-center py-8 text-gray-500">
                    ${locale.includes('zh') ? '暂无客户，请添加新客户' : locale.includes('es') ? 'Sin clientes, añade uno nuevo' : 'No customers, add a new one'}
                </div>
            `;
            return;
        }

        // 🔥 表格形式显示
        listDiv.innerHTML = `
            <div class="overflow-x-auto">
                <table class="min-w-full text-sm">
                    <thead class="bg-gray-100">
                        <tr>
                            <th class="px-2 py-2 text-left font-medium text-gray-600 w-12">${headers.number}</th>
                            <th class="px-2 py-2 text-left font-medium text-gray-600">${headers.company}</th>
                            <th class="px-2 py-2 text-left font-medium text-gray-600">${headers.cif}</th>
                            <th class="px-2 py-2 text-left font-medium text-gray-600 hidden sm:table-cell">${headers.address}</th>
                            <th class="px-2 py-2 text-left font-medium text-gray-600 hidden md:table-cell">${headers.city}</th>
                            <th class="px-2 py-2 text-left font-medium text-gray-600 hidden lg:table-cell">${headers.postcode}</th>
                            <th class="px-2 py-2 text-left font-medium text-gray-600">${headers.phone}</th>
                            <th class="px-2 py-2 text-center font-medium text-gray-600 w-20">${headers.actions}</th>
                        </tr>
                    </thead>
                    <tbody class="divide-y divide-gray-200">
                        ${customers.map(customer => `
                            <tr class="hover:bg-gray-50 transition-colors"
                                data-customer-id="${customer.id}">
                                <td class="px-2 py-2">
                                    ${customer.customer_number
                                        ? `<span class="inline-flex items-center justify-center min-w-[24px] h-6 px-1.5 bg-blue-600 text-white text-xs font-bold rounded-full">${customer.customer_number}</span>`
                                        : '<span class="text-gray-400">—</span>'}
                                </td>
                                <td class="px-2 py-2 font-medium text-gray-900">${this.escapeHtml(customer.company || customer.customer_name || '')}</td>
                                <td class="px-2 py-2 text-gray-600">${this.escapeHtml(customer.cif || '')}</td>
                                <td class="px-2 py-2 text-gray-600 hidden sm:table-cell text-xs">${this.escapeHtml(customer.address || '')}</td>
                                <td class="px-2 py-2 text-gray-600 hidden md:table-cell">${this.escapeHtml(customer.city || '')}</td>
                                <td class="px-2 py-2 text-gray-600 hidden lg:table-cell">${this.escapeHtml(customer.postcode || '')}</td>
                                <td class="px-2 py-2 text-gray-600">${this.escapeHtml(customer.phone || '')}</td>
                                <td class="px-2 py-2 text-center">
                                    <div class="flex justify-center space-x-1">
                                        <button onclick="pos.editCustomerManagement(${customer.id})"
                                                class="text-blue-600 hover:text-blue-800 p-1 rounded hover:bg-blue-50 transition-all"
                                                title="${locale.includes('zh') ? '编辑' : locale.includes('es') ? 'Editar' : 'Edit'}">
                                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/>
                                            </svg>
                                        </button>
                                        <button onclick="pos.deleteCustomerManagement(${customer.id}, '${this.escapeHtml(customer.company || customer.customer_name || '')}')"
                                                class="text-red-600 hover:text-red-800 p-1 rounded hover:bg-red-50 transition-all"
                                                title="${locale.includes('zh') ? '删除' : locale.includes('es') ? 'Eliminar' : 'Delete'}">
                                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/>
                                            </svg>
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        `).join('')}
                    </tbody>
                </table>
            </div>
            <div class="text-xs text-gray-400 mt-2 text-right">${customers.length} ${locale.includes('zh') ? '个客户' : locale.includes('es') ? 'clientes' : 'customers'}</div>
        `;
    }

    /**
     * 🔥 过滤客户列表
     */
    filterCustomersList(query) {
        if (!this.customersManagementList) return;

        // 如果没有传入query，从搜索框获取
        if (query === undefined) {
            const searchInputNew = document.getElementById('contacts-customer-search');
            const searchInputOld = document.getElementById('customer-management-search');
            const searchInput = searchInputNew || searchInputOld;
            query = searchInput ? searchInput.value : '';
        }

        const searchQuery = String(query).toLowerCase().trim();

        if (!searchQuery) {
            this.renderCustomersManagementList(this.customersManagementList);
            return;
        }

        const filtered = this.customersManagementList.filter(customer => {
            const customerNumber = String(customer.customer_number || '');
            const company = (customer.company || '').toLowerCase();
            const cif = (customer.cif || '').toLowerCase();
            const phone = (customer.phone || '').toLowerCase();

            return customerNumber === searchQuery ||
                   company.includes(searchQuery) ||
                   cif.includes(searchQuery) ||
                   phone.includes(searchQuery);
        });

        this.renderCustomersManagementList(filtered);
    }

    /**
     * 🔥 打开添加客户弹窗
     */
    openAddCustomerModal() {
        const modal = document.getElementById('customer-edit-modal');
        const title = document.getElementById('customer-modal-title');
        const form = document.getElementById('customer-edit-form');
        const locale = document.documentElement.lang || 'en';

        if (!modal) return;

        // Reset form
        if (form) form.reset();
        document.getElementById('customer-edit-id').value = '';

        // Set title
        if (title) {
            title.textContent = locale.includes('zh') ? '添加客户' :
                               locale.includes('es') ? 'Agregar Cliente' : 'Add Customer';
        }

        modal.classList.remove('hidden');
    }

    /**
     * 🔥 编辑客户
     */
    async editCustomerManagement(customerId) {
        const modal = document.getElementById('customer-edit-modal');
        const title = document.getElementById('customer-modal-title');
        const locale = document.documentElement.lang || 'en';

        if (!modal) return;

        // Set title
        if (title) {
            title.textContent = locale.includes('zh') ? '编辑客户' :
                               locale.includes('es') ? 'Editar Cliente' : 'Edit Customer';
        }

        try {
            // Fetch customer data
            const response = await this.ajaxRequest({
                pos_action: 'get_customer_data',
                customer_id: customerId
            });

            if (response.success && response.data) {
                const customer = response.data;

                // Fill form
                document.getElementById('customer-edit-id').value = customerId;
                document.getElementById('customer-edit-number').value = customer.customer_number || '';
                document.getElementById('customer-edit-company').value = customer.company || '';
                document.getElementById('customer-edit-cif').value = customer.cif || '';
                document.getElementById('customer-edit-address').value = customer.address || '';
                document.getElementById('customer-edit-city').value = customer.city || '';
                document.getElementById('customer-edit-postcode').value = customer.postcode || '';
                document.getElementById('customer-edit-phone').value = customer.phone || '';
                document.getElementById('customer-edit-email').value = customer.email || '';

                modal.classList.remove('hidden');
            } else {
                throw new Error('Failed to load customer data');
            }
        } catch (error) {
            console.error('[Customers] Edit failed:', error);
            this.showToast(
                locale.includes('zh') ? '加载客户信息失败' :
                locale.includes('es') ? 'Error al cargar datos' : 'Failed to load customer data',
                'error'
            );
        }
    }

    /**
     * 🔥 关闭客户编辑弹窗
     */
    closeCustomerEditModal() {
        const modal = document.getElementById('customer-edit-modal');
        if (modal) {
            modal.classList.add('hidden');
        }
    }

    /**
     * 🔥 保存客户
     */
    async saveCustomerManagement(event) {
        event.preventDefault();

        const locale = document.documentElement.lang || 'en';
        const customerId = document.getElementById('customer-edit-id').value;
        const isEdit = !!customerId;

        const formData = {
            pos_action: isEdit ? 'update_invoice_customer' : 'add_invoice_customer',
            customer_number: document.getElementById('customer-edit-number').value || '',
            company: document.getElementById('customer-edit-company').value || '',
            cif: document.getElementById('customer-edit-cif').value || '',
            address: document.getElementById('customer-edit-address').value || '',
            city: document.getElementById('customer-edit-city').value || '',
            postcode: document.getElementById('customer-edit-postcode').value || '',
            phone: document.getElementById('customer-edit-phone').value || '',
            email: document.getElementById('customer-edit-email').value || ''
        };

        if (isEdit) {
            formData.customer_id = customerId;
        }

        // Validate required fields
        if (!formData.company || !formData.cif) {
            this.showToast(
                locale.includes('zh') ? '请填写客户名称和税号' :
                locale.includes('es') ? 'Complete nombre y CIF' : 'Company name and CIF are required',
                'error'
            );
            return;
        }

        try {
            const response = await this.ajaxRequest(formData);

            if (response.success) {
                this.showToast(
                    isEdit ?
                        (locale.includes('zh') ? '客户更新成功' : locale.includes('es') ? 'Cliente actualizado' : 'Customer updated') :
                        (locale.includes('zh') ? '客户添加成功' : locale.includes('es') ? 'Cliente agregado' : 'Customer added'),
                    'success'
                );
                this.closeCustomerEditModal();
                this.loadCustomersManagement();
            } else {
                throw new Error(response.data?.message || 'Save failed');
            }
        } catch (error) {
            console.error('[Customers] Save failed:', error);
            this.showToast(
                error.message || (locale.includes('zh') ? '保存失败' : locale.includes('es') ? 'Error al guardar' : 'Failed to save'),
                'error'
            );
        }
    }

    /**
     * 🔥 删除客户
     */
    async deleteCustomerManagement(customerId, customerName) {
        const locale = document.documentElement.lang || 'en';

        const confirmMsg = locale.includes('zh') ? `确定要删除客户 "${customerName}" 吗？` :
                          locale.includes('es') ? `¿Eliminar cliente "${customerName}"?` :
                          `Delete customer "${customerName}"?`;

        if (!confirm(confirmMsg)) return;

        try {
            const response = await this.ajaxRequest({
                pos_action: 'delete_invoice_customer',
                customer_id: customerId
            });

            if (response.success) {
                this.showToast(
                    locale.includes('zh') ? '客户删除成功' :
                    locale.includes('es') ? 'Cliente eliminado' : 'Customer deleted',
                    'success'
                );
                this.loadCustomersManagement();
            } else {
                throw new Error(response.data?.message || 'Delete failed');
            }
        } catch (error) {
            console.error('[Customers] Delete failed:', error);
            this.showToast(
                locale.includes('zh') ? '删除失败' :
                locale.includes('es') ? 'Error al eliminar' : 'Failed to delete',
                'error'
            );
        }
    }

    /**
     * 加载编辑产品供应商列表（用于下拉选择）
     */
    loadEditProductSuppliers() {
        this.ajaxRequest({ pos_action: 'get_suppliers' })
        .then(data => {
            if (data.success && data.data.suppliers) {
                this.editProductsSuppliers = data.data.suppliers;
                const datalist = document.getElementById('edit-product-supplier-datalist');
                if (datalist) {
                    datalist.innerHTML = this.editProductsSuppliers.map(s =>
                        `<option value="${this.escapeHtml(s.name)}">`
                    ).join('');
                }
            }
        })
        .catch(error => console.error('[EditProducts] 加载供应商失败:', error));
    }

    /**
     * 加载编辑产品列表（指定页码）
     */
    loadEditProductsPage(page) {
        if (page < 1 || page > this.editProductsTotalPages) return;
        this.editProductsCurrentPage = page;
        this.loadEditProductsList();
    }

    /**
     * 搜索防抖
     */
    debounceEditProductSearch(searchTerm) {
        clearTimeout(this.editProductsSearchTimeout);
        this.editProductsSearchTimeout = setTimeout(() => {
            this.editProductsSearchTerm = searchTerm.trim();
            this.editProductsCurrentPage = 1;
            this.loadEditProductsList();
        }, 300);
    }

    /**
     * Enter 键立即搜索（跳过防抖）
     */
    immediateEditProductSearch(searchTerm) {
        clearTimeout(this.editProductsSearchTimeout);
        this.editProductsSearchTerm = searchTerm.trim();
        this.editProductsCurrentPage = 1;
        this.loadEditProductsList();
    }

    /**
     * 按日期筛选产品
     */
    filterEditProductsByDate() {
        this.editProductsCurrentPage = 1;
        const dateInput = document.getElementById('edit-products-date-filter');
        const clearBtn = document.getElementById('edit-products-date-clear');
        if (clearBtn) clearBtn.classList.toggle('hidden', !dateInput.value);
        this.loadEditProductsList();
    }

    /**
     * 清除日期筛选
     */
    clearEditProductsDateFilter() {
        const dateInput = document.getElementById('edit-products-date-filter');
        if (dateInput) dateInput.value = '';
        document.getElementById('edit-products-date-clear')?.classList.add('hidden');
        this.editProductsCurrentPage = 1;
        this.loadEditProductsList();
    }

    /**
     * 加载编辑产品列表
     */
    loadEditProductsList() {
        const tbody = document.getElementById('edit-products-table-body');
        const locale = document.documentElement.lang || 'en';

        if (!tbody) return;

        // 显示加载状态
        const loadingText = locale.includes('zh') ? '加载中...' :
                           locale.includes('es') ? 'Cargando...' : 'Loading...';
        tbody.innerHTML = `<tr><td colspan="10" class="px-4 py-8 text-center text-gray-500">${loadingText}</td></tr>`;

        // 构建请求参数
        const params = {
            pos_action: 'get_products_for_edit',
            page: this.editProductsCurrentPage,
            per_page: this.editProductsPerPage
        };

        if (this.editProductsSearchTerm) {
            params.search = this.editProductsSearchTerm;
        }

        const dateFilter = document.getElementById('edit-products-date-filter')?.value;
        if (dateFilter) {
            params.date_filter = dateFilter;
        }

        this.ajaxRequest(params)
        .then(data => {
            if (data.success) {
                this.editProductsData = data.data.products || [];
                this.editedProductIds = (data.data.edited_products || []).map(Number);
                console.log('[EditProducts] Server returned edited_products:', this.editedProductIds);
                this.editProductsTotalPages = data.data.total_pages || 1;
                this.renderEditProductsTable();
                this.updateEditProductsPagination(data.data);
                this.clearProductSelection();
            } else {
                const errorText = locale.includes('zh') ? '加载失败' :
                                 locale.includes('es') ? 'Error al cargar' : 'Failed to load';
                tbody.innerHTML = `<tr><td colspan="10" class="px-4 py-8 text-center text-red-500">${errorText}</td></tr>`;
            }
        })
        .catch(error => {
            console.error('[EditProducts] Error loading products:', error);
            const errorText = locale.includes('zh') ? '加载失败' :
                             locale.includes('es') ? 'Error al cargar' : 'Failed to load';
            tbody.innerHTML = `<tr><td colspan="10" class="px-4 py-8 text-center text-red-500">${errorText}</td></tr>`;
        });
    }

    /**
     * 渲染编辑产品表格
     */
    renderEditProductsTable() {
        const tbody = document.getElementById('edit-products-table-body');
        const locale = document.documentElement.lang || 'en';

        if (!tbody) return;

        if (!this.editProductsData || this.editProductsData.length === 0) {
            const emptyText = locale.includes('zh') ? '暂无产品' :
                             locale.includes('es') ? 'No hay productos' : 'No products found';
            tbody.innerHTML = `<tr><td colspan="11" class="px-4 py-8 text-center text-gray-500">${emptyText}</td></tr>`;
            return;
        }

        const saveText = locale.includes('zh') ? '保存' :
                        locale.includes('es') ? 'Guardar' : 'Save';
        const savedText = locale.includes('zh') ? '已保存' :
                         locale.includes('es') ? 'Guardado' : 'Saved';
        const deleteText = locale.includes('zh') ? '删除' :
                          locale.includes('es') ? 'Eliminar' : 'Delete';
        const namePlaceholder = locale.includes('zh') ? '产品名称' :
                               locale.includes('es') ? 'Nombre' : 'Name';
        const supplierPlaceholder = locale.includes('zh') ? '供应商' :
                                   locale.includes('es') ? 'Proveedor' : 'Supplier';

        // 读取已保存产品列表（从服务器端 user_meta）
        const savedProducts = this.editedProductIds || [];

        tbody.innerHTML = this.editProductsData.map(product => {
            const isSaved = savedProducts.includes(product.id);
            const btnText = isSaved ? savedText : saveText;
            const btnClass = isSaved
                ? 'w-full px-2 py-1 bg-gray-400 text-white text-xs rounded cursor-default'
                : 'w-full px-2 py-1 bg-blue-600 hover:bg-blue-700 text-white text-xs rounded transition-colors cursor-pointer';
            const btnDisabled = isSaved ? 'disabled' : '';
            return `
            <tr id="edit-product-row-${product.id}" class="hover:bg-gray-50">
                <td class="px-3 py-2 text-center">
                    <input type="checkbox"
                           class="edit-product-checkbox w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500 cursor-pointer"
                           data-product-id="${product.id}"
                           data-product-name="${this.escapeHtml(product.name || '')}"
                           onchange="pos.toggleProductSelect()">
                </td>
                <td class="px-3 py-2">
                    <input type="text"
                           id="edit-sku-${product.id}"
                           value="${this.escapeHtml(product.sku || '')}"
                           class="w-full px-2 py-1 text-sm border border-gray-300 rounded focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                           placeholder="SKU"
                           oninput="pos.markEditProductDirty(${product.id})">
                </td>
                <td class="px-3 py-2">
                    <input type="text"
                           id="edit-name-${product.id}"
                           value="${this.escapeHtml(product.name || '')}"
                           class="w-full px-2 py-1 text-sm border border-gray-300 rounded focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                           placeholder="${namePlaceholder}"
                           oninput="pos.markEditProductDirty(${product.id})">
                </td>
                <td class="px-3 py-2">
                    <input type="text"
                           id="edit-chinese-name-${product.id}"
                           value="${this.escapeHtml(product.chinese_name || '')}"
                           class="w-full px-2 py-1 text-sm border border-gray-300 rounded focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                           placeholder="中文名称"
                           oninput="pos.markEditProductDirty(${product.id})">
                </td>
                <td class="px-3 py-2">
                    <input type="number"
                           id="edit-price-${product.id}"
                           value="${product.regular_price || product.price || ''}"
                           step="0.01"
                           min="0"
                           class="w-full px-2 py-1 text-sm border border-gray-300 rounded focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                           placeholder="0.00"
                           oninput="pos.markEditProductDirty(${product.id})">
                </td>
                <td class="px-3 py-2">
                    <input type="number"
                           id="edit-cost-price-${product.id}"
                           value="${product.cost_price || ''}"
                           step="0.01"
                           min="0"
                           class="w-full px-2 py-1 text-sm border border-gray-300 rounded focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                           placeholder="0.00"
                           oninput="pos.markEditProductDirty(${product.id})">
                </td>
                <td class="px-3 py-2">
                    <input type="text"
                           id="edit-supplier-${product.id}"
                           value="${this.escapeHtml(product.supplier || '')}"
                           list="edit-product-supplier-datalist"
                           class="w-full px-2 py-1 text-sm border border-gray-300 rounded focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                           placeholder="${supplierPlaceholder}"
                           oninput="pos.markEditProductDirty(${product.id})">
                </td>
                <td class="px-3 py-2">
                    <input type="number"
                           id="edit-stock-${product.id}"
                           value="${product.stock !== null && product.stock !== undefined ? product.stock : ''}"
                           step="1"
                           min="0"
                           class="w-full px-2 py-1 text-sm border border-gray-300 rounded focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                           placeholder="0"
                           oninput="pos.markEditProductDirty(${product.id})">
                </td>
                <td class="px-3 py-2">
                    <input type="text"
                           id="edit-product-number-${product.id}"
                           value="${this.escapeHtml(product.product_number || '')}"
                           class="w-full px-2 py-1 text-sm border border-gray-300 rounded focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                           placeholder="01"
                           oninput="pos.markEditProductDirty(${product.id})">
                </td>
                <td class="px-3 py-2 text-center">
                    <div class="flex flex-col gap-1 items-center">
                        <button onclick="pos.saveEditProduct(${product.id})"
                                id="edit-save-btn-${product.id}"
                                class="${btnClass}"
                                ${btnDisabled}>
                            ${btnText}
                        </button>
                        <button onclick="pos.deleteProduct(${product.id}, '${this.escapeHtml(product.name).replace(/'/g, "\\'")}');"
                                class="w-full px-2 py-1 bg-red-500 hover:bg-red-600 text-white text-xs rounded transition-colors">
                            ${deleteText}
                        </button>
                    </div>
                </td>
            </tr>
        `}).join('');
    }

    /**
     * 更新分页控件状态
     */
    updateEditProductsPagination(data) {
        const prevBtn = document.getElementById('edit-products-prev-btn');
        const nextBtn = document.getElementById('edit-products-next-btn');
        const pageIndicator = document.getElementById('edit-products-page-indicator');
        const paginationInfo = document.getElementById('edit-products-pagination-info');
        const locale = document.documentElement.lang || 'en';

        // 更新按钮状态
        if (prevBtn) prevBtn.disabled = this.editProductsCurrentPage <= 1;
        if (nextBtn) nextBtn.disabled = this.editProductsCurrentPage >= this.editProductsTotalPages;

        // 更新页码显示
        if (pageIndicator) {
            pageIndicator.textContent = `${this.editProductsCurrentPage} / ${this.editProductsTotalPages}`;
        }

        // 更新分页信息
        if (paginationInfo && data) {
            const total = data.total || 0;
            const showing = data.products ? data.products.length : 0;
            const start = showing > 0 ? (this.editProductsCurrentPage - 1) * this.editProductsPerPage + 1 : 0;
            const end = start + showing - 1;

            if (locale.includes('zh')) {
                paginationInfo.textContent = total > 0 ? `显示 ${start}-${end}，共 ${total} 个产品` : '暂无产品';
            } else if (locale.includes('es')) {
                paginationInfo.textContent = total > 0 ? `Mostrando ${start}-${end} de ${total} productos` : 'Sin productos';
            } else {
                paginationInfo.textContent = total > 0 ? `Showing ${start}-${end} of ${total} products` : 'No products';
            }
        }
    }

    /**
     * 标记产品已编辑（将保存按钮从"已保存"切换为"保存"）
     */
    markEditProductDirty(productId) {
        const locale = document.documentElement.lang || 'en';
        const saveBtn = document.getElementById(`edit-save-btn-${productId}`);
        if (saveBtn && saveBtn.disabled) {
            const saveText = locale.includes('zh') ? '保存' :
                            locale.includes('es') ? 'Guardar' : 'Save';
            saveBtn.textContent = saveText;
            saveBtn.disabled = false;
            saveBtn.classList.remove('bg-gray-400', 'cursor-default', 'bg-green-600');
            saveBtn.classList.add('bg-blue-600', 'hover:bg-blue-700', 'cursor-pointer');
        }
    }

    /**
     * 保存单个产品编辑
     */
    async saveEditProduct(productId) {
        const locale = document.documentElement.lang || 'en';
        const saveBtn = document.getElementById(`edit-save-btn-${productId}`);

        // 获取编辑后的值
        const sku = document.getElementById(`edit-sku-${productId}`)?.value.trim() || '';
        const name = document.getElementById(`edit-name-${productId}`)?.value.trim() || '';
        const chineseName = document.getElementById(`edit-chinese-name-${productId}`)?.value.trim() || '';
        const regularPrice = document.getElementById(`edit-price-${productId}`)?.value || '';
        const costPrice = document.getElementById(`edit-cost-price-${productId}`)?.value || '';
        const supplier = document.getElementById(`edit-supplier-${productId}`)?.value.trim() || '';
        const stock = document.getElementById(`edit-stock-${productId}`)?.value || '';
        const productNumber = document.getElementById(`edit-product-number-${productId}`)?.value.trim() || '';

        // 验证必填字段
        if (!name) {
            const msg = locale.includes('zh') ? '产品名称不能为空' :
                       locale.includes('es') ? 'El nombre es requerido' : 'Product name is required';
            this.showToast(msg, 'error');
            return;
        }

        // 显示保存中状态
        const savingText = locale.includes('zh') ? '...' :
                          locale.includes('es') ? '...' : '...';
        const originalText = saveBtn ? saveBtn.textContent : '';
        if (saveBtn) {
            saveBtn.disabled = true;
            saveBtn.textContent = savingText;
        }

        try {
            const response = await this.ajaxRequest({
                pos_action: 'update_product',
                product_id: productId,
                name: name,
                sku: sku,
                regular_price: regularPrice,
                cost_price: costPrice,
                product_supplier: supplier,
                stock: stock !== '' ? parseInt(stock) : -1,
                product_number: productNumber,
                chinese_name: chineseName
            });

            if (response.success) {
                const successMsg = locale.includes('zh') ? '产品已更新' :
                                  locale.includes('es') ? 'Producto actualizado' : 'Product updated';
                this.showToast(successMsg, 'success');

                // 后台静默刷新产品缓存，确保离线数据同步
                if (window.ProductCacheManager && typeof window.ProductCacheManager.cacheAllProductsPaginated === 'function') {
                    // 静默刷新缓存（forceRefresh=true, silent=true）
                    window.ProductCacheManager.cacheAllProductsPaginated(true, true)
                        .then(() => {
                            console.log('[EditProducts] 产品缓存已静默同步');
                        })
                        .catch(err => {
                            console.warn('[EditProducts] 缓存同步失败:', err);
                        });
                }

                // 更新内存中的已编辑列表（服务器端已通过 user_meta 保存）
                if (!this.editedProductIds.includes(productId)) {
                    this.editedProductIds.push(productId);
                }

                // 显示已保存状态（保持禁用直到用户再次编辑）
                if (saveBtn) {
                    const savedLabel = locale.includes('zh') ? '已保存' :
                                      locale.includes('es') ? 'Guardado' : 'Saved';
                    saveBtn.textContent = '✓';
                    saveBtn.classList.remove('bg-blue-600', 'hover:bg-blue-700', 'cursor-pointer');
                    saveBtn.classList.add('bg-green-600');
                    setTimeout(() => {
                        saveBtn.textContent = savedLabel;
                        saveBtn.classList.remove('bg-green-600');
                        saveBtn.classList.add('bg-gray-400', 'cursor-default');
                        saveBtn.disabled = true;
                    }, 1000);
                }
            } else {
                throw new Error(response.data?.message || 'Update failed');
            }
        } catch (error) {
            console.error('[EditProducts] Save error:', error);
            const errorMsg = locale.includes('zh') ? '保存失败' :
                            locale.includes('es') ? 'Error al guardar' : 'Save failed';
            this.showToast(errorMsg + ': ' + (error.message || ''), 'error');

            // 恢复按钮为可保存状态
            if (saveBtn) {
                const saveText = locale.includes('zh') ? '保存' :
                                locale.includes('es') ? 'Guardar' : 'Save';
                saveBtn.textContent = saveText;
                saveBtn.disabled = false;
                saveBtn.classList.remove('bg-gray-400', 'cursor-default');
                saveBtn.classList.add('bg-blue-600', 'hover:bg-blue-700', 'cursor-pointer');
            }
        }
    }

    /**
     * 删除产品
     */
    showConfirmDialog(message, title = '') {
        return new Promise((resolve) => {
            const locale = document.documentElement.lang || 'en';
            const confirmText = locale.includes('zh') ? '确认删除' : locale.includes('es') ? 'Confirmar' : 'Confirm';
            const cancelText = locale.includes('zh') ? '取消' : locale.includes('es') ? 'Cancelar' : 'Cancel';

            const overlay = document.createElement('div');
            overlay.className = 'fixed inset-0 z-[10000] flex items-center justify-center';
            overlay.innerHTML = `
                <div class="absolute inset-0 bg-black/50" id="confirm-backdrop"></div>
                <div class="relative bg-white rounded-xl shadow-2xl max-w-md w-full mx-4 transform scale-95 opacity-0 transition-all duration-200" id="confirm-box">
                    <div class="p-6">
                        <div class="flex items-center gap-3 mb-4">
                            <div class="w-10 h-10 rounded-full bg-red-100 flex items-center justify-center flex-shrink-0">
                                <svg class="w-5 h-5 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L4.082 16.5c-.77.833.192 2.5 1.732 2.5z"/>
                                </svg>
                            </div>
                            <h3 class="text-lg font-semibold text-gray-900">${title || (locale.includes('zh') ? '确认操作' : locale.includes('es') ? 'Confirmar acción' : 'Confirm Action')}</h3>
                        </div>
                        <p class="text-gray-600 text-sm leading-relaxed mb-6">${message}</p>
                        <div class="flex gap-3 justify-end">
                            <button id="confirm-cancel-btn" class="px-5 py-2.5 text-sm font-medium text-gray-700 bg-gray-100 hover:bg-gray-200 rounded-lg transition-colors">${cancelText}</button>
                            <button id="confirm-ok-btn" class="px-5 py-2.5 text-sm font-medium text-white bg-red-600 hover:bg-red-700 rounded-lg transition-colors">${confirmText}</button>
                        </div>
                    </div>
                </div>
            `;
            document.body.appendChild(overlay);

            requestAnimationFrame(() => {
                const box = document.getElementById('confirm-box');
                if (box) { box.classList.remove('scale-95', 'opacity-0'); box.classList.add('scale-100', 'opacity-100'); }
            });

            const close = (result) => {
                const box = document.getElementById('confirm-box');
                if (box) { box.classList.remove('scale-100', 'opacity-100'); box.classList.add('scale-95', 'opacity-0'); }
                setTimeout(() => { overlay.remove(); resolve(result); }, 150);
            };

            document.getElementById('confirm-ok-btn').addEventListener('click', () => close(true));
            document.getElementById('confirm-cancel-btn').addEventListener('click', () => close(false));
            document.getElementById('confirm-backdrop').addEventListener('click', () => close(false));
        });
    }

    async deleteProduct(productId, productName) {
        const locale = document.documentElement.lang || 'en';

        // 确认删除 - 自定义弹窗
        const confirmMsg = locale.includes('zh')
            ? `确定要删除产品 "${productName}" 吗？此操作不可撤销。`
            : locale.includes('es')
            ? `¿Seguro que desea eliminar el producto "${productName}"? Esta acción no se puede deshacer.`
            : `Are you sure you want to delete product "${productName}"? This action cannot be undone.`;

        const titleText = locale.includes('zh') ? '删除产品' : locale.includes('es') ? 'Eliminar producto' : 'Delete Product';
        const confirmed = await this.showConfirmDialog(confirmMsg, titleText);
        if (!confirmed) {
            return;
        }

        try {
            const response = await this.ajaxRequest({
                pos_action: 'delete_product',
                product_id: productId
            });

            if (response.success) {
                const successMsg = locale.includes('zh') ? '产品已删除' :
                                  locale.includes('es') ? 'Producto eliminado' : 'Product deleted';
                this.showToast(successMsg, 'success');

                // 从表格中移除该行
                const row = document.getElementById(`edit-product-row-${productId}`);
                if (row) {
                    row.remove();
                }

                // 刷新产品列表
                this.loadEditProductsList();

                // 静默刷新产品缓存
                if (window.ProductCacheManager && typeof window.ProductCacheManager.cacheAllProductsPaginated === 'function') {
                    window.ProductCacheManager.cacheAllProductsPaginated(true, true)
                        .catch(err => console.warn('[DeleteProduct] 缓存同步失败:', err));
                }
            } else {
                throw new Error(response.data?.message || 'Delete failed');
            }
        } catch (error) {
            console.error('[DeleteProduct] Error:', error);
            const errorMsg = locale.includes('zh') ? '删除失败' :
                            locale.includes('es') ? 'Error al eliminar' : 'Delete failed';
            this.showToast(errorMsg + ': ' + (error.message || ''), 'error');
        }
    }

    /**
     * 全选/取消全选产品
     */
    toggleSelectAllProducts(checked) {
        document.querySelectorAll('.edit-product-checkbox').forEach(cb => {
            cb.checked = checked;
        });
        this.updateBulkDeleteBar();
    }

    /**
     * 单个产品选中状态变化
     */
    toggleProductSelect() {
        const allCheckboxes = document.querySelectorAll('.edit-product-checkbox');
        const checkedCount = document.querySelectorAll('.edit-product-checkbox:checked').length;
        const selectAll = document.getElementById('edit-products-select-all');
        if (selectAll) {
            selectAll.checked = checkedCount === allCheckboxes.length && allCheckboxes.length > 0;
        }
        this.updateBulkDeleteBar();
    }

    /**
     * 更新批量删除栏显示
     */
    updateBulkDeleteBar() {
        const checkedCount = document.querySelectorAll('.edit-product-checkbox:checked').length;
        const bar = document.getElementById('edit-products-bulk-bar');
        const countSpan = document.getElementById('edit-products-selected-count');
        const locale = document.documentElement.lang || 'en';

        if (checkedCount > 0) {
            bar.classList.remove('hidden');
            if (locale.includes('zh')) {
                countSpan.textContent = `已选择 ${checkedCount} 个产品`;
            } else if (locale.includes('es')) {
                countSpan.textContent = `${checkedCount} productos seleccionados`;
            } else {
                countSpan.textContent = `${checkedCount} products selected`;
            }
        } else {
            bar.classList.add('hidden');
        }
    }

    /**
     * 清除所有选中状态
     */
    clearProductSelection() {
        document.querySelectorAll('.edit-product-checkbox').forEach(cb => {
            cb.checked = false;
        });
        const selectAll = document.getElementById('edit-products-select-all');
        if (selectAll) selectAll.checked = false;
        const bar = document.getElementById('edit-products-bulk-bar');
        if (bar) bar.classList.add('hidden');
    }

    /**
     * 批量删除选中的产品
     */
    async bulkDeleteProducts() {
        const locale = document.documentElement.lang || 'en';
        const checked = document.querySelectorAll('.edit-product-checkbox:checked');
        const ids = Array.from(checked).map(cb => parseInt(cb.dataset.productId));

        if (ids.length === 0) return;

        const confirmMsg = locale.includes('zh')
            ? `确定要删除选中的 ${ids.length} 个产品吗？此操作不可撤销。`
            : locale.includes('es')
            ? `¿Seguro que desea eliminar ${ids.length} productos seleccionados? Esta acción no se puede deshacer.`
            : `Are you sure you want to delete ${ids.length} selected products? This action cannot be undone.`;

        const titleText = locale.includes('zh') ? '批量删除产品' : locale.includes('es') ? 'Eliminar productos' : 'Delete Products';
        const confirmed = await this.showConfirmDialog(confirmMsg, titleText);
        if (!confirmed) return;

        try {
            const response = await this.ajaxRequest({
                pos_action: 'bulk_delete_products',
                product_ids: JSON.stringify(ids)
            });

            if (response.success) {
                const r = response.data;
                let msg;
                if (locale.includes('zh')) {
                    msg = `已删除 ${r.deleted} 个产品`;
                    if (r.failed > 0) msg += `，${r.failed} 个失败`;
                } else if (locale.includes('es')) {
                    msg = `${r.deleted} productos eliminados`;
                    if (r.failed > 0) msg += `, ${r.failed} fallidos`;
                } else {
                    msg = `${r.deleted} products deleted`;
                    if (r.failed > 0) msg += `, ${r.failed} failed`;
                }
                this.showToast(msg, 'success');
                this.loadEditProductsList();

                if (window.ProductCacheManager && typeof window.ProductCacheManager.cacheAllProductsPaginated === 'function') {
                    window.ProductCacheManager.cacheAllProductsPaginated(true, true)
                        .catch(err => console.warn('[BulkDelete] Cache sync failed:', err));
                }
            } else {
                throw new Error(response.data?.message || 'Bulk delete failed');
            }
        } catch (error) {
            console.error('[BulkDelete] Error:', error);
            const errorMsg = locale.includes('zh') ? '批量删除失败' :
                            locale.includes('es') ? 'Error al eliminar' : 'Bulk delete failed';
            this.showToast(errorMsg + ': ' + (error.message || ''), 'error');
        }
    }

    /**
     * 下载产品明细PDF
     */
    async downloadProductDetailsPDF() {
        const locale = document.documentElement.lang || 'en';

        const loadingMsg = locale.includes('zh') ? '正在生成PDF...' :
                          locale.includes('es') ? 'Generando PDF...' : 'Generating PDF...';
        this.showToast(loadingMsg, 'info');

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'generate_product_details_pdf',
                    nonce: ruiyi_pos_ajax.nonce
                })
            });

            const data = await response.json();

            if (data.success && data.data.pdf_url) {
                const pdfFilename = data.data.filename || 'product-details.pdf';
                await this.downloadPdfToDir(data.data.pdf_url, pdfFilename);
            } else {
                throw new Error(data.data?.message || 'PDF generation failed');
            }
        } catch (error) {
            console.error('[ProductPDF] Error:', error);
            const errorMsg = locale.includes('zh') ? 'PDF生成失败' :
                            locale.includes('es') ? 'Error al generar PDF' : 'PDF generation failed';
            this.showToast(errorMsg + ': ' + (error.message || ''), 'error');
        }
    }

    /**
     * 导出产品Excel (XLSX)
     */
    async exportProductsExcel() {
        const locale = document.documentElement.lang || 'en';

        const loadingMsg = locale.includes('zh') ? '正在导出Excel...' :
                          locale.includes('es') ? 'Exportando Excel...' : 'Exporting Excel...';
        this.showToast(loadingMsg, 'info');

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'export_products_csv',
                    nonce: ruiyi_pos_ajax.nonce
                })
            });

            const data = await response.json();

            if (data.success && data.data.csv) {
                // Parse CSV string into a workbook using SheetJS
                const wb = XLSX.read(data.data.csv, { type: 'string' });
                const wbOut = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
                const blob = new Blob([wbOut], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                const today = new Date().toISOString().slice(0, 10);
                a.href = url;
                a.download = `productos-${today}.xlsx`;
                a.target = '_blank';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(url);

                const successMsg = locale.includes('zh') ? `已导出 ${data.data.count} 个产品` :
                                  locale.includes('es') ? `${data.data.count} productos exportados` :
                                  `${data.data.count} products exported`;
                this.showToast(successMsg, 'success');
            } else {
                throw new Error(data.data?.message || 'Export failed');
            }
        } catch (error) {
            console.error('[ExportProductsExcel] Error:', error);
            const errorMsg = locale.includes('zh') ? '导出失败' :
                            locale.includes('es') ? 'Error al exportar' : 'Export failed';
            this.showToast(errorMsg + ': ' + (error.message || ''), 'error');
        }
    }

    /**
     * 导入产品文件 (CSV / XLSX / XLS)
     */
    async importProductsFile(fileInput) {
        const locale = document.documentElement.lang || 'en';
        const file = fileInput.files[0];

        if (!file) return;

        // Reset file input so the same file can be re-selected
        fileInput.value = '';

        const loadingMsg = locale.includes('zh') ? '正在导入数据...' :
                          locale.includes('es') ? 'Importando datos...' : 'Importing data...';
        this.showToast(loadingMsg, 'info');

        try {
            let csvData;
            const ext = file.name.split('.').pop().toLowerCase();

            if (ext === 'xlsx' || ext === 'xls') {
                // Parse Excel file with SheetJS → convert to CSV string
                const arrayBuffer = await new Promise((resolve, reject) => {
                    const reader = new FileReader();
                    reader.onload = (e) => resolve(e.target.result);
                    reader.onerror = () => reject(new Error('File read error'));
                    reader.readAsArrayBuffer(file);
                });
                const wb = XLSX.read(arrayBuffer, { type: 'array' });
                const firstSheet = wb.Sheets[wb.SheetNames[0]];
                csvData = XLSX.utils.sheet_to_csv(firstSheet);
            } else {
                // Read as plain text CSV
                csvData = await new Promise((resolve, reject) => {
                    const reader = new FileReader();
                    reader.onload = (e) => resolve(e.target.result);
                    reader.onerror = () => reject(new Error('File read error'));
                    reader.readAsText(file, 'UTF-8');
                });
            }

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'import_products_csv',
                    nonce: ruiyi_pos_ajax.nonce,
                    csv_data: csvData
                })
            });

            const data = await response.json();

            if (data.success) {
                const d = data.data;
                let msg;
                if (locale.includes('zh')) {
                    msg = `导入完成: 新增 ${d.created} 个, 更新 ${d.updated} 个`;
                    if (d.errors && d.errors.length > 0) msg += `, 错误 ${d.errors.length} 个`;
                } else if (locale.includes('es')) {
                    msg = `Importación completada: ${d.created} creados, ${d.updated} actualizados`;
                    if (d.errors && d.errors.length > 0) msg += `, ${d.errors.length} errores`;
                } else {
                    msg = `Import complete: ${d.created} created, ${d.updated} updated`;
                    if (d.errors && d.errors.length > 0) msg += `, ${d.errors.length} errors`;
                }
                this.showToast(msg, (d.errors && d.errors.length > 0) ? 'warning' : 'success');

                if (d.errors && d.errors.length > 0) {
                    console.warn('[ImportProducts] Errors:', d.errors);
                }

                // Refresh the product list
                this.loadEditProductsList();

                // Sync product cache
                if (window.ProductCacheManager) {
                    window.ProductCacheManager.cacheAllProductsPaginated(true, true)
                        .catch(err => console.warn('[ImportProducts] Cache sync failed:', err));
                }
            } else {
                throw new Error(data.data?.message || 'Import failed');
            }
        } catch (error) {
            console.error('[ImportProducts] Error:', error);
            const errorMsg = locale.includes('zh') ? '导入失败' :
                            locale.includes('es') ? 'Error al importar' : 'Import failed';
            this.showToast(errorMsg + ': ' + (error.message || ''), 'error');
        }
    }

    // ========================================
    // 📥 导入数据 (IMPORT DATA) - Column Mapping
    // ========================================

    /**
     * 把上传的文件解析成 SheetJS workbook，自动处理：
     *   1. 真正的 xlsx/xls 二进制（SheetJS 原生）
     *   2. 普通 CSV（SheetJS 原生）
     *   3. HTML 表格伪装成 .xls（很多厂商/ERP 导出都是这种）——
     *      用 DOMParser 解析后用 XLSX.utils.table_to_sheet 转成正规 workbook
     *
     * 说明：批发商从自家老 ERP/进销存软件导出的"Excel"有相当比例实际是
     * 一段 <html><table>…</table></html>，只是后缀写成 .xls。直接交给
     * SheetJS 的 type:'array' 会报错。本方法先读前 2KB 检测文件类型再分流。
     */
    async parseFileToWorkbook(file) {
        // 先读一小段头部（2KB 足够判断）
        const headText = await new Promise((resolve, reject) => {
            const r = new FileReader();
            r.onload = e => resolve(e.target.result);
            r.onerror = () => reject(new Error('File read error'));
            r.readAsText(file.slice(0, 2048), 'UTF-8');
        });

        // 去掉 BOM 和前导空白后，检测是否为 HTML
        const headClean = headText.replace(/^\uFEFF/, '').replace(/^\s+/, '');
        const looksLikeHtml = /^(<!doctype\s+html|<html|<meta|<table|<\?xml|<body)/i.test(headClean);

        if (looksLikeHtml) {
            // 读整个文件为 UTF-8 文本
            const fullText = await new Promise((resolve, reject) => {
                const r = new FileReader();
                r.onload = e => resolve(e.target.result);
                r.onerror = () => reject(new Error('File read error'));
                r.readAsText(file, 'UTF-8');
            });

            // 用 DOMParser 解析，提取最大的 <table>
            const doc = new DOMParser().parseFromString(fullText, 'text/html');
            const tables = doc.querySelectorAll('table');
            if (!tables.length) {
                throw new Error('HTML 文件中未找到 <table> 表格');
            }

            // 如果有多个 table，选行数最多的那个（常见：厂商报表的主表）
            let targetTable = tables[0];
            let maxRows = targetTable.querySelectorAll('tr').length;
            for (let i = 1; i < tables.length; i++) {
                const n = tables[i].querySelectorAll('tr').length;
                if (n > maxRows) {
                    targetTable = tables[i];
                    maxRows = n;
                }
            }

            // SheetJS 提供的 table_to_sheet 会自动处理 rowspan/colspan
            const sheet = XLSX.utils.table_to_sheet(targetTable, { raw: false });
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, sheet, 'Sheet1');
            return wb;
        }

        // 二进制 Excel / CSV：交给 SheetJS 自动识别
        const arrayBuffer = await new Promise((resolve, reject) => {
            const r = new FileReader();
            r.onload = e => resolve(e.target.result);
            r.onerror = () => reject(new Error('File read error'));
            r.readAsArrayBuffer(file);
        });
        return XLSX.read(arrayBuffer, { type: 'array' });
    }

    /**
     * 处理导入文件选择 - 读取文件并显示预览
     */
    async handleImportFileSelect(fileInput) {
        const locale = document.documentElement.lang || 'en';
        const file = fileInput.files[0];
        if (!file) return;

        try {
            // 统一用 parseFileToWorkbook 处理各种格式（xlsx/xls/csv/HTML 伪装 .xls）
            const wb = await this.parseFileToWorkbook(file);
            const firstSheet = wb.Sheets[wb.SheetNames[0]];
            const rows = XLSX.utils.sheet_to_json(firstSheet, { header: 1, defval: '' });

            if (!rows || rows.length < 2) {
                const msg = locale.includes('zh') ? '文件为空或只有表头' :
                           locale.includes('es') ? 'El archivo está vacío o solo tiene encabezado' : 'File is empty or has only headers';
                this.showToast(msg, 'error');
                return;
            }

            const headers = rows[0].map(h => (h || '').toString().trim());
            const dataRows = rows.slice(1).filter(r => r.some(cell => cell !== null && cell !== undefined && cell.toString().trim() !== ''));

            this._importData = {
                fileName: file.name,
                headers: headers,
                rows: dataRows,
                mapping: new Array(headers.length).fill('')
            };

            this.renderImportPreview();
        } catch (error) {
            console.error('[ImportData] File parse error:', error);
            const msg = locale.includes('zh') ? '文件解析失败' :
                       locale.includes('es') ? 'Error al analizar archivo' : 'File parse error';
            this.showToast(msg + ': ' + (error.message || ''), 'error');
        }
    }

    /**
     * 渲染导入预览 - 显示表格和列映射选择
     */
    renderImportPreview() {
        const locale = document.documentElement.lang || 'en';
        const d = this._importData;
        if (!d) return;

        // Hide upload, show preview
        document.getElementById('import-data-upload-area').classList.add('hidden');
        document.getElementById('import-data-preview-area').classList.remove('hidden');

        // File info
        document.getElementById('import-data-file-name').textContent = d.fileName;
        const rowCountText = locale.includes('zh') ? `${d.rows.length} 行数据` :
                            locale.includes('es') ? `${d.rows.length} filas` : `${d.rows.length} rows`;
        document.getElementById('import-data-row-count').textContent = `(${rowCountText})`;

        // Field options
        const fields = [
            { value: '', label: locale.includes('zh') ? '(不导入)' : locale.includes('es') ? '(No importar)' : '(Skip)' },
            { value: 'name', label: locale.includes('zh') ? '产品名称' : locale.includes('es') ? 'Nombre' : 'Product Name' },
            { value: 'regular_price', label: locale.includes('zh') ? '现价' : locale.includes('es') ? 'Precio' : 'Price' },
            { value: 'cost_price', label: locale.includes('zh') ? '进货价' : locale.includes('es') ? 'Coste' : 'Cost Price' },
            { value: 'supplier', label: locale.includes('zh') ? '供应商' : locale.includes('es') ? 'Proveedor' : 'Supplier' },
            { value: 'category', label: locale.includes('zh') ? '产品分类' : locale.includes('es') ? 'Categoría' : 'Category' },
            { value: 'stock_quantity', label: locale.includes('zh') ? '产品库存' : locale.includes('es') ? 'Stock' : 'Stock' },
            { value: 'sku', label: 'SKU' }
        ];

        // Auto-detect mapping
        const autoMap = {
            'name': ['name', '名称', 'nombre', 'product name', '产品名称', '品名'],
            'regular_price': ['price', '价格', 'precio', 'regular_price', '产品价格', '售价', '单价', '现价'],
            'cost_price': ['cost_price', '进货价', 'coste', 'costo', '成本价', 'cost', '采购价', '成本'],
            'supplier': ['supplier', '供应商', 'proveedor', 'provider', '供货商', '厂家', '厂商'],
            'category': ['category', '分类', 'categoría', 'categoria', '产品分类', '类别'],
            'stock_quantity': ['stock', '库存', 'stock_quantity', '产品库存', '数量', 'quantity', 'cantidad'],
            'sku': ['sku', 'SKU', '编码', 'código', 'codigo', 'code', '条码', 'barcode']
        };

        const usedFields = new Set();
        d.mapping = d.headers.map(header => {
            const h = header.toLowerCase().trim();
            for (const [field, aliases] of Object.entries(autoMap)) {
                if (!usedFields.has(field) && aliases.some(a => a.toLowerCase() === h)) {
                    usedFields.add(field);
                    return field;
                }
            }
            return '';
        });

        // Build mapping selects
        const mappingRow = document.getElementById('import-data-mapping-row');
        mappingRow.innerHTML = '';
        d.headers.forEach((header, index) => {
            const wrapper = document.createElement('div');
            wrapper.className = 'flex flex-col items-center gap-1';

            const label = document.createElement('span');
            label.className = 'text-xs text-gray-500 font-medium truncate max-w-[120px]';
            label.textContent = header;
            label.title = header;

            const select = document.createElement('select');
            select.className = 'text-sm border border-gray-300 rounded-md px-2 py-1.5 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 min-w-[120px]';
            select.dataset.colIndex = index;

            fields.forEach(f => {
                const opt = document.createElement('option');
                opt.value = f.value;
                opt.textContent = f.label;
                if (f.value === d.mapping[index]) opt.selected = true;
                select.appendChild(opt);
            });

            select.addEventListener('change', (e) => {
                const colIdx = parseInt(e.target.dataset.colIndex);
                const newVal = e.target.value;

                // Prevent duplicate mapping
                if (newVal) {
                    const existingIdx = d.mapping.findIndex((m, i) => m === newVal && i !== colIdx);
                    if (existingIdx !== -1) {
                        d.mapping[existingIdx] = '';
                        const otherSelect = mappingRow.querySelector(`select[data-col-index="${existingIdx}"]`);
                        if (otherSelect) otherSelect.value = '';
                    }
                }
                d.mapping[colIdx] = newVal;
            });

            wrapper.appendChild(label);
            wrapper.appendChild(select);
            mappingRow.appendChild(wrapper);
        });

        // Build preview table (first 10 rows)
        const thead = document.getElementById('import-data-preview-thead');
        const tbody = document.getElementById('import-data-preview-tbody');

        thead.innerHTML = '<tr>' + d.headers.map(h =>
            `<th class="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">${this.escapeHtml(h)}</th>`
        ).join('') + '</tr>';

        const previewRows = d.rows.slice(0, 10);
        tbody.innerHTML = previewRows.map(row =>
            '<tr class="hover:bg-gray-50">' + d.headers.map((_, i) =>
                `<td class="px-3 py-2 text-sm text-gray-700 whitespace-nowrap">${this.escapeHtml((row[i] !== null && row[i] !== undefined) ? row[i].toString() : '')}</td>`
            ).join('') + '</tr>'
        ).join('');
    }

    /**
     * 重置导入数据 - 清除状态并返回上传界面
     */
    resetImportData() {
        this._importData = null;
        document.getElementById('import-data-upload-area').classList.remove('hidden');
        document.getElementById('import-data-preview-area').classList.add('hidden');
        document.getElementById('import-data-file-input').value = '';
        document.getElementById('import-data-mapping-row').innerHTML = '';
        document.getElementById('import-data-preview-thead').innerHTML = '';
        document.getElementById('import-data-preview-tbody').innerHTML = '';
        // Reset loading overlay
        document.getElementById('import-data-loading-overlay').classList.add('hidden');
        document.getElementById('import-data-progress-bar').style.width = '0%';
        const startBtn = document.getElementById('import-data-start-btn');
        if (startBtn) {
            startBtn.disabled = false;
            startBtn.classList.remove('opacity-50', 'cursor-not-allowed');
        }
    }

    /**
     * 执行导入 - 按列映射构建数据并发送到后端
     */
    async executeImportData() {
        const locale = document.documentElement.lang || 'en';
        const d = this._importData;
        if (!d) return;

        // Validate: at least "name" must be mapped
        if (!d.mapping.includes('name')) {
            const msg = locale.includes('zh') ? '请至少映射"产品名称"列' :
                       locale.includes('es') ? 'Debe mapear al menos la columna "Nombre"' : 'Please map at least the "Product Name" column';
            this.showToast(msg, 'warning');
            return;
        }

        // Show loading overlay
        const overlay = document.getElementById('import-data-loading-overlay');
        const progressBar = document.getElementById('import-data-progress-bar');
        const progressText = document.getElementById('import-data-progress-text');
        const loadingText = document.getElementById('import-data-loading-text');
        const spinner = document.getElementById('import-data-spinner');
        const successIcon = document.getElementById('import-data-success-icon');
        const startBtn = document.getElementById('import-data-start-btn');

        overlay.classList.remove('hidden');
        spinner.classList.remove('hidden');
        successIcon.classList.add('hidden');
        startBtn.disabled = true;
        startBtn.classList.add('opacity-50', 'cursor-not-allowed');
        progressBar.style.width = '0%';
        progressBar.classList.remove('bg-green-500', 'bg-red-500');
        progressBar.classList.add('bg-blue-600');
        loadingText.textContent = locale.includes('zh') ? '正在准备数据...' :
                                  locale.includes('es') ? 'Preparando datos...' : 'Preparing data...';
        progressText.textContent = `0 / ${d.rows.length}`;

        // Animate progress to ~20% during data prep
        progressBar.style.width = '15%';

        try {
            // Build CSV with internal field names as headers
            const internalHeaders = d.mapping.map(m => m || '__skip__');
            const csvLines = [internalHeaders.join(',')];

            d.rows.forEach(row => {
                const cells = d.headers.map((_, i) => {
                    const val = (row[i] !== null && row[i] !== undefined) ? row[i].toString() : '';
                    if (val.includes(',') || val.includes('"') || val.includes('\n')) {
                        return '"' + val.replace(/"/g, '""') + '"';
                    }
                    return val;
                });
                csvLines.push(cells.join(','));
            });

            const csvData = csvLines.join('\n');

            // Update progress — uploading
            progressBar.style.width = '30%';
            loadingText.textContent = locale.includes('zh') ? '正在上传数据...' :
                                      locale.includes('es') ? 'Subiendo datos...' : 'Uploading data...';

            // Simulate gradual progress while waiting for server
            let fakeProgress = 30;
            const progressInterval = setInterval(() => {
                if (fakeProgress < 85) {
                    fakeProgress += Math.random() * 8;
                    if (fakeProgress > 85) fakeProgress = 85;
                    progressBar.style.width = fakeProgress + '%';
                    const estimated = Math.round(d.rows.length * fakeProgress / 100);
                    progressText.textContent = `~${estimated} / ${d.rows.length}`;
                }
            }, 500);

            loadingText.textContent = locale.includes('zh') ? `正在导入 ${d.rows.length} 个产品...` :
                                      locale.includes('es') ? `Importando ${d.rows.length} productos...` : `Importing ${d.rows.length} products...`;

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'import_products_mapped',
                    nonce: ruiyi_pos_ajax.nonce,
                    csv_data: csvData
                })
            });

            clearInterval(progressInterval);

            const data = await response.json();

            if (data.success) {
                const r = data.data;

                // Show completion state
                progressBar.style.width = '100%';
                progressBar.classList.remove('bg-blue-600');
                progressBar.classList.add('bg-green-500');
                spinner.classList.add('hidden');
                successIcon.classList.remove('hidden');
                progressText.textContent = `${r.created} / ${d.rows.length}`;

                let msg;
                if (locale.includes('zh')) {
                    msg = `导入完成！新增 ${r.created} 个，跳过重复 ${r.skipped} 个`;
                    if (r.errors && r.errors.length > 0) msg += `，错误 ${r.errors.length} 个`;
                } else if (locale.includes('es')) {
                    msg = `Importación completada: ${r.created} creados, ${r.skipped} duplicados omitidos`;
                    if (r.errors && r.errors.length > 0) msg += `, ${r.errors.length} errores`;
                } else {
                    msg = `Import complete! ${r.created} created, ${r.skipped} duplicates skipped`;
                    if (r.errors && r.errors.length > 0) msg += `, ${r.errors.length} errors`;
                }
                loadingText.textContent = msg;
                loadingText.classList.add('text-green-700');

                if (r.errors && r.errors.length > 0) {
                    console.warn('[ImportData] Errors:', r.errors);
                }

                // Wait 2s so user can see the result, then reset
                await new Promise(resolve => setTimeout(resolve, 2000));
                loadingText.classList.remove('text-green-700');

                // Reset import UI
                this.resetImportData();

                // Refresh product list
                this.loadEditProductsList();

                // Sync product cache
                if (window.ProductCacheManager) {
                    window.ProductCacheManager.cacheAllProductsPaginated(true, true)
                        .catch(err => console.warn('[ImportData] Cache sync failed:', err));
                }
            } else {
                throw new Error(data.data?.message || 'Import failed');
            }
        } catch (error) {
            console.error('[ImportData] Error:', error);

            // Show error state on overlay
            progressBar.style.width = '100%';
            progressBar.classList.remove('bg-blue-600');
            progressBar.classList.add('bg-red-500');
            spinner.classList.add('hidden');
            const errorMsg = locale.includes('zh') ? '导入失败' :
                            locale.includes('es') ? 'Error al importar' : 'Import failed';
            loadingText.textContent = errorMsg + ': ' + (error.message || '');
            loadingText.classList.add('text-red-600');
            progressText.textContent = '';

            // Hide overlay after 2.5s and restore button
            await new Promise(resolve => setTimeout(resolve, 2500));
            overlay.classList.add('hidden');
            loadingText.classList.remove('text-red-600');
            startBtn.disabled = false;
            startBtn.classList.remove('opacity-50', 'cursor-not-allowed');
        }
    }

    // ========================================
    // 📊 EXCEL IMPORT (Excel导入) - Three-Step Flow
    // ========================================

    /**
     * Convert column index (0-based) to Excel letter (A, B, C, ... Z, AA, AB, ...)
     */
    colIndexToLetter(index) {
        let letter = '';
        let i = index;
        while (i >= 0) {
            letter = String.fromCharCode((i % 26) + 65) + letter;
            i = Math.floor(i / 26) - 1;
        }
        return letter;
    }

    /**
     * Handle Excel import file selection — parse and render full spreadsheet preview
     */
    async handleExcelImportFileSelect(fileInput) {
        const locale = document.documentElement.lang || 'en';
        const file = fileInput.files[0];
        if (!file) return;

        try {
            // 统一用 parseFileToWorkbook 处理各种格式（xlsx/xls/csv/HTML 伪装 .xls）
            const wb = await this.parseFileToWorkbook(file);
            const firstSheet = wb.Sheets[wb.SheetNames[0]];
            const rows = XLSX.utils.sheet_to_json(firstSheet, { header: 1, defval: '' });

            if (!rows || rows.length === 0) {
                const msg = locale.includes('zh') ? '文件为空' :
                           locale.includes('es') ? 'El archivo está vacío' : 'File is empty';
                this.showToast(msg, 'error');
                return;
            }

            // Store parsed data
            this._excelImportData = {
                fileName: file.name,
                allRows: rows,
                totalRows: rows.length,
                totalCols: Math.max(...rows.map(r => r.length)),
            };

            // Show preview area, hide upload
            document.getElementById('excel-import-upload-area').classList.add('hidden');
            document.getElementById('excel-import-preview-area').classList.remove('hidden');

            // File info
            document.getElementById('excel-import-file-name').textContent = file.name;
            const rowCountText = locale.includes('zh') ? `${rows.length} 行` :
                                locale.includes('es') ? `${rows.length} filas` : `${rows.length} rows`;
            document.getElementById('excel-import-row-count').textContent = `(${rowCountText})`;

            // Set row input max values
            document.getElementById('excel-import-start-row').max = rows.length;
            document.getElementById('excel-import-end-row').max = rows.length;
            document.getElementById('excel-import-start-row').value = '';
            document.getElementById('excel-import-end-row').value = '';

            // Render full spreadsheet preview
            this.renderExcelImportFullPreview();

        } catch (error) {
            console.error('[ExcelImport] File parse error:', error);
            const msg = locale.includes('zh') ? '文件解析失败' :
                       locale.includes('es') ? 'Error al analizar archivo' : 'File parse error';
            this.showToast(msg + ': ' + (error.message || ''), 'error');
        }

        // Reset file input so same file can be re-selected
        fileInput.value = '';
    }

    /**
     * Render the full spreadsheet preview table (Step 1)
     */
    renderExcelImportFullPreview() {
        const d = this._excelImportData;
        if (!d) return;

        const locale = document.documentElement.lang || 'en';
        // Build header row with column letters
        let theadHtml = '<tr><th class="px-2 py-1.5 bg-gray-100 text-gray-500 font-medium border border-gray-200 sticky left-0 z-20">#</th>';
        for (let c = 0; c < d.totalCols; c++) {
            theadHtml += `<th class="px-2 py-1.5 bg-gray-100 text-gray-500 font-medium border border-gray-200 text-center">${this.colIndexToLetter(c)}</th>`;
        }
        theadHtml += '</tr>';
        document.getElementById('excel-import-full-thead').innerHTML = theadHtml;

        // Build body rows (all rows)
        let tbodyHtml = '';
        d.allRows.forEach((row, rowIdx) => {
            tbodyHtml += `<tr data-row="${rowIdx + 1}">`;
            tbodyHtml += `<td class="px-2 py-1 bg-gray-50 text-gray-500 font-medium border border-gray-200 text-center sticky left-0 z-10">${rowIdx + 1}</td>`;
            for (let c = 0; c < d.totalCols; c++) {
                const val = (row[c] !== null && row[c] !== undefined) ? row[c].toString() : '';
                tbodyHtml += `<td class="px-2 py-1 border border-gray-200 whitespace-nowrap">${this.escapeHtml(val)}</td>`;
            }
            tbodyHtml += '</tr>';
        });
        document.getElementById('excel-import-full-tbody').innerHTML = tbodyHtml;

        // Disable next button until range is valid
        document.getElementById('excel-import-next-btn').disabled = true;
    }

    /**
     * Highlight selected rows in preview table and enable/disable Next button
     */
    excelImportHighlightRows() {
        const d = this._excelImportData;
        if (!d) return;

        const startVal = parseInt(document.getElementById('excel-import-start-row').value);
        const endVal = parseInt(document.getElementById('excel-import-end-row').value);
        const tbody = document.getElementById('excel-import-full-tbody');
        const nextBtn = document.getElementById('excel-import-next-btn');
        const locale = document.documentElement.lang || 'en';

        // Clear all highlights
        tbody.querySelectorAll('tr').forEach(tr => {
            tr.classList.remove('bg-blue-50');
        });

        const validStart = !isNaN(startVal) && startVal >= 1 && startVal <= d.totalRows;
        const validEnd = !isNaN(endVal) && endVal >= 1 && endVal <= d.totalRows;
        const validRange = validStart && validEnd && startVal <= endVal;

        nextBtn.disabled = !validRange;

        if (validRange) {
            const selectedCount = endVal - startVal + 1;
            const info = locale.includes('zh') ? `已选择 ${selectedCount} 行` :
                        locale.includes('es') ? `${selectedCount} filas seleccionadas` :
                        `${selectedCount} rows selected`;
            document.getElementById('excel-import-range-info').textContent = info;

            // Highlight selected rows
            for (let r = startVal; r <= endVal; r++) {
                const tr = tbody.querySelector(`tr[data-row="${r}"]`);
                if (tr) {
                    tr.classList.add('bg-blue-50');
                }
            }

            // Auto-scroll to start row
            const startTr = tbody.querySelector(`tr[data-row="${startVal}"]`);
            if (startTr) {
                startTr.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        } else if (validStart || validEnd) {
            const info = locale.includes('zh') ? '请输入有效的行范围' :
                        locale.includes('es') ? 'Ingrese un rango válido' :
                        'Enter a valid row range';
            document.getElementById('excel-import-range-info').textContent = info;
        }
    }

    /**
     * Proceed to Step 2 — show selected range preview + column mapping
     */
    excelImportNextStep() {
        const d = this._excelImportData;
        if (!d) return;

        const locale = document.documentElement.lang || 'en';
        const startRow = parseInt(document.getElementById('excel-import-start-row').value);
        const endRow = parseInt(document.getElementById('excel-import-end-row').value);

        // Extract selected rows (convert to 0-based index)
        const selectedRows = d.allRows.slice(startRow - 1, endRow);

        if (selectedRows.length === 0) {
            const msg = locale.includes('zh') ? '选择的范围内没有数据' :
                       locale.includes('es') ? 'No hay datos en el rango seleccionado' : 'No data in selected range';
            this.showToast(msg, 'error');
            return;
        }

        // Find non-empty columns within the selected range
        const nonEmptyCols = [];
        for (let c = 0; c < d.totalCols; c++) {
            const hasData = selectedRows.some(row => {
                const val = row[c];
                return val !== null && val !== undefined && val.toString().trim() !== '';
            });
            if (hasData) {
                nonEmptyCols.push(c);
            }
        }

        if (nonEmptyCols.length === 0) {
            const msg = locale.includes('zh') ? '选择的范围内所有列都为空' :
                       locale.includes('es') ? 'Todas las columnas están vacías en el rango' : 'All columns are empty in selected range';
            this.showToast(msg, 'error');
            return;
        }

        // Store step 2 state
        this._excelImportData.startRow = startRow;
        this._excelImportData.endRow = endRow;
        this._excelImportData.selectedRows = selectedRows;
        this._excelImportData.nonEmptyCols = nonEmptyCols;

        // Switch to Step 2
        document.getElementById('excel-import-step1').classList.add('hidden');
        document.getElementById('excel-import-step2').classList.remove('hidden');

        // Store default button HTML for later restoration
        const startBtn = document.getElementById('excel-import-start-btn');
        if (!startBtn.dataset.defaultHtml) {
            startBtn.dataset.defaultHtml = startBtn.innerHTML;
        }

        // Populate mapping dropdowns
        this.populateExcelImportMappingDropdowns(nonEmptyCols);

        // Show initial raw preview (first 5 rows) so user can see data before mapping
        document.getElementById('excel-import-filter-stats').textContent = '';
        this.renderExcelImportRawPreview(selectedRows, nonEmptyCols);
    }

    /**
     * Render raw preview table (first 5 rows, no filtering) — shown before user maps columns
     */
    renderExcelImportRawPreview(selectedRows, nonEmptyCols) {
        const previewRows = selectedRows.slice(0, 5);
        const startRow = this._excelImportData.startRow;

        let theadHtml = '<tr><th class="px-3 py-2 bg-gray-100 text-gray-500 font-medium border border-gray-200 text-center">#</th>';
        nonEmptyCols.forEach(colIdx => {
            theadHtml += `<th class="px-3 py-2 bg-gray-100 text-gray-500 font-medium border border-gray-200 text-center">${this.colIndexToLetter(colIdx)}</th>`;
        });
        theadHtml += '</tr>';
        document.getElementById('excel-import-step2-thead').innerHTML = theadHtml;

        let tbodyHtml = '';
        previewRows.forEach((row, idx) => {
            tbodyHtml += `<tr class="hover:bg-gray-50">`;
            tbodyHtml += `<td class="px-3 py-1.5 bg-gray-50 text-gray-500 font-medium border border-gray-200 text-center">${startRow + idx}</td>`;
            nonEmptyCols.forEach(colIdx => {
                const val = (row[colIdx] !== null && row[colIdx] !== undefined) ? row[colIdx].toString() : '';
                tbodyHtml += `<td class="px-3 py-1.5 border border-gray-200 whitespace-nowrap">${this.escapeHtml(val)}</td>`;
            });
            tbodyHtml += '</tr>';
        });
        document.getElementById('excel-import-step2-tbody').innerHTML = tbodyHtml;
    }

    /**
     * Populate the 5 mapping dropdowns with non-empty column letters
     */
    populateExcelImportMappingDropdowns(nonEmptyCols) {
        const locale = document.documentElement.lang || 'en';
        const skipLabel = locale.includes('zh') ? '(不选择)' :
                         locale.includes('es') ? '(No seleccionar)' : '(Skip)';

        const selects = [
            'excel-import-map-sku',
            'excel-import-map-name',
            'excel-import-map-price',
            'excel-import-map-cost-price',
            'excel-import-map-supplier',
            'excel-import-map-stock',
            'excel-import-map-category'
        ];

        selects.forEach(id => {
            const select = document.getElementById(id);
            select.innerHTML = '';
            const skipOpt = document.createElement('option');
            skipOpt.value = '';
            skipOpt.textContent = skipLabel;
            select.appendChild(skipOpt);
            nonEmptyCols.forEach(colIdx => {
                const opt = document.createElement('option');
                opt.value = colIdx;
                opt.textContent = this.colIndexToLetter(colIdx);
                select.appendChild(opt);
            });
            select.value = '';
        });

        document.getElementById('excel-import-start-btn').disabled = true;
    }

    /**
     * Render Step 2 preview table — shows ALL valid (filtered) rows with stats
     * @param {Array<{row, originalRowNum}>} filteredRows - valid rows from excelImportFilterRows()
     * @param {Array<number>} nonEmptyCols - indices of non-empty columns
     */
    renderExcelImportStep2Preview(filteredRows, nonEmptyCols) {
        const locale = document.documentElement.lang || 'en';
        const d = this._excelImportData;
        const totalRows = d.selectedRows.length;
        const validCount = filteredRows.length;
        const statsEl = document.getElementById('excel-import-filter-stats');
        const startBtn = document.getElementById('excel-import-start-btn');

        // Update stats text
        if (validCount > 0) {
            statsEl.textContent = locale.includes('zh')
                ? `从 ${totalRows} 行中识别出 ${validCount} 个有效产品`
                : locale.includes('es')
                ? `${validCount} productos válidos identificados de ${totalRows} filas`
                : `${validCount} valid products found from ${totalRows} rows`;
            statsEl.className = 'text-sm text-green-700 font-medium';
        } else {
            statsEl.textContent = locale.includes('zh')
                ? '未找到有效产品，请检查列映射是否正确'
                : locale.includes('es')
                ? 'No se encontraron productos válidos, verifique el mapeo de columnas'
                : 'No valid products found, please check column mapping';
            statsEl.className = 'text-sm text-amber-600 font-medium';
        }

        // Update button label with count
        if (validCount > 0) {
            startBtn.innerHTML = locale.includes('zh')
                ? `<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg> 导入 ${validCount} 个产品`
                : locale.includes('es')
                ? `<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg> Importar ${validCount} productos`
                : `<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg> Import ${validCount} products`;
        }

        // Header with column letters
        let theadHtml = '<tr><th class="px-3 py-2 bg-gray-100 text-gray-500 font-medium border border-gray-200 text-center">#</th>';
        nonEmptyCols.forEach(colIdx => {
            theadHtml += `<th class="px-3 py-2 bg-gray-100 text-gray-500 font-medium border border-gray-200 text-center">${this.colIndexToLetter(colIdx)}</th>`;
        });
        theadHtml += '</tr>';
        document.getElementById('excel-import-step2-thead').innerHTML = theadHtml;

        // Body — all valid rows with original Excel row numbers
        let tbodyHtml = '';
        filteredRows.forEach(({ row, originalRowNum }) => {
            tbodyHtml += `<tr class="hover:bg-gray-50">`;
            tbodyHtml += `<td class="px-3 py-1.5 bg-gray-50 text-gray-500 font-medium border border-gray-200 text-center">${originalRowNum}</td>`;
            nonEmptyCols.forEach(colIdx => {
                const val = (row[colIdx] !== null && row[colIdx] !== undefined) ? row[colIdx].toString() : '';
                tbodyHtml += `<td class="px-3 py-1.5 border border-gray-200 whitespace-nowrap">${this.escapeHtml(val)}</td>`;
            });
            tbodyHtml += '</tr>';
        });
        document.getElementById('excel-import-step2-tbody').innerHTML = tbodyHtml;
    }

    // Keywords that indicate a row is NOT a product (invoice headers, footers, summaries)
    static EXCEL_IMPORT_FILTER_KEYWORDS = [
        'CODIGO', 'DESCRIPCION', 'Unds', 'Precio', 'SubTotal',
        'Ticket', 'Fecha', 'Vendedor', 'Almacen', 'Imprimir',
        'Fatura', 'FACTURA', 'Cliente ID', 'CIF', 'Tel.',
        'Unidades', 'Sub Total', 'Total:', 'SIMPLIFICADA',
        'Nº Ticket', 'P.IVA', 'Dto. Total'
    ];

    /**
     * Filter rows to keep only valid product rows based on mapping.
     * Returns array of { row, originalRowNum } for valid rows.
     */
    excelImportFilterRows() {
        const d = this._excelImportData;
        if (!d || !d.selectedRows) return [];

        const nameColIdx = document.getElementById('excel-import-map-name').value;
        if (nameColIdx === '') return [];

        const nameCol = parseInt(nameColIdx);
        const priceColVal = document.getElementById('excel-import-map-price').value;
        const priceCol = priceColVal !== '' ? parseInt(priceColVal) : null;
        const keywords = this.constructor.EXCEL_IMPORT_FILTER_KEYWORDS;

        const validRows = [];
        d.selectedRows.forEach((row, idx) => {
            const originalRowNum = d.startRow + idx;

            // Rule 1: Name column must have a non-empty value
            const nameVal = row[nameCol];
            if (nameVal === null || nameVal === undefined || nameVal.toString().trim() === '') return;

            // Rule 2: At least 3 non-empty cells (filters out sparse rows like Chinese description continuations)
            let nonEmptyCount = 0;
            for (let c = 0; c < row.length; c++) {
                if (row[c] !== null && row[c] !== undefined && row[c].toString().trim() !== '') {
                    nonEmptyCount++;
                    if (nonEmptyCount >= 3) break;
                }
            }
            if (nonEmptyCount < 3) return;

            // Rule 3: No invoice keywords in any cell
            for (let c = 0; c < row.length; c++) {
                const cellVal = row[c];
                if (cellVal === null || cellVal === undefined) continue;
                const cellStr = cellVal.toString();
                for (const kw of keywords) {
                    if (cellStr.includes(kw)) return;
                }
            }

            // Rule 4: If price column is mapped, its value must be a valid number (when non-empty)
            if (priceCol !== null) {
                const priceVal = row[priceCol];
                if (priceVal !== null && priceVal !== undefined && priceVal.toString().trim() !== '') {
                    const num = parseFloat(priceVal.toString().replace(',', '.'));
                    if (isNaN(num)) return;
                }
            }

            validRows.push({ row, originalRowNum });
        });

        return validRows;
    }

    /**
     * Handle mapping dropdown change — prevent duplicates, auto-filter, update preview
     * @param {HTMLSelectElement} changedSelect - the select element that was just changed
     */
    excelImportMappingChanged(changedSelect) {
        const selects = [
            'excel-import-map-sku',
            'excel-import-map-name',
            'excel-import-map-price',
            'excel-import-map-cost-price',
            'excel-import-map-supplier',
            'excel-import-map-stock',
            'excel-import-map-category'
        ];

        // Clear any OTHER select that has the same column value as the one just changed
        const changedVal = changedSelect.value;
        if (changedVal !== '') {
            selects.forEach(id => {
                if (id !== changedSelect.id && document.getElementById(id).value === changedVal) {
                    document.getElementById(id).value = '';
                }
            });
        }

        const nameVal = document.getElementById('excel-import-map-name').value;
        const startBtn = document.getElementById('excel-import-start-btn');

        if (nameVal === '') {
            // Name not mapped yet — show raw preview, disable button, restore default label
            startBtn.disabled = true;
            if (startBtn.dataset.defaultHtml) startBtn.innerHTML = startBtn.dataset.defaultHtml;
            document.getElementById('excel-import-filter-stats').textContent = '';
            const d = this._excelImportData;
            if (d && d.selectedRows && d.nonEmptyCols) {
                this.renderExcelImportRawPreview(d.selectedRows, d.nonEmptyCols);
            }
            return;
        }

        // Run auto-filter and update preview
        const validRows = this.excelImportFilterRows();
        this._excelImportData.filteredRows = validRows;

        this.renderExcelImportStep2Preview(validRows, this._excelImportData.nonEmptyCols);

        // Update button state
        startBtn.disabled = (validRows.length === 0);
    }

    /**
     * Go back to Step 1 (preserving parsed data)
     */
    excelImportBack() {
        document.getElementById('excel-import-step2').classList.add('hidden');
        document.getElementById('excel-import-step1').classList.remove('hidden');
    }

    /**
     * Execute Excel import — build CSV from mapped columns, send to server
     */
    async executeExcelImport() {
        const locale = document.documentElement.lang || 'en';
        const d = this._excelImportData;
        if (!d || !d.filteredRows || d.filteredRows.length === 0) return;

        const mappingFields = {
            sku: document.getElementById('excel-import-map-sku').value,
            name: document.getElementById('excel-import-map-name').value,
            regular_price: document.getElementById('excel-import-map-price').value,
            cost_price: document.getElementById('excel-import-map-cost-price').value,
            supplier: document.getElementById('excel-import-map-supplier').value,
            stock_quantity: document.getElementById('excel-import-map-stock').value,
            category: document.getElementById('excel-import-map-category').value,
        };

        // Validate name is mapped
        if (mappingFields.name === '') return;

        // Use filtered rows (only valid product rows)
        const rowsToImport = d.filteredRows.map(item => item.row);

        // Show loading overlay
        const overlay = document.getElementById('excel-import-loading-overlay');
        const progressBar = document.getElementById('excel-import-progress-bar');
        const progressText = document.getElementById('excel-import-progress-text');
        const loadingText = document.getElementById('excel-import-loading-text');
        const spinner = document.getElementById('excel-import-spinner');
        const successIcon = document.getElementById('excel-import-success-icon');
        const startBtn = document.getElementById('excel-import-start-btn');

        overlay.classList.remove('hidden');
        spinner.classList.remove('hidden');
        successIcon.classList.add('hidden');
        startBtn.disabled = true;
        startBtn.classList.add('opacity-50', 'cursor-not-allowed');
        progressBar.style.width = '0%';
        progressBar.classList.remove('bg-green-500', 'bg-red-500');
        progressBar.classList.add('bg-blue-600');
        loadingText.textContent = locale.includes('zh') ? '正在准备数据...' :
                                  locale.includes('es') ? 'Preparando datos...' : 'Preparing data...';
        loadingText.classList.remove('text-green-700', 'text-red-600');
        const importCount = rowsToImport.length;
        progressText.textContent = `0 / ${importCount}`;

        progressBar.style.width = '15%';

        try {
            // Build CSV: header row uses internal field names, unmapped cols use __skip__
            const allNonEmptyCols = d.nonEmptyCols;
            const csvHeaders = [];
            allNonEmptyCols.forEach(colIdx => {
                const colStr = colIdx.toString();
                let fieldName = '__skip__';
                for (const [field, mappedCol] of Object.entries(mappingFields)) {
                    if (mappedCol === colStr) {
                        fieldName = field;
                        break;
                    }
                }
                csvHeaders.push(fieldName);
            });

            const csvLines = [csvHeaders.join(',')];

            rowsToImport.forEach(row => {
                const cells = allNonEmptyCols.map(colIdx => {
                    const val = (row[colIdx] !== null && row[colIdx] !== undefined) ? row[colIdx].toString() : '';
                    if (val.includes(',') || val.includes('"') || val.includes('\n')) {
                        return '"' + val.replace(/"/g, '""') + '"';
                    }
                    return val;
                });
                csvLines.push(cells.join(','));
            });

            const csvData = csvLines.join('\n');

            // Update progress
            progressBar.style.width = '30%';
            loadingText.textContent = locale.includes('zh') ? `正在导入 ${importCount} 个产品...` :
                                      locale.includes('es') ? `Importando ${importCount} productos...` :
                                      `Importing ${importCount} products...`;

            // Simulate gradual progress
            let fakeProgress = 30;
            const progressInterval = setInterval(() => {
                if (fakeProgress < 85) {
                    fakeProgress += Math.random() * 8;
                    if (fakeProgress > 85) fakeProgress = 85;
                    progressBar.style.width = fakeProgress + '%';
                    const estimated = Math.round(importCount * fakeProgress / 100);
                    progressText.textContent = `~${estimated} / ${importCount}`;
                }
            }, 500);

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'import_products_mapped',
                    nonce: ruiyi_pos_ajax.nonce,
                    csv_data: csvData
                })
            });

            clearInterval(progressInterval);

            const data = await response.json();

            if (data.success) {
                const r = data.data;

                // Show success
                progressBar.style.width = '100%';
                progressBar.classList.remove('bg-blue-600');
                progressBar.classList.add('bg-green-500');
                spinner.classList.add('hidden');
                successIcon.classList.remove('hidden');
                progressText.textContent = `${r.created} / ${importCount}`;

                let msg;
                if (locale.includes('zh')) {
                    msg = `导入完成！新增 ${r.created} 个，跳过重复 ${r.skipped} 个`;
                    if (r.errors && r.errors.length > 0) msg += `，错误 ${r.errors.length} 个`;
                } else if (locale.includes('es')) {
                    msg = `Importación completada: ${r.created} creados, ${r.skipped} duplicados omitidos`;
                    if (r.errors && r.errors.length > 0) msg += `, ${r.errors.length} errores`;
                } else {
                    msg = `Import complete! ${r.created} created, ${r.skipped} duplicates skipped`;
                    if (r.errors && r.errors.length > 0) msg += `, ${r.errors.length} errors`;
                }
                loadingText.textContent = msg;
                loadingText.classList.add('text-green-700');

                if (r.errors && r.errors.length > 0) {
                    console.warn('[ExcelImport] Errors:', r.errors);
                }

                // Wait 2s then reset
                await new Promise(resolve => setTimeout(resolve, 2000));
                loadingText.classList.remove('text-green-700');

                this.resetExcelImport();

                // Refresh product list and sync cache
                this.loadEditProductsList();
                if (window.ProductCacheManager) {
                    window.ProductCacheManager.cacheAllProductsPaginated(true, true)
                        .catch(err => console.warn('[ExcelImport] Cache sync failed:', err));
                }
            } else {
                throw new Error(data.data?.message || 'Import failed');
            }
        } catch (error) {
            console.error('[ExcelImport] Error:', error);

            progressBar.style.width = '100%';
            progressBar.classList.remove('bg-blue-600');
            progressBar.classList.add('bg-red-500');
            spinner.classList.add('hidden');
            const errorMsg = locale.includes('zh') ? '导入失败' :
                            locale.includes('es') ? 'Error al importar' : 'Import failed';
            loadingText.textContent = errorMsg + ': ' + (error.message || '');
            loadingText.classList.add('text-red-600');
            progressText.textContent = '';

            await new Promise(resolve => setTimeout(resolve, 2500));
            overlay.classList.add('hidden');
            loadingText.classList.remove('text-red-600');
            startBtn.disabled = false;
            startBtn.classList.remove('opacity-50', 'cursor-not-allowed');
        }
    }

    /**
     * Reset Excel import — clear all state, return to upload view
     */
    resetExcelImport() {
        this._excelImportData = null;

        // Reset Step 1
        document.getElementById('excel-import-upload-area').classList.remove('hidden');
        document.getElementById('excel-import-preview-area').classList.add('hidden');
        document.getElementById('excel-import-file-input').value = '';
        document.getElementById('excel-import-full-thead').innerHTML = '';
        document.getElementById('excel-import-full-tbody').innerHTML = '';
        document.getElementById('excel-import-start-row').value = '';
        document.getElementById('excel-import-end-row').value = '';
        document.getElementById('excel-import-range-info').textContent = '';

        // Reset Step 2
        document.getElementById('excel-import-step2').classList.add('hidden');
        document.getElementById('excel-import-step1').classList.remove('hidden');
        document.getElementById('excel-import-step2-thead').innerHTML = '';
        document.getElementById('excel-import-step2-tbody').innerHTML = '';
        document.getElementById('excel-import-filter-stats').textContent = '';

        // Reset loading overlay
        document.getElementById('excel-import-loading-overlay').classList.add('hidden');
        document.getElementById('excel-import-progress-bar').style.width = '0%';
        const startBtn = document.getElementById('excel-import-start-btn');
        if (startBtn) {
            startBtn.disabled = false;
            startBtn.classList.remove('opacity-50', 'cursor-not-allowed');
        }
    }

    /**
     * 从设置模态框保存产品
     */
    async saveProductFromSettings() {
        const name = document.getElementById('settings-product-name').value.trim();
        const sku = document.getElementById('settings-product-sku').value.trim();
        const productNumber = document.getElementById('settings-product-number')?.value.trim() || '';
        const retailPrice = document.getElementById('settings-product-retail-price').value;
        const stock = document.getElementById('settings-product-stock').value;

        // 🔥 SKU现在是可选的，只需要名称和价格
        if (!name || !retailPrice) {
            const locale = document.documentElement.lang || 'en';
            const msg = locale.includes('zh') ? '请填写产品名称和价格' :
                       locale.includes('es') ? 'Por favor complete nombre y precio' :
                       'Please fill in name and price';
            this.showToast(msg, 'error');
            return;
        }

        try {
            const data = await this.ajaxRequest({
                pos_action: 'create_product',
                product_name: name,
                product_sku: sku,
                product_number: productNumber,
                product_price: retailPrice,
                product_stock: (stock === '' || stock === '0') ? '-1' : stock
            });

            if (data.success) {
                const locale = document.documentElement.lang || 'en';
                const successMsg = locale.includes('zh') ? '✅ 产品创建成功！' :
                                  locale.includes('es') ? '✅ Producto creado correctamente!' :
                                  '✅ Product created successfully!';

                this.showSuccessPopup(successMsg);

                // 清空表单
                document.getElementById('settings-product-name').value = '';
                document.getElementById('settings-product-sku').value = '';
                document.getElementById('settings-product-number') && (document.getElementById('settings-product-number').value = '');
                document.getElementById('settings-product-retail-price').value = '';
                document.getElementById('settings-product-stock').value = '';

                // 刷新产品缓存
                if (typeof this.refreshProductCache === 'function') {
                    this.refreshProductCache();
                }
            } else {
                this.showToast(data.data?.message || 'Error saving product', 'error');
            }
        } catch (error) {
            console.error('Error saving product:', error);
            this.showToast('Error saving product', 'error');
        }
    }

    // ========================================
    // 🔥 快速添加产品功能 (Quick Add Product - F6)
    // ========================================

    /**
     * 打开快速添加产品弹窗
     */
    showQuickAddProductModal() {
        // 🔥 清空Varios输入框并失焦
        const variosInput = document.getElementById('varios-price-input');
        if (variosInput) {
            variosInput.value = '';
            variosInput.blur();
        }

        const modal = document.getElementById('quick-add-product-modal');
        if (modal) {
            // 清空表单
            this.resetQuickAddProductForm();
            modal.classList.remove('hidden');

            // 聚焦到产品编号输入框
            setTimeout(() => {
                const numberInput = document.getElementById('quick-product-number');
                if (numberInput) {
                    numberInput.focus();
                }
            }, 100);

            // 绑定产品编号输入事件
            this.bindQuickProductNumberSearch();

            // 🔥 防止全局键盘快捷键拦截弹窗内的输入（特别是 -、+、_ 等特殊字符）
            // 对弹窗内所有输入框添加 stopPropagation，阻止事件冒泡到 document 级别的处理器
            modal.querySelectorAll('input, textarea').forEach(input => {
                if (!input._quickAddStopPropHandler) {
                    input._quickAddStopPropHandler = function(e) {
                        // 只允许功能键和 Escape 冒泡到全局处理器
                        if (!/^F\d+$/.test(e.key) && e.key !== 'Escape') {
                            e.stopPropagation();
                        }
                    };
                    input.addEventListener('keydown', input._quickAddStopPropHandler);
                }
            });
        }
    }

    /**
     * 关闭快速添加产品弹窗
     */
    closeQuickAddProductModal() {
        const modal = document.getElementById('quick-add-product-modal');
        if (modal) {
            modal.classList.add('hidden');
        }

        // 🔥 关闭弹窗后聚焦回Varios
        setTimeout(() => this.focusVariosInput(), 100);
    }

    /**
     * 重置快速添加产品表单
     */
    resetQuickAddProductForm() {
        document.getElementById('quick-product-number').value = '';
        document.getElementById('quick-product-name').value = '';
        document.getElementById('quick-product-sku').value = '';
        document.getElementById('quick-product-price').value = '';
        document.getElementById('quick-product-quantity').value = '1';
        document.getElementById('quick-product-existing-id').value = '';
        document.getElementById('quick-product-search-status').innerHTML = '';
        // 🔥 关闭并清空下拉列表和匹配按钮
        const dropdown = document.getElementById('quick-product-dropdown');
        if (dropdown) { dropdown.classList.add('hidden'); dropdown.innerHTML = ''; }
        const matchBtn = document.getElementById('quick-product-match-btn');
        if (matchBtn) matchBtn.classList.add('hidden');
        this._quickSearchResults = [];
        this._quickSearchSelectedIndex = 0;
    }

    /**
     * 绑定产品编号搜索事件
     */
    bindQuickProductNumberSearch() {
        const numberInput = document.getElementById('quick-product-number');
        if (!numberInput) return;

        // 移除旧的事件监听器（防止重复绑定）
        if (this._quickProductNumberHandler) {
            numberInput.removeEventListener('input', this._quickProductNumberHandler);
        }

        // 使用 setTimeout 实现防抖
        let debounceTimer = null;
        const self = this;

        // 创建新的事件处理器
        this._quickProductNumberHandler = async function(e) {
            clearTimeout(debounceTimer);
            debounceTimer = setTimeout(async () => {
                const productNumber = e.target.value.trim();
                if (productNumber.length > 0) {
                    await self.searchQuickProductByNumber(productNumber);
                } else {
                    // 清空搜索状态
                    document.getElementById('quick-product-search-status').innerHTML = '';
                    // 🔥 关闭下拉列表和匹配按钮
                    const dd = document.getElementById('quick-product-dropdown');
                    if (dd) { dd.classList.add('hidden'); dd.innerHTML = ''; }
                    const matchBtn = document.getElementById('quick-product-match-btn');
                    if (matchBtn) matchBtn.classList.add('hidden');
                    self._quickSearchResults = [];
                    self._quickSearchSelectedIndex = 0;
                    // 🔥 只清空 existingId，不清空其他字段
                    document.getElementById('quick-product-existing-id').value = '';
                }
            }, 300);
        };

        numberInput.addEventListener('input', this._quickProductNumberHandler);

        // 🔥 绑定所有输入框的空格键导航
        this.bindQuickAddEnterNavigation();
    }

    /**
     * 🔥 绑定快速添加弹窗的空格键导航
     * 按空格键：跳到下一个输入框；最后一个字段按空格键添加至购物车
     * Enter键：仅用于产品编号下拉列表的选择
     */
    bindQuickAddEnterNavigation() {
        // 🔥 定义输入框顺序（按Tab顺序）
        const fieldIds = [
            'quick-product-number',
            'quick-product-name',
            'quick-product-sku',
            'quick-product-price',
            'quick-product-quantity'
        ];

        fieldIds.forEach((fieldId, index) => {
            const input = document.getElementById(fieldId);
            if (!input) return;

            if (input._quickAddEnterHandler) {
                input.removeEventListener('keydown', input._quickAddEnterHandler);
            }

            input._quickAddEnterHandler = (e) => {
                // 🔥 产品编号输入框：上下键导航下拉列表
                if (fieldId === 'quick-product-number' && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
                    const dd = document.getElementById('quick-product-dropdown');
                    if (dd && !dd.classList.contains('hidden') && this._quickSearchResults && this._quickSearchResults.length > 0) {
                        e.preventDefault();
                        const items = dd.querySelectorAll('.quick-product-dropdown-item');
                        let idx = this._quickSearchSelectedIndex || 0;
                        if (e.key === 'ArrowDown') { idx = (idx + 1) % items.length; }
                        else { idx = (idx - 1 + items.length) % items.length; }
                        this._quickSearchSelectedIndex = idx;
                        items.forEach((item, i) => { item.classList.toggle('bg-green-50', i === idx); });
                        items[idx]?.scrollIntoView({ block: 'nearest' });
                    }
                    return;
                }

                // 🔥 Enter键：仅用于产品编号下拉列表选择
                if (e.key === 'Enter') {
                    if (fieldId === 'quick-product-number') {
                        const dd = document.getElementById('quick-product-dropdown');
                        if (dd && !dd.classList.contains('hidden') && this._quickSearchResults && this._quickSearchResults.length > 0) {
                            e.preventDefault();
                            e.stopPropagation();
                            this.selectQuickProduct(this._quickSearchSelectedIndex || 0);
                            return;
                        }
                    }
                    // Enter键不做其他操作
                    return;
                }

            };

            input.addEventListener('keydown', input._quickAddEnterHandler);
        });
    }

    /**
     * 🔥 通过产品编号搜索产品（显示下拉列表）
     */
    async searchQuickProductByNumber(productNumber) {
        const loadingEl = document.getElementById('quick-product-number-loading');
        const matchBtn = document.getElementById('quick-product-match-btn');
        const matchCountEl = document.getElementById('quick-product-match-count');
        const dropdownEl = document.getElementById('quick-product-dropdown');
        const statusEl = document.getElementById('quick-product-search-status');
        const locale = document.documentElement.lang || 'en';

        loadingEl?.classList.remove('hidden');
        matchBtn?.classList.add('hidden');
        statusEl.innerHTML = '';

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'search_product_by_number',
                    nonce: ruiyi_pos_ajax.nonce,
                    product_number: productNumber
                })
            });

            const data = await response.json();
            loadingEl?.classList.add('hidden');

            if (data.success && data.data.products && data.data.products.length > 0) {
                const products = data.data.products;
                this._quickSearchResults = products;
                this._quickSearchSelectedIndex = 0;

                // 🔥 UX改进：不自动打开下拉列表，而是显示"匹配产品 (N)"按钮
                if (matchCountEl) matchCountEl.textContent = products.length;
                matchBtn?.classList.remove('hidden');

                // 🔥 预渲染下拉列表内容（但不显示，等用户点击按钮）
                this._renderQuickProductDropdown(products);
                dropdownEl.classList.add('hidden');

                // 🔥 不清空其他字段 — 用户可以直接填写不同名称和价格创建新产品
                // 只清空 existingId，用户必须通过按钮选择才能关联已有产品
                document.getElementById('quick-product-existing-id').value = '';

                const matchMsg = locale.includes('zh') ? `🔍 找到 ${products.length} 个匹配产品，点击右侧按钮查看` :
                                locale.includes('es') ? `🔍 ${products.length} coincidencias, haga clic para ver` :
                                `🔍 ${products.length} matches found, click to view`;
                statusEl.innerHTML = `<span class="text-blue-600">${matchMsg}</span>`;
            } else {
                // 无匹配结果
                dropdownEl.innerHTML = '';
                dropdownEl.classList.add('hidden');
                matchBtn?.classList.add('hidden');
                this._quickSearchResults = [];
                document.getElementById('quick-product-existing-id').value = '';

                const notFoundMsg = locale.includes('zh') ? '⚠️ 产品未找到，将创建新产品' :
                                   locale.includes('es') ? '⚠️ Producto no encontrado, se creará nuevo' :
                                   '⚠️ Product not found, will create new';
                statusEl.innerHTML = `<span class="text-yellow-600">${notFoundMsg}</span>`;
            }
        } catch (error) {
            console.error('Error searching product by number:', error);
            loadingEl?.classList.add('hidden');
            matchBtn?.classList.add('hidden');
            dropdownEl?.classList.add('hidden');
            statusEl.innerHTML = `<span class="text-red-600">❌ ${locale.includes('zh') ? '搜索出错' : locale.includes('es') ? 'Error de búsqueda' : 'Search error'}</span>`;
        }
    }

    /**
     * 🔥 渲染下拉列表内容（不显示）
     */
    _renderQuickProductDropdown(products) {
        const dropdownEl = document.getElementById('quick-product-dropdown');
        if (!dropdownEl) return;
        let html = '';
        products.forEach((product, index) => {
            const displayPrice = `<span class="font-medium">${this.formatPrice(product.price)}</span>`;
            html += `<div class="quick-product-dropdown-item px-3 py-2 hover:bg-green-50 cursor-pointer border-b border-gray-100 last:border-b-0 flex justify-between items-center ${index === 0 ? 'bg-green-50' : ''}" data-index="${index}" onmousedown="pos.selectQuickProduct(${index})">
                <div class="min-w-0 flex-1">
                    <span class="font-medium text-gray-900">${this.escapeHtml(product.name)}</span>
                    <span class="text-xs text-gray-400 ml-1">#${this.escapeHtml(String(product.product_number || ''))}</span>
                    ${product.sku ? `<span class="text-xs text-gray-400 ml-1">SKU:${this.escapeHtml(product.sku)}</span>` : ''}
                </div>
                <div class="ml-2 text-sm whitespace-nowrap">${displayPrice}</div>
            </div>`;
        });
        dropdownEl.innerHTML = html;
    }

    /**
     * 🔥 切换匹配产品下拉列表显示/隐藏
     */
    toggleQuickProductDropdown() {
        const dropdownEl = document.getElementById('quick-product-dropdown');
        if (!dropdownEl) return;
        if (dropdownEl.classList.contains('hidden')) {
            dropdownEl.classList.remove('hidden');
        } else {
            dropdownEl.classList.add('hidden');
        }
    }

    /**
     * 🔥 从下拉列表选择产品
     */
    selectQuickProduct(index) {
        const products = this._quickSearchResults;
        if (!products || !products[index]) return;

        const product = products[index];
        const locale = document.documentElement.lang || 'en';

        // 填充表单字段（使用 ?? 避免价格0被转为空字符串）
        document.getElementById('quick-product-number').value = product.product_number ?? '';
        document.getElementById('quick-product-name').value = product.name ?? '';
        document.getElementById('quick-product-sku').value = product.sku ?? '';
        document.getElementById('quick-product-price').value = product.price ?? '';
        document.getElementById('quick-product-existing-id').value = product.id ?? '';

        // 关闭下拉列表和匹配按钮
        const dropdownEl = document.getElementById('quick-product-dropdown');
        dropdownEl.classList.add('hidden');
        dropdownEl.innerHTML = '';
        const matchBtn = document.getElementById('quick-product-match-btn');
        if (matchBtn) matchBtn.classList.add('hidden');

        // 显示已选状态
        const statusEl = document.getElementById('quick-product-search-status');
        const msg = locale.includes('zh') ? '✅ 已选择: ' + product.name :
                   locale.includes('es') ? '✅ Seleccionado: ' + product.name :
                   '✅ Selected: ' + product.name;
        statusEl.innerHTML = `<span class="text-green-600">${msg}</span>`;

        // 🔥 UX改进：聚焦到价格输入框，让用户确认或修改价格
        setTimeout(() => {
            const priceInput = document.getElementById('quick-product-price');
            if (priceInput) { priceInput.focus(); priceInput.select(); }
        }, 50);
    }

    /**
     * 🔥 价格标准化：将逗号转为点号，支持欧洲格式（如 1,80 → 1.80）
     */
    normalizePrice(value) {
        if (typeof value !== 'string') value = String(value ?? '');
        // 去除空格，将逗号替换为点号
        value = value.trim().replace(/,/g, '.');
        // 如果有多个点号，只保留最后一个作为小数点（如 1.000.50 → 1000.50）
        const parts = value.split('.');
        if (parts.length > 2) {
            value = parts.slice(0, -1).join('') + '.' + parts[parts.length - 1];
        }
        const num = parseFloat(value);
        return isNaN(num) ? NaN : num;
    }

    async addQuickProductToCart() {
        const productNumber = document.getElementById('quick-product-number').value.trim();
        const name = document.getElementById('quick-product-name').value.trim();
        const sku = document.getElementById('quick-product-sku').value.trim();
        const priceRaw = document.getElementById('quick-product-price').value;
        const quantityRaw = document.getElementById('quick-product-quantity').value;
        const existingId = document.getElementById('quick-product-existing-id').value;
        const locale = document.documentElement.lang || 'en';

        // 🔥 使用 normalizePrice 处理逗号格式价格
        const price = this.normalizePrice(priceRaw);
        // 🔥 Bug 4 修复：使用 parseFloat 支持小数数量
        const quantity = parseFloat(quantityRaw) || 1;

        // 🔥 Bug 5 修复：严格验证必填字段和价格有效性
        if (!name) {
            const msg = locale.includes('zh') ? '请填写产品名称' :
                       locale.includes('es') ? 'Por favor complete el nombre' :
                       'Please fill in product name';
            this.showToast(msg, 'error');
            return;
        }
        if (priceRaw.trim() === '' || isNaN(price) || price < 0) {
            const msg = locale.includes('zh') ? '请输入有效的价格' :
                       locale.includes('es') ? 'Por favor ingrese un precio válido' :
                       'Please enter a valid price';
            this.showToast(msg, 'error');
            return;
        }

        const effectivePrice = price;

        // 如果已存在产品ID，直接添加到购物车
        if (existingId) {
            const product = {
                id: parseInt(existingId),
                name: name,
                sku: sku,
                price: effectivePrice,
                regular_price: price,
                sale_price: null,
                product_number: productNumber
            };

            // 🔥 Bug 2 & 3 修复：检查用户是否修改了价格，如果是则标记为 customPrice
            // 这样 proceedAddToCart 会创建新行而不是合并到已有行
            const originalProduct = this._quickSearchResults?.find(p => p.id == existingId);
            const originalEffectivePrice = originalProduct
                ? originalProduct.price
                : null;
            const userChangedPrice = originalEffectivePrice !== null && Math.abs(effectivePrice - originalEffectivePrice) > 0.001;

            if (userChangedPrice) {
                // 用户修改了价格，直接创建带 customPrice 的购物车项
                const cartItem = {
                    ...product,
                    cartItemId: ++this.cartItemIdCounter,
                    quantity: quantity,
                    originalPrice: originalEffectivePrice,
                    customPrice: true,
                    discountPercent: 0,
                    weightBased: false
                };
                this.cart.push(cartItem);
                this.selectedProductId = cartItem.cartItemId;
                this.updateCart();
            } else {
                // 价格未修改，正常添加（支持小数数量，直接设置数量而非循环）
                const existingItem = this.cart.find(item =>
                    item.id === product.id && !item.weightBased && !item.customPrice
                );
                if (existingItem) {
                    existingItem.quantity += quantity;
                    this.selectedProductId = existingItem.cartItemId;
                    this.updateCart();
                } else {
                    const cartItem = {
                        ...product,
                        cartItemId: ++this.cartItemIdCounter,
                        quantity: quantity,
                        originalPrice: product.price,
                        customPrice: false,
                        discountPercent: 0,
                        weightBased: false
                    };
                    this.cart.push(cartItem);
                    this.selectedProductId = cartItem.cartItemId;
                    this.updateCart();
                }
            }

            const successMsg = locale.includes('zh') ? `✅ ${name} x${quantity} 已成功添加` :
                              locale.includes('es') ? `✅ ${name} x${quantity} añadido correctamente` :
                              `✅ ${name} x${quantity} added successfully`;
            this.showToast(successMsg, 'success');

            // 🔥 保持弹窗打开，重置表单准备添加下一个产品
            this.resetQuickAddProductForm();
            setTimeout(() => {
                const numberInput = document.getElementById('quick-product-number');
                if (numberInput) numberInput.focus();
            }, 100);
            return;
        }

        // 如果产品不存在，先创建产品然后添加到购物车
        // 🔥 发送标准化后的价格到后端（点号格式）
        const normalizedPriceStr = String(price);
        try {
            const data = await this.ajaxRequest({
                pos_action: 'create_product',
                product_name: name,
                product_sku: sku,
                product_number: productNumber,
                product_price: normalizedPriceStr,
                product_stock: '-1'
            });

            if (data.success && data.data.product) {
                const createdProduct = data.data.product;
                const newProduct = {
                    id: createdProduct.id,
                    name: createdProduct.name || name,
                    sku: createdProduct.sku || sku,
                    price: effectivePrice,
                    regular_price: price,
                    sale_price: null,
                    product_number: productNumber,
                    image: createdProduct.image || ''
                };

                // 直接设置数量而非循环添加
                const cartItem = {
                    ...newProduct,
                    cartItemId: ++this.cartItemIdCounter,
                    quantity: quantity,
                    originalPrice: newProduct.price,
                    customPrice: false,
                    discountPercent: 0,
                    weightBased: false
                };
                this.cart.push(cartItem);
                this.selectedProductId = cartItem.cartItemId;
                this.updateCart();

                const successMsg = locale.includes('zh') ? `✅ ${name} x${quantity} 已成功添加` :
                                  locale.includes('es') ? `✅ ${name} x${quantity} añadido correctamente` :
                                  `✅ ${name} x${quantity} added successfully`;
                this.showToast(successMsg, 'success');

                if (typeof this.refreshProductCache === 'function') {
                    this.refreshProductCache();
                }

                // 保持弹窗打开，重置表单准备添加下一个产品
                this.resetQuickAddProductForm();
                setTimeout(() => {
                    const numberInput = document.getElementById('quick-product-number');
                    if (numberInput) numberInput.focus();
                }, 100);
            } else {
                this.showToast(data.data?.message || 'Error creating product', 'error');
            }
        } catch (error) {
            console.error('Error creating product:', error);
            this.showToast('Error creating product', 'error');
        }
    }

    // ========================================
    // 历史订单功能 (Order History)
    // ========================================

    /**
     * 打开历史订单弹窗
     */
    openOrderHistoryModal() {
        const modal = document.getElementById('order-history-modal');
        if (modal) {
            modal.classList.remove('hidden');
            this.loadOrderHistory();
        }
    }

    /**
     * 关闭历史订单弹窗
     */
    closeOrderHistoryModal() {
        const modal = document.getElementById('order-history-modal');
        if (modal) {
            modal.classList.add('hidden');
        }
    }

    /**
     * 加载历史订单列表
     */
    async loadOrderHistory() {
        const loadingEl = document.getElementById('order-history-loading');
        const listEl = document.getElementById('order-history-list');
        const emptyEl = document.getElementById('order-history-empty');

        const search = document.getElementById('order-history-search')?.value || '';
        const status = document.getElementById('order-history-status-filter')?.value || 'all';
        const dateRange = document.getElementById('order-history-date-filter')?.value || 'all';
        const customDate = document.getElementById('order-history-date-picker')?.value || '';

        // 🔥 Show/hide date picker based on selection
        const datePickerWrapper = document.getElementById('order-history-date-picker-wrapper');
        if (datePickerWrapper) {
            if (dateRange === 'custom') {
                datePickerWrapper.classList.remove('hidden');
            } else {
                datePickerWrapper.classList.add('hidden');
            }
        }

        // Show loading
        loadingEl?.classList.remove('hidden');
        listEl?.classList.add('hidden');
        emptyEl?.classList.add('hidden');

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'get_order_history',
                    nonce: ruiyi_pos_ajax.nonce,
                    search: search,
                    status: status,
                    date_range: dateRange,
                    custom_date: customDate
                })
            });

            const data = await response.json();
            loadingEl?.classList.add('hidden');

            if (data.success && data.data.orders && data.data.orders.length > 0) {
                this.renderOrderHistoryList(data.data.orders);
                listEl?.classList.remove('hidden');
            } else {
                emptyEl?.classList.remove('hidden');
            }
        } catch (error) {
            console.error('Error loading order history:', error);
            loadingEl?.classList.add('hidden');
            emptyEl?.classList.remove('hidden');
        }
    }

    /**
     * 渲染历史订单列表
     */
    renderOrderHistoryList(orders) {
        const listEl = document.getElementById('order-history-list');
        if (!listEl) return;

        // 🔥 存储订单数据，供其他函数使用（如openRectificativaModal）
        this.cachedOrders = orders;

        const locale = document.documentElement.lang || 'en';

        const html = orders.map(order => {
            const isCompleted = order.status === 'completed' || order.status === 'wc-completed';
            const isCancelled = order.status === 'cancelled' || order.status === 'wc-cancelled';
            const isPending = !isCompleted && !isCancelled;

            // 🔥 POS退货订单检测
            const isPosRefund = order.is_pos_refund || false;

            // 🔥 Status display
            let statusClass, statusText;
            if (isCancelled && isPosRefund) {
                // POS退货订单 - 使用橙色标记
                statusClass = 'bg-orange-100 text-orange-800';
                statusText = locale.includes('zh') ? '退货' : locale.includes('es') ? 'Devolución' : 'Refund';
            } else if (isCancelled) {
                statusClass = 'bg-red-100 text-red-800';
                statusText = locale.includes('zh') ? '已取消' : locale.includes('es') ? 'Cancelado' : 'Cancelled';
            } else if (isCompleted) {
                statusClass = 'bg-green-100 text-green-800';
                statusText = locale.includes('zh') ? '已完成' : locale.includes('es') ? 'Completado' : 'Completed';
            } else {
                statusClass = 'bg-yellow-100 text-yellow-800';
                statusText = locale.includes('zh') ? '待付款' : locale.includes('es') ? 'Pendiente' : 'Pending';
            }

            // 🔥 支付方式标签
            let paymentBadge = '';
            if (order.payment_type) {
                let paymentLabel = '';
                let paymentBadgeClass = '';
                switch (order.payment_type) {
                    case 'cash':
                        paymentLabel = locale.includes('zh') ? '现金' : locale.includes('es') ? 'Efectivo' : 'Cash';
                        paymentBadgeClass = 'bg-green-100 text-green-800';
                        break;
                    case 'card':
                        paymentLabel = locale.includes('zh') ? '刷卡' : locale.includes('es') ? 'Tarjeta' : 'Card';
                        paymentBadgeClass = 'bg-blue-100 text-blue-800';
                        break;
                    case 'transfer':
                        paymentLabel = locale.includes('zh') ? '转账' : locale.includes('es') ? 'Transferencia' : 'Transfer';
                        paymentBadgeClass = 'bg-purple-100 text-purple-800';
                        break;
                    case 'cash_card':
                        paymentLabel = locale.includes('zh') ? '现金+刷卡' : locale.includes('es') ? 'Mixto' : 'Mixed';
                        paymentBadgeClass = 'bg-orange-100 text-orange-800';
                        break;
                    default:
                        paymentLabel = order.payment_type;
                        paymentBadgeClass = 'bg-gray-100 text-gray-800';
                }
                paymentBadge = `<span class="px-2 py-1 rounded-full text-xs font-medium ${paymentBadgeClass}">${paymentLabel}</span>`;
            }

            // 🔥 只有同时有发票号和PDF才算已开票
            const hasInvoice = !!(order.invoice_label && order.invoice_pdf_url);
            // 🔥 Display invoice_label only if truly invoiced (with PDF), otherwise show order number
            const displayNumber = hasInvoice ? order.invoice_label : `#${order.number}`;

            // 🔥 Build action buttons based on order status
            let actionButtons = '';

            if (isCancelled) {
                // 已取消订单 - 显示两个下载按钮（原发票 + 退货发票）
                if (order.has_rectificativa && order.rectificativa_label) {
                    // 已有退货发票 - 显示两个下载按钮
                    const originalLabel = locale.includes('zh') ? '原发票' : locale.includes('es') ? 'Factura' : 'Invoice';
                    const rectLabel = locale.includes('zh') ? '退货发票' : locale.includes('es') ? 'Rectificativa' : 'Rectificative';

                    let downloadButtons = '';

                    // Original invoice download button
                    if (order.invoice_pdf_url) {
                        downloadButtons += `
                            <button onclick="pos.downloadPdfToDir('${order.invoice_pdf_url}', '${order.invoice_label.toLowerCase()}.pdf')"
                               class="px-3 py-1.5 rounded-lg text-xs font-medium transition-colors bg-blue-500 hover:bg-blue-600 text-white inline-flex items-center cursor-pointer">
                                <svg class="w-3 h-3 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/>
                                </svg>
                                ${originalLabel}
                            </button>
                        `;
                    }

                    // Rectificativa download button
                    if (order.rectificativa_pdf_url) {
                        downloadButtons += `
                            <button onclick="pos.downloadPdfToDir('${order.rectificativa_pdf_url}', '${order.rectificativa_label.toLowerCase()}.pdf')"
                               class="px-3 py-1.5 rounded-lg text-xs font-medium transition-colors bg-orange-500 hover:bg-orange-600 text-white inline-flex items-center cursor-pointer">
                                <svg class="w-3 h-3 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/>
                                </svg>
                                ${rectLabel}
                            </button>
                        `;
                    }

                    // If no PDF URLs available, just show text
                    if (!downloadButtons) {
                        downloadButtons = `
                            <div class="text-xs text-gray-500 text-right">
                                <div class="font-medium text-orange-600">${order.rectificativa_label}</div>
                                <div>${locale.includes('zh') ? '退货发票' : locale.includes('es') ? 'Fact. Rectificativa' : 'Rectificative'}</div>
                            </div>
                        `;
                    }

                    actionButtons = `<div class="flex gap-2">${downloadButtons}</div>`;
                } else if (hasInvoice) {
                    // 有原发票但无退货发票 - 显示生成按钮
                    const rectBtnText = locale.includes('zh') ? '生成退货发票' : locale.includes('es') ? 'Generar Rectificativa' : 'Generate Rectificative';
                    actionButtons = `
                        <button onclick="pos.openRectificativaModal(${order.id})"
                                class="px-4 py-2 rounded-lg text-sm font-medium transition-colors bg-orange-500 hover:bg-orange-600 text-white">
                            ${rectBtnText}
                        </button>
                    `;
                } else {
                    // 无原发票 - 显示提示
                    const noInvoiceText = locale.includes('zh') ? '无发票' : locale.includes('es') ? 'Sin factura' : 'No invoice';
                    actionButtons = `<span class="text-gray-400 text-sm">${noInvoiceText}</span>`;
                }
            } else if (isCompleted) {
                // 已完成订单 - 根据是否已开票显示不同按钮
                const returnBtnText = locale.includes('zh') ? '退货' : locale.includes('es') ? 'Devolución' : 'Return';
                const voidBtnText = locale.includes('zh') ? '作废' : locale.includes('es') ? 'Anular' : 'Void';

                let invoiceOrDownloadBtn = '';
                // 🔥 只有在批发商发票功能开启时才显示发票相关按钮
                if (pos.wholesaleInvoiceEnabled) {
                    // 🔥 检查发票是否有客户信息（公司名或CIF）
                    const hasInvoiceCustomer = !!(order.invoice_customer_company || order.invoice_customer_cif);

                    if (order.invoice_pdf_url && hasInvoice && hasInvoiceCustomer) {
                        // 已开票且有客户信息 - 显示下载发票 + 编辑按钮
                        const downloadBtnText = locale.includes('zh') ? '下载发票' : locale.includes('es') ? 'Descargar' : 'Download';
                        const editBtnText = locale.includes('zh') ? '编辑' : locale.includes('es') ? 'Editar' : 'Edit';
                        invoiceOrDownloadBtn = `
                            <button onclick="pos.downloadPdfToDir('${order.invoice_pdf_url}', '${order.invoice_label.toLowerCase()}.pdf')"
                               class="px-3 py-1.5 rounded-lg text-xs font-medium transition-colors bg-blue-500 hover:bg-blue-600 text-white inline-flex items-center cursor-pointer">
                                <svg class="w-3 h-3 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/>
                                </svg>
                                ${downloadBtnText}
                            </button>
                            <button onclick="pos.openInvoiceCustomerModal(${order.id}, 'invoice')"
                                    class="px-3 py-1.5 rounded-lg text-xs font-medium transition-colors bg-gray-500 hover:bg-gray-600 text-white">
                                ${editBtnText}
                            </button>
                        `;
                    } else if (order.invoice_pdf_url && hasInvoice && !hasInvoiceCustomer) {
                        // 已开票但无客户信息 - 显示创建发票按钮（要求填写客户信息）
                        const createBtnText = locale.includes('zh') ? '创建发票' : locale.includes('es') ? 'Crear Factura' : 'Create Invoice';
                        invoiceOrDownloadBtn = `
                            <button onclick="pos.openInvoiceCustomerModal(${order.id}, 'invoice')"
                                    class="px-4 py-2 rounded-lg text-sm font-medium transition-colors bg-orange-500 hover:bg-orange-600 text-white">
                                ${createBtnText}
                            </button>
                        `;
                    } else {
                        // 未开票或无PDF文件 - 显示开票按钮
                        const invoiceBtnText = locale.includes('zh') ? '开票' : locale.includes('es') ? 'Factura' : 'Invoice';
                        invoiceOrDownloadBtn = `
                            <button onclick="pos.openInvoiceCustomerModal(${order.id}, 'invoice')"
                                    class="px-4 py-2 rounded-lg text-sm font-medium transition-colors bg-purple-600 hover:bg-purple-700 text-white">
                                ${invoiceBtnText}
                            </button>
                        `;
                    }
                }

                // 🔥 打印发票/创建发票按钮仅在批发商发票功能关闭时显示
                let invoiceBtn = '';
                if (!pos.wholesaleInvoiceEnabled) {
                    const createInvoiceBtnText = locale.includes('zh') ? '创建发票' : locale.includes('es') ? 'Crear Factura' : 'Create Invoice';
                    const printInvoiceBtnText = locale.includes('zh') ? '打印发票' : locale.includes('es') ? 'Imprimir Factura' : 'Print Invoice';
                    const hasCustomerInfo = !!(order.customer_name || order.customer_phone || order.customer_company);
                    invoiceBtn = hasCustomerInfo ? `
                        <button onclick="pos.printHistoricalReceipt(${order.id})"
                                class="px-4 py-2 rounded-lg text-sm font-medium transition-colors bg-teal-600 hover:bg-teal-700 text-white">
                            ${printInvoiceBtnText}
                        </button>
                    ` : `
                        <button onclick="pos.openOrderInvoiceModal(${order.id})"
                                class="px-4 py-2 rounded-lg text-sm font-medium transition-colors bg-teal-600 hover:bg-teal-700 text-white">
                            ${createInvoiceBtnText}
                        </button>
                    `;
                }

                // 🔥 退货按钮仅在批发商发票功能开启时显示
                const returnBtn = pos.wholesaleInvoiceEnabled ? `
                    <button onclick="pos.openRectificativaModal(${order.id})"
                            class="px-4 py-2 rounded-lg text-sm font-medium transition-colors bg-orange-500 hover:bg-orange-600 text-white">
                        ${returnBtnText}
                    </button>
                ` : '';

                actionButtons = `
                    ${invoiceBtn}
                    ${invoiceOrDownloadBtn}
                    ${returnBtn}
                    <button onclick="pos.voidOrder(${order.id}, false)"
                            class="px-4 py-2 rounded-lg text-sm font-medium transition-colors bg-red-500 hover:bg-red-600 text-white">
                        ${voidBtnText}
                    </button>
                `;
            } else {
                // 待付款订单 - 显示预结单、完成和删除按钮
                const albaranBtnText = locale.includes('zh') ? '预结单' : locale.includes('es') ? 'Albarán' : 'Albarán';
                const completeBtnText = locale.includes('zh') ? '完成' : locale.includes('es') ? 'Completar' : 'Complete';
                const deleteBtnText = locale.includes('zh') ? '删除' : locale.includes('es') ? 'Eliminar' : 'Delete';
                actionButtons = `
                    <button onclick="pos.openInvoiceCustomerModal(${order.id}, 'delivery')"
                            class="px-4 py-2 rounded-lg text-sm font-medium transition-colors bg-orange-500 hover:bg-orange-600 text-white">
                        ${albaranBtnText}
                    </button>
                    ${pos.wholesaleInvoiceEnabled ? `
                    <button onclick="pos.completeOrder(${order.id})"
                            class="px-4 py-2 rounded-lg text-sm font-medium transition-colors bg-green-500 hover:bg-green-600 text-white">
                        ${completeBtnText}
                    </button>
                    ` : ''}
                    <button onclick="pos.voidOrder(${order.id}, true)"
                            class="px-4 py-2 rounded-lg text-sm font-medium transition-colors bg-red-500 hover:bg-red-600 text-white">
                        ${deleteBtnText}
                    </button>
                `;
            }

            // 🔥 金额显示 - 处理退货订单和已取消订单
            const totalRaw = parseFloat(order.total_raw || 0);
            let totalDisplay, totalClass;
            if (isPosRefund) {
                // POS退货订单：金额已经是负数，直接显示（红色，无删除线）
                totalDisplay = order.total;
                totalClass = 'text-red-600 font-bold';
            } else if (isCancelled) {
                // 普通已取消订单：显示负数 + 删除线
                totalDisplay = totalRaw < 0 ? order.total : `-${order.total}`;
                totalClass = 'text-red-600 line-through';
            } else {
                totalDisplay = order.total;
                totalClass = 'text-gray-900';
            }

            // 🔥 通用按钮 - 查看和打印小票 (使用文字而非图标) - 已取消订单不显示
            const viewBtnText = locale.includes('zh') ? '查看' : locale.includes('es') ? 'Ver' : 'View';
            const printBtnText = locale.includes('zh') ? '打印小票' : locale.includes('es') ? 'Imprimir Ticket' : 'Print Receipt';
            // 🔥 根据设置决定是否显示打印小票按钮
            const showPrintBtn = ruiyi_pos_ajax.print_receipt_visible;
            const printButton = showPrintBtn ? `
                <button onclick="pos.printHistoricalReceipt(${order.id})"
                        class="px-3 py-2 rounded-lg text-sm font-medium transition-colors bg-green-600 hover:bg-green-700 text-white">
                    ${printBtnText}
                </button>
            ` : '';
            const commonButtons = (isCancelled && !isPosRefund) ? '' : `
                <button onclick="pos.viewOrderDetails(${order.id})"
                        class="px-3 py-2 rounded-lg text-sm font-medium transition-colors bg-gray-500 hover:bg-gray-600 text-white">
                    ${viewBtnText}
                </button>
                ${printButton}
            `;

            return `
                <div class="flex items-center justify-between p-4 border-b border-gray-200 hover:bg-gray-50 transition-colors ${isPosRefund ? 'bg-orange-50' : isCancelled ? 'bg-red-50' : ''}">
                    <div class="flex-1">
                        <div class="flex items-center gap-3">
                            <span class="font-semibold ${hasInvoice ? 'text-blue-600' : 'text-gray-400'}">${displayNumber}</span>
                            <span class="px-2 py-1 rounded-full text-xs font-medium ${statusClass}">${statusText}</span>
                            ${paymentBadge}
                        </div>
                        <div class="mt-1 text-sm text-gray-500">
                            <span>${order.date}</span>
                            ${order.customer_name ? `<span class="ml-3">${order.customer_name}</span>` : ''}
                        </div>
                    </div>
                    <div class="flex items-center gap-2">
                        <span class="text-lg font-bold ${totalClass} mr-2">${totalDisplay}</span>
                        ${commonButtons}
                        ${actionButtons}
                    </div>
                </div>
            `;
        }).join('');

        listEl.innerHTML = html;
    }

    /**
     * 打开发票客户信息弹窗
     */
    openInvoiceCustomerModal(orderId, type = 'invoice') {
        const modal = document.getElementById('invoice-customer-modal');
        if (!modal) return;

        // 🔥 关键修复：清空Varios输入框并失焦，防止键盘输入错误聚焦
        const variosInput = document.getElementById('varios-price-input');
        if (variosInput) {
            variosInput.value = '';
            variosInput.blur();
        }

        // Store order info
        document.getElementById('invoice-order-id').value = orderId;
        document.getElementById('invoice-type').value = type;

        // Update title and button text
        const locale = document.documentElement.lang || 'en';
        const orderNumberEl = document.getElementById('invoice-customer-order-number');
        const downloadBtnText = document.getElementById('invoice-download-btn-text');

        if (orderNumberEl) {
            orderNumberEl.textContent = `${locale.includes('zh') ? '订单' : locale.includes('es') ? 'Pedido' : 'Order'} #${orderId}`;
        }

        if (downloadBtnText) {
            if (type === 'invoice') {
                downloadBtnText.textContent = locale.includes('zh') ? '下载发票' :
                                             locale.includes('es') ? 'Descargar Factura' : 'Download Invoice';
            } else {
                downloadBtnText.textContent = locale.includes('zh') ? '下载预结单' :
                                             locale.includes('es') ? 'Descargar Albarán' : 'Download Albarán';
            }
        }

        // Clear form
        document.getElementById('invoice-customer-id').value = '';
        document.getElementById('invoice-customer-number').value = ''; // 🔥 Clear customer number
        document.getElementById('invoice-customer-search').value = '';
        document.getElementById('invoice-customer-name').value = '';
        document.getElementById('invoice-company').value = '';
        document.getElementById('invoice-cif').value = '';
        document.getElementById('invoice-address').value = '';
        document.getElementById('invoice-address-2').value = '';
        document.getElementById('invoice-city').value = '';
        document.getElementById('invoice-state').value = '';
        document.getElementById('invoice-postcode').value = '';
        document.getElementById('invoice-country').value = 'España';
        document.getElementById('invoice-phone').value = ''; // 🔥 Textarea for multiple phones
        document.getElementById('invoice-email').value = '';
        // 🔥 清空业务员输入框
        const spInput = document.getElementById('invoice-salesperson-input');
        if (spInput) spInput.value = '';
        document.getElementById('invoice-salesperson').value = '';
        // 🔥 使用公司设置中的默认银行信息
        document.getElementById('invoice-payment-method').value = 'cash';
        const defaultBank = ruiyi_pos_ajax.default_bank || {};
        document.getElementById('invoice-bank-name').value = defaultBank.bank_name || '';
        document.getElementById('invoice-bank-iban').value = defaultBank.bank_iban || '';
        document.getElementById('invoice-bank-bic').value = defaultBank.bank_bic || '';
        // 🔥 清空备注
        document.getElementById('invoice-notes').value = '';

        // Hide search results
        const searchResults = document.getElementById('invoice-customer-search-results');
        if (searchResults) searchResults.classList.add('hidden');

        // Load salespersons dropdown
        this.loadSalespersons();

        // Initialize customer search autocomplete
        this.initCustomerSearchAutocomplete();

        // Load order customer data if available
        this.loadInvoiceCustomerData(orderId);

        modal.classList.remove('hidden');

        // 🔥 关键修复：聚焦到客户搜索输入框
        setTimeout(() => {
            const searchInput = document.getElementById('invoice-customer-search');
            if (searchInput) {
                searchInput.focus();
            }
        }, 100);
    }

    /**
     * 关闭发票客户信息弹窗
     */
    closeInvoiceCustomerModal() {
        const modal = document.getElementById('invoice-customer-modal');
        if (modal) {
            modal.classList.add('hidden');
        }
    }

    /**
     * 加载订单的客户信息（用于发票）
     */
    async loadInvoiceCustomerData(orderId) {
        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'get_order_customer_data',
                    nonce: ruiyi_pos_ajax.nonce,
                    order_id: orderId
                })
            });

            const data = await response.json();

            if (data.success && data.data) {
                const customer = data.data;
                if (customer.name) document.getElementById('invoice-customer-name').value = customer.name;
                if (customer.company) document.getElementById('invoice-company').value = customer.company;
                if (customer.cif) document.getElementById('invoice-cif').value = customer.cif;
                if (customer.address) document.getElementById('invoice-address').value = customer.address;
                if (customer.address_2) document.getElementById('invoice-address-2').value = customer.address_2;
                if (customer.city) document.getElementById('invoice-city').value = customer.city;
                if (customer.state) document.getElementById('invoice-state').value = customer.state;
                if (customer.postcode) document.getElementById('invoice-postcode').value = customer.postcode;
                if (customer.country) document.getElementById('invoice-country').value = customer.country;
                if (customer.phone) document.getElementById('invoice-phone').value = customer.phone; // 🔥 May contain multiple phones
                if (customer.email) document.getElementById('invoice-email').value = customer.email;
                // 🔥 加载支付方式和银行信息
                if (customer.payment_method) document.getElementById('invoice-payment-method').value = customer.payment_method;
                if (customer.bank_name) document.getElementById('invoice-bank-name').value = customer.bank_name;
                if (customer.bank_iban) document.getElementById('invoice-bank-iban').value = customer.bank_iban;
                if (customer.bank_bic) document.getElementById('invoice-bank-bic').value = customer.bank_bic;
            }
        } catch (error) {
            console.error('Error loading customer data:', error);
        }
    }

    /**
     * 下载发票文档（发票或送货单）- 先显示文件名弹窗
     */
    async downloadInvoiceDocument() {
        const form = document.getElementById('invoice-customer-form');
        if (!form.checkValidity()) {
            form.reportValidity();
            return;
        }

        const orderId = document.getElementById('invoice-order-id').value;
        const invoiceType = document.getElementById('invoice-type').value;
        const customerId = document.getElementById('invoice-customer-id').value;
        const salespersonId = document.getElementById('invoice-salesperson').value;
        const salespersonInput = document.getElementById('invoice-salesperson-input');
        const salespersonName = salespersonInput ? salespersonInput.value.trim() : '';

        // 🔥 公司名称作为客户名称使用
        const companyName = document.getElementById('invoice-company').value;
        document.getElementById('invoice-customer-name').value = companyName;

        // 🔥 获取客户编号
        const customerNumber = document.getElementById('invoice-customer-number').value;

        const customerData = {
            customer_id: customerId,
            customer_number: customerNumber, // 🔥 客户编号
            salesperson_id: salespersonId,
            // 🔥 如果没有选择现有业务员，传递新业务员名称供自动创建
            new_salesperson_name: (!salespersonId && salespersonName) ? salespersonName : '',
            name: companyName, // 使用公司名称作为客户名称
            company: companyName,
            cif: document.getElementById('invoice-cif').value,
            address: document.getElementById('invoice-address').value,
            address_2: document.getElementById('invoice-address-2').value,
            city: document.getElementById('invoice-city').value,
            state: document.getElementById('invoice-state').value,
            postcode: document.getElementById('invoice-postcode').value,
            country: document.getElementById('invoice-country').value,
            phone: document.getElementById('invoice-phone').value, // 🔥 Supports multiple phones (one per line)
            email: document.getElementById('invoice-email').value,
            // 🔥 银行信息和支付方式
            payment_method: document.getElementById('invoice-payment-method').value,
            bank_name: document.getElementById('invoice-bank-name').value,
            bank_iban: document.getElementById('invoice-bank-iban').value,
            bank_bic: document.getElementById('invoice-bank-bic').value,
            // 🔥 备注
            notes: document.getElementById('invoice-notes').value
        };

        const locale = document.documentElement.lang || 'en';

        // 🔥 生成默认文件名
        const cif = document.getElementById('invoice-cif').value || '';
        const defaultFilename = invoiceType === 'invoice'
            ? `Factura_${orderId}`
            : `Albaran_${orderId}`;

        // 🔥 检查是否启用自定义文件名功能
        const pdfCustomFilenameEnabled = localStorage.getItem('pos_pdf_custom_filename') === 'true';

        if (pdfCustomFilenameEnabled) {
            // 🔥 存储待下载数据
            this.pendingPdfDownload = {
                orderId,
                invoiceType,
                customerData,
                defaultFilename
            };

            // 🔥 显示文件名输入弹窗
            const modal = document.getElementById('pdf-filename-modal');
            const filenameInput = document.getElementById('pdf-custom-filename');
            const defaultFilenameHint = document.getElementById('pdf-default-filename');

            filenameInput.value = defaultFilename;
            defaultFilenameHint.textContent = locale.includes('zh')
                ? `默认文件名: ${defaultFilename}.pdf`
                : locale.includes('es')
                ? `Nombre por defecto: ${defaultFilename}.pdf`
                : `Default filename: ${defaultFilename}.pdf`;

            modal.classList.remove('hidden');
            filenameInput.focus();
            filenameInput.select();
        } else {
            // 🔥 直接下载，使用默认文件名
            this.pendingPdfDownload = {
                orderId,
                invoiceType,
                customerData,
                defaultFilename
            };
            // 直接调用下载，使用默认文件名
            this.executeDownload(orderId, invoiceType, customerData, defaultFilename);
        }
    }

    /**
     * 执行下载（内部方法）
     */
    async executeDownload(orderId, invoiceType, customerData, filename) {
        const downloadBtn = document.getElementById('invoice-download-btn');
        const originalText = downloadBtn.innerHTML;
        const locale = document.documentElement.lang || 'en';

        // Show loading state
        downloadBtn.disabled = true;
        downloadBtn.innerHTML = `
            <svg class="animate-spin w-5 h-5 mr-2" fill="none" viewBox="0 0 24 24">
                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
            ${locale.includes('zh') ? '处理中...' : locale.includes('es') ? 'Procesando...' : 'Processing...'}
        `;

        try {
            const action = invoiceType === 'invoice' ? 'generate_invoice' : 'generate_delivery_note';

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: action,
                    nonce: ruiyi_pos_ajax.nonce,
                    order_id: orderId,
                    customer_data: JSON.stringify(customerData)
                })
            });

            const data = await response.json();

            if (data.success && data.data.pdf_url) {
                // 🔥 优先使用后端返回的文件名（与发票号一致），其次用传入的文件名
                const finalFilename = data.data.filename || (filename ? `${filename}.pdf` : 'invoice.pdf');

                await this.downloadPdfToDir(data.data.pdf_url, finalFilename);
                this.closeInvoiceCustomerModal();
            } else {
                this.showToast(data.data?.message || 'Error generating document', 'error');
            }
        } catch (error) {
            console.error('Error generating document:', error);
            this.showToast('Error generating document', 'error');
        } finally {
            downloadBtn.disabled = false;
            downloadBtn.innerHTML = originalText;
        }
    }

    /**
     * 关闭PDF文件名弹窗
     */
    closePdfFilenameModal() {
        const modal = document.getElementById('pdf-filename-modal');
        modal.classList.add('hidden');
        this.pendingPdfDownload = null;
    }

    /**
     * 确认下载PDF（带自定义文件名）
     */
    async confirmPdfDownload() {
        if (!this.pendingPdfDownload) return;

        const { orderId, invoiceType, customerData } = this.pendingPdfDownload;
        const customFilename = document.getElementById('pdf-custom-filename').value.trim();

        // 关闭文件名弹窗
        this.closePdfFilenameModal();

        // 使用自定义文件名下载
        this.executeDownload(orderId, invoiceType, customerData, customFilename);
    }

    /**
     * 加载业务员列表到datalist (支持选择或输入新名称)
     */
    async loadSalespersons() {
        const datalist = document.getElementById('invoice-salesperson-list');
        const input = document.getElementById('invoice-salesperson-input');
        const hiddenInput = document.getElementById('invoice-salesperson');
        if (!datalist || !input) return;

        // Store salesperson data for matching
        this.salespersonsList = [];

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'get_salespersons',
                    nonce: ruiyi_pos_ajax.nonce
                })
            });

            const data = await response.json();

            if (data.success && data.data) {
                // Clear and rebuild datalist options
                datalist.innerHTML = '';
                this.salespersonsList = data.data;

                data.data.forEach(sp => {
                    const option = document.createElement('option');
                    option.value = sp.name + (sp.region ? ` (${sp.region})` : '');
                    option.dataset.id = sp.id;
                    datalist.appendChild(option);
                });

                // Add event listener to match input with existing salesperson
                input.addEventListener('input', () => {
                    const inputValue = input.value.trim();
                    const matchedSp = this.salespersonsList.find(sp => {
                        const displayName = sp.name + (sp.region ? ` (${sp.region})` : '');
                        return displayName === inputValue || sp.name === inputValue;
                    });

                    if (matchedSp) {
                        hiddenInput.value = matchedSp.id;
                    } else {
                        // New salesperson name - will be created on submit
                        hiddenInput.value = '';
                    }
                });
            }
        } catch (error) {
            console.error('Error loading salespersons:', error);
        }
    }

    /**
     * 初始化客户搜索自动完成
     */
    initCustomerSearchAutocomplete() {
        const searchInput = document.getElementById('invoice-customer-search');
        const resultsDiv = document.getElementById('invoice-customer-search-results');
        const customerNumberInput = document.getElementById('invoice-customer-number');

        if (!searchInput || !resultsDiv) return;

        // Remove existing listeners by cloning
        const newSearchInput = searchInput.cloneNode(true);
        searchInput.parentNode.replaceChild(newSearchInput, searchInput);

        let debounceTimer;

        newSearchInput.addEventListener('input', (e) => {
            const query = e.target.value.trim();
            const searchIcon = document.getElementById('customer-search-icon');
            const searchLoading = document.getElementById('customer-search-loading');

            // Clear previous timer
            clearTimeout(debounceTimer);

            // Allow single digit for numeric queries (customer number), otherwise require 2+ chars
            const isNumeric = /^\d+$/.test(query);
            const minLength = isNumeric ? 1 : 2;

            if (query.length < minLength) {
                resultsDiv.classList.add('hidden');
                // Hide loading, show search icon
                if (searchLoading) searchLoading.classList.add('hidden');
                if (searchIcon) searchIcon.classList.remove('hidden');
                return;
            }

            // Show loading spinner immediately
            if (searchIcon) searchIcon.classList.add('hidden');
            if (searchLoading) searchLoading.classList.remove('hidden');

            // Debounce: 300ms
            debounceTimer = setTimeout(() => {
                this.searchCustomers(query);
            }, 300);
        });

        // Hide results when clicking outside
        document.addEventListener('click', (e) => {
            if (!e.target.closest('#invoice-customer-search') && !e.target.closest('#invoice-customer-search-results')) {
                resultsDiv.classList.add('hidden');
            }
        });

        // 🔥 新客户编号验证 - 检查编号是否已被使用
        if (customerNumberInput) {
            const newNumberInput = customerNumberInput.cloneNode(true);
            customerNumberInput.parentNode.replaceChild(newNumberInput, customerNumberInput);

            let numberValidationTimer;
            const validationDiv = document.getElementById('customer-number-validation');
            const numberLoading = document.getElementById('customer-number-loading');
            const locale = document.documentElement.lang || 'en';

            newNumberInput.addEventListener('input', (e) => {
                const customerNumber = e.target.value.trim();

                clearTimeout(numberValidationTimer);

                // Reset validation
                if (validationDiv) {
                    validationDiv.classList.add('hidden');
                    validationDiv.textContent = '';
                }
                newNumberInput.classList.remove('border-red-500', 'border-green-500');

                // Hide loading spinner
                if (numberLoading) numberLoading.classList.add('hidden');

                if (!customerNumber || customerNumber.length === 0) {
                    return;
                }

                // Show loading spinner immediately
                if (numberLoading) numberLoading.classList.remove('hidden');

                // Debounce: 500ms
                numberValidationTimer = setTimeout(() => {
                    this.checkCustomerNumberExists(customerNumber, newNumberInput, validationDiv, numberLoading);
                }, 500);
            });
        }
    }

    /**
     * 检查客户编号是否已存在
     * 🔥 该字段仅用于创建新客户，所以不需要排除任何ID
     */
    async checkCustomerNumberExists(customerNumber, inputElement, validationDiv, loadingSpinner) {
        const locale = document.documentElement.lang || 'en';

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'check_customer_number',
                    nonce: ruiyi_pos_ajax.nonce,
                    customer_number: customerNumber,
                    exclude_id: 0  // 🔥 始终检查所有客户，不排除任何ID
                })
            });

            const data = await response.json();

            // Hide loading spinner
            if (loadingSpinner) loadingSpinner.classList.add('hidden');

            if (data.success) {
                if (data.data.exists) {
                    // Number already exists - show error
                    inputElement.classList.add('border-red-500');
                    inputElement.classList.remove('border-green-500');
                    if (validationDiv) {
                        validationDiv.classList.remove('hidden', 'text-green-600');
                        validationDiv.classList.add('text-red-600');
                        validationDiv.innerHTML = locale.includes('zh')
                            ? `<span class="font-medium">编号已存在:</span> ${data.data.customer_name} (${data.data.customer_cif || 'N/A'})`
                            : locale.includes('es')
                            ? `<span class="font-medium">Nº existe:</span> ${data.data.customer_name} (${data.data.customer_cif || 'N/A'})`
                            : `<span class="font-medium"># exists:</span> ${data.data.customer_name} (${data.data.customer_cif || 'N/A'})`;
                    }
                } else {
                    // Number is available - show success
                    inputElement.classList.add('border-green-500');
                    inputElement.classList.remove('border-red-500');
                    if (validationDiv) {
                        validationDiv.classList.remove('hidden', 'text-red-600');
                        validationDiv.classList.add('text-green-600');
                        validationDiv.textContent = locale.includes('zh')
                            ? '✓ 编号可用'
                            : locale.includes('es')
                            ? '✓ Nº disponible'
                            : '✓ # available';
                    }
                }
            }
        } catch (error) {
            console.error('Error checking customer number:', error);
            // Hide loading spinner on error
            if (loadingSpinner) loadingSpinner.classList.add('hidden');
        }
    }

    /**
     * 搜索客户 - 支持通过名称、CIF或客户编号搜索
     */
    async searchCustomers(query) {
        const resultsDiv = document.getElementById('invoice-customer-search-results');
        const searchIcon = document.getElementById('customer-search-icon');
        const searchLoading = document.getElementById('customer-search-loading');
        if (!resultsDiv) return;

        const locale = document.documentElement.lang || 'en';

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'search_customers',
                    nonce: ruiyi_pos_ajax.nonce,
                    query: query
                })
            });

            const data = await response.json();

            // Hide loading, show search icon
            if (searchLoading) searchLoading.classList.add('hidden');
            if (searchIcon) searchIcon.classList.remove('hidden');

            if (data.success && data.data && data.data.length > 0) {
                resultsDiv.innerHTML = data.data.map(customer => `
                    <div class="px-4 py-3 hover:bg-purple-50 cursor-pointer border-b border-gray-100 last:border-0"
                         onclick="pos.selectCustomer(${customer.id})">
                        <div class="flex items-center">
                            ${customer.customer_number ? `<span class="inline-flex items-center justify-center min-w-[28px] h-7 px-2 bg-blue-600 text-white text-xs font-bold rounded-full mr-2">#${customer.customer_number}</span>` : ''}
                            <span class="font-medium text-gray-900">${customer.company || customer.customer_name}</span>
                        </div>
                        <div class="text-sm text-gray-500 ${customer.customer_number ? 'ml-9' : ''}">
                            ${customer.cif ? `<span class="mr-3">CIF: ${customer.cif}</span>` : ''}
                            ${customer.customer_name && customer.company ? `<span>${customer.customer_name}</span>` : ''}
                        </div>
                        ${customer.city ? `<div class="text-xs text-gray-400 ${customer.customer_number ? 'ml-9' : ''}">${customer.city}${customer.state ? ', ' + customer.state : ''}</div>` : ''}
                    </div>
                `).join('');
                resultsDiv.classList.remove('hidden');
            } else {
                const noResultsText = locale.includes('zh') ? '未找到匹配客户' :
                                     locale.includes('es') ? 'No se encontraron clientes' : 'No customers found';
                resultsDiv.innerHTML = `<div class="px-4 py-3 text-gray-500 text-center">${noResultsText}</div>`;
                resultsDiv.classList.remove('hidden');
            }
        } catch (error) {
            console.error('Error searching customers:', error);
            // Hide loading, show search icon on error
            if (searchLoading) searchLoading.classList.add('hidden');
            if (searchIcon) searchIcon.classList.remove('hidden');
            resultsDiv.classList.add('hidden');
        }
    }

    /**
     * 选择客户并自动填充表单
     */
    async selectCustomer(customerId) {
        const resultsDiv = document.getElementById('invoice-customer-search-results');
        if (resultsDiv) resultsDiv.classList.add('hidden');

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'get_customer_data',
                    nonce: ruiyi_pos_ajax.nonce,
                    customer_id: customerId
                })
            });

            const data = await response.json();

            if (data.success && data.data) {
                const customer = data.data;

                // Store customer ID
                document.getElementById('invoice-customer-id').value = customerId;

                // 🔥 清空新客户编号字段（该字段仅用于创建新客户）
                const customerNumberInput = document.getElementById('invoice-customer-number');
                if (customerNumberInput) {
                    customerNumberInput.value = ''; // 选择已有客户时清空此字段
                    customerNumberInput.classList.remove('border-red-500', 'border-green-500');
                    const validationDiv = document.getElementById('customer-number-validation');
                    if (validationDiv) {
                        validationDiv.classList.add('hidden');
                        validationDiv.textContent = '';
                    }
                }

                // Update search input with selected customer
                const searchInput = document.getElementById('invoice-customer-search');
                if (searchInput) {
                    searchInput.value = customer.company || customer.customer_name || '';
                }

                // Fill form fields (公司名称作为主要显示字段)
                if (customer.company) {
                    document.getElementById('invoice-company').value = customer.company;
                    // 🔥 使用公司名称填充隐藏的客户名称字段
                    document.getElementById('invoice-customer-name').value = customer.company;
                }
                if (customer.cif) document.getElementById('invoice-cif').value = customer.cif;
                if (customer.address) document.getElementById('invoice-address').value = customer.address;
                if (customer.address_2) document.getElementById('invoice-address-2').value = customer.address_2;
                if (customer.city) document.getElementById('invoice-city').value = customer.city;
                if (customer.state) document.getElementById('invoice-state').value = customer.state;
                if (customer.postcode) document.getElementById('invoice-postcode').value = customer.postcode;
                if (customer.country) document.getElementById('invoice-country').value = customer.country;
                if (customer.phone) document.getElementById('invoice-phone').value = customer.phone; // 🔥 May contain multiple phones
                if (customer.email) document.getElementById('invoice-email').value = customer.email;

                // Set salesperson if available (填充业务员输入框和隐藏ID)
                if (customer.salesperson_id) {
                    document.getElementById('invoice-salesperson').value = customer.salesperson_id;
                    // 🔥 查找对应的业务员名称并填充输入框
                    if (this.salespersonsList) {
                        const sp = this.salespersonsList.find(s => s.id == customer.salesperson_id);
                        if (sp) {
                            const spInput = document.getElementById('invoice-salesperson-input');
                            if (spInput) {
                                spInput.value = sp.name + (sp.region ? ` (${sp.region})` : '');
                            }
                        }
                    }
                }

                const locale = document.documentElement.lang || 'en';
                this.showToast(
                    locale.includes('zh') ? '客户信息已填充' :
                    locale.includes('es') ? 'Datos del cliente cargados' :
                    'Customer data loaded',
                    'success'
                );
            }
        } catch (error) {
            console.error('Error getting customer data:', error);
        }
    }

    /**
     * 完成订单 - 将待付款订单状态改为已完成
     */
    async completeOrder(orderId) {
        const locale = document.documentElement.lang || 'en';

        // Confirmation
        const confirmMsg = locale.includes('zh')
            ? '确定要将此订单标记为已完成吗？'
            : locale.includes('es')
                ? '¿Está seguro de marcar este pedido como completado?'
                : 'Are you sure you want to mark this order as completed?';

        if (!confirm(confirmMsg)) return;

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'complete_order',
                    nonce: ruiyi_pos_ajax.nonce,
                    order_id: orderId
                })
            });

            const data = await response.json();

            if (data.success) {
                this.showToast(
                    locale.includes('zh')
                        ? `订单 #${orderId} 已标记为完成`
                        : locale.includes('es')
                            ? `Pedido #${orderId} marcado como completado`
                            : `Order #${orderId} marked as completed`,
                    'success'
                );

                // Reload the order list
                this.loadOrderHistory();
            } else {
                throw new Error(data.data?.message || 'Failed to complete order');
            }
        } catch (error) {
            console.error('Error completing order:', error);
            this.showToast(
                locale.includes('zh')
                    ? '标记订单失败'
                    : locale.includes('es')
                        ? 'Error al completar el pedido'
                        : 'Failed to complete order',
                'error'
            );
        }
    }

    /**
     * 作废订单 - 已完成订单改为取消，待付款订单永久删除
     */
    async voidOrder(orderId, isPending = false) {
        const locale = document.documentElement.lang || 'en';

        // Different confirmation messages for pending vs completed orders
        let confirmMsg;
        if (isPending) {
            confirmMsg = locale.includes('zh')
                ? '确定要永久删除此待付款订单吗？此操作不可恢复！'
                : locale.includes('es')
                    ? '¿Está seguro de eliminar permanentemente este pedido pendiente? ¡Esta acción no se puede deshacer!'
                    : 'Are you sure you want to permanently delete this pending order? This action cannot be undone!';
        } else {
            confirmMsg = locale.includes('zh')
                ? '确定要作废此订单吗？订单将被标记为已取消。'
                : locale.includes('es')
                    ? '¿Está seguro de anular este pedido? Se marcará como cancelado.'
                    : 'Are you sure you want to void this order? It will be marked as cancelled.';
        }

        if (!confirm(confirmMsg)) return;

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'void_order',
                    nonce: ruiyi_pos_ajax.nonce,
                    order_id: orderId,
                    is_pending: isPending ? '1' : '0'
                })
            });

            const data = await response.json();

            if (data.success) {
                // 🔥 作废直接取消订单，不自动下载PDF退货单
                const successMsg = isPending
                    ? (locale.includes('zh')
                        ? `订单 #${orderId} 已永久删除`
                        : locale.includes('es')
                            ? `Pedido #${orderId} eliminado permanentemente`
                            : `Order #${orderId} permanently deleted`)
                    : (locale.includes('zh')
                        ? `订单 #${orderId} 已作废`
                        : locale.includes('es')
                            ? `Pedido #${orderId} anulado`
                            : `Order #${orderId} voided`);

                this.showToast(successMsg, 'success');

                // Reload the order list
                this.loadOrderHistory();
            } else {
                throw new Error(data.data?.message || 'Failed to void order');
            }
        } catch (error) {
            console.error('Error voiding order:', error);
            this.showToast(
                locale.includes('zh')
                    ? '作废订单失败'
                    : locale.includes('es')
                        ? 'Error al anular el pedido'
                        : 'Failed to void order',
                'error'
            );
        }
    }

    // ========================================
    // 退货发票功能 (Rectificativa Invoice)
    // ========================================

    /**
     * 打开退货发票弹窗
     */
    async openRectificativaModal(orderId) {
        const modal = document.getElementById('rectificativa-modal');
        if (!modal) return;

        const locale = document.documentElement.lang || 'en';

        // 🔥 从缓存的订单数据中查找订单
        const order = this.cachedOrders?.find(o => o.id === orderId);
        if (!order) {
            console.error('Order not found in cache:', orderId);
            this.showNotification(locale.includes('zh') ? '找不到订单数据' : 'Order data not found', 'error');
            return;
        }

        // 获取原发票信息
        const originalInvoiceLabel = order.invoice_label || '';
        const originalInvoiceDate = order.original_invoice_date || '';

        // Store order ID
        document.getElementById('rectificativa-order-id').value = orderId;

        // Display order number
        const orderDisplay = document.getElementById('rectificativa-order-number-display');
        if (orderDisplay) {
            orderDisplay.textContent = `${locale.includes('zh') ? '订单' : locale.includes('es') ? 'Pedido' : 'Order'} #${orderId}`;
        }

        // Set original invoice info
        document.getElementById('rectificativa-original-number').value = originalInvoiceLabel;
        document.getElementById('rectificativa-original-date').value = originalInvoiceDate;

        // Set emission date (today)
        const today = new Date();
        const emissionDate = today.toLocaleDateString('es-ES', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
        });
        document.getElementById('rectificativa-emission-date').value = emissionDate;

        // 🔥 从订单数据中自动填充客户信息（原始发票的客户信息）
        document.getElementById('rectificativa-customer-id').value = '';
        document.getElementById('rectificativa-customer-search').value = '';
        document.getElementById('rectificativa-customer-name').value = order.invoice_customer_name || order.customer_name || '';
        document.getElementById('rectificativa-company').value = order.invoice_customer_company || '';
        document.getElementById('rectificativa-cif').value = order.invoice_customer_cif || '';
        document.getElementById('rectificativa-address').value = order.invoice_customer_address || '';
        document.getElementById('rectificativa-city').value = order.invoice_customer_city || '';
        document.getElementById('rectificativa-postcode').value = order.invoice_customer_postcode || '';

        // Generate new invoice number - fetch from server
        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'get_rectificativa_number',
                    nonce: ruiyi_pos_ajax.nonce,
                    order_id: orderId,
                    original_invoice: originalInvoiceLabel
                })
            });

            const data = await response.json();
            if (data.success && data.data.rectificativa_number) {
                document.getElementById('rectificativa-new-number').value = data.data.rectificativa_number;
            } else {
                // Fallback: generate locally
                const year = today.getFullYear();
                const fallbackNumber = `Fact_${year}001_RT`;
                document.getElementById('rectificativa-new-number').value = fallbackNumber;
            }
        } catch (error) {
            console.error('Error getting rectificativa number:', error);
            // Fallback
            const year = today.getFullYear();
            const fallbackNumber = `Fact_${year}001_RT`;
            document.getElementById('rectificativa-new-number').value = fallbackNumber;
        }

        // Show modal
        modal.classList.remove('hidden');
    }

    /**
     * 搜索客户（退货弹窗用）
     */
    async searchRectificativaCustomer(query) {
        const resultsDiv = document.getElementById('rectificativa-customer-results');
        if (!query || query.length < 2) {
            resultsDiv.classList.add('hidden');
            return;
        }

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'search_customers',
                    nonce: ruiyi_pos_ajax.nonce,
                    query: query
                })
            });

            const data = await response.json();
            if (data.success && data.data && data.data.length > 0) {
                let html = '';
                data.data.forEach(customer => {
                    html += `
                        <div class="p-3 hover:bg-gray-100 cursor-pointer border-b last:border-b-0"
                             onclick="pos.selectRectificativaCustomer(${JSON.stringify(customer).replace(/"/g, '&quot;')})">
                            <div class="font-medium">${customer.customer_name || customer.company || 'Sin nombre'}</div>
                            <div class="text-sm text-gray-500">${customer.cif || ''} - ${customer.city || ''}</div>
                        </div>
                    `;
                });
                resultsDiv.innerHTML = html;
                resultsDiv.classList.remove('hidden');
            } else {
                resultsDiv.classList.add('hidden');
            }
        } catch (error) {
            console.error('Error searching customers:', error);
            resultsDiv.classList.add('hidden');
        }
    }

    /**
     * 选择客户（退货弹窗用）
     */
    selectRectificativaCustomer(customer) {
        document.getElementById('rectificativa-customer-id').value = customer.id || '';
        document.getElementById('rectificativa-customer-name').value = customer.customer_name || customer.name || '';
        document.getElementById('rectificativa-company').value = customer.company || '';
        document.getElementById('rectificativa-cif').value = customer.cif || '';
        document.getElementById('rectificativa-address').value = customer.address || '';
        document.getElementById('rectificativa-city').value = customer.city || '';
        document.getElementById('rectificativa-postcode').value = customer.postcode || '';
        document.getElementById('rectificativa-customer-search').value = '';
        document.getElementById('rectificativa-customer-results').classList.add('hidden');
    }

    /**
     * 关闭退货发票弹窗
     */
    closeRectificativaModal() {
        const modal = document.getElementById('rectificativa-modal');
        if (modal) {
            modal.classList.add('hidden');
        }
    }

    /**
     * 生成退货发票（包含取消订单）
     */
    async generateRectificativaInvoice() {
        const orderId = document.getElementById('rectificativa-order-id').value;
        const newInvoiceNumber = document.getElementById('rectificativa-new-number').value;
        const originalInvoiceNumber = document.getElementById('rectificativa-original-number').value;
        const originalInvoiceDate = document.getElementById('rectificativa-original-date').value;
        const emissionDate = document.getElementById('rectificativa-emission-date').value;

        // Get customer data
        const customerName = document.getElementById('rectificativa-customer-name').value;
        const company = document.getElementById('rectificativa-company').value;
        const cif = document.getElementById('rectificativa-cif').value;
        const address = document.getElementById('rectificativa-address').value;
        const city = document.getElementById('rectificativa-city').value;
        const postcode = document.getElementById('rectificativa-postcode').value;

        const locale = document.documentElement.lang || 'en';

        // Validate required fields
        if (!orderId || !newInvoiceNumber) {
            this.showToast('Missing required data', 'error');
            return;
        }

        if (!customerName || !cif || !address || !city || !postcode) {
            this.showToast(
                locale.includes('zh') ? '请填写所有必填字段' :
                locale.includes('es') ? 'Por favor complete todos los campos obligatorios' :
                'Please fill in all required fields',
                'error'
            );
            return;
        }

        // Disable button and show loading
        const btn = document.getElementById('rectificativa-download-btn');
        const originalText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = `<svg class="animate-spin h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>${locale.includes('zh') ? '处理中...' : locale.includes('es') ? 'Procesando...' : 'Processing...'}`;

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_pos_ajax',
                    pos_action: 'void_order_with_rectificativa',
                    nonce: ruiyi_pos_ajax.nonce,
                    order_id: orderId,
                    new_invoice_number: newInvoiceNumber,
                    original_invoice_number: originalInvoiceNumber,
                    original_invoice_date: originalInvoiceDate,
                    emission_date: emissionDate,
                    customer_name: customerName,
                    company: company,
                    cif: cif,
                    address: address,
                    city: city,
                    postcode: postcode
                })
            });

            const data = await response.json();

            if (data.success && data.data.pdf_url) {
                // Download PDF file to selected directory or browser default
                const rectPdfFilename = data.data.filename || 'rectificativa.pdf';
                await this.downloadPdfToDir(data.data.pdf_url, rectPdfFilename);

                // Show success toast
                this.showToast(
                    locale.includes('zh') ? '退货发票生成成功！订单已取消' :
                    locale.includes('es') ? '¡Factura rectificativa generada! Pedido cancelado' :
                    'Rectificative invoice generated! Order cancelled',
                    'success'
                );

                // Close modal and reload order list
                this.closeRectificativaModal();
                this.loadOrderHistory();

            } else if (data.success) {
                // Success but no PDF URL
                this.showToast(data.data?.message || 'Invoice generated but PDF not available', 'warning');
                this.closeRectificativaModal();
                this.loadOrderHistory();
            } else {
                throw new Error(data.data?.message || 'Failed to generate rectificativa');
            }
        } catch (error) {
            console.error('Error generating rectificativa invoice:', error);
            this.showToast(
                locale.includes('zh') ? '生成退货发票失败: ' + error.message :
                locale.includes('es') ? 'Error al generar factura rectificativa: ' + error.message :
                'Failed to generate rectificative invoice: ' + error.message,
                'error'
            );
        } finally {
            // Reset button state
            const btn = document.getElementById('rectificativa-download-btn');
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = `<svg class="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/>
                </svg>${locale.includes('zh') ? '下载退货单' : locale.includes('es') ? 'Descargar Rectificativa' : 'Download Rectificative'}`;
            }
        }
    }

    // ========================================
    // 日结单和月结单功能 (Daily & Monthly Settlement)
    // ========================================

    /**
     * 🔥 初始化页面关闭自动保存功能
     * Initialize page close auto-save feature
     * 当用户关闭页面时，自动保存当天的日结单到月结单
     */
    initPageCloseAutoSave() {
        // 只有启用了自动保存功能才初始化
        if (!this.autoDailySettlementEnabled) {
            console.log('[Page Close Auto Save] Feature disabled, skipping initialization');
            return;
        }

        console.log('[Page Close Auto Save] Initializing page close auto-save...');

        // 使用 visibilitychange 事件检测页面隐藏（更可靠）
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'hidden') {
                this.onPageCloseAutoSave();
            }
        });

        // 使用 pagehide 事件作为备份（移动端更可靠）
        window.addEventListener('pagehide', (event) => {
            this.onPageCloseAutoSave();
        });

        console.log('[Page Close Auto Save] Initialized successfully');
    }

    /**
     * 🔥 页面关闭时执行自动保存
     * Execute auto-save when page closes
     * 每次关闭页面都会保存（如果有数据），支持一天多次保存
     */
    onPageCloseAutoSave() {
        // 检查是否启用
        if (!this.autoDailySettlementEnabled) {
            return;
        }

        // 获取今天的日期
        const today = new Date().toISOString().split('T')[0];

        console.log('[Page Close Auto Save] Page closing, triggering auto save for ' + today);

        // 使用 sendBeacon 发送保存请求（页面关闭时也能可靠发送）
        const formData = new FormData();
        formData.append('action', 'ruiyi_pos_ajax');
        formData.append('pos_action', 'page_close_auto_save');
        formData.append('date_to_save', today);
        formData.append('nonce', ruiyi_pos_ajax.nonce);

        // sendBeacon 可以在页面关闭时可靠地发送数据
        const success = navigator.sendBeacon(ruiyi_pos_ajax.ajax_url, formData);

        if (success) {
            console.log('[Page Close Auto Save] Beacon sent successfully');
        } else {
            console.log('[Page Close Auto Save] Beacon failed, trying fetch...');
            // 如果 sendBeacon 失败，尝试使用 fetch（keepalive）
            fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                body: formData,
                keepalive: true // 允许请求在页面关闭后继续
            }).catch(() => {});
        }
    }

    /**
     * 🔥 初始化日结单自动保存检查
     * Initialize auto daily settlement check
     */
    initMidnightSettlementCheck() {
        // 记录当前日期用于检测日期变化
        this.lastCheckedDate = new Date().toISOString().split('T')[0];
        // 记录上次触发保存的时间戳，避免同一时间窗口内多次触发
        this.lastAutoSaveTriggeredAt = localStorage.getItem('ruiyi_pos_last_auto_save_triggered_at') || '';

        console.log('=== [Auto Settlement] INITIALIZATION ===');
        console.log(`[Auto Settlement] Current date: ${this.lastCheckedDate}`);
        console.log(`[Auto Settlement] Feature enabled: ${this.autoDailySettlementEnabled}`);
        console.log(`[Auto Settlement] Configured time: ${this.autoDailySettlementTime}`);
        console.log(`[Auto Settlement] Multiple saves per day: YES`);
        console.log(`[Auto Settlement] Check interval: every 30 seconds`);
        console.log('=========================================');

        // 每30秒检查一次
        this.intervalIds.push(setInterval(() => {
            this.checkDateChangeAndAutoSave();
        }, 300000)); // 5分钟检查一次 (日期变化不需要秒级精度)

        // 页面加载时也检查一次（处理页面在设定时间后刷新的情况）
        setTimeout(() => {
            console.log('[Auto Settlement] Running initial check after page load...');
            this.checkDateChangeAndAutoSave();
        }, 2000);
    }

    /**
     * 🔥 检查是否到达设定时间并自动保存
     * Check if reached configured time and trigger auto save
     */
    checkDateChangeAndAutoSave() {
        const now = new Date();
        const currentDate = now.toISOString().split('T')[0];
        const currentHours = now.getHours();
        const currentMinutes = now.getMinutes();
        const currentTimeStr = `${currentHours.toString().padStart(2,'0')}:${currentMinutes.toString().padStart(2,'0')}`;

        // 解析设定的保存时间
        const [targetHour, targetMinute] = this.autoDailySettlementTime.split(':').map(Number);

        console.log(`[Auto Settlement] Check at ${currentTimeStr} - target: ${this.autoDailySettlementTime}, enabled: ${this.autoDailySettlementEnabled}`);

        // 功能未启用则跳过
        if (!this.autoDailySettlementEnabled) {
            return;
        }

        // 计算要保存的日期
        // 如果设定时间在00:00-03:59之间，保存的是"昨天"的数据（凌晨结算昨天的营业）
        // 如果设定时间在04:00-23:59之间，保存的是"今天"的数据（当天营业结束后结算）
        let dateToSave;
        if (targetHour >= 0 && targetHour < 4) {
            // 凌晨时段：保存昨天的数据
            const yesterday = new Date();
            yesterday.setDate(yesterday.getDate() - 1);
            dateToSave = yesterday.toISOString().split('T')[0];
        } else {
            // 其他时段（04:00-23:59）：保存今天的数据（当天营业结束）
            dateToSave = currentDate;
        }

        // 检查当前时间是否在设定时间的窗口内（允许1分钟误差）
        const isWithinTargetWindow = (currentHours === targetHour &&
                                       currentMinutes >= targetMinute &&
                                       currentMinutes <= targetMinute + 1);

        // 生成今天的触发标识（防止同一天多次触发）
        const todayTriggerKey = `${currentDate}_${this.autoDailySettlementTime}`;

        if (isWithinTargetWindow) {
            console.log(`[Auto Settlement] ⏰ Within target time window (${this.autoDailySettlementTime}), will save: ${dateToSave}`);

            // 检查是否在这个时间窗口内已经触发过（防止同一分钟内多次触发）
            if (this.lastAutoSaveTriggeredAt === todayTriggerKey) {
                console.log(`[Auto Settlement] ⏭️ Already triggered in this time window`);
                return;
            }

            // 🔥 不再检查是否已保存过，允许一天多次保存
            console.log(`[Auto Settlement] ✅ Triggering auto save for ${dateToSave}`);
            this.performAutoSaveDailySettlement(dateToSave);

            // 更新触发标识（仅用于防止同一时间窗口内重复触发）
            this.lastAutoSaveTriggeredAt = todayTriggerKey;
            localStorage.setItem('ruiyi_pos_last_auto_save_triggered_at', todayTriggerKey);
        }

        // 更新日期检查（用于检测日期变化）
        if (currentDate !== this.lastCheckedDate) {
            console.log(`[Auto Settlement] 📅 Date changed from ${this.lastCheckedDate} to ${currentDate}`);
            this.lastCheckedDate = currentDate;
        }
    }

    /**
     * 🔥 执行自动保存日结单
     * Perform the auto save of daily settlement
     */
    async performAutoSaveDailySettlement(dateToSave) {
        const locale = document.documentElement.lang || 'en';

        console.log('=== [Auto Settlement] PERFORM SAVE ===');
        console.log(`[Auto Settlement] Date to save: ${dateToSave}`);

        // 检查设置是否启用
        if (!this.autoDailySettlementEnabled) {
            console.log('[Auto Settlement] ❌ Feature is disabled in settings, skipping');
            return;
        }

        // 检查该日期是否已经保存过
        const lastAutoSaveDate = localStorage.getItem('ruiyi_pos_last_auto_settlement_date');
        if (lastAutoSaveDate === dateToSave) {
            console.log(`[Auto Settlement] ⏭️ ${dateToSave} already saved in localStorage, skipping`);
            return;
        }

        console.log(`[Auto Settlement] 🚀 Starting AJAX call to save ${dateToSave}...`);

        try {
            // 调用保存日结单的AJAX
            const formData = new FormData();
            formData.append('action', 'ruiyi_pos_ajax');
            formData.append('pos_action', 'auto_save_daily_settlement');
            formData.append('date_to_save', dateToSave);
            formData.append('nonce', ruiyi_pos_ajax.nonce);

            console.log('[Auto Settlement] AJAX URL:', ruiyi_pos_ajax.ajax_url);
            console.log('[Auto Settlement] Sending request...');

            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                body: formData
            });

            console.log('[Auto Settlement] Response status:', response.status);
            const data = await response.json();
            console.log('[Auto Settlement] Response data:', JSON.stringify(data, null, 2));

            if (data.success) {
                // 检查是否被跳过（没有数据需要保存）
                if (data.data?.skipped) {
                    console.log(`[Auto Settlement] ⚠️ Skipped for ${dateToSave}: ${data.data?.reason || 'no data'}`);
                    // 即使跳过也标记为已处理，避免重复尝试
                    localStorage.setItem('ruiyi_pos_last_auto_settlement_date', dateToSave);
                    return;
                }

                // 记录该日期已经自动保存
                localStorage.setItem('ruiyi_pos_last_auto_settlement_date', dateToSave);

                console.log(`[Auto Settlement] ✅ Successfully saved daily settlement for ${dateToSave}`);
                console.log(`[Auto Settlement] Settlement ID: ${data.data?.settlement_id}`);
                console.log(`[Auto Settlement] Total amount: ${data.data?.total_amount}`);
                console.log(`[Auto Settlement] Transactions: ${data.data?.transactions_count}`);
                console.log(`[Auto Settlement] Daily data deleted: ${data.data?.daily_data_deleted}`);

                // 显示通知
                this.showToast(
                    locale.includes('zh') ? `${dateToSave} 日结单已自动保存到月结单` :
                    locale.includes('es') ? `Cierre diario ${dateToSave} guardado automáticamente` :
                    `Daily settlement ${dateToSave} auto-saved`,
                    'success'
                );

                // 清空日结单缓存数据并刷新显示
                this.dailySettlementData = null;

                // 如果账单弹窗是打开的，刷新日结单显示
                const billsModal = document.getElementById('bills-modal');
                if (billsModal && !billsModal.classList.contains('hidden')) {
                    this.loadDailySettlement();
                }
            } else {
                console.error(`[Auto Settlement] ❌ Failed for ${dateToSave}:`, data.data?.message);
                console.error('[Auto Settlement] Full response:', data);
            }
        } catch (error) {
            console.error(`[Auto Settlement] ❌ Exception during save for ${dateToSave}:`, error);
        }
        console.log('======================================');
    }

    /**
     * 打开日结单弹窗 (Legacy - 保留兼容性)
     */
    openDailySettlementModal() {
        this.openBillsModal('daily');
    }

    /**
     * 关闭日结单弹窗 (Legacy - 保留兼容性)
     */
    closeDailySettlementModal() {
        this.closeBillsModal();
    }

    /**
     * 加载日结单数据
     */
    async loadDailySettlement() {
        const loadingEl = document.getElementById('daily-settlement-loading');
        const contentEl = document.getElementById('daily-settlement-content');

        loadingEl.classList.remove('hidden');
        contentEl.classList.add('hidden');

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_retail_get_daily_summary',
                    nonce: ruiyi_pos_ajax.nonce
                })
            });

            const data = await response.json();

            if (data.success) {
                this.dailySettlementData = data.data;
                this.displayDailySummary(data.data);
                loadingEl.classList.add('hidden');
                contentEl.classList.remove('hidden');
            } else {
                this.showToast(data.data?.message || 'Error al cargar cierre diario', 'error');
            }
        } catch (error) {
            console.error('Error loading daily settlement:', error);
            this.showToast('Error al cargar cierre diario', 'error');
        }
    }

    /**
     * 显示日结单数据
     */
    displayDailySummary(data) {
        // 更新日期
        document.getElementById('daily-settlement-date').textContent = data.date;

        // 更新统计卡片 - 欧元符号在后
        document.getElementById('daily-total-amount').textContent = parseFloat(data.total_amount).toFixed(2) + '€';
        document.getElementById('daily-card-amount').textContent = parseFloat(data.card_amount).toFixed(2) + '€';
        document.getElementById('daily-cash-amount').textContent = parseFloat(data.cash_amount).toFixed(2) + '€';
        document.getElementById('daily-transfer-amount').textContent = parseFloat(data.transfer_amount || 0).toFixed(2) + '€';
        document.getElementById('daily-orders-count').textContent = data.orders_count;

        // 分类销售统计已删除
    }

    /**
     * 保存日结单（不打印）
     */
    async saveDailySettlement() {
        if (!this.dailySettlementData) {
            this.showToast('No data to save', 'error');
            return;
        }

        const data = this.dailySettlementData;

        // 检查是否有数据
        if (data.total_amount <= 0) {
            const locale = document.documentElement.lang || 'en';
            const noDataText = locale.includes('zh') ? '今日暂无交易数据' :
                              locale.includes('es') ? 'No hay datos de hoy' :
                              'No transactions today';
            this.showToast(noDataText, 'warning');
            return;
        }

        // 确认保存
        const locale = document.documentElement.lang || 'en';
        const confirmText = locale.includes('zh') ? '确认保存日结单到月结单？\n\n保存后今日数据将被清空。' :
                           locale.includes('es') ? '¿Confirmar guardar en cierre mensual?\n\nLos datos de hoy se limpiarán.' :
                           'Confirm save to monthly summary?\n\nToday\'s data will be cleared.';

        if (!confirm(confirmText)) {
            return;
        }

        try {
            // 保存到月结单
            const saveResult = await this.saveDailyToMonthly();

            if (!saveResult) {
                console.error('保存失败');
                return;
            }

            // 保存成功
            const successText = locale.includes('zh') ? '日结单已保存' :
                               locale.includes('es') ? 'Cierre diario guardado' :
                               'Daily settlement saved';
            this.closeBillsModal();
            this.showToast(successText, 'success');

        } catch (error) {
            console.error('Save error:', error);
            this.showToast('Error al guardar', 'error');
        }
    }

    /**
     * 打印日结单
     */
    async printDailySettlement() {
        if (!this.dailySettlementData) {
            this.showToast('No data to print', 'error');
            return;
        }

        const data = this.dailySettlementData;

        // 检查是否有数据
        if (data.total_amount <= 0) {
            const locale = document.documentElement.lang || 'en';
            const noDataText = locale.includes('zh') ? '今日暂无交易数据' :
                              locale.includes('es') ? 'No hay datos de hoy' :
                              'No transactions today';
            this.showToast(noDataText, 'warning');
            return;
        }

        // 确认打印并保存
        const locale = document.documentElement.lang || 'en';
        const confirmText = locale.includes('zh') ? '确认打印日结单并保存到月结单？\n\n打印后今日数据将被清空。' :
                           locale.includes('es') ? '¿Confirmar impresión y guardar en cierre mensual?\n\nLos datos de hoy se limpiarán.' :
                           'Confirm print and save to monthly summary?\n\nToday\'s data will be cleared.';

        if (!confirm(confirmText)) {
            return;
        }

        try {
            // 步骤1：先保存到月结单（确保数据不丢失）
            const saveResult = await this.saveDailyToMonthly();

            if (!saveResult) {
                console.error('保存失败，取消打印');
                return;
            }

            // 步骤2：保存成功后再打印
            try {
                if (typeof getLodop === 'function') {
                    const LODOP = getLodop();
                    if (LODOP && LODOP.VERSION) {
                        this.printDailyWithCLODOP(data);
                    } else {
                        this.printDailyWithBrowser(data);
                    }
                } else {
                    this.printDailyWithBrowser(data);
                }

                // 🔥 打印完成后刷新日结单显示
                setTimeout(() => {
                    this.closeDailySettlementModal();
                    this.showToast('日结单已打印并保存', 'success');
                }, 1000);

            } catch (printError) {
                console.error('打印错误:', printError);
                // 🔥 即使打印失败，也已经保存成功了，所以提示用户
                this.showToast('数据已保存，但打印失败: ' + printError.message, 'warning');
            }

        } catch (error) {
            console.error('Print error:', error);
            this.showToast('Error al imprimir', 'error');
        }
    }

    /**
     * 使用CLodop打印日结单 - 西班牙语版本
     */
    printDailyWithCLODOP(data) {
        try {
            // 检查getLodop函数是否可用
            if (typeof getLodop !== 'function') {
                console.error('[日结单打印] getLodop函数未定义，CLODOP未加载');
                throw new Error('CLODOP not available - getLodop function not found');
            }

            const LODOP = getLodop();

            // 检查LODOP对象是否有效
            if (!LODOP || !LODOP.VERSION) {
                console.error('[日结单打印] CLODOP对象无效或未连接');
                throw new Error('CLODOP service not connected');
            }

            // CLODOP ready

            // 获取默认打印机
            const defaultPrinter = window.clodopConfig?.defaultPrinter || '';

            LODOP.SET_LICENSES("","D615C875005D74B88EC9E2585C79798E9CA","","");
            LODOP.PRINT_INIT("日结单");
            LODOP.SET_PRINT_PAGESIZE(3, "80mm", 0, "");

            if (defaultPrinter) {
                LODOP.SET_PRINTER_INDEX(defaultPrinter);
            }

            // 统一字体设置（与月结单一致）
            const fontName = "Arial";
            const fontSize = 9;

            let y = 5;
            let elementIndex = 0;

            // ====== 店铺抬头（与结账小票一致：名称 + 地址 + 电话 + 邮箱 + 税号） ======
            const _storeSettings = ruiyi_pos_ajax.store_settings || {};
            const storeName      = _storeSettings.store_name || 'TIENDA RETAIL';
            const storeAddress   = _storeSettings.store_address || '';
            const storePhone     = _storeSettings.store_phone || '';
            const storeEmail     = _storeSettings.store_email || '';
            const storeTaxNumber = _storeSettings.store_tax_number || '';

            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", storeName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;
            y += 5;

            if (storeAddress) {
                // 地址可能很长会折行：按字符数估算占用行数（80mm@10pt ≈ 每行 32 字符）
                const addrLines = Math.max(1, Math.ceil(storeAddress.length / 32));
                const addrHeight = addrLines * 5;
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", addrHeight + "mm", storeAddress);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
                elementIndex++;
                y += addrHeight;
            }
            if (storePhone) {
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Tel: " + storePhone);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
                elementIndex++;
                y += 5;
            }
            if (storeEmail) {
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Email: " + storeEmail);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
                elementIndex++;
                y += 5;
            }
            if (storeTaxNumber) {
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "NIF/CIF: " + storeTaxNumber);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
                elementIndex++;
                y += 5;
            }
            y += 2;

            // ====== 标题 - CIERRE DIARIO - 左对齐 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "CIERRE DIARIO");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 11);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;
            y += 6;

            // ====== 日期 - 格式化为 DD-MM-YYYY ======
            let fechaDisplay = data.date;
            if (data.date && data.date.includes('-')) {
                const dateParts = data.date.split('-');
                if (dateParts.length === 3) {
                    fechaDisplay = `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`;
                }
            }
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", `Fecha: ${fechaDisplay}`);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 6;

            // ====== 分隔线 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "3mm", "================================");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 5;

            // ====== 汇总统计 - 全部靠左，欧元符号在数字后面 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "TOTAL DEL DIA: " + parseFloat(data.total_amount).toFixed(2) + " €");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;
            y += 5;

            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Tarjeta: " + parseFloat(data.card_amount).toFixed(2) + " €");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 5;

            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Efectivo: " + parseFloat(data.cash_amount).toFixed(2) + " €");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 5;

            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Transferencia: " + parseFloat(data.transfer_amount || 0).toFixed(2) + " €");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 5;

            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Pedidos: " + data.orders_count);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 6;

            // ====== 结束分隔线 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "3mm", "================================");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 5;

            // ====== 打印时间 ======
            const printTime = new Date().toLocaleString('es-ES', {
                day: '2-digit',
                month: '2-digit',
                year: 'numeric',
                hour: '2-digit',
                minute: '2-digit'
            });
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Impreso: " + printTime);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
            y += 5;

            // 执行打印
            LODOP.PRINT();

            // Print executed

        } catch (error) {
            console.error('[日结单打印] CLodop print error:', error);
            throw error;
        }
    }

    /**
     * 浏览器打印日结单（备用）
     */
    printDailyWithBrowser(data) {
        const locale = document.documentElement.lang || 'en';
        const printWindow = window.open('', '', 'width=300,height=600');
        const html = `
            <html>
            <head>
                <title>${locale.includes('zh') ? '日结单' : locale.includes('es') ? 'Cierre Diario' : 'Daily Settlement'}</title>
                <style>
                    body { font-family: monospace; width: 80mm; margin: 10mm; }
                    h1 { text-align: center; font-size: 16pt; }
                    h2 { text-align: center; font-size: 14pt; }
                    .line { border-top: 1px dashed #000; margin: 5px 0; }
                    .total { font-size: 14pt; font-weight: bold; }
                </style>
            </head>
            <body>
                <h1>${ruiyi_pos_ajax.store_settings?.store_name || 'RUIYI RETAIL POS'}</h1>
                <h2>${locale.includes('zh') ? '日结单' : locale.includes('es') ? 'CIERRE DIARIO' : 'DAILY SETTLEMENT'}</h2>
                <p>${locale.includes('es') ? 'Fecha' : locale.includes('zh') ? '日期' : 'Date'}: ${data.date}</p>
                <div class="line"></div>
                <p class="total">${locale.includes('es') ? 'TOTAL' : locale.includes('zh') ? '今日总额' : 'TOTAL'}: ${parseFloat(data.total_amount).toFixed(2)}€</p>
                <p>${locale.includes('es') ? 'Tarjeta' : locale.includes('zh') ? '刷卡' : 'Card'}: ${parseFloat(data.card_amount).toFixed(2)}€</p>
                <p>${locale.includes('es') ? 'Efectivo' : locale.includes('zh') ? '现金' : 'Cash'}: ${parseFloat(data.cash_amount).toFixed(2)}€</p>
                <p>${locale.includes('es') ? 'Transferencia' : locale.includes('zh') ? '转账' : 'Transfer'}: ${parseFloat(data.transfer_amount || 0).toFixed(2)}€</p>
                <p>${locale.includes('es') ? 'Pedidos' : locale.includes('zh') ? '订单数' : 'Orders'}: ${data.orders_count}</p>
                <div class="line"></div>
            </body>
            </html>
        `;
        printWindow.document.write(html);
        printWindow.document.close();
        printWindow.print();
    }

    /**
     * 保存日结单到月结单
     */
    async saveDailyToMonthly() {
        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_retail_save_daily_to_monthly',
                    nonce: ruiyi_pos_ajax.nonce
                })
            });

            const data = await response.json();

            if (data.success) {
                const locale = document.documentElement.lang || 'en';
                const successText = locale.includes('zh') ? '日结单已保存到月结单' :
                                   locale.includes('es') ? 'Cierre diario guardado exitosamente' :
                                   'Daily summary saved';
                this.showToast(successText, 'success');

                // 清空前端数据
                this.dailySettlementData = null;

                // 返回成功状态
                return true;
            } else {
                console.error('保存失败:', data.data?.message);
                const errorMsg = data.data?.message || 'Error al guardar';
                this.showToast(errorMsg, 'error');
                return false;
            }
        } catch (error) {
            console.error('Save error:', error);
            const locale = document.documentElement.lang || 'en';
            const errorText = locale.includes('zh') ? '保存失败' :
                             locale.includes('es') ? 'Error al guardar el cierre diario' :
                             'Failed to save daily summary';
            this.showToast(errorText, 'error');
            return false;
        }
    }

    /**
     * 打开月结单弹窗
     */
    openMonthlySettlementModal() {
        const modal = document.getElementById('monthly-settlement-modal');
        if (modal) {
            modal.classList.remove('hidden');
            this.loadMonthlySettlement();
        }
    }

    /**
     * 关闭月结单弹窗
     */
    closeMonthlySettlementModal() {
        const modal = document.getElementById('monthly-settlement-modal');
        if (modal) {
            modal.classList.add('hidden');
        }
    }

    /**
     * 🔥 切换月结单筛选类型（按月份/按日期）
     */
    toggleMonthlyFilterType(type) {
        const monthFilter = document.getElementById('monthly-filter-month');
        const dateFilter = document.getElementById('monthly-filter-date');

        if (type === 'month') {
            monthFilter.classList.remove('hidden');
            dateFilter.classList.add('hidden');
        } else {
            monthFilter.classList.add('hidden');
            dateFilter.classList.remove('hidden');
        }
    }

    /**
     * 🔥 按特定日期加载月结单数据
     */
    async loadMonthlySettlementByDate() {
        const loadingEl = document.getElementById('monthly-settlement-loading');
        const contentEl = document.getElementById('monthly-settlement-content');
        const dateInput = document.getElementById('monthly-date-filter-input');
        const selectedDate = dateInput.value;

        if (!selectedDate) {
            this.showToast('请选择日期', 'warning');
            return;
        }

        loadingEl.classList.remove('hidden');
        contentEl.classList.add('hidden');

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_retail_get_monthly_summary',
                    nonce: ruiyi_pos_ajax.nonce,
                    specific_date: selectedDate
                })
            });

            const data = await response.json();

            if (data.success) {
                this.monthlySettlementData = data.data;
                this.displayMonthlySummary(data.data);
                loadingEl.classList.add('hidden');
                contentEl.classList.remove('hidden');
            } else {
                this.showToast(data.data?.message || 'Error al cargar cierre', 'error');
                loadingEl.classList.add('hidden');
            }
        } catch (error) {
            this.showToast('Error al cargar cierre', 'error');
            loadingEl.classList.add('hidden');
        }
    }

    /**
     * 加载月结单数据
     */
    async loadMonthlySettlement() {
        const loadingEl = document.getElementById('monthly-settlement-loading');
        const contentEl = document.getElementById('monthly-settlement-content');
        const monthInput = document.getElementById('monthly-filter-input');

        loadingEl.classList.remove('hidden');
        contentEl.classList.add('hidden');

        try {
            const response = await fetch(ruiyi_pos_ajax.ajax_url, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    action: 'ruiyi_retail_get_monthly_summary',
                    nonce: ruiyi_pos_ajax.nonce,
                    month: monthInput.value
                })
            });

            const data = await response.json();

            if (data.success) {
                this.monthlySettlementData = data.data;
                this.displayMonthlySummary(data.data);
                loadingEl.classList.add('hidden');
                contentEl.classList.remove('hidden');
            } else {
                this.showToast(data.data?.message || 'Error al cargar cierre mensual', 'error');
                loadingEl.classList.add('hidden');
            }
        } catch (error) {
            this.showToast('Error al cargar cierre mensual', 'error');
            loadingEl.classList.add('hidden');
        }
    }

    /**
     * 显示月结单数据
     */
    displayMonthlySummary(data) {
        // 更新汇总卡片 - 欧元符号在后
        document.getElementById('monthly-total-amount').textContent = parseFloat(data.summary.total).toFixed(2) + '€';
        document.getElementById('monthly-card-amount').textContent = parseFloat(data.summary.card).toFixed(2) + '€';
        document.getElementById('monthly-cash-amount').textContent = parseFloat(data.summary.cash).toFixed(2) + '€';
        document.getElementById('monthly-transfer-amount').textContent = parseFloat(data.summary.transfer || 0).toFixed(2) + '€';

        // 填充记录表格 - 显示每次结单记录（同一天可能有多次）
        const recordsList = document.getElementById('monthly-records-list');
        if (data.records && data.records.length > 0) {
            recordsList.innerHTML = data.records.map((record, index) => {
                // 🔥 格式化结单时间显示（显示实际时间：DD-MM-YYYY HH:MM）
                let dateTimeDisplay = record.date; // 默认只显示日期

                // 如果有结单时间，显示日期 + 实际时间格式
                if (record.settlement_datetime) {
                    const dt = new Date(record.settlement_datetime);
                    const day = String(dt.getDate()).padStart(2, '0');
                    const month = String(dt.getMonth() + 1).padStart(2, '0');
                    const year = dt.getFullYear();
                    // 🔥 修复：显示实际的小时和分钟
                    const hours = String(dt.getHours()).padStart(2, '0');
                    const minutes = String(dt.getMinutes()).padStart(2, '0');
                    dateTimeDisplay = `${day}-${month}-${year} ${hours}:${minutes}`;
                }

                return `
                <tr class="hover:bg-gray-50">
                    <td class="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                        ${dateTimeDisplay}
                        ${record.settlement_id ? `<br><span class="text-xs text-gray-500">ID: ${record.settlement_id}</span>` : ''}
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-900 text-right font-semibold">
                        ${parseFloat(record.total_amount).toFixed(2)}€
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-900 text-right">
                        ${parseFloat(record.cash_amount).toFixed(2)}€
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-900 text-right">
                        ${parseFloat(record.card_amount).toFixed(2)}€
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-900 text-right">
                        ${parseFloat(record.transfer_amount || 0).toFixed(2)}€
                    </td>
                    <td class="px-4 py-4 whitespace-nowrap text-center">
                        <button onclick="pos.reprintDailySettlement(${index})"
                                class="inline-flex items-center px-2 py-1 text-xs font-medium text-purple-700 bg-purple-100 hover:bg-purple-200 rounded transition-colors"
                                title="${document.documentElement.lang?.includes('zh') ? '打印' : document.documentElement.lang?.includes('es') ? 'Imprimir' : 'Print'}">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"/>
                            </svg>
                        </button>
                    </td>
                </tr>
            `;
            }).join('');
        } else {
            const locale = document.documentElement.lang || 'en';
            const noDataText = locale.includes('zh') ? '暂无记录' :
                              locale.includes('es') ? 'Sin registros' :
                              'No records';
            recordsList.innerHTML = `
                <tr>
                    <td colspan="5" class="px-6 py-8 text-center text-gray-500">
                        ${noDataText}
                    </td>
                </tr>
            `;
        }
    }

    /**
     * 重新打印历史日结单
     */
    reprintDailySettlement(recordIndex) {
        if (!this.monthlySettlementData || !this.monthlySettlementData.records) {
            this.showToast('No data available', 'error');
            return;
        }

        const record = this.monthlySettlementData.records[recordIndex];
        if (!record) {
            this.showToast('Record not found', 'error');
            return;
        }

        const locale = document.documentElement.lang || 'en';

        // 构造日结单数据格式
        const data = {
            total_amount: parseFloat(record.total_amount) || 0,
            card_amount: parseFloat(record.card_amount) || 0,
            cash_amount: parseFloat(record.cash_amount) || 0,
            orders_count: record.orders_count || 0,
            settlement_date: record.date,
            settlement_id: record.settlement_id || '',
            is_reprint: true // 标记为重打
        };

        try {
            if (typeof getLodop === 'function') {
                const LODOP = getLodop();
                if (LODOP && LODOP.VERSION) {
                    this.printHistoricalDailyWithCLODOP(data);
                    this.showToast(
                        locale.includes('zh') ? '正在打印历史日结单...' :
                        locale.includes('es') ? 'Imprimiendo cierre diario...' :
                        'Printing daily settlement...',
                        'success'
                    );
                } else {
                    this.showToast(
                        locale.includes('zh') ? 'CLODOP未连接，请检查打印服务' :
                        locale.includes('es') ? 'CLODOP no conectado' :
                        'CLODOP not connected',
                        'error'
                    );
                }
            } else {
                this.showToast(
                    locale.includes('zh') ? 'CLODOP未加载' :
                    locale.includes('es') ? 'CLODOP no cargado' :
                    'CLODOP not loaded',
                    'error'
                );
            }
        } catch (error) {
            console.error('Reprint error:', error);
            this.showToast('Print error: ' + error.message, 'error');
        }
    }

    /**
     * 使用CLodop打印历史日结单
     */
    printHistoricalDailyWithCLODOP(data) {
        try {
            const LODOP = getLodop();
            if (!LODOP || !LODOP.VERSION) {
                throw new Error('CLODOP service not connected');
            }

            const defaultPrinter = window.clodopConfig?.defaultPrinter || '';

            LODOP.SET_LICENSES("","D615C875005D74B88EC9E2585C79798E9CA","","");
            LODOP.PRINT_INIT("历史日结单");
            LODOP.SET_PRINT_PAGESIZE(3, "80mm", 0, "");

            if (defaultPrinter) {
                LODOP.SET_PRINTER_INDEX(defaultPrinter);
            }

            const fontName = "Arial";
            const fontSize = 9;
            let y = 5;

            // 获取店铺信息（与结账小票抬头保持一致）
            const storeSettings = ruiyi_pos_ajax.store_settings || {};
            const storeName      = storeSettings.store_name || 'TIENDA';
            const storeAddress   = storeSettings.store_address || '';
            const storePhone     = storeSettings.store_phone || '';
            const storeEmail     = storeSettings.store_email || '';
            const storeTaxNumber = storeSettings.store_tax_number || '';

            // ====== 店铺抬头（全部 10pt，统一行高 5mm） ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "72mm", "5mm", storeName);
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", 10);
            LODOP.SET_PRINT_STYLEA(0, "Bold", 1);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);
            y += 5;

            if (storeAddress) {
                // 地址可能很长会折行：按字符数估算占用行数（80mm@10pt ≈ 每行 32 字符）
                const addrLines = Math.max(1, Math.ceil(storeAddress.length / 32));
                const addrHeight = addrLines * 5;
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "72mm", addrHeight + "mm", storeAddress);
                LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(0, "FontSize", 10);
                LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);
                y += addrHeight;
            }
            if (storePhone) {
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "72mm", "5mm", "Tel: " + storePhone);
                LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(0, "FontSize", 10);
                LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);
                y += 5;
            }
            if (storeEmail) {
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "72mm", "5mm", "Email: " + storeEmail);
                LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(0, "FontSize", 10);
                LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);
                y += 5;
            }
            if (storeTaxNumber) {
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "72mm", "5mm", "NIF/CIF: " + storeTaxNumber);
                LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(0, "FontSize", 10);
                LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);
                y += 5;
            }
            y += 2;

            // ====== 标题 (带重打标记) ======
            const locale = document.documentElement.lang || 'en';
            const title = locale.includes('zh') ? '【重打】日结单' :
                         locale.includes('es') ? '【COPIA】CIERRE DIARIO' :
                         '【REPRINT】DAILY SETTLEMENT';
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "72mm", "5mm", title);
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", 11);
            LODOP.SET_PRINT_STYLEA(0, "Bold", 1);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);
            y += 7;

            // ====== 分隔线 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "72mm", "4mm", "================================");
            LODOP.SET_PRINT_STYLEA(0, "FontName", "Courier New");
            LODOP.SET_PRINT_STYLEA(0, "FontSize", 9);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);
            y += 5;

            // ====== 结单日期 ======
            const dateLabel = locale.includes('zh') ? '结单日期' :
                             locale.includes('es') ? 'Fecha de cierre' : 'Settlement Date';
            LODOP.ADD_PRINT_TEXT(y + "mm", "4mm", "68mm", "4mm", `${dateLabel}: ${data.settlement_date}`);
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", fontSize);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 1);
            y += 5;

            // ====== 结单编号 ======
            if (data.settlement_id) {
                const idLabel = locale.includes('zh') ? '结单编号' :
                               locale.includes('es') ? 'ID de cierre' : 'Settlement ID';
                LODOP.ADD_PRINT_TEXT(y + "mm", "4mm", "68mm", "4mm", `${idLabel}: ${data.settlement_id}`);
                LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(0, "FontSize", fontSize);
                LODOP.SET_PRINT_STYLEA(0, "Alignment", 1);
                y += 5;
            }

            // ====== 分隔线 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "72mm", "4mm", "--------------------------------");
            LODOP.SET_PRINT_STYLEA(0, "FontName", "Courier New");
            LODOP.SET_PRINT_STYLEA(0, "FontSize", 9);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);
            y += 5;

            // ====== 销售汇总 ======
            const summaryLabel = locale.includes('zh') ? '销售汇总' :
                                locale.includes('es') ? 'RESUMEN DE VENTAS' : 'SALES SUMMARY';
            LODOP.ADD_PRINT_TEXT(y + "mm", "4mm", "68mm", "4mm", summaryLabel);
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", fontSize);
            LODOP.SET_PRINT_STYLEA(0, "Bold", 1);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 1);
            y += 5;

            // 现金
            const cashLabel = locale.includes('zh') ? '现金' : locale.includes('es') ? 'Efectivo' : 'Cash';
            LODOP.ADD_PRINT_TEXT(y + "mm", "4mm", "40mm", "4mm", cashLabel + ":");
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", fontSize);
            LODOP.ADD_PRINT_TEXT(y + "mm", "44mm", "28mm", "4mm", data.cash_amount.toFixed(2) + "€");
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", fontSize);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 3);
            y += 4;

            // 刷卡
            const cardLabel = locale.includes('zh') ? '刷卡' : locale.includes('es') ? 'Tarjeta' : 'Card';
            LODOP.ADD_PRINT_TEXT(y + "mm", "4mm", "40mm", "4mm", cardLabel + ":");
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", fontSize);
            LODOP.ADD_PRINT_TEXT(y + "mm", "44mm", "28mm", "4mm", data.card_amount.toFixed(2) + "€");
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", fontSize);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 3);
            y += 4;

            // 转账
            const transferLabel = locale.includes('zh') ? '转账' : locale.includes('es') ? 'Transferencia' : 'Transfer';
            LODOP.ADD_PRINT_TEXT(y + "mm", "4mm", "40mm", "4mm", transferLabel + ":");
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", fontSize);
            LODOP.ADD_PRINT_TEXT(y + "mm", "44mm", "28mm", "4mm", (data.transfer_amount || 0).toFixed(2) + "€");
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", fontSize);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 3);
            y += 4;

            // ====== 分隔线 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "72mm", "4mm", "================================");
            LODOP.SET_PRINT_STYLEA(0, "FontName", "Courier New");
            LODOP.SET_PRINT_STYLEA(0, "FontSize", 9);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);
            y += 5;

            // ====== 总计 ======
            const totalLabel = locale.includes('zh') ? '总计' : locale.includes('es') ? 'TOTAL' : 'TOTAL';
            LODOP.ADD_PRINT_TEXT(y + "mm", "4mm", "40mm", "5mm", totalLabel + ":");
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", 11);
            LODOP.SET_PRINT_STYLEA(0, "Bold", 1);
            LODOP.ADD_PRINT_TEXT(y + "mm", "44mm", "28mm", "5mm", data.total_amount.toFixed(2) + "€");
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", 11);
            LODOP.SET_PRINT_STYLEA(0, "Bold", 1);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 3);
            y += 8;

            // ====== 打印时间 ======
            const now = new Date();
            const printTime = now.toLocaleString('es-ES', {
                day: '2-digit', month: '2-digit', year: 'numeric',
                hour: '2-digit', minute: '2-digit'
            });
            const printLabel = locale.includes('zh') ? '打印时间' :
                              locale.includes('es') ? 'Impreso' : 'Printed';
            LODOP.ADD_PRINT_TEXT(y + "mm", "4mm", "68mm", "4mm", `${printLabel}: ${printTime}`);
            LODOP.SET_PRINT_STYLEA(0, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(0, "FontSize", 8);
            LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);
            y += 10;

            // 打印
            LODOP.PRINT();

        } catch (error) {
            console.error('[历史日结单打印] 错误:', error);
            throw error;
        }
    }

    /**
     * 打印月结单（Clodop小票）
     */
    async printMonthlySettlement() {
        if (!this.monthlySettlementData) {
            this.showToast('No data to print', 'error');
            return;
        }

        const data = this.monthlySettlementData;

        // 检查是否有数据
        if (!data.records || data.records.length === 0) {
            const locale = document.documentElement.lang || 'en';
            const noDataText = locale.includes('zh') ? '本月暂无结单记录' :
                              locale.includes('es') ? 'No hay registros este mes' :
                              'No records this month';
            this.showToast(noDataText, 'warning');
            return;
        }

        try {
            // 尝试使用CLodop打印，如果失败则使用浏览器打印
            if (typeof getLodop === 'function') {
                const LODOP = getLodop();
                if (LODOP && LODOP.VERSION) {
                    this.printMonthlyWithCLODOP(data);
                } else {
                    this.printMonthlyWithBrowser(data);
                }
            } else {
                this.printMonthlyWithBrowser(data);
            }

            this.showToast('月结单已发送到打印机', 'success');

        } catch (error) {
            console.error('[月结单打印] 打印错误:', error);
            this.showToast('Error al imprimir', 'error');
        }
    }

    /**
     * 使用CLodop打印月结单 - 全部靠左对齐版本（参考酒吧POS系统样式）
     */
    printMonthlyWithCLODOP(data) {
        try {
            // 检查getLodop函数是否可用
            if (typeof getLodop !== 'function') {
                console.error('[月结单打印] getLodop函数未定义，CLODOP未加载');
                throw new Error('CLODOP not available - getLodop function not found');
            }

            const LODOP = getLodop();

            // 检查LODOP对象是否有效
            if (!LODOP || !LODOP.VERSION) {
                console.error('[月结单打印] CLODOP对象无效或未连接');
                throw new Error('CLODOP service not connected');
            }

            // 获取默认打印机
            const defaultPrinter = window.clodopConfig?.defaultPrinter || '';

            LODOP.SET_LICENSES("","D615C875005D74B88EC9E2585C79798E9CA","","");
            LODOP.PRINT_INIT("月结单");
            LODOP.SET_PRINT_PAGESIZE(3, "80mm", 0, "");

            if (defaultPrinter) {
                LODOP.SET_PRINTER_INDEX(defaultPrinter);
            }

            // 统一字体设置
            const fontName = "Arial";
            const fontSize = 9;

            let y = 5;
            let elementIndex = 0;

            // ====== 店铺抬头（与结账小票一致：名称 + 地址 + 电话 + 邮箱 + 税号） ======
            const _storeSettings = ruiyi_pos_ajax.store_settings || {};
            const storeName      = _storeSettings.store_name || 'TIENDA RETAIL';
            const storeAddress   = _storeSettings.store_address || '';
            const storePhone     = _storeSettings.store_phone || '';
            const storeEmail     = _storeSettings.store_email || '';
            const storeTaxNumber = _storeSettings.store_tax_number || '';

            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", storeName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;
            y += 5;

            if (storeAddress) {
                // 地址可能很长会折行：按字符数估算占用行数（80mm@10pt ≈ 每行 32 字符）
                const addrLines = Math.max(1, Math.ceil(storeAddress.length / 32));
                const addrHeight = addrLines * 5;
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", addrHeight + "mm", storeAddress);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
                elementIndex++;
                y += addrHeight;
            }
            if (storePhone) {
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Tel: " + storePhone);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
                elementIndex++;
                y += 5;
            }
            if (storeEmail) {
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Email: " + storeEmail);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
                elementIndex++;
                y += 5;
            }
            if (storeTaxNumber) {
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "NIF/CIF: " + storeTaxNumber);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
                elementIndex++;
                y += 5;
            }
            y += 2;

            // ====== 标题 - CIERRE MENSUAL - 左对齐 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "CIERRE MENSUAL");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 11);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;
            y += 6;

            // ====== 月份 - 从筛选框获取 ======
            const monthInput = document.getElementById('monthly-filter-input');
            const monthValue = monthInput ? monthInput.value : new Date().toISOString().slice(0, 7);
            const [yearNum, monthNum] = monthValue.split('-');
            const monthNames = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
                              'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
            const monthDisplay = `${monthNames[parseInt(monthNum) - 1]} ${yearNum}`;

            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", `Mes: ${monthDisplay}`);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 6;

            // ====== 分隔线 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "3mm", "================================");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 5;

            // ====== 汇总统计 - 全部靠左，欧元符号在数字后面 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "TOTAL PERIODO: " + parseFloat(data.summary.total || 0).toFixed(2) + " €");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;
            y += 5;

            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Tarjeta: " + parseFloat(data.summary.card || 0).toFixed(2) + " €");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 5;

            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Efectivo: " + parseFloat(data.summary.cash || 0).toFixed(2) + " €");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 5;

            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Cierres: " + (data.summary.count || data.records.length));
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 6;

            // ====== 分隔线 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "3mm", "================================");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 5;

            // ====== 日结单明细标题 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "DETALLE POR DIA");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 10);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;
            y += 6;

            // ====== 表头 - 四列标题（靠左） ======
            // Fecha(日期) | Total(总额) | Tarjeta(刷卡) | Efectivo(现金)
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "15mm", "4mm", "Fecha");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;

            LODOP.ADD_PRINT_TEXT(y + "mm", "17mm", "17mm", "4mm", "Total");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;

            LODOP.ADD_PRINT_TEXT(y + "mm", "34mm", "19mm", "4mm", "Tarjeta");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;

            LODOP.ADD_PRINT_TEXT(y + "mm", "53mm", "23mm", "4mm", "Efectivo");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
            LODOP.SET_PRINT_STYLEA(elementIndex, "Bold", 1);
            elementIndex++;
            y += 4;

            // ====== 表头分隔线 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "3mm", "--------------------------------");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
            elementIndex++;
            y += 4;

            // ====== 每日明细 - 表格形式，全部靠左对齐 ======
            data.records.forEach(record => {
                // 解析日期（只显示 DD/MM）
                let dateDisplay = '';

                if (record.settlement_datetime) {
                    const dt = new Date(record.settlement_datetime);
                    const day = String(dt.getDate()).padStart(2, '0');
                    const month = String(dt.getMonth() + 1).padStart(2, '0');
                    dateDisplay = `${day}/${month}`;
                } else if (record.date) {
                    const datePart = record.date.split('-');
                    if (datePart.length === 3) {
                        dateDisplay = `${datePart[2]}/${datePart[1]}`;
                    }
                }

                // 获取金额
                const total = parseFloat(record.total_amount || 0).toFixed(2);
                const card = parseFloat(record.card_amount || 0).toFixed(2);
                const cash = parseFloat(record.cash_amount || 0).toFixed(2);

                // 日期列（靠左）
                LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "15mm", "4mm", dateDisplay);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
                elementIndex++;

                // 总额列（靠左）
                LODOP.ADD_PRINT_TEXT(y + "mm", "17mm", "17mm", "4mm", total + "€");
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
                elementIndex++;

                // 刷卡列（靠左）
                LODOP.ADD_PRINT_TEXT(y + "mm", "34mm", "19mm", "4mm", card + "€");
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
                elementIndex++;

                // 现金列（靠左）
                LODOP.ADD_PRINT_TEXT(y + "mm", "53mm", "23mm", "4mm", cash + "€");
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
                LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
                elementIndex++;

                y += 4;
            });

            y += 2;

            // ====== 结束分隔线 ======
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "3mm", "================================");
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", fontSize);
            elementIndex++;
            y += 5;

            // ====== 打印时间 ======
            const printTime = new Date().toLocaleString('es-ES', {
                day: '2-digit',
                month: '2-digit',
                year: 'numeric',
                hour: '2-digit',
                minute: '2-digit'
            });
            LODOP.ADD_PRINT_TEXT(y + "mm", "2mm", "76mm", "5mm", "Impreso: " + printTime);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontName", fontName);
            LODOP.SET_PRINT_STYLEA(elementIndex, "FontSize", 8);
            y += 5;

            // 执行打印
            LODOP.PRINT();

        } catch (error) {
            console.error('Monthly settlement print error:', error);
            throw error;
        }
    }

    /**
     * 浏览器打印月结单（备用）
     */
    printMonthlyWithBrowser(data) {
        const locale = document.documentElement.lang || 'en';
        const monthInput = document.getElementById('monthly-filter-input');
        const monthValue = monthInput.value;
        const [year, month] = monthValue.split('-');

        const printWindow = window.open('', '', 'width=800,height=600');

        let recordsHtml = data.records.map(record => {
            let dateDisplay = record.date;
            if (record.settlement_datetime) {
                const dt = new Date(record.settlement_datetime);
                const day = String(dt.getDate()).padStart(2, '0');
                const month = String(dt.getMonth() + 1).padStart(2, '0');
                const year = dt.getFullYear();
                dateDisplay = `${day}-${month}-${year}`;
            }

            return `
                <tr>
                    <td>${dateDisplay}</td>
                    <td style="text-align: right">${parseFloat(record.total_amount).toFixed(2)}€</td>
                    <td style="text-align: right">${parseFloat(record.cash_amount).toFixed(2)}€</td>
                    <td style="text-align: right">${parseFloat(record.card_amount).toFixed(2)}€</td>
                </tr>
            `;
        }).join('');

        const html = `
            <html>
            <head>
                <title>${locale.includes('zh') ? '月结单' : locale.includes('es') ? 'Cierre Mensual' : 'Monthly Settlement'}</title>
                <style>
                    body { font-family: Arial, sans-serif; margin: 20px; }
                    h1 { text-align: center; font-size: 18pt; margin-bottom: 5px; }
                    h2 { text-align: center; font-size: 16pt; margin-bottom: 10px; }
                    .summary { background: #f0f0f0; padding: 15px; margin: 20px 0; border-radius: 5px; }
                    .summary-item { font-size: 14pt; margin: 5px 0; }
                    .summary-item.total { font-size: 16pt; font-weight: bold; }
                    table { width: 100%; border-collapse: collapse; margin-top: 20px; }
                    th, td { border: 1px solid #ddd; padding: 8px; }
                    th { background-color: #4a5568; color: white; text-align: left; }
                    .line { border-top: 1px dashed #000; margin: 10px 0; }
                </style>
            </head>
            <body>
                <div style="text-align:center;font-size:10pt;line-height:1.4;">
                    <div style="font-weight:bold;">${ruiyi_pos_ajax.store_settings?.store_name || 'RUIYI RETAIL POS'}</div>
                    ${(() => {
                        const s = ruiyi_pos_ajax.store_settings || {};
                        let lines = '';
                        if (s.store_address)    lines += `<div>${s.store_address}</div>`;
                        if (s.store_phone)      lines += `<div>Tel: ${s.store_phone}</div>`;
                        if (s.store_email)      lines += `<div>Email: ${s.store_email}</div>`;
                        if (s.store_tax_number) lines += `<div>NIF/CIF: ${s.store_tax_number}</div>`;
                        return lines;
                    })()}
                </div>
                <h2>${locale.includes('zh') ? '月结单' : locale.includes('es') ? 'CIERRE MENSUAL' : 'MONTHLY SETTLEMENT'}</h2>
                <p style="text-align: center;">${locale.includes('es') ? 'Mes' : locale.includes('zh') ? '月份' : 'Month'}: ${month}/${year}</p>

                <div class="summary">
                    <div class="summary-item total">${locale.includes('es') ? 'TOTAL DEL MES' : locale.includes('zh') ? '月度总额' : 'MONTHLY TOTAL'}: ${parseFloat(data.summary.total).toFixed(2)}€</div>
                    <div class="summary-item">${locale.includes('es') ? 'Tarjeta' : locale.includes('zh') ? '刷卡总额' : 'Total Card'}: ${parseFloat(data.summary.card).toFixed(2)}€</div>
                    <div class="summary-item">${locale.includes('es') ? 'Efectivo' : locale.includes('zh') ? '现金总额' : 'Total Cash'}: ${parseFloat(data.summary.cash).toFixed(2)}€</div>
                </div>

                <h3>${locale.includes('es') ? 'Detalle Diario' : locale.includes('zh') ? '日结单明细' : 'Daily Details'}</h3>
                <table>
                    <thead>
                        <tr>
                            <th>${locale.includes('es') ? 'Fecha' : locale.includes('zh') ? '日期' : 'Date'}</th>
                            <th style="text-align: right">${locale.includes('es') ? 'Total' : locale.includes('zh') ? '总额' : 'Total'}</th>
                            <th style="text-align: right">${locale.includes('es') ? 'Efectivo' : locale.includes('zh') ? '现金' : 'Cash'}</th>
                            <th style="text-align: right">${locale.includes('es') ? 'Tarjeta' : locale.includes('zh') ? '刷卡' : 'Card'}</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${recordsHtml}
                    </tbody>
                </table>

                <p style="margin-top: 30px; text-align: center; font-size: 10pt;">
                    ${locale.includes('es') ? 'Impreso' : locale.includes('zh') ? '打印时间' : 'Printed'}: ${new Date().toLocaleString()}
                </p>
            </body>
            </html>
        `;

        printWindow.document.write(html);
        printWindow.document.close();
        printWindow.focus();

        setTimeout(() => {
            printWindow.print();
            printWindow.close();
        }, 500);
    }

    // 🔥 ========================================
    // Zero Price Product Modal Methods
    // ========================================

    /**
     * Show zero price input modal
     * @param {Object} product - Product with €0 price
     */
    showZeroPriceModal(product) {
        if (!product || !product.id) return;

        this.pendingZeroPriceProduct = product;

        // Update modal content
        const productNameEl = document.getElementById('zero-price-product-name');
        if (productNameEl) {
            productNameEl.textContent = product.name;
        }

        // Clear and focus input
        const priceInput = document.getElementById('zero-price-input');
        if (priceInput) {
            priceInput.value = '';
            setTimeout(() => priceInput.focus(), 100);
        }

        // Show modal
        const modal = document.getElementById('zero-price-modal');
        if (modal) {
            modal.classList.remove('hidden');
        }
    }

    /**
     * Close zero price input modal
     */
    closeZeroPriceModal() {
        const modal = document.getElementById('zero-price-modal');
        if (modal) {
            modal.classList.add('hidden');
        }

        // Clear stored product
        this.pendingZeroPriceProduct = null;

        // Clear input
        const priceInput = document.getElementById('zero-price-input');
        if (priceInput) {
            priceInput.value = '';
        }

        // Refocus on Varios input
        setTimeout(() => this.focusVariosInput(), 100);
    }

    /**
     * Confirm zero price and add product to cart with user-entered price
     */
    confirmZeroPrice() {
        const priceInput = document.getElementById('zero-price-input');
        const enteredPrice = parseFloat(priceInput.value);

        // Validate price
        if (isNaN(enteredPrice) || enteredPrice <= 0) {
            this.showToast(
                posTranslations['Please enter valid price'] || 'Please enter a valid price greater than €0',
                'error'
            );
            priceInput.focus();
            return;
        }

        if (!this.pendingZeroPriceProduct) {
            this.closeZeroPriceModal();
            return;
        }

        const productWithPrice = {
            ...this.pendingZeroPriceProduct,
            price: enteredPrice,
            originalPrice: enteredPrice,
            customPrice: true,
            _zeroPriceConfirmed: true
        };

        this.closeZeroPriceModal();

        const cartItem = {
            ...productWithPrice,
            cartItemId: ++this.cartItemIdCounter,
            quantity: 1,
            discountPercent: 0,
            weightBased: false
        };

        this.cart.push(cartItem);
        this.selectedProductId = cartItem.cartItemId;
        this.updateCart();
        this.updateScaleCheckoutState();

        // Show success message
        this.showToast(
            `${productWithPrice.name} ${posTranslations['Product added to cart'] || 'added to cart'} (€${enteredPrice.toFixed(2)})`,
            'success'
        );
    }

}

// Initialize POS system
document.addEventListener('DOMContentLoaded', function() {
    window.pos = new ProfessionalPOS();

    // 账单按钮事件监听 (Bills - Combined Daily & Monthly Settlement)
    const billsBtn = document.getElementById('top-bills-btn');
    if (billsBtn) {
        billsBtn.addEventListener('click', function() {
            window.pos.openBillsModal();
        });
    }

    // 设置按钮事件监听 (Settings - Combined Supplier, Add Product & Backend)
    const settingsBtn = document.getElementById('top-settings-btn');
    if (settingsBtn) {
        settingsBtn.addEventListener('click', function() {
            window.pos.openSettingsModal();
        });
    }

    // 历史订单按钮事件监听 (Order History)
    const orderHistoryBtn = document.getElementById('top-order-history-btn');
    if (orderHistoryBtn) {
        orderHistoryBtn.addEventListener('click', function() {
            window.pos.openOrderHistoryModal();
        });
    }

    // 历史订单筛选器事件监听
    const orderHistorySearch = document.getElementById('order-history-search');
    const orderHistoryStatusFilter = document.getElementById('order-history-status-filter');
    const orderHistoryDateFilter = document.getElementById('order-history-date-filter');

    let orderSearchTimeout = null;

    if (orderHistorySearch) {
        orderHistorySearch.addEventListener('input', function() {
            if (orderSearchTimeout) clearTimeout(orderSearchTimeout);
            orderSearchTimeout = setTimeout(() => {
                window.pos.loadOrderHistory();
            }, 500);
        });
    }

    if (orderHistoryStatusFilter) {
        orderHistoryStatusFilter.addEventListener('change', function() {
            window.pos.loadOrderHistory();
        });
    }

    if (orderHistoryDateFilter) {
        orderHistoryDateFilter.addEventListener('change', function() {
            window.pos.loadOrderHistory();
        });
    }
});
</script>

